void init_arrays(int* offset, int* key, struct record* rec, int size) {
    // Allocate memory for arrays
    offset = (int*)malloc(size * sizeof(int));
    key = (int*)malloc(size * sizeof(int));
    rec = (struct record*)malloc(size * sizeof(struct record));

    // Initialize offset and key arrays
    for (int i = 0; i < size; i++) {
        offset[i] = i;
        key[i] = i + 1;
    }

    // Initialize record array with random integers
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        rec[i].val = rand() % 100;
    }

    // Print arrays (debugging only)
    printf("Offset: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", offset[i]);
    }
    printf("\n");
    printf("Key: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", key[i]);
    }
    printf("\n");
    printf("Record: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", rec[i].val);
    }
    printf("\n");

    // Free allocated memory
    free(offset);
    free(key);
    free(rec);
}

// Define struct record
typedef struct {
    int val;
} record;

int main() {
    int size = 10;
    int* offset;
    int* key;
    record* rec;

    init_arrays(&offset, &key, &rec, size);

    return 0;
}
