#define MAX_HOSTNAME 256
#define MAX_IPADDR 16

typedef enum {
    STATUS_OK,
    STATUS_ERROR
} status_code;

u_char* resolve_dns(const char* hostname) {
    struct hostent* host;
    struct sockaddr_in sa;
    char ipaddr[MAX_IPADDR];

    if ((host = gethostbyname(hostname)) == NULL) {
        return NULL;
    }

    inet_ntop(AF_INET, &((struct in_addr*)host->h_addr)->s_addr, ipaddr, sizeof(ipaddr));
    return (u_char*)ipaddr;
}

int main() {
    FILE* file = fopen("network_data.csv", "r");
    if (!file) {
        printf("Error opening file\n");
        return -1;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        int fields = 0;
        char* token = strtok(line, ",");
        while (token && fields < 2) {
            if (strtol(token, NULL, 10)) {
                fields++;
            }
            token = strtok(NULL, ",");
        }

        if (fields >= 2) {
            double avg = (atof(token) + atof(strtok(NULL, ","))) / 2;
            sprintf(line, "%.*s%.1f", strlen(line)-fields*3-1, line, avg);
        }
    }

    fclose(file);

    return 0;
}
