#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <sys/types.h>
#include <unistd.h>

#define LOG_MAX_SIZE 1048576 // 1MB

typedef struct {
    int id;
    time_t timestamp;
    char* message;
} LogEntry;

void log_entry(const LogEntry entry) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    FILE* file = fopen("log.txt", "a+");
    if (!file) {
        perror("Error opening log file");
        exit(1);
    }

    fprintf(file, "%d %ld: %s\n", entry.id, entry.timestamp, entry.message);
    fclose(file);

    pthread_mutex_unlock(&lock);
}

void rotate_log() {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    FILE* file = fopen("log.txt", "r");
    if (!file) {
        perror("Error opening log file for rotation");
        exit(1);
    }

    char buffer[LOG_MAX_SIZE];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Process the log entry
    }

    fclose(file);

    rename("log.txt", "log_old.txt");
    FILE* new_file = fopen("log.txt", "w");
    if (!new_file) {
        perror("Error opening new log file for rotation");
        exit(1);
    }

    fclose(new_file);

    pthread_mutex_unlock(&lock);
}

void log_message(int id, const char* message, ...) {
    LogEntry entry;
    entry.id = id;
    entry.timestamp = time(NULL);

    va_list args;
    va_start(args, message);
    char buffer[256];
    vsnprintf(buffer, sizeof(buffer), message, args);
    va_end(args);

    entry.message = strdup(buffer);

    log_entry(entry);

    // Check if the log file has exceeded the maximum size
    FILE* file = fopen("log.txt", "rb");
    if (!file) {
        perror("Error opening log file for size check");
        exit(1);
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);

    fclose(file);

    if (size >= LOG_MAX_SIZE) {
        rotate_log();
    }
}

int main() {
    // Example usage:
    log_message(1, "Event type: %s", "success");
    log_message(2, "Event type: %s", "failure");

    return 0;
}
