#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ALGORITHMS 1000

typedef struct {
    char* name;
    int (*function)(void*, void*);
    void* param1;
    void* param2;
} Algorithm;

Algorithm availableAlgorithms[MAX_ALGORITHMS];
int algorithmCount = 0;

void addAlgorithm(Algorithm algo) {
    availableAlgorithms[algorithmCount] = algo;
    algorithmCount++;
}

int loadStaticAlgorithms() {
    // Load statically linked algorithms here
    addAlgorithm((Algorithm){.name="SHA256", .function=&sha256Function, .param1=NULL, .param2=NULL});
    addAlgorithm((Algorithm){.name="AES", .function=&aesFunction, .param1=NULL, .param2=NULL});
    return 0;
}

int loadDynamicAlgorithms(char* configPath) {
    // Load dynamically loaded algorithms from file or command-line options
    FILE* configFile = fopen(configPath, "r");
    if (!configFile) {
        fprintf(stderr, "Error opening configuration file: %s\n", configPath);
        return -1;
    }

    // Parse configuration file and load algorithms
    char line[256];
    while (fgets(line, sizeof(line), configFile)) {
        // Tokenize line and extract algorithm name and parameters
        char* token = strtok(line, ",");
        if (!token) continue;

        Algorithm algo;
        algo.name = token;
        token = strtok(NULL, ",");
        if (token) {
            algo.param1 = strdup(token);
        }
        token = strtok(NULL, ",");
        if (token) {
            algo.param2 = strdup(token);
        }

        // Load algorithm dynamically
        int (*func)(void*, void*) = dlopen(algo.name, RTLD_LAZY);
        if (!func) {
            fprintf(stderr, "Error loading algorithm %s: %s\n", algo.name, dlerror());
            continue;
        }
        algo.function = func;

        addAlgorithm(algo);
    }

    fclose(configFile);
    return 0;
}

int getAvailableAlgorithms(Algorithm** result, int* count) {
    *count = algorithmCount;
    *result = (Algorithm*)malloc(sizeof(Algorithm) * *count);
    memcpy(*result, availableAlgorithms, sizeof(Algorithm) * *count);
    return 0;
}

void unloadAlgorithms() {
    for (int i = 0; i < algorithmCount; i++) {
        if (availableAlgorithms[i].function) {
            dlclose(availableAlgorithms[i].function);
        }
        free((void*)availableAlgorithms[i].param1);
        free((void*)availableAlgorithms[i].param2);
    }
    free((void*)availableAlgorithms);
}
