['```cpp
void insertAfterValue(Node*& head, int targetValue, int insertValue) {
    Node* current = head;
    while (current != nullptr) {
        if (current->value == targetValue) {
            Node* newNode = new Node(insertValue);
            newNode->next = current->next;
            newNode->prev = current;
            if (current->next != nullptr) {
                current->next->prev = newNode;
            } else {
                head->next = newNode;
            }
            current->next = newNode;
            return;
        }
        current = current->next;
    }
    // If target value is not found, append insert_value to the end of the list
    Node* tail = head;
    while (tail->next != nullptr) {
        tail = tail->next;
    }
    Node* newNode = new Node(insertValue);
    newNode->prev = tail;
    tail->next = newNode;
}
