#include <boost/beast/core.hpp>
#include <boost/beast/http.hpp>
#include <boost/beast/version.hpp>
#include <boost/log/core.hpp>
#include <boost/log/trivial.hpp>
#include <boost/log/utility/init.loggers.hpp>

#include "RequestHandler.h"
#include "ConnectionPool.h"
#include "MonitoringSystem.h"

int main()
{
    // Initialize Boost.Log
    boost::log::core::get()->set_filter(boost::log::trivial::severity >= boost::log::trivial::info);

    // Initialize the connection pool with a default size and timeout
    ConnectionPool pool(10, 1000);

    // Set up the request handler
    RequestHandler requestHandler;

    // Start listening for incoming connections
    boost::asio::io_service io;
    boost::beast::tcp_stream stream(io);
    stream.connect("127.0.0.1:8080");

    // Accept and process incoming connections
    while (true)
    {
        // Wait for a new connection
        auto conn = stream.accept();

        // Start handling the request
        pool.acquire();
        boost::beast::http::request<boost::beast::http::string_body> req;
        req.version(11);
        req.method(boost::beast::http::verb::get);

        // Process GET requests
        if (req.method() == boost::beast::http::verb::get)
        {
            requestHandler.handleGETRequest(req, conn);
        }
        else if (req.method() == boost::beast::http::verb::post)
        {
            // Process POST requests
            requestHandler.handlePOSTRequest(req, conn);
        }

        // Release the connection back to the pool
        pool.release();
    }

    return 0;
}
