    logger.setOutputDestination("logs.txt");

    // Log messages
    logger.log(Logger::DEBUG, "This is a debug message");
    logger.log(Logger::INFO, "This is an info message");
    logger.log(Logger::WARN, "This is a warning message");
    logger.log(Logger::ERROR, "This is an error message");
    logger.log(Logger::FATAL, "This is a fatal message");

