['```java
import java.io.*;
import java.security.MessageDigest;
import java.util.*;

public class FileProcessorService {

    private static final int MAX_CONCURRENT_OPERATIONS = 10;
    private static final int RETRY_ATTEMPTS = 3;

    public Map<String, String> processFilePaths(List<String> filePaths) {
        Map<String, String> fileHashes = new HashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_OPERATIONS);

        for (String filePath : filePaths) {
            if (filePath == null || filePath.isEmpty()) {
                continue;
            }

            Future<Map.Entry<String, String>> future = executor.submit(() -> processFile(filePath));
            try {
                Map.Entry<String, String> entry = future.get();
                if (entry != null) {
                    fileHashes.put(entry.getKey(), entry.getValue());
                }
            } catch (InterruptedException | ExecutionException e) {
                logFailedOperation(e);
            }
        }

        executor.shutdown();
        return fileHashes;
    }

    private Map.Entry<String, String> processFile(String filePath) {
        try (InputStream is = new FileInputStream(filePath)) {
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[1024];
            int bytesRead;
            StringBuilder fileName = new StringBuilder();
            boolean isDir = false;

            File file = new File(filePath);
            if (!file.exists()) {
                return null; // skip non-existent files
            }

            if (file.isDirectory()) {
                isDir = true;
            } else {
                fileName.append(file.getName());
            }

            while ((bytesRead = is.read(buffer)) != -1) {
                md5.update(buffer, 0, bytesRead);
            }

            String hash = bytesToHex(md5.digest());

            return new AbstractMap.SimpleEntry<>(isDir ? null : fileName.toString(), hash);

        } catch (IOException e) {
            logFailedOperation(e);
            return null;
        }
    }

    private void logFailedOperation(Throwable t) {
        // implement logging mechanism here
        System.out.println("Failed operation: " + t.getMessage());
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : bytes) {
            String HEXES = Integer.toHexString(0xFF & b);
            if (HEXES.length() == 1) {
                hexString.append('0');
            }
            hexString.append(HEXES);
        }
        return hexString.toString();
    }
}
