function extractCloudProviderTerms(doc) {
  const termsRegex = /(\b(snowflake|lambda|ec2)\b)/gi;
  let termFrequency = {};

  for (let chunkIndex = 0; chunkIndex < doc.length; chunkIndex += 10000) {
    const chunk = doc.substring(chunkIndex, chunkIndex + 10000);

    for (const match in chunk.match(termsRegex)) {
      const term = match.group(1).toLowerCase();

      if (!termFrequency[term]) {
        termFrequency[term] = 0;
      }

      termFrequency[term]++;
    }
  }

  return termFrequency;
}
