['```javascript
function renderFooterScripts(scripts, enableLazyLoading = false, priority = 'key', priorityOrder = 'asc') {
  const scriptElements = scripts
    .filter(script => typeof script.key === 'string' && typeof script.code === 'string' && script.code.trim() !== '')
    .map((script, index) => {
      let id = `script-${index}`;
      if (priority === 'key') {
        id = script.key;
      }
      const scriptElement = `<script id="${id}" src="data:text/javascript;base64,${btoa(script.code)}"></script>`;
      return enableLazyLoading ? `<noscript>${scriptElement}</noscript>` : scriptElement;
    })
    .sort((a, b) => {
      if (priorityOrder === 'asc') {
        if (priority === 'key') return a.localeCompare(b);
        else if (priority === 'code') return a.length - b.length;
      } else {
        if (priority === 'key') return b.localeCompare(a);
        else if (priority === 'code') return b.length - a.length;
      }
    })
    .join('');

  return `<footer>${scriptElements}</footer>`;
}
