function refreshDialogFields(resourceId, url, fields) {
  let retryCount = 0;
  const maxRetryCount = 3;
  const initialBackoffTime = 100; // in milliseconds
  const backoffFactor = 2;

  function getTimestamp() {
    return window.parent.dialogTimestamp;
  }

  async function refresh(fieldsToRefresh, retry) {
    try {
      if (retry) {
        await wait(retryCount * initialBackoffTime * Math.pow(backoffFactor, retryCount));
      }

      const response = await fetch(url);
      const data = await response.json();

      if (!data.fields) return; // partial success response

      for (const field of fieldsToRefresh) {
        if (data.fields[field]) {
          window.parent.dialogFields[field] = data.fields[field];
        } else {
          console.log(`Failed to refresh field: ${field}`);
        }
      }

      const updatedFields = Object.keys(data.fields);

      // Update the timestamp and cache
      window.parent.dialogTimestamp = Date.now();
      window.parent.dialogFields = { ...window.parent.dialogFields, ...data(fields) };

      return updatedFields;
    } catch (error) {
      if (retryCount < maxRetryCount) {
        retryCount++;
        return await refresh(fieldsToRefresh, true);
      }
      throw error;
    }
  }

  function wait(ms) {
    return new Promise(resolve => setTimeout(() => resolve(), ms));
  }

  if (!fields.length) return; // no fields to refresh

  const timestamp = getTimestamp();
  const lastUpdatedFields = Object.keys(window.parent.dialogFields);

  let updatedFields = [];
  for (const field of fields) {
    if (!lastUpdatedFields.includes(field)) {
      updatedFields.push(field);
    }
  }

  if (updatedFields.length > 0) {
    try {
      const refreshedFields = await refresh(updatedFields, false);
      return refreshedFields;
    } catch (error) {
      console.error(error);
    }
  }
}
