function mergeSortedArrays(arrays) {
  const queue = [...arrays].flat().map(([val, index]) => ({ value: val, arrayIndex: index }));
  queue.sort((a, b) => a.value - b.value);

  let mergedArray = [];
  while (queue.length > 0) {
    let { value, arrayIndex } = queue.shift();
    mergedArray.push(value);

    const nextValues = arrays[arrayIndex].slice(1);
    if (nextValues.length > 0) {
      queue.push(...nextValues.map((val, i) => ({ value: val, arrayIndex })));
      queue.sort((a, b) => a.value - b.value);
    }
  }

  return mergedArray;
}

// Example usage:
const arrays = [
  [1, 3, 5],
  [2, 4, 6],
  [0, 7, 8]
];

console.log(mergeSortedArrays(arrays)); // Output: [0, 1, 2, 3, 4, 5, 6, 7, 8]

// Integration into data processing pipeline:
const pipeline = [
  ...dataFeeds.map(feed => feed.data),
  mergeSortedArrays(pipeline)
];

