const fs = require('fs');
const path = require('path');
const mime = require('mime-types');

module.exports = function loader(directory, options) {
  const cache = {};
  const types = {};

  function loadFile(filename) {
    return new Promise((resolve, reject) => {
      try {
        const file = fs.readFileSync(path.join(directory, filename));
        const code = file.toString();
        const type = mime.lookup(path.extname(filename));
        const extension = `${type}.js`;
        const modifiedCode = code.replace(/\.js$/, `_${filename.split('.')[0]}${extension.replace('.js', '')}`);

        try {
          // Execute the loaded code
          eval(modifiedCode);
          resolve();
        } catch (err) {
          reject(err);
        }
      } catch (err) {
        if (err.code === 'ENOENT') {
          reject(new Error(`File not found: ${filename}`));
        } else if (err.errno === 13) {
          reject(new Error(`Permission denied for file: ${filename}`));
        } else {
          reject(err);
        }
      }
    });
  }

  function loadDependencies(filename) {
    return new Promise((resolve, reject) => {
      try {
        const deps = fs.readdirSync(path.join(directory, filename.replace /\.js$/, ''));

        if (!deps.length) {
          resolve();
        } else {
          Promise.all(deps.map(loadFile)).then(() => resolve());
        }
      } catch (err) {
        if (err.code === 'ENOENT') {
          reject(new Error(`Directory not found: ${filename}`));
        } else {
          reject(err);
        }
      }
    });
  }

  function loadFiles() {
    return new Promise((resolve, reject) => {
      fs.readdir(directory, (err, files) => {
        if (err) {
          reject(err);
        } else {
          const promises = files.map(filename => loadFile(filename));

          Promise.all(promises).then(() => resolve());
        }
      });
    });
  }

  return { loadFiles, loadDependencies };
};
