package com.example.theme.cache;

import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class ThemeCache {
    private Map<String, Bitmap> cachedThemes = new HashMap<>();
    private File cacheRootDir;
    private int maxFileSizeThreshold;

    public ThemeCache(File cacheRootDir, int maxFileSizeThreshold) {
        this.cacheRootDir = cacheRootDir;
        this.maxFileSizeThreshold = maxFileSizeThreshold;
    }

    public void setDefaultThemeDirectory(String themeDirectory) throws IOException {
        if (!cacheRootDir.exists()) {
            cacheRootDir.mkdir();
        }
        File defaultThemeDir = new File(cacheRootDir, themeDirectory);
        if (!defaultThemeDir.exists()) {
            defaultThemeDir.mkdir();
        }
    }

    public void cachePNGFile(String themeName, String filePath) throws IOException {
        FileInputStream fileInputStream = new FileInputStream(filePath);
        Bitmap bitmap = BitmapFactory.decodeStream(fileInputStream);

        // Validate and downscale large PNG files
        if (bitmap.getAllocationByteCount() > maxFileSizeThreshold) {
            bitmap = downscaleBitmap(bitmap);
        }

        // Recycle the original bitmap
        bitmap.recycle();

        cachedThemes.put(themeName, bitmap);

        // Save the cached theme to disk
        FileOutputStream fileOutputStream = new FileOutputStream(getCacheFilePath(themeName));
        bitmap.compress(Bitmap.CompressFormat.PNG, 100, fileOutputStream);
    }

    public void applyCachedTheme(String themeName) {
        Bitmap cachedBitmap = cachedThemes.get(themeName);
        if (cachedBitmap != null) {
            // Apply the cached theme
            // ...
        }
    }

    private File getCacheFilePath(String themeName) {
        return new File(cacheRootDir, themeName + ".png");
    }

    private Bitmap downscaleBitmap(Bitmap bitmap) {
        int newWidth = bitmap.getWidth() / 2;
        int newHeight = bitmap.getHeight() / 2;
        bitmap = Bitmap.createScaledBitmap(bitmap, newWidth, newHeight, false);
        return bitmap;
    }
}
