function fetchWeatherData($location) {
    $apiUrl = 'https://weather-api.com/realtime';
    $apiKey = 'YOUR_API_KEY';
    $cacheExpireTime = 3600; // 1 hour

    // Initialize the retry mechanism with a delay of 500ms and up to 5 attempts
    $retryDelayMs = 500;
    $maxAttempts = 5;

    for ($attempt = 0; $attempt <= $maxAttempts; $attempt++) {
        try {
            // Connect to the API with HTTP client
            $httpClient = new GuzzleHttp\Client();
            $response = $httpClient->request('GET', $apiUrl . '?location=' . $location, ['headers' => ['X-Api-Key' => $apiKey]]);

            if ($response->getStatusCode() == 200) {
                // Validate the API response
                $data = json_decode($response->getBody()->getContents(), true);
                if (isset($data['temperature'], $data['humidity'])) {
                    // Store the data in the cache
                    $cache = new Memcached();
                    $cache->set('weather_data_' . $location, $data, $cacheExpireTime);

                    return ['success' => true, 'message' => 'Cache updated successfully'];
                } else {
                    // Invalid API response, log and proceed with default values or cached entry
                    error_log('Invalid API response: ' . json_encode($data));
                    return ['success' => false, 'message' => 'Failed to retrieve weather data'];
                }
            } elseif ($response->getStatusCode() == 503) {
                // Temporary maintenance, wait for a short period and try again
                if ($attempt < $maxAttempts - 1) {
                    usleep($retryDelayMs * 1000);
                    continue;
                } else {
                    // Exceeded maximum attempts, fail gracefully
                    error_log('Failed to connect to the API after ' . $maxAttempts . ' attempts');
                    return ['success' => false, 'message' => 'Failed to retrieve weather data'];
                }
            } else {
                // Unknown error, log and proceed with default values or cached entry
                error_log('API request failed: ' . json_encode($response->getBody()->getContents()));
                return ['success' => false, 'message' => 'Failed to retrieve weather data'];
            }
        } catch (GuzzleHttp\Expection $e) {
            // Log the exception and proceed with default values or cached entry
            error_log('Error connecting to API: ' . json_encode($e));
            return ['success' => false, 'message' => 'Failed to retrieve weather data'];
        }
    }

    return ['success' => false, 'message' => 'Failed to retrieve weather data'];
}
