function integrateRandomStringAndFile($directory, $length, $characterSet, $separator)
{
    $tempStorage = $_ENV['TEMP_STORAGE'] ?? './tmp';
    if (!is_dir($tempStorage)) {
        mkdir($tempStorage, 0777, true);
    }

    function generateRandomString(int $length, string $characterSet): string
    {
        $chars = str_split($characterSet);
        shuffle($chars);
        return implode('', array_slice($chars, 0, $length));
    }

    function readFileSync(string $file): ?string
    {
        if (!file_exists($file)) {
            return null;
        }
        try {
            $content = file_get_contents($file);
            return $content;
        } catch (Exception $e) {
            error_log('Error reading file: ' . $e->getMessage());
            return null;
        }
    }

    function combineStrings(string $randomString, string $fileContent, string $separator): string
    {
        return $randomString . $separator . $fileContent;
    }

    $randomString = generateRandomString($length, $characterSet);
    $fileContent = readFileSync($directory . '/' . basename($file));
    if ($fileContent === null) {
        error_log('File not found or inaccessible');
        return '';
    }
    $result = combineStrings($randomString, $fileContent, $separator);

    file_put_contents($tempStorage . '/' . 'output.txt', $result);
    return $result;
}
