function getCertificate(oauthClientId) {
  const options = {
    method: 'GET',
    headers: { 
      Accept: 'text/plain'
    },
    url: `https://remote-server.com/certificate/${oauthClientId}.pem`,
    // Enable connection pooling to improve performance
    pool: { max: 10, min: 1, idleTimeoutMillis: 30000 }, 
    // Set the request timeout
    timeout: 5000,
    // Handle network failures and retry with exponential backoff
    retries: 3,
    retryDelay: (attempt) => Math.min(1000 * Math.pow(2, attempt), 30000)
  };

  const cert = await axios.request(options);

  if (!cert.data || !Buffer.isBuffer(cert.data)) {
    throw new Error('Failed to retrieve certificate');
  }

  return cert.data.toString();
}

async function streamData(oauthClientId) {
  const options = {
    method: 'GET',
    headers: { 
      Accept: 'text/plain'
    },
    url: `https://remote-server.com/stream/${oauthClientId}`,
    // Set the request timeout
    timeout: 5000,
    // Handle network failures and retry with exponential backoff
    retries: 3,
    retryDelay: (attempt) => Math.min(1000 * Math.pow(2, attempt), 30000)
  };

  const stream = await axios.stream(options);

  if (!stream || !stream.isReadable()) {
    throw new Error('Failed to establish data stream');
  }

  // Create a robust data structure for storing and iterating over the stream
  const dataStructure = new Map();

  let paused = false;

  stream.on('data', (chunk) => {
    if (paused) return;
    // Process the chunk of data here...
    dataStructure.set(new Date().getTime(), chunk);
  });

  stream.on('end', () => {
    console.log('Data stream ended');
  });

  stream.on('error', (err) => {
    console.error(`Error occurred while streaming: ${err}`);
  });

  // Implement pause and resume functionality for the data stream
  return {
    start() {
      if (!paused) return;
      paused = false;
      stream.resume();
    },
    stop() {
      paused = true;
      stream.pause();
    }
  };
}

