#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    float latency;
    long data_transferred;
} Connection;

Connection* connections = NULL;
int connection_count = 0;

void add_connection(int id, float latency, long data_transferred) {
    Connection* new_connection = (Connection*)malloc(sizeof(Connection));
    new_connection->id = id;
    new_connection->latency = latency;
    new_connection->data_transferred = data_transferred;

    if (connection_count == 0) {
        connections = new_connection;
    } else {
        Connection* temp = connections;
        connections = new_connection;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_connection;
    }
    connection_count++;
}

void remove_connection(int id) {
    if (connection_count == 0) return;

    Connection* temp = connections;
    for (int i = 0; i < connection_count - 1; i++) {
        if (temp->id == id) break;
        temp = temp->next;
    }

    if (temp->id == id) {
        free(temp);
    } else {
        Connection* prev = temp;
        for (int i = 0; i < connection_count - 1; i++) {
            prev = prev->next;
        }
        prev->next = NULL;
    }

    connection_count--;
}

Connection* find_highest_throughput() {
    if (connection_count == 0) return NULL;

    Connection* temp = connections;
    Connection* highest_throughput = temp;
    long max_data_transferred = temp->data_transferred;

    for (int i = 1; i < connection_count; i++) {
        if (temp->next->data_transferred > max_data_transferred) {
            max_data_transferred = temp->next->data_transferred;
            highest_throughput = temp->next;
        }
        temp = temp->next;
    }

    return highest_throughput;
}

float get_average_latency(int id) {
    if (connection_count == 0) return -1.0;

    Connection* temp = connections;
    float total_latency = 0.0;

    for (int i = 0; i < connection_count; i++) {
        if (temp->id == id) break;
        total_latency += temp->latency;
        temp = temp->next;
    }

    return total_latency / connection_count;
}

long get_total_data_transferred(int id) {
    if (connection_count == 0) return -1L;

    Connection* temp = connections;
    long total_data_transferred = 0L;

    for (int i = 0; i < connection_count; i++) {
        if (temp->id == id) break;
        total_data_transferred += temp->data_transferred;
        temp = temp->next;
    }

    return total_data_transferred;
}

void print_connections() {
    Connection* temp = connections;
    for (int i = 0; i < connection_count; i++) {
        printf("ID: %d, Latency: %.2f, Data Transferred: %ld\n", temp->id, temp->latency, temp->data_transferred);
        temp = temp->next;
    }
}

int main() {
    add_connection(1, 10.0, 100000L);
    add_connection(2, 20.0, 200000L);
    add_connection(3, 30.0, 300000L);

    print_connections();

    Connection* highest_throughput = find_highest_throughput();
    printf("Highest Throughput: ID=%d, Average Latency=%.2f, Total Data Transferred=%ld\n", 
           highest_throughput->id, get_average_latency(highest_throughput->id), get_total_data_transferred(highest_throughput->id));

    remove_connection(1);
    print_connections();

    return 0;
}
