#include <thread>
#include <chrono>

class CooldownManager {
public:
    void selectAndExecuteAttack() {
        std::unique_lock<std::mutex> lock(mutex_);
        auto now = std::chrono::steady_clock::now();
        if (last_attack_used_ == 1 && now - last_attack_time_[0] < std::chrono::seconds(9)) {
            // Attack 1 cooldown not over, try another
            return;
        } else if (last_attack_used_ == 2 && now - last_attack_time_[1] < std::chrono::seconds(15)) {
            // Attack 2 cooldown not over, try another
            return;
        } else if (last_attack_used_ == 3 && now - last_attack_time_[2] < std::chrono::seconds(21)) {
            // Attack 3 cooldown not over, try another
            return;
        }

        int attack_number = rand() % 3 + 1; // Randomly select an attack
        if (attack_number == last_attack_used_) { // Same attack in a row?
            while (true) {
                attack_number = rand() % 3 + 1; // Choose another
                if (attack_number != last_attack_used_)
                    break;
            }
        }

        last_attack_used_ = attack_number;
        last_attack_time_[last_attack_used_ - 1] = now;

        std::cout << "Selected attack: " << attack_number << std::endl;
    }

private:
    std::mutex mutex_;
    std::condition_variable cond_;
    int last_attack_used_{0};
    std::array<std::chrono::steady_clock::time_point, 3> last_attack_time_ = {{std::chrono::steady_clock::now()}};
};

CooldownManager cooldown_manager;

void gameLoop() {
    while (true) {
        cooldown_manager.selectAndExecuteAttack();
        // Game logic and rendering here
        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // Simulate game loop timing
    }
}
