using System;
using System.Threading;

public class DynamicValueGenerator
{
    private int? _minInt;
    private int? _maxInt;
    private double? _minFloat;
    private double? _maxFloat;
    private bool _inclusive;

    public void UpdateRange(int min, int max, double minFloat = default(double), double maxFloat = default(double), bool inclusive = true)
    {
        if (min > max) throw new ArgumentException("Min value cannot be greater than Max value", nameof(min));
        if (max < min && !inclusive) throw new ArgumentException("Exclusive range cannot have a Min value equal to or greater than the Max value", nameof(max));

        _minInt = min;
        _maxInt = max;
        _minFloat = minFloat;
        _maxFloat = maxFloat;
        _inclusive = inclusive;

        if (!inclusive && (min == max || Math.Abs(min - max) < 1e-6))
            throw new ArgumentException("Exclusive range cannot have a Min value equal to the Max value", nameof(min));
    }

    public int GenerateInt()
    {
        return new Random().Next(_minInt ?? 0, _maxInt ?? int.MaxValue);
    }

    public double GenerateFloat()
    {
        var random = new Random();
        if (_inclusive)
            return random.NextDouble() * (_maxFloat - _minFloat) + _minFloat;
        else
            return random.NextDouble() * Math.Abs(_maxFloat - _minFloat) + _minFloat;
    }

    public override string ToString()
    {
        var result = $"Range: [{_minInt}, {_maxInt}] (int), [{_minFloat}, {_maxFloat}] (float)";
        if (_inclusive)
            result += " (inclusive)";
        else
            result += " (exclusive)";
        return result;
    }
}
