#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef enum {
    STRING,
    INTEGER,
    BOOLEAN
} EntryType;

typedef struct _ConfigEntry {
    char* key;
    EntryType type;
    void* value;
    size_t size;
    bool valid;
} ConfigEntry;

int load_config(const char* filename, ConfigEntry** entries) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1; // error handling

    *entries = (ConfigEntry*)calloc(100, sizeof(ConfigEntry)); // initial memory allocation
    int entry_count = 0;

    char line[1024];
    while (fgets(line, 1024, file)) {
        ConfigEntry* entry = &(*entries)[entry_count++];
        entry->key = strndup(line, strlen(line) - 1); // skip newline character

        if (strncasecmp(line, "string=", 7) == 0) {
            entry->type = STRING;
            entry->value = strdup(strchr(line + 8, '=') + 1);
        } else if (strncasecmp(line, "integer=", 9) == 0) {
            entry->type = INTEGER;
            int* value_ptr = (int*)malloc(sizeof(int));
            *value_ptr = atoi(strchr(line + 10, '=') + 1);
            entry->value = (void*)value_ptr;
        } else if (strncasecmp(line, "boolean=", 9) == 0) {
            entry->type = BOOLEAN;
            bool* value_ptr = (bool*)malloc(sizeof(bool));
            *value_ptr = atoi(strchr(line + 10, '=') + 1) ? true : false;
            entry->value = (void*)value_ptr;
        } else {
            // invalid line format
            free(entry->key);
            for (int i = 0; i < entry_count - 1; i++) {
                free((*entries)[i].key);
                if ((*entries)[i].type == INTEGER) free((int*)(*entries)[i].value);
                else if ((*entries)[i].type == BOOLEAN) free((bool*)(*entries)[i].value);
            }
            free(*entries);
            *entries = NULL;
            return -2; // invalid config file
        }
    }

    fclose(file);

    for (int i = 0; i < entry_count; i++) {
        if ((*entries)[i]->valid) {
            // integrate with external API for version control updates
        } else {
            free((*entries)[i]->key);
            if ((*entries)[i]->type == INTEGER) free((int*)(*entries)[i].value);
            else if ((*entries)[i]->type == BOOLEAN) free((bool*)(*entries)[i].value);
        }
    }

    return entry_count;
}

void print_config(ConfigEntry** entries, int count) {
    for (int i = 0; i < count; i++) {
        printf("Key: %s, Type: ", (*entries)[i]->key);
        switch ((*entries)[i]->type) {
            case STRING:
                printf("string, Value: %s\n", (char*)((*entries)[i]->value));
                break;
            case INTEGER:
                printf("integer, Value: %d\n", *(int*)(*entries)[i].value);
                break;
            case BOOLEAN:
                printf("boolean, Value: %s\n", (*entries)[i]->type == BOOLEAN ? "true" : "false");
                break;
        }
    }
}

int main() {
    ConfigEntry** entries;
    int entry_count = load_config("config.txt", &entries);
    print_config(entries, entry_count);

    // release resources
    for (int i = 0; i < entry_count; i++) {
        free((*entries)[i]->key);
        if ((*entries)[i]->type == INTEGER) free((int*)(*entries)[i].value);
        else if ((*entries)[i]->type == BOOLEAN) free((bool*)(*entries)[i].value);
    }
    free(*entries);

    return 0;
}
