function processStringAndDOM(str, sizeLimit, selector, testFunc) {
  if (str.length > sizeLimit) return [];

  const escapedStr = str.replace(/[<>&"]/g, function(match) {
    switch (match) {
      case '<': return '&lt;';
      case '>': return '&gt;';
      case '&': return '&amp;';
      case '"': return '&quot;';
      default: return match;
    }
  });

  const doc = document.querySelector(selector);
  if (!doc) return [];

  let result = [];
  (function traverse(node, parent) {
    testFunc.call(null, node, function(node) {
      if (node.matches(selector)) result.push(node);
      traverse(node.children, node);
    });
  })(doc.firstElementChild);

  return result;
}
