#include <string.h>
#include <dirent.h>

#define MAX_LINE_LENGTH 1024
#define CACHE_SIZE 1000

typedef struct {
    char* file_path;
    int lines_processed;
} CacheEntry;

int main() {
    DIR* dir = opendir("path_to_directory");
    if (dir == NULL) {
        // Create the directory if it doesn't exist
        mkdir("path_to_directory", 0777);
        dir = opendir("path_to_directory");
    }

    // Initialize cache
    CacheEntry* cache = malloc(CACHE_SIZE * sizeof(CacheEntry));
    int cache_index = 0;

    while ((struct dirent* entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG && strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
            char file_path[MAX_LINE_LENGTH];
            sprintf(file_path, "%s/%s", "path_to_directory", entry->d_name);

            // Read file contents
            FILE* file = fopen(file_path, "r");
            if (file == NULL) {
                printf("Error opening file %s\n", file_path);
                continue;
            }

            char line[MAX_LINE_LENGTH];
            while (fgets(line, MAX_LINE_LENGTH, file)) {
                // Process line contents
                int fields = 0;
                char* token = strtok(line, " ");
                while (token != NULL) {
                    token = strtok(NULL, " ");
                    fields++;
                }

                if (fields > 2 && strcmp(token, "") != 0) {
                    // Allocate memory for the line's content
                    char* line_content = malloc((fields + 1) * sizeof(char));
                    strcpy(line_content, "");

                    int i;
                    for (i = 0; i < fields; i++) {
                        token = strtok(NULL, " ");
                        if (token != NULL) {
                            strcat(line_content, token);
                            strcat(line_content, ",");
                        }
                    }

                    // Print line contents in comma-separated format
                    printf("%s\n", line_content);

                    // Compute average of last two numeric fields as the final entry
                    int sum = 0;
                    for (i = fields - 2; i < fields; i++) {
                        token = strtok(NULL, " ");
                        if (token != NULL) {
                            int num = atoi(token);
                            sum += num;
                        }
                    }

                    printf("Average: %d\n", sum / (fields - 2));

                    // Free allocated memory
                    free(line_content);
                }
            }

            // Update cache entry or create new one
            if (cache_index >= CACHE_SIZE) {
                cache_index = 0;
            }

            CacheEntry* current_cache_entry = &cache[cache_index];
            current_cache_entry->file_path = file_path;
            current_cache_entry->lines_processed = fields;

            cache_index++;

            // Cache optimization using LRU strategy
            if (cache_index >= CACHE_SIZE) {
                for (int i = 0; i < CACHE_SIZE - 1; i++) {
                    cache[i] = cache[i + 1];
                }
            }

            fclose(file);
        }
    }

    closedir(dir);

    free(cache);
    return 0;
}
