#include <tiffio.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <md5.h>

typedef struct {
    int samples;
    uint16_t bitsPerSample;
    char* metadata;
} SampleInfo;

void processTIFF(const char* tiffFile, const char* inputString) {
    // TIFF parsing
    TIFF* tif = TIFFOpen(tiffFile, "r");
    if (!tif) {
        printf("Error opening TIFF file.\n");
        return;
    }

    // Get the number of samples
    uint16_t samples = tif->image.width * tif->image.height;

    // Initialize sample information
    SampleInfo* sampleInfos = (SampleInfo*)calloc(samples, sizeof(SampleInfo));
    if (!sampleInfos) {
        TIFFClose(tif);
        printf("Memory allocation failed.\n");
        return;
    }

    // Process each sample
    for (int i = 0; i < samples; i++) {
        // Get the metadata for this sample
        uint16_t bitsPerSample = tif->image.sampleFormat[i].bitsPerSample;
        char* metadata = (char*)malloc(bitsPerSample * sizeof(char));
        if (!metadata) {
            TIFFClose(tif);
            printf("Memory allocation failed.\n");
            return;
        }

        // Store the sample information
        sampleInfos[i].samples = tif->image.sampleFormat[i].samples;
        sampleInfos[i].bitsPerSample = bitsPerSample;
        sampleInfos[i].metadata = metadata;

        // Copy the metadata to the allocated buffer
        memcpy(metadata, &tif->image.sampleFormat[i], bitsPerSample);
    }

    // Compute MD5 hash of input string
    unsigned char md5[16];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, inputString, strlen(inputString));
    MD5_Final(md5, &ctx);

    // Print the sample information and MD5 hash
    for (int i = 0; i < samples; i++) {
        printf("Sample %d: Bits per sample = %d, Metadata = %s\n",
               i + 1, sampleInfos[i].bitsPerSample,
               sampleInfos[i].metadata);
        free(sampleInfos[i].metadata);
    }

    // Free memory and close the TIFF file
    for (int i = 0; i < samples; i++) {
        free(&sampleInfos[i]);
    }
    free(sampleInfos);
    TIFFClose(tif);

    // Print the MD5 hash
    for (int i = 0; i < 16; i++) {
        printf("%02x", md5[i]);
    }
    printf("\n");
}

int main() {
    processTIFF("path/to/tiff/file.tiff", "input string");
    return 0;
}
