#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_FILENAME_LENGTH 256
#define UNIQUE_IDENTIFIER_LENGTH 8
#define TIMESTAMP_FORMAT "%Y%m%d%H%M%S"

char* generate_new_filename(const char* original_filename, const int max_length) {
    // Validate original filename to prevent malicious path traversal attempts
    if (strlen(original_filename) > MAX_FILENAME_LENGTH || !original_filename[0]) {
        return NULL;
    }

    // Generate unique identifier from the first few characters of the original filename
    unsigned int hash = 0;
    for (int i = 0; i < UNIQUE_IDENTIFIER_LENGTH && i < strlen(original_filename); i++) {
        hash += (unsigned int)original_filename[i];
    }
    char unique_identifier[UNIQUE_IDENTIFIER_LENGTH + 1];
    sprintf(unique_identifier, "%08x", hash);

    // Infer file type from the original filename's extension if present
    const char* file_type = strrchr(original_filename, '.');
    char new_file_type[MAX_FILENAME_LENGTH + 1];
    if (file_type) {
        strcpy(new_file_type, file_type);
    } else {
        strcpy(new_file_type, ".txt"); // Default to generic type
    }

    // Generate timestamp
    time_t current_time = time(NULL);
    struct tm* timestamp_tm = localtime(&current_time);
    char timestamp[MAX_FILENAME_LENGTH + 1];
    strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, timestamp_tm);

    // Construct new filename
    char new_filename[max_length + 1];
    sprintf(new_filename, "%s-%s-%s", unique_identifier, new_file_type, timestamp);

    return new_filename;
}
