#include <openssl/aes.h>
#include <openssl/err.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void manage_theme_caching(const char* password) {
    const EVP_CIPHER* cipher = EVP_aes_256_cbc();
    unsigned char* password_hash;
    int password_len = strlen(password);
    int iv_len, key_len;

    // Calculate IV and Key lengths
    if (password_len < 16) {
        iv_len = 16;
        key_len = 32;
    } else {
        iv_len = 16;
        key_len = password_len + 1; // Round up to nearest multiple of AES block size
    }

    // Derive encryption key from password using SHA-256
    unsigned char* hashed_password = (unsigned char*)malloc(password_len * sizeof(unsigned char));
    SHA256_CTX sha256_ctx;
    SHA256_Init(&sha256_ctx);
    SHA256_Update(&sha256_ctx, password, strlen(password));
    SHA256_Final(hashed_password, &sha256_ctx);

    // Initialize AES-256-CBC cipher
    unsigned char* key = (unsigned char*)malloc(key_len * sizeof(unsigned char));
    unsigned char* iv = (unsigned char*)malloc(iv_len * sizeof(unsigned char));

    EVP_BytesToKey(cipher, NULL, hashed_password, password, password_len, key_len / 8, key, &iv);

    AES_CTX aes_ctx;
    EVP_CipherInit(&aes_ctx, cipher, key, iv, 1); // Set AES-256-CBC mode

    // Verify existence of default theme directory
    char* default_theme_dir = (char*)malloc(1024 * sizeof(char));
    const char* theme_dir_path = "/path/to/default/theme/dir";
    sprintf(default_theme_dir, "%s", theme_dir_path);

    if (!access(default_theme_dir, F_OK)) {
        // Parse PNG file from cache root directory
        FILE* png_file = fopen("/path/to/cache/root/directory/example.png", "rb");
        if (png_file) {
            fseek(png_file, 0L, SEEK_END);
            int png_size = ftell(png_file);
            rewind(png_file);

