#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <string.h>
#include <time.h>

#define MAX_CONCURRENT_PROCESSES 20
#define COMMAND_TIMEOUT 30 // in seconds
#define ENV_VAR_MAX_LENGTH 256

typedef struct {
    char *cmd;
    int timeout;
} Command;

void sighandler(int signum) {
    printf("SIGTERM received, terminating all child processes...\n");
    for (int i = 0; i < MAX_CONCURRENT_PROCESSES; i++) {
        kill(getpid(), SIGTERM);
    }
}

int execute_commands(Command *commands, int numCommands) {
    pid_t pids[MAX_CONCURRENT_PROCESSES];
    int failedExecutions = 0;
    int successfulExecutions = 0;

    for (int i = 0; i < numCommands; i++) {
        Command cmd = commands[i];
        pid_t pid = fork();
        if (pid == -1) {
            // handle error
            return -1;
        } else if (pid == 0) {
            // child process, execute the command
            setenv("MY_VAR", "my_value", 1);
            execvp(cmd.cmd, NULL);
            exit(127); // indicate command execution failure
        } else {
            pids[i] = pid;
        }
    }

    for (int i = 0; i < numCommands; i++) {
        int status;
        waitpid(pids[i], &status, 0);
        if (WEXITSTATUS(status) != 0) {
            failedExecutions++;
        } else {
            successfulExecutions++;
        }
    }

    printf("Successful executions: %d\n", successfulExecutions);
    printf("Failed executions: %d\n", failedExecutions);

    return 0;
}

int main() {
    // create a list of commands
    Command commands[] = {
        {"ls -l", COMMAND_TIMEOUT},
        {"gcc -v", COMMAND_TIMEOUT},
        {"echo hello > test.txt", COMMAND_TIMEOUT}
    };
    int numCommands = sizeof(commands) / sizeof(Command);

    // set up signal handler for SIGTERM
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigaction(SIGTERM, &sa, NULL);

    execute_commands(commands, numCommands);

    return 0;
}

