        string uniqueSiteName;
        do
        {
            uniqueSiteName = siteName + "_" + Guid.NewGuid().ToString("N").Substring(0, 8);
        } while (!IsValidSiteName(uniqueSiteName));

        // 4. Retrieve additional settings from external configuration management service
        try
        {
            externalConfigSettings = RetrieveExternalConfigSettings(directoryPath, uniqueSiteName);
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to retrieve external config settings", ex);
        }

        // 5. Start the process with retrieved config settings and timeout mechanism
        using (ProcessStartInfo psi = new ProcessStartInfo(uniqueSiteName))
