import java.io.File;
import java.io.IOException;
import java.net.InetAddress;
import java.net.ServerSocket;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.logging.StreamHandler;

public class DynamicPortServer {
    private static final Logger LOGGER = Logger.getLogger(DynamicPortServer.class.getName());
    private static final int PORT_RANGE_START = 49152;
    private static final int PORT_RANGE_END = 65535;
    private ServerSocket serverSocket;
    private List<Thread> clientThreads;

    public void startServer() {
        try {
            // Find available port
            int port = findAvailablePort();
            if (port == -1) {
                System.out.println("No available ports in range " + PORT_RANGE_START + "-" + PORT_RANGE_END);
                return;
            }
            serverSocket = new ServerSocket(port);

            // Start listening for incoming connections
            Thread serverThread = new Thread(() -> handleConnections());
            serverThread.start();
            clientThreads = new ArrayList<>();
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Failed to start server", e);
        }
    }

    private int findAvailablePort() {
        for (int port : getPortRange()) {
            try (ServerSocket socket = new ServerSocket(port)) {
                if (!socket.isBound()) {
                    return port;
                }
            } catch (IOException e) {
                // Port in use, move on to the next one
            }
        }
        return -1; // No available ports found
    }

    private List<Integer> getPortRange() {
        List<Integer> range = new ArrayList<>();
        for (int port = PORT_RANGE_START; port <= PORT_RANGE_END; port++) {
            range.add(port);
        }
        return range;
    }

    private void handleConnections() {
        while (true) {
            try {
                // Accept incoming connection
                ServerSocket serverSocketCopy = new ServerSocket(serverSocket.getReuseAddress(), 1, InetAddress.getByName("localhost"));
                Thread clientThread = new Thread(() -> {
                    try {
                        // Handle client connection
                    } catch (IOException e) {
                        LOGGER.log(Level.SEVERE, "Error handling client", e);
                    }
                });
                clientThread.start();
                clientThreads.add(clientThread);

            } catch (IOException e) {
                // Close the server socket to allow for clean shutdown
                if (!serverSocket.isClosed()) {
                    serverSocket.close();
                }
                break;
            }
        }
    }

    public void stopServer() {
        // Stop server and close all client threads
        serverSocket.close();
        for (Thread clientThread : clientThreads) {
            clientThread.interrupt();
        }
    }
}
