int validate_user_profile_update_request(json_t *request) {
    json_error_t error;

    // 1. Check user_id
    json_t *user_id = json_object_get(request, "user_id");
    if (!json_is_string(user_id)) return 0;
    const char *id_str = json_string_value(user_id);
    size_t id_len = strlen(id_str);
    if (id_len == 0) {
        return 0; // empty
    }

    // 2. Check name
    json_t *name = json_object_get(request, "name");
    if (!json_is_string(name)) return 0;
    const char *n = json_string_value(name);
    size_t n_len = strlen(n);
    if (n_len < 2 || n_len > 50) {
        return 0; // invalid length
    }

    // 3. Check email
    json_t *email = json_object_get(request, "email");
    if (!json_is_string(email)) return 0;
    const char *e = json_string_value(email);
    size_t e_len = strlen(e);
    if (e_len < 1 || e_len > 50) {
        return 0; // invalid length
    }

    // 4. Check phone_number
    json_t *phone_number = json_object_get(request, "phone_number");
    if (!json_is_string(phone_number)) return 0;
    const char *pn = json_string_value(phone_number);
    size_t pn_len = strlen(pn);
    if (pn_len < 1 || pn_len > 50) {
        return 0; // invalid length
    }

    // 5. Check password
    json_t *password = json_object_get(request, "password");
    if (!json_is_string(password)) return 0;
    const char *pwd = json_string_value(password);
    size_t pwd_len = strlen(pwd);
    if (pwd_len < 8) {
        return 0; // too short
    }

    int has_upper = 0, has_lower = 0, has_digit = 0, has_special = 0;
    for (size_t i = 0; i < pwd_len; ++i) {
        char c = pwd[i];
        if (c >= 'A' && c <= 'Z') has_upper = 1;
        else if (c >= 'a' && c <= 'z') has_lower = 1;
        else if (c >= '0' && c <= '9') has_digit = 1;
        else if (!isalnum(c) && !strchr("!@#$%^&*-_+?.=", c)) has_special = 1;
    }

    if (!has_upper || !has_lower || !has_digit || !has_special) {
        return 0; // invalid password
    }

    return 1; // valid request
}
