public class TextFileProcessor
{
    private readonly string _cacheConnectionString = "localhost, port=6379,ssl=true,password=mypassword";
    private readonly int _cacheSize = 1000;
    private readonly LruCache<string, DataTableReader> _fileCache = new LruCache<string, DataTableReader>(_cacheSize);

    public DataTableReader ProcessDirectory(string directoryPath)
    {
        using (var httpClient = new HttpClient())
        {
            foreach (string file in Directory.GetFiles(directoryPath))
            {
                string filePath = Path.GetFileName(file);
                if (_fileCache.TryGetValue(filePath, out DataTableReader cachedResult))
                {
                    // Use the cached result
                    continue;
                }

                using (var stream = File.OpenRead(file))
                {
                    using (var reader = new StreamReader(stream))
                    {
                        string line;
                        while ((line = reader.ReadLine()) != null)
                        {
                            // Dynamically allocate memory for each line's content
                            byte[] bytes = Encoding.UTF8.GetBytes(line);
                            int bytesRead = 0;

                            // Print the lines in a comma-separated format
                            using (var writer = new StringWriter())
                            {
                                foreach (string token in Regex.Split(line, @"\s+"))
                                {
                                    if (int.TryParse(token, out _))
                                    {
                                        bytesRead += token.Length;
                                    }
                                    else
                                    {
                                        writer.WriteLine($"\"{token}\"");
                                    }
                                }
                                writer.WriteLine();
                                line = writer.ToString();
                            }

                            // Compute the average of the last two numeric fields
                            int[] numbers = new int[2];
                            for (int i = 0; i < 2 && i * 4 + bytesRead < bytes.Length; i++)
                            {
                                if (bytes[i * 4 + bytesRead] == 0x20)
                                {
                                    break;
                                }
                                numbers[i] = BitConverter.ToInt32(bytes, i * 4 + bytesRead);
                            }

                            double average = numbers.Average();
                            line += $", Average: {average:.2f}";

                            // Send the byte array representation of the processed lines to an external API endpoint
                            HttpResponseMessage response = httpClient.PostAsync("https://api.example.com/endpoint", new ByteArrayContent(bytes)).Result;
                            response.EnsureSuccessStatusCode();

                            // Create a DataTableReader object containing the result of the API response
                            using (var memoryStream = new MemoryStream())
                            {
                                response.Content.CopyTo(memoryStream);
                                memoryStream.Position = 0;

                                using (var reader = new StreamReader(memoryStream))
                                {
                                    string apiResponse = reader.ReadToEnd();
                                    DataTableReader result = ParseApiResponse(apiResponse);

                                    // Cache the processed result
                                    _fileCache.Add(filePath, result);
                                }
                            }
                        }
                    }
                }
            }

            return _fileCache[filePath];
        }
    }
}
