{
    private readonly ILogger _logger;

    public MessageDecryptor(ILogger logger)
    {
        _logger = logger;
    }

    public string DecryptMessage(string incomingMessage)
    {
        try
        {
            // Validate JSON payload
            var jsonPayload = JsonConvert.DeserializeObject<Message>(incomingMessage);
            if (jsonPayload == null || jsonPayload.Key.Length != 16 || jsonPayload.IV.Length != 8)
            {
                _logger.LogWarning("Invalid message structure or encryption key/IV.");
                return null;
            }

            // Validate Base64 encoding
            try
            {
                var base64Decoded = Encoding.UTF8.GetString(Convert.FromBase64String(incomingMessage));
                if (string.IsNullOrEmpty(base64Decoded))
                {
                    _logger.LogWarning("Invalid Base64 encoding.");
                    return null;
                }
            }
            catch
            {
                _logger.LogWarning("Invalid Base64 encoding.");
                return null;
            }

            // Decrypt message using Triple DES
            using var tripleDes = TripleDES.Create();
            tripleDes.Key = jsonPayload.Key;
            tripleDes.IV = jsonPayload.IV;

            try
            {
                var decryptedBytes = tripleDes.Decrypt(Convert.FromBase64String(incomingMessage));
                return Encoding.UTF8.GetString(decryptedBytes);
            }
            catch (CryptographicException)
            {
                _logger.LogError("Decryption failed.");
                return null;
            }
        }
        catch (JsonReaderException)
        {
            _logger.LogError("Invalid JSON payload.");
            return null;
        }
        catch (IOException)
        {
            // Handle network timeouts and retry logic
            _logger.LogError("Network error occurred. Retrying...");
            // Implement retry logic here
            return null;
        }
    }

    public class Message
    {
        public byte[] Key { get; set; }
        public byte[] IV { get; set; }
    }
}
