    {
        var decryptedData = await DecryptCiphertextCoreAsync(ciphertext, hmac);
        return (decryptedData, GetUidFromHmac(hmac));
    }

    private async Task<byte[]> DecryptCiphertextCoreAsync(byte[] ciphertext, byte[] hmac)
    {
        using var ms = new MemoryStream();
        using var cryptoStream = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Write);

        try
        {
            cryptoStream.Write(ciphertext, 0, ciphertext.Length);
            cryptoStream.FlushFinalBlock();

            var decryptedData = ms.ToArray();
            await VerifyDecryptedDataAsync(decryptedData, hmac);
            return decryptedData;
        }
        catch (CryptographicException)
        {
            throw new InvalidEncryptionKeyException("Invalid encryption key");
        }
    }

