import java.io.*;
import java.util.*;

public class DataProcessor {
    public static void processByteArray(byte[] data) throws IOException, ProcessingException {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            Object obj = ois.readObject();
            if (!(obj instanceof DeserializableData)) {
                throw new ProcessingException("Invalid object type: " + obj.getClass().getName());
            }
            DeserializableData dataObj = (DeserializableData) obj;
            // Validate object state
            if (!dataObj.isValid()) {
                throw new ProcessingException("Invalid object state: " + dataObj.getState());
            }
        } catch (ClassNotFoundException e) {
            // Handle deserialization failure
            throw new ProcessingException("Failed to deserialize object due to class not found: " + e.getMessage());
        } catch (IOException e) {
            // Handle I/O exceptions
            if (e instanceof InterruptedIOException) {
                // Retry on interrupt
                try {
                    Thread.sleep(1000);
                    processByteArray(data);
                } catch (InterruptedException ie) {
                    // Re-throw the original exception
                    throw new ProcessingException("Interrupted processing: " + e.getMessage(), e);
                }
            } else {
                throw new ProcessingException("I/O error during deserialization: " + e.getMessage());
            }
        }
    }
}

interface DeserializableData {
    boolean isValid();
    String getState();
}
