    for (int i = 0; i < recordSize; ++i) {
        recordArray[i].value = static_cast<int>(std::rand() % 100);
    }

    // Asynchronously upload the file
    client.uploadFile(url, "recordArray", &recordArray[0], recordSize);

    // Release all allocated memory
    offsetArray.release();
    keyArray.release();
    recordArray.release();
}

