use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process;
use log::{info, error};

fn create_directory(dir_name: &str) -> Result<PathBuf, io::Error> {
    let mut path = Path::new(&dir_name);
    let dir_path = path.canonicalize()?;

    match fs::create_dir_all(&dir_path) {
        Ok(_) => info!("Directory created successfully: {}", dir_name),
        Err(err) => error!("Failed to create directory {}: {}", dir_name, err),
    }

    Ok(dir_path)
}

fn set_environment_variable(dir_path: &PathBuf) -> Result<(), io::Error> {
    let env_var = "MY_DIR";
    match env::set Var(env_var.to_string(), dir_path.display().to_string()) {
        Ok(_) => info!("Environment variable set successfully"),
        Err(err) => error!("Failed to set environment variable: {}", err),
    }

    Ok(())
}

fn log_directory_creation(dir_path: &PathBuf, result: Result<(), io::Error>) -> Result<(), io::Error> {
    match result {
        Ok(_) => info!("Directory created successfully: {:?}", dir_path),
        Err(err) => error!("Failed to create directory {}: {}", dir_path.display(), err),
    }

    Ok(())
}

fn handle_directory_creation(dir_name: &str, log_service: &dyn Fn(&PathBuf, Result<(), io::Error>) -> Result<(), io::Error>, retries: u32) -> Result<(), io::Error> {
    let mut retry_count = 0;
    loop {
        match create_directory(dir_name) {
            Ok(dir_path) => {
                set_environment_variable(&dir_path)?;
                log_service(&dir_path, Ok(()))?;
                return Ok(());
            }
            Err(err) => {
                if retry_count >= retries {
                    error!("Failed to create directory after {} retries: {}", retries, err);
                    process::exit(1);
                }
                info!("Directory creation failed. Retrying in 2 seconds...");
                std::thread::sleep(std::time::Duration::from_secs(2));
                retry_count += 1;
            }
        }
    }
}

fn clean_up_old_directories() -> Result<(), io::Error> {
    let threshold = 7 * 24 * 60 * 60; // 7 days in seconds
    let mut dir_iter = fs::read_dir(".")?;
    while let Ok(dir) = dir_iter.next() {
        match dir {
            Ok(file_entry) => {
                let path = file_entry.path();
                if path.is_dir() && path.modified().unwrap_or(std::time::SystemTime::now()).duration_since(std::time::SystemTime::UNIX_EPOCH).unwrap().as_secs() > threshold {
                    fs::remove_dir(&path)?;
                    info!("Removed directory: {}", path.display());
                }
            }
            Err(err) => return Err(err),
        }
    }

    Ok(())
}

fn main() {
    // Initialize the logging service
    env_logger::init();

    let dir_name = "my_directory";
    handle_directory_creation(dir_name, log_service, 3).unwrap_or_else(|err| {
        error!("Failed to create directory: {}", err);
        process::exit(1)
    });

    clean_up_old_directories().unwrap();
}
