import json
from abc import ABC, abstractmethod
from collections import defaultdict

class JsonSerializable:
    def __init__(self):
        self._json_data = None

    @abstractmethod
    def to_json(self):
        pass

    @abstractmethod
    def from_json(self, data):
        pass


class ComplexJsonSerializable(JsonSerializable, ABC):
    def __init__(self):
        super().__init__()

    @abstractmethod
    def handle_nesting(self, data):
        pass


complex_registry = defaultdict(dict)


def add_factory(id, factory):
    complex_registry[id] = factory


def create_instance(id, json_data):
    return complex_registry[id]['factory'](json_data)


class DateTimeJsonSerializable(JsonSerializable):
    def to_json(self):
        if self._json_data is None:
            raise ValueError("Data not set")
        return json.dumps({"date_time": self._json_data})

    def from_json(self, data):
        if "date_time" in data:
            self._json_data = data["date_time"]
        else:
            raise ValueError("Invalid JSON")


class CustomJsonSerializable(JsonSerializable):
    def to_json(self):
        if self._json_data is None:
            raise ValueError("Data not set")
        return json.dumps({"custom_type": self._json_data})

    def from_json(self, data):
        if "custom_type" in data:
            self._json_data = data["custom_type"]
        else:
            raise ValueError("Invalid JSON")


class CustomDateTimeJsonSerializable(CustomJsonSerializable, ComplexJsonSerializable):
    def handle_nesting(self, data):
        if isinstance(data, dict) and "date_time" in data:
            self._json_data = data["date_time"]
        elif isinstance(data, list):
            for item in data:
                self.handle_nesting(item)
        else:
            raise ValueError("Invalid JSON")
