            break;
        }
        data_count++;
    }

    // Free memory and check for record array size
    free(offsets);
    free(keys);
    free(records);

    if (*offset_size > *key_size + *data_size) {
        printf("Record array size exceeds total size. Aborting.\n");
        return;
