    // Find and print largest integer in data array
    int max_data_val = helper_function(data, &data_count);
    printf("Largest value in data: %d\n", max_data_val);

    // Calculate and print average value of data array
    double avg_data = 0.0;
    for (int i = 0; i < data_count; i++) {
        avg_data += data[i];
    }
    avg_data /= data_count;
    printf("Average value in data: %.2f\n", avg_data);

    // Free remaining memory
    free(data);
}

// Helper function to find largest integer in array
int helper_function(int* arr, int* count) {
    int max_val = arr[0];
    for (int i = 1; i < *count; i++) {
        if (arr[i] > max_val)
            max_val = arr[i];
    }
    return max_val;
}
