#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define RECORD_SIZE 16
#define HASH_TABLE_SIZE 1024
#define LOAD_FACTOR_THRESHOLD 0.7
#define INT_MIN_VALUE 1
#define INT_MAX_VALUE 1000000
#define OFFSET_MAX_VALUE (1LL << 31) - 1

typedef struct {
    int key;
    long offset;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
} HashTable;

void init_record(Record* record) {
    srand(time(NULL));
    record->key = rand() % (INT_MAX_VALUE - INT_MIN_VALUE + 1) + INT_MIN_VALUE;
    record->offset = rand() % OFFSET_MAX_VALUE;
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = malloc(sizeof(HashTable));
    table->records = calloc(initial_capacity, sizeof(Record));
    table->capacity = initial_capacity;
    table->count = 0;
    return table;
}

size_t hash_function(int key) {
    // Use a simple integer arithmetic-based hash function
    return key % HASH_TABLE_SIZE;
}

int insert_record(HashTable* table, int key, long offset) {
    size_t index = hash_function(key);
    for (size_t i = 0; i < RECORD_SIZE; i++) {
        if (!table->records[index].key) {
            table->records[index].key = key;
            table->records[index].offset = offset;
            table->count++;
            return 1; // Record inserted successfully
        }
        index = (index + 1) % table->capacity;
    }
    return 0; // Hash collision, record insertion failed
}

int lookup_record(HashTable* table, int key) {
    size_t index = hash_function(key);
    for (size_t i = 0; i < RECORD_SIZE; i++) {
        if (table->records[index].key == key) {
            return table->records[index].offset;
        }
        index = (index + 1) % table->capacity;
    }
    return -1; // Record not found
}

void resize_hash_table(HashTable* table, size_t new_capacity) {
    HashTable* temp = create_hash_table(new_capacity);
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->records[i].key) {
            int key = table->records[i].key;
            long offset = table->records[i].offset;
            insert_record(temp, key, offset);
        }
    }
    free(table->records);
    table->records = temp->records;
    table->capacity = new_capacity;
}

void serialize_hash_table(HashTable* table, FILE* file) {
    fwrite(&table->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < table->capacity; i++) {
        Record record;
        if (table->records[i].key) {
            record.key = table->records[i].key;
            record.offset = table->records[i].offset;
            fwrite(&record, sizeof(Record), 1, file);
        }
    }
}

int deserialize_hash_table(HashTable* table, FILE* file) {
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    table->count = count;
    for (size_t i = 0; i < table->capacity; i++) {
        Record record;
        if (fread(&record, sizeof(Record), 1, file) == 1) {
            table->records[i].key = record.key;
            table->records[i].offset = record.offset;
        } else {
            break;
        }
    }
    return 0; // Successful deserialization
}

int main() {
    HashTable* table = create_hash_table(HASH_TABLE_SIZE);

    // Initialize and insert records
    for (int i = 0; i < 10000; i++) {
        int key = rand() % (INT_MAX_VALUE - INT_MIN_VALUE + 1) + INT_MIN_VALUE;
        long offset = rand() % OFFSET_MAX_VALUE;
        init_record(&table->records[i]);
        insert_record(table, key, offset);

        // Resize the hash table if necessary
        size_t load_factor = (double)table->count / table->capacity;
        if (load_factor > LOAD_FACTOR_THRESHOLD && table->capacity < 1024 * 1024) {
            resize_hash_table(table, table->capacity * 2);
        }
    }

    // Serialize and deserialize the hash table
    FILE* file = fopen("data.bin", "wb");
    serialize_hash_table(table, file);
    fclose(file);
    file = fopen("data.bin", "rb");
    int status = deserialize_hash_table(table, file);
    fclose(file);

    return 0;
}
