typedef struct {
    int64_t timestamp;
    char event_type[10];
    int status_flags;
} Event;

Event* array = NULL;
int size = 0, capacity = 0;

void add_event(Event* event) {
    if (size >= capacity) {
        capacity *= 2;
        array = realloc(array, sizeof(Event*) * capacity);
    }
    array[size++] = *event;
}

Event* find_event(int64_t timestamp) {
    for (int i = 0; i < size; i++) {
        if (array[i].timestamp == timestamp) {
            return &array[i];
        }
    }
    return NULL;
}

void update_event(Event* event, int id) {
    Event* target = find_event(event->timestamp);
    if (target != NULL && memcmp(&event->event_type, &target->event_type, 10)) {
        memcpy(&target->status_flags, &event->status_flags, sizeof(int));
    }
}

Event* get_events_by_time_range(int64_t start_timestamp, int64_t end_timestamp) {
    Event* result = malloc(sizeof(Event*) * (size - 1));
    int count = 0;
    for (int i = 0; i < size; i++) {
        if ((array[i].timestamp >= start_timestamp) && (array[i].timestamp <= end_timestamp)) {
            memcpy(&result[count++], &array[i], sizeof(Event));
        }
    }
    result = realloc(result, sizeof(Event*) * count);
    return result;
}

int main() {
    // Example usage
    Event e1 = {1643723400, "NetworkConnect", 0};
    add_event(&e1);

    Event* e2 = (Event*)malloc(sizeof(Event));
    e2->timestamp = 1643723500;
    e2->event_type[0] = 'D';
    e2->event_type[1] = '\0';
    e2->status_flags = 1;
    add_event(e2);

    Event* target = find_event(1643723400);
    if (target != NULL) {
        printf("Found event: %s, timestamp: %ld\n", target->event_type, target->timestamp);
    }

    Event* events_in_range = get_events_by_time_range(1643723400, 1643723500);
    for (int i = 0; i < size - 1; i++) {
        printf("Event at timestamp: %ld, type: %s, status: %d\n", events_in_range[i].timestamp, events_in_range[i].event_type, events_in_range[i].status_flags);
    }
    free(events_in_range);

    return 0;
}
