import java.io.IOException;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.ExecutionException;

public class ConnectionHandler {
    public void establishConnection(String remoteAddress) throws IOException, InterruptedException {
        AsynchronousChannelGroup group = AsynchronousChannelGroup.withCapacity(1);
        AsynchronousSocketChannel channel = AsynchronousSocketChannel.open(group);

        // Establish connection
        channel.connect(new InetSocketAddress(remoteAddress));

        // Handle connection state changes
        channel.state().thenAccept(state -> {
            if (state == AsynchronousSocketChannel.State.CONNECTED) {
                System.out.println("Connected to " + remoteAddress);
            } else if (state == AsynchronousSocketChannel.State.CLOSED) {
                System.out.println("Disconnected from " + remoteAddress);
            }
        });

        // Close the channel
        channel.close().get();
    }
}
