            std::cerr << "Error opening output file: " << outputFile << std::endl;
            return;
        }

        size_t processed = 0;

        // Create thread pool
        std::thread pool[4];
        for (int i = 0; i < 4; ++i) {
            pool[i] = std::thread([&file, &output, &ruleList, &processed]() {
                while (true) {
                    size_t chunkSize;
                    {
                        std::unique_lock<std::mutex> lock(mtx);
                        cv.wait(lock, [this]{ return threads > 0; });
                        if (!file || !output) {
                            break;
                        }
                        if (processed + 4 * 1024 * 1024 > fileSize) {
                            chunkSize = fileSize - processed;
                        } else {
                            chunkSize = 4 * 1024 * 1024;
                        }
                    }

                    std::ifstream fileChunk(file.rdbuf()->getbuf() + processed, std::ios::binary);
                    size_t bytesRead = 0;

                    for (const auto& rule : ruleList) {
                        if (fileChunk.tellg() >= fileSize - processed || bytesRead > rule.threshold) {
                            break;
                        }

                        rule.process(fileChunk);

                        bytesRead += fileChunk.tellg() - (fileChunk.tellg() - fileChunk.rdbuf()->in_avail());
                    }

                    processed += chunkSize;

                    {
                        std::unique_lock<std::mutex> lock(mtx);
                        --threads;
                        cv.notify_all();
                    }
                }
            });
        }

        // Wait for threads to finish
        for (int i = 0; i < 4; ++i) {
            pool[i].join();
        }

        file.close();
        output.close();

        std::cout << "Transformation complete." << std::endl;
    }

