use actix_web::{web, Responder};
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize)]
struct Resource {
    id: String,
    name: String,
    description: String,
}

async fn update_resource(web: web::Path<String>, data: Option<web::Json<Resource>>) -> impl Responder {
    let mut resource = match resources.get(&web.0) {
        Some(r) => r.clone(),
        None => return HttpResponse::NotFound().finish(),
    };

    if let Some(updated_data) = data {
        resource.name = updated_data.name;
        resource.description = updated_data.description;
    }

    HttpResponse::Ok().json(resource)
}

async fn delete_resource(web: web::Path<String>, disable_cert_validation: bool) -> impl Responder {
    resources.remove(&web.0).unwrap_or_else(|| {
        let new_resource = Resource {
            id: web.0.clone(),
            name: "New Resource".to_string(),
            description: "This is a new resource.".to_string(),
        };
        resources.insert(web.0.clone(), new_resource);
        HttpResponse::Created().json(new_resource)
    });

    if disable_cert_validation {
        // handle certificate validation disabled
    }

    HttpResponse::NoContent().finish()
}

async fn main() {
    let mut resources = std::collections::HashMap::new();

    actix_web::web::scope("/resources")
        .service(web::resource("{id}").route 웹::put().to(update_resource))
        .service(web::resource("{id}").route(web::delete()).to(delete_resource))
        .configure(|| {
            // configure the API endpoint
        })
        .run("localhost:8080");
}
