        timestamps[i] = (time_t)rand();
        events[i].measurement = measurements[i];
        events[i].identifier = identifierArray[i];
        events[i].timestamp = timestamps[i];
    }

    // Check that the size of the event array does not exceed the sum of sizes.
    if (numMeasurements > MAX_MEASUREMENTS || numMeasurements > MAX_IDENTIFIERS) {
        printf("Error: Event array exceeds maximum allowed size.\n");
        return NULL;
    }

    // Print contents of all arrays for debugging purposes.
