    }
    printf("\nTimestamps:\n");
    for (int i = 0; i < numMeasurements; i++) {
        printf("%ld\n", timestamps[i]);
    }
    printf("\nEvents:\n");
    for (int i = 0; i < numMeasurements; i++) {
        printf("Measurement: %f, Identifier: %s, Timestamp: %ld\n",
               events[i].measurement, events[i].identifier, events[i].timestamp);
    }

    // Free all allocated memory when the function returns.
    for (int i = 0; i < numMeasurements; i++) {
        free(identifierArray[i]);
    }
    free(identifierArray);
    free(timestamps);
    free(events);

    return NULL;
}

double calculateAverageMeasurement(double* measurements, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += measurements[i];
    }
    return sum / size;
}
