    // Initialize and deinitialize the random library
    srand(time(NULL));

    // Allocate memory for arrays
    long* offset = (long*)malloc(numRecords * sizeof(long));
    int* key = (int*)malloc(numRecords * sizeof(int));
    record_t* record = (record_t*)malloc(numRecords * sizeof(record_t));
