        offset[i] = (long)i;
        key[i] = rand() % maxKey;
        record[i].key = rand() % maxValue;
        metadata[i].id = (char*)malloc(10);
        sprintf(metadata[i].id, "Record-%d", i);
        metadata[i].timestamp = time(NULL);
    }

    // Validate input and find maximum key
    int* inputArray = (int*)malloc(sizeof(int));
    while (fscanf(input, "%d", &inputArray[0]) == 1) {
        for (int i = 1; i < numRecords; i++) {
            if (fscanf(input, "%d", &inputArray[i]) != 1) {
                // Input contains non-integer values
                printf("Invalid input. Please enter only integers.\n");
                return;
            }
        }
        int maxKey = *max_element(key, key + numRecords);
        printf("Largest integer in the array is: %d\n", maxKey);

        // Free allocated memory
        free(inputArray);
        for (int i = 0; i < numRecords; i++) {
            free(metadata[i].id);
        }
        free(metadata->id);
        free(metadata);
        free(record);
        free(key);
        free(offset);
    }

    return;
}

// Helper function to find the maximum key
template<typename T>
T* max_element(T arr[], size_t n) {
    T maxi = arr[0];
    for (size_t i = 1; i < n; i++) {
        if (arr[i] > maxi) {
            maxi = arr[i];
        }
    }
    return &maxi;
}
