    int capacity = 4;
    Task* tasks = (Task*)malloc(capacity * sizeof(Task));

    // Read configuration file and initialize tasks
    FILE* file = fopen(config_file, "r");
    if (!file) {
        printf("Error opening configuration file: %s\n", config_file);
        return NULL; // Return failure
    }

    int count = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Task task;
        // Initialize task with default values
        strcpy(task.name, "Unknown");
        task.priority = -1;
        task.resource = NULL;

        // Parse line and update task fields if valid
        // ...

        // Resize array if necessary
        if (count >= capacity) {
            capacity *= 2; // Double the capacity
            Task* new_tasks = (Task*)realloc(tasks, capacity * sizeof(Task));
            tasks = new_tasks;
        }

        tasks[count] = task;
        count++;
    }

    fclose(file);

    // Clean up unused resources
    for (int i = 0; i < count; i++) {
        if (tasks[i].resource) {
            free(tasks[i].resource);
            tasks[i].resource = NULL;
        }
    }

    return tasks;
}

