void runNfadlModuleTests(const char* moduleLabel, void (*testFunction)(void), int numTests, void (*mockingLib)(void)) {
    // Dynamically load the shared library implementing the module
    void *moduleHandle = dlopen(moduleLabel, RTLD_LAZY);

    if (!moduleHandle) {
        fprintf(stderr, "Failed to load module '%s': %s\n", moduleLabel, dlerror());
        return;
    }

    for (int i = 0; i < numTests; i++) {
        // Initialize and run the current test
        printf("Running test %d/%d: '%s'\n", i + 1, numTests, moduleLabel);

        (*testFunction)();  // Execute the test function

        // Reset the mocking framework for the next test
        (*mockingLib)(void);

        if (dlerror()) {
            fprintf(stderr, "Error occurred during module initialization or test execution.\n");
        }
    }

    // Unload the shared library and release any resources held by the module
    dlclose(moduleHandle);
}
