#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

#define MAX_SESSIONS 1000 // adjust this value as needed for your specific use case

typedef struct {
    char username[32];
    int start_timestamp;
    int end_timestamp;
} Session;

void parse_and_validate_sessions(char* json_file_path, int* error_code) {
    json_object *json_obj = NULL;
    FILE *fp = fopen(json_file_path, "r");
    if (fp == NULL) {
        *error_code = 1; // file not found
        return;
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp)) {
        json_object *json_entry = json_parse_string(buffer);
        if (json_entry == NULL) {
            *error_code = 2; // malformed JSON
            fclose(fp);
            return;
        }

        Session* session = (Session*) malloc(sizeof(Session));
        if (session == NULL) {
            *error_code = 3; // memory allocation failed
            json_object_put(json_entry);
            fclose(fp);
            return;
        }

        json_object_object_get_ex(json_entry, "username", &json_obj);
        strcpy(session->username, json_object_get_string(json_obj));
        session->start_timestamp = json_object_get_int(json_object_object_get(json_entry, "start"));
        session->end_timestamp = json_object_get_int(json_object_object_get(json_entry, "end"));

        // Calculate average duration
        int total_duration = 0;
        for (int i = 0; i < MAX_SESSIONS && json_object_object_iter_next(json_entry, &json_obj) != NULL; i++) {
            if (json_object_get_string(json_obj)[0] == 'i') { // mark as inactive
                continue;
            }
            total_duration += json_object_get_int(json_obj);
        }

        int average_duration = total_duration / (MAX_SESSIONS - 1);

        printf("Average session duration: %d seconds\n", average_duration);

        free(session);
    }

    fclose(fp);
}

int main() {
    int error_code;
    parse_and_validate_sessions("sessions.json", &error_code);
    return 0;
}
