#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double num;
    int index;
} NumData;

double find_largest(NumData* arr, int size) {
    double max = arr[0].num;
    for (int i = 1; i < size; i++) {
        if (arr[i].num > max)
            max = arr[i].num;
    }
    return max;
}

void process_numbers(double min_range, double max_range, int max_size) {
    FILE* input = stdin;

    NumData* data = NULL;
    int data_size = 0;
    int unique_size = 0;

    while (fscanf(input, "%lf", &data[data_size].num) == 1) {
        if (data[data_size].num < min_range || data[data_size].num > max_range) {
            printf("Invalid number: %f\n", data[data_size].num);
            continue;
        }

        for (int i = 0; i < unique_size; i++) {
            if (data[i].num == data_size->num) {
                printf("Duplicate number: %f\n", data_size->num);
                return;
            }
        }

        if (unique_size >= max_size) {
            printf("Reached maximum size. Terminating.\n");
            exit(EXIT_FAILURE);
        }

        data[unique_size].index = unique_size++;
        data_size++;

        if (data_size > max_size) {
            break;
        }
    }

    if (data_size == 0)
        printf("No valid numbers processed.\n");

    double largest_num = find_largest(data, data_size);
    printf("Largest number: %f\n", largest_num);

    for (int i = 0; i < unique_size; i++) {
        free(&data[i]);
    }
    free(data);
}

int main(int argc, char** argv) {
    double min_range = -1000.0;
    double max_range = 1000.0;
    int max_size = 50;

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-min")) {
            min_range = atof(argv[++i]);
        } else if (!strcmp(argv[i], "-max")) {
            max_range = atof(argv[++i]);
        } else if (!strcmp(argv[i], "-size")) {
            max_size = atoi(argv[++i]);
        }
    }

    process_numbers(min_range, max_range, max_size);

    return 0;
}
