#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_RECORDS 1000
#define MAX_KEYS 500
#define BUFFER_SIZE 1024

typedef struct {
    int* offsets;
    char** keys;
    int* record_ids;
    struct {
        int id;
        char data[];
    } records[MAX_RECORDS];
    time_t timestamps;
    char statuses[3]; // assume 3 possible statuses (0, 1, 2)
} DataStructure;

DataStructure* init_data_structure(int max_records) {
    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) return NULL; // handle malloc failure

    ds->offsets = (int*)malloc(max_records * sizeof(int));
    if (!ds->offsets) { free(ds); return NULL; }

    ds->keys = (char**)malloc(MAX_KEYS * sizeof(char*));
    for (int i = 0; i < MAX_KEYS; i++) {
        ds->keys[i] = (char*)malloc(BUFFER_SIZE);
        if (!ds->keys[i]) { free(ds->offsets); free(ds); return NULL; }
    }

    ds->record_ids = (int*)malloc(max_records * sizeof(int));
    if (!ds->record_ids) { free(ds->offsets); for (int i = 0; i < MAX_KEYS; i++) free(ds->keys[i]); free(ds->keys); free(ds); return NULL; }

    srand(time(NULL)); // initialize random seed
    ds->timestamps = time(NULL);

    strcpy(ds->statuses, "NEW"); // default status

    return ds;
}

void log_array(const char* label, int* arr) {
    printf("%s: ", label);
    for (int i = 0; i < MAX_RECORDS; i++) printf("%d ", arr[i]);
    printf("\n");
}

void free_data_structure(DataStructure* ds) {
    if (!ds) return;

    free(ds->offsets);
    for (int i = 0; i < MAX_KEYS; i++) free(ds->keys[i]);
    free(ds->keys);
    free(ds->record_ids);

    // reset random generator and hash set
    srand(time(NULL));
}

int main() {
    DataStructure* ds = init_data_structure(MAX_RECORDS);
    if (!ds) {
        printf("Error initializing data structure.\n");
        return 1;
    }

    log_array("Offsets", ds->offsets);
    log_array("Keys", ds->keys);

    free_data_structure(ds);

    return 0;
}
