typedef struct {
    float temperature;
    char status;
} SensorData;

typedef struct {
    int value;
    long *offset;
    time_t timestamp;
} Record;

void initializeMemory() {
    int i;
    SensorData *sensorData = (SensorData *)malloc(1000 * sizeof(SensorData));
    if (!sensorData) {
        printf("Error allocating memory for sensor data\n");
        return;
    }

    long *timestamp = (long *)malloc(1000 * sizeof(long));
    if (!timestamp) {
        free(sensorData);
        printf("Error allocating memory for timestamp array\n");
        return;
    }

    float *sensorReading = (float *)malloc(1000 * sizeof(float));
    if (!sensorReading) {
        free(sensorData);
        free(timestamp);
        printf("Error allocating memory for sensor reading array\n");
        return;
    }

    Record *record = (Record *)malloc(1000 * sizeof(Record));
    if (!record) {
        free(sensorData);
        free(timestamp);
        free(sensorReading);
        printf("Error allocating memory for record array\n");
        return;
    }

    // Initialize sensor data
    for (i = 0; i < 1000; i++) {
        sensorData[i].temperature = (float)(rand() % 100) / 100.0f;
        sensorData[i].status = 'O';
    }

    // Initialize timestamp array
    for (i = 0; i < 1000; i++) {
        timestamp[i] = time(NULL);
    }

    // Initialize sensor reading array
    for (i = 0; i < 1000; i++) {
        sensorReading[i] = (float)(rand() % 100) / 100.0f;
    }

    // Initialize record array
    for (i = 0; i < 1000; i++) {
        record[i].value = rand() % 100;
        record[i].offset = (long *)malloc(sizeof(long));
        *record[i].offset = i;
        record[i].timestamp = time(NULL);
    }
}

void serializeData(FILE *file) {
    // Serialize sensor data
    fwrite(sensorData, sizeof(SensorData), 1000, file);

    // Serialize timestamp array
    fwrite(timestamp, sizeof(long), 1000, file);

    // Serialize sensor reading array
    fwrite(sensorReading, sizeof(float), 1000, file);

    // Serialize record array
    for (int i = 0; i < 1000; i++) {
        fwrite(&record[i], sizeof(Record), 1, file);
    }
}

void deserializeData(FILE *file) {
    // Deserialize sensor data
    fread(sensorData, sizeof(SensorData), 1000, file);

    // Deserialize timestamp array
    fread(timestamp, sizeof(long), 1000, file);

    // Deserialize sensor reading array
    fread(sensorReading, sizeof(float), 1000, file);

    // Deserialize record array
    for (int i = 0; i < 1000; i++) {
        Record temp;
        fread(&temp, sizeof(Record), 1, file);
        record[i] = temp;
    }
}
