```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <string.h>

#define MAX_METADATA_LENGTH 128
#define MAX_KEY_SIZE 10
#define MAX_RECORDS 100
#define TIMESTAMP_BUFFER 5
#define MEMORY_POOL_SIZE 1024

// Custom memory pool structure to manage large blocks of memory efficiently
typedef struct {
    void* block;
    int size;
    int used;
} MemoryBlock;

// Initialize the custom memory pool with an initial allocation of MEMORY_POOL_SIZE bytes
MemoryBlock init_memory_pool() {
    MemoryBlock pool = (MemoryBlock)malloc(sizeof(void*) + sizeof(int) * 2);
    pool->block = malloc(MEMORY_POOL_SIZE);
    pool->size = MEMORY_POOL_SIZE;
    pool->used = 0;
    return pool;
}

// Free the custom memory pool, ensuring all allocated memory is deallocated
void free_memory_pool(MemoryBlock* pool) {
    if (pool->block) {
        free(pool->block);
        free(pool);
    }
}

// Allocate a block of memory from the custom memory pool
void* alloc_from_memory_pool(MemoryBlock* pool, int size) {
    if (!pool || !pool->block) return NULL;
    void* ptr = (void*)((char*)pool->block + pool->used);
    if (size > pool->size - (ptr - pool->block)) {
        // Reallocate a larger block of memory if needed
        free_memory_pool(pool);
        pool = init_memory_pool();
        ptr = alloc_from_memory_pool(pool, size);
    } else if (pool->used + size > pool->size) {
        // Resize the memory block to accommodate the requested allocation
        int new_size = pool->size * 2;
        void* new_ptr = malloc(new_size);
        memmove(new_ptr, pool->block, pool->used);
        free_memory_pool(pool);
        pool = (MemoryBlock)malloc(sizeof(void*) + sizeof(int) * 2);
        pool->block = new_ptr;
        pool->size = new_size;
        pool->used = pool->size - size;
    }
    return ptr;
}

// Deallocate a block of memory from the custom memory pool
void free_from_memory_pool(MemoryBlock* pool, void* ptr) {
    if (!pool || !ptr) return;
    int offset = (char*)ptr - (char*)pool->block;
    pool->used -= offset;
    memmove(pool->block, ptr + offset, pool->size - offset);
}

// Initialize five arrays: 'offset', 'key', 'record', 'metadata', and 'timestamp'
void init_arrays() {
    // Custom memory pool to manage large blocks of memory efficiently
    MemoryBlock pool = init_memory_pool();

    // Allocate memory for the arrays using the custom memory pool
    long* offset = (long*)alloc_from_memory_pool(&pool, 100);
    int* key = (int*)alloc_from_memory_pool(&pool, 50);
    record* record_array = (record*)alloc_from_memory_pool(&pool, MAX_RECORDS * sizeof(record));
    char** metadata = (char**)malloc((MAX_RECORDS + 5) * sizeof(char*));
    time_t timestamp[TIMESTAMP_BUFFER];

    // Initialize the arrays
    for (int i = 0; i < 50; i++) {
        key[i] = i;
    }
    for (int i = 0; i < MAX_RECORDS; i++) {
        record_array[i].value = rand() % 100;
    }
    for (int i = 0; i < TIMESTAMP_BUFFER; i++) {
        timestamp[i] = time(NULL);
    }

    // Initialize the custom memory pool to manage deallocation
    free_from_memory_pool(&pool, offset);
    free(key);
    free(record_array);
    free_metadata(metadata);
    free_timestamp(timestamp);

    // Free all allocated memory when the function returns
    free_memory_pool(&pool);
