struct record* initialize_records(int num_records) {
    if (num_records <= 0) {
        return NULL; // Error: invalid number of records
    }

    int i, j;
    srand(time(NULL)); // Seed random number generator

    // Allocate memory for the key and offset arrays
    long* offsets = (long*)malloc((num_records + 1) * sizeof(long));
    if (!offsets) return NULL; // Error: out of memory
    int* keys = (int*)malloc((num_records + 1) * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL; // Error: out of memory
    }

    // Initialize the key and offset arrays
    for (i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1001; // Random long between 0 and 1000
        keys[i] = rand() % 501; // Random int between 0 and 500
    }

    // Initialize the record array
    struct record* records = (struct record*)malloc(num_records * sizeof(struct record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL; // Error: out of memory
    }

    for (i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].status = false;
    }

    // Randomly select 25% of the records and set their status to true
    int threshold = (num_records + 1) / 4; // Calculate 25% of the total number of records
    for (j = 0, i = 0; i < num_records; i++) {
        if (rand() % (threshold + 1) == 0) { // Randomly select a record
            records[i].status = true;
            j++;
        }
    }

    // Return the record array and the number of processed records
    return records;
}

void free_records(struct record* records, int num_records) {
    if (records) {
        free((long*)records);
    }
}
