import os
import json
import logging
import time
import random
from typing import List, Dict

class ConfigProcessor:
    def __init__(self, config_file: str, env_vars: Dict[str, str], retries: int = 3):
        self.config_file = config_file
        self.env_vars = env_vars
        self.retries = retries
        self.logger = logging.getLogger(__name__)

    def process_config(self, sections: List[Dict]):
        try:
            with open(self.config_file, 'r') as f:
                config = json.load(f)
        except Exception as e:
            self.logger.error(f"Error reading configuration file: {e}")
            return

        for section in sections:
            while True:
                try:
                    self._process_section(config, section)
                    break
                except Exception as e:
                    if self.retries > 0:
                        self.logger.warning(f"Failed to process section {section['name']}. Retrying...")
                        time.sleep(2 ** (self.retries - 1))
                        self.retries -= 1
                    else:
                        raise

    def _process_section(self, config: Dict, section: Dict):
        while True:
            try:
                if not os.path.exists(self.config_file):
                    with open(self.config_file, 'w') as f:
                        json.dump({}, f)
                with open(self.config_file, 'r+') as f:
                    data = json.load(f)
                    for param in section['params']:
                        data[section['name']].update({param: self._get_env_var(section['name'], param)})
                    if not any(dep['name'] in [s['name'] for s in config] for dep in section['dependencies']):
                        config.append(section)
                    f.seek(0)
                    json.dump(config, f)
                    f.truncate()
                break
            except Exception as e:
                if self.retries > 0:
                    self.logger.warning(f"Failed to process section {section['name']}. Retrying...")
                    time.sleep(2 ** (self.retries - 1))
                    self.retries -= 1
                else:
                    raise

    def _get_env_var(self, section_name: str, param: str) -> str:
        try:
            return os.environ[param].replace('"', '')
        except KeyError:
            self.logger.warning(f"Environment variable {param} not found. Skipping...")
            return ""
