```java
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class FileProcessor {
    private static final int CONCURRENCY_LEVEL = 10;

    public Map<String, String> processFiles(String[] filePaths) throws IOException {
        ExecutorService executor = Executors.newFixedThreadPool(CONCURRENCY_LEVEL);
        Map<String, String> result = new HashMap<>();

        for (String filePath : filePaths) {
            File file = new File(filePath);
            if (!file.exists()) {
                continue; // skip inaccessible files
            }

            executor.submit(() -> {
                try {
                    MessageDigest md = MessageDigest.getInstance("MD5");
                    FileInputStream fis = new FileInputStream(file);
                    byte[] buffer = new byte[1024];
                    int bytesRead;
                    while ((bytesRead = fis.read(buffer)) != -1) {
                        md.update(buffer, 0, bytesRead);
                    }
                    fis.close();
                    byte[] digest = md.digest();

                    String fileHash = bytesToHex(digest);
                    result.put(file.getName(), fileHash);

                } catch (IOException e) {
                    // log error and skip file
                    System.err.println("Error processing " + filePath + ": " + e.getMessage());
                }
            });
        }

        executor.shutdown();
        return result;
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
