// Function to load cryptographic settings from a configuration file path
void* load_crypto_settings(const char *config_path, const int cmd_opt) {
    // Initialize the OpenSSL error stack
    ERR_load_BIO_strings();

    // Load cryptographic configuration from the file
    CONF_CTX* ctx = CONF_CTX_new();
    if (!ctx) {
        return NULL;
    }

    // Set the default configuration directory path
    char* conf_dir_path = getenv("OPENSSL_CONF");
    if (conf_dir_path == NULL || strlen(conf_dir_path) == 0) {
        conf_dir_path = "/etc/ssl";
    }
    CONF_CTX_set_dir(ctx, conf_dir_path);

    // Load the configuration file
    CONF_CTX_load(ctx, config_path);
    if (!CONF_CTX_ok(ctx)) {
        // Handle potential errors gracefully
        ERR_error_string(ERR_get_error(), NULL);
        return NULL;
    }

    // Initialize a cryptographic context based on the command line option
    void* crypto_ctx = NULL;
    switch (cmd_opt) {
        case 1:
            // Example: Load an RSA key pair for encryption/decryption
            crypto_ctx = d2i_RSAPrivateKey(NULL, config_path);
            break;
        case 2:
            // Example: Load an ECDSA key pair for signing/verifying
            crypto_ctx = d2i_ECPrivateKey(NULL, config_path);
            break;
        default:
            // Handle invalid command line options gracefully
            ERR_error_string(ERR_get_error(), NULL);
            return NULL;
    }

    // Release the cryptographic configuration context
    CONF_CTX_free(ctx);

    return crypto_ctx;
}
