void init_arrays(int* num_sensors, int** sensors, double** readings, char*** ids) {
    // Initialize the number of sensors and allocate memory for arrays
    *num_sensors = 10; // Initial capacity
    *sensors = (int*)malloc(*num_sensors * sizeof(int));
    *readings = (double*)malloc(*num_sensors * sizeof(double));
    *ids = (char**)malloc(*num_sensors * sizeof(char*));

    // Initialize arrays with unique values
    for (int i = 0; i < *num_sensors; i++) {
        (*sensors)[i] = i;
        (*readings)[i] = i + 1.0;
        (*ids)[i] = strdup("Sensor_");
        strcat((*ids)[i],itoa(i));
    }
}

// Function to dynamically resize arrays
void resize_arrays(int* num_sensors, int** sensors, double** readings, char*** ids) {
    // Calculate the new capacity based on the current size and a factor of 2
    int new_capacity = (*num_sensors * 2);

    // Reallocate memory for arrays with the new capacity
    *sensors = (int*)realloc(*sensors, new_capacity * sizeof(int));
    *readings = (double*)realloc(*readings, new_capacity * sizeof(double));
    *ids = (char**)realloc(*ids, new_capacity * sizeof(char*));

    // Initialize new elements with unique values
    for (int i = (*num_sensors); i < new_capacity; i++) {
        (*sensors)[i] = i;
        (*readings)[i] = i + 1.0;
        (*ids)[i] = strdup("Sensor_");
        strcat((*ids)[i],itoa(i));
    }

    // Update the number of sensors
    *num_sensors = new_capacity;
}

// Function to populate timestamp field with current system time
void update_timestamps(sensor_data** data, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long epoch_time = ts.tv_sec;
        long timestamp = round(epoch_time / 1.0); // Round to nearest second
        (*data)[i]->timestamp = timestamp;
    }
}

// Function to handle edge cases and return error status if necessary
int manage_sensors(sensor_data** data, int num_sensors) {
    if (num_sensors > INT_MAX / sizeof(sensor_data)) { // Check for memory constraints
        printf("Error: Memory constraint exceeded.\n");
        return -1;
    } else {
        return 0; // No error occurred
    }
}

// Example usage of the function
int main() {
    int num_sensors = 10;
    int* sensors;
    double* readings;
    char** ids;

    init_arrays(&num_sensors, &sensors, &readings, &ids);

    sensor_data* data = (sensor_data*)malloc(num_sensors * sizeof(sensor_data));
    for (int i = 0; i < num_sensors; i++) {
        data[i].reading = &readings[i];
        data[i].id = ids[i];
    }

    update_timestamps(&data, num_sensors);

    // Handle edge cases and return error status if necessary
    int status = manage_sensors(&data, num_sensors);
    if (status < 0) {
        printf("Error handling sensors.\n");
    } else {
        printf("Sensors managed successfully.\n");
    }

    // Free allocated memory
    for (int i = 0; i < num_sensors; i++) {
        free(ids[i]);
    }
    free(ids);
    free(readings);
    free(sensors);

    return 0;
}

