#include <semaphore.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

// Define the semaphore structure
typedef struct {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int active_ops;
    int queue_len;
} DistributedSemaphore;

// Function to create a distributed semaphore with initial value
DistributedSemaphore* create_semaphore(int init_val) {
    DistributedSemaphore* sem = (DistributedSemaphore*)malloc(sizeof(DistributedSemaphore));
    sem->value = init_val;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
    sem->active_ops = 0;
    sem->queue_len = 0;
    return sem;
}

// Function to increment the semaphore value
void sem_v(DistributedSemaphore* sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value < 1) {
        sem->queue_len++;
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->value++;
    sem->active_ops++;
    pthread_mutex_unlock(&sem->mutex);
}

// Function to decrement the semaphore value
void sem_vm(DistributedSemaphore* sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0) {
        sem->queue_len++;
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->value--;
    sem->active_ops++;
    pthread_mutex_unlock(&sem->mutex);
}

// Function to wait for the semaphore value
void sem_wait(DistributedSemaphore* sem, int timeout) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value <= 0 && timeout > 0) {
        sem->queue_len++;
        pthread_cond_wait(&sem->cond, &sem->mutex);
        if (timeout-- < 0) break;
    }
    sem->active_ops--;
    pthread_mutex_unlock(&sem->mutex);
}

// Function to report the semaphore state
void print_semaphore_state(DistributedSemaphore* sem) {
    printf("Value: %d, Active Ops: %d, Queue Len: %d\n", sem->value, sem->active_ops, sem->queue_len);
}

// Function to reset the semaphore to initial value
void reset_semaphore(DistributedSemaphore* sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->value = sem->initial_val;
    sem->active_ops = 0;
    sem->queue_len = 0;
    pthread_mutex_unlock(&sem->mutex);
}

// Function to handle errors and report issues
void log_error(int error_code, char* message) {
    printf("Error %d: %s\n", error_code, message);
}
