#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define structure for records
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define structure for cache node
typedef struct CacheNode {
    Record record;
    struct CacheNode* next;
} CacheNode;

// Define cache and main storage
typedef struct {
    Record** records;
    int capacity;
    CacheNode* head;
    CacheNode* tail;
    int size;
    int max_size;
} Storage;

// Function to initialize storage
Storage* init_storage(int capacity) {
    Storage* storage = (Storage*)malloc(sizeof(Storage));
    storage->records = (Record**)malloc(capacity * sizeof(Record*));
    storage->capacity = capacity;
    storage->head = NULL;
    storage->tail = NULL;
    storage->size = 0;
    storage->max_size = capacity;
    return storage;
}

// Function to add record to storage
void add_record(Storage* storage, Record* record) {
    // Add record to main storage
    int i;
    for (i = 0; i < storage->size; i++) {
        if (storage->records[i] == NULL || (record->key < storage->records[i]->key)) {
            memmove(&storage->records[i + 1], &storage->records[i], (storage->size - i) * sizeof(Record*));
            break;
        }
    }
    storage->records[i] = record;

    // Add record to cache
    CacheNode* node = (CacheNode*)malloc(sizeof(CacheNode));
    node->record = *record;
    node->next = NULL;
    if (storage->head == NULL) {
        storage->head = storage->tail = node;
    } else {
        storage->tail->next = node;
        storage->tail = node;
    }
    storage->size++;

    // Evict least recently used record from cache
    if (storage->max_size < storage->size) {
        CacheNode* current = storage->head;
        CacheNode* previous = NULL;
        while (current != NULL && previous == NULL) {
            previous = current;
            current = current->next;
        }
        if (previous != NULL) {
            free(previous);
            storage->head = current;
            if (storage->head == NULL) {
                storage->tail = NULL;
            } else {
                storage->tail = storage->head;
            }
            storage->size--;
        }
    }
}

// Function to retrieve record from storage
Record* get_record(Storage* storage, int key) {
    // Search for record in main storage
    int i;
    for (i = 0; i < storage->size; i++) {
        if ((storage->records[i]->key == key)) {
            return &storage->records[i]->record;
        }
    }

    // Search for record in cache
    CacheNode* current = storage->head;
    while (current != NULL) {
        if ((current->record.key == key)) {
            return &current->record;
        }
        current = current->next;
    }

    return NULL;
}

// Function to free memory
void free_storage(Storage* storage) {
    int i;
    for (i = 0; i < storage->size; i++) {
        if (storage->records[i] != NULL) {
            free(storage->records[i]);
        }
    }
    while (storage->head != NULL) {
        CacheNode* node = storage->head;
        storage->head = node->next;
        free(node);
    }
    free(storage->records);
    free(storage);
}

int main() {
    srand(time(NULL));
    Storage* storage = init_storage(10);

    for (int i = 0; i < 5; i++) {
        Record record = {{i}, rand(), rand()};
        add_record(storage, &record);
    }

    for (int i = 4; i >= 0; i--) {
        Record* found = get_record(storage, i);
        if (found != NULL) {
            printf("Found record: %ld, %d, %d\n", found->offset, found->key, found->value);
        } else {
            printf("Record not found: %d\n", i);
        }
    }

    free_storage(storage);

    return 0;
}
