#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

typedef struct {
    char* key;
    long offset;
    int value;
} item;

// Function to add a new item to the collection
item* addItem(item** collection, size_t* size, const char* key, long offset, int value) {
    item* newItem = (item*)malloc(sizeof(item));
    if (!newItem) {
        return NULL; // Out of memory
    }
    newItem->key = strdup(key);
    if (!newItem->key) {
        free(newItem);
        return NULL; // Out of memory
    }
    newItem->offset = offset;
    newItem->value = value;

    (*size)++;
    (*collection) = (item*)realloc(*collection, sizeof(item) * (*size));
    if (!(*collection)) {
        free(newItem->key);
        free(newItem);
        return NULL; // Out of memory
    }

    (*collection)[*size - 1] = *newItem;
    return newItem;
}

// Function to update an existing item in the collection
int updateItem(item** collection, size_t* size, const char* key, long offset, int value) {
    for (size_t i = 0; i < (*size); i++) {
        if (!strcmp((*collection)[i].key, key)) {
            (*collection)[i].offset = offset;
            (*collection)[i].value = value;
            return 1; // Update successful
        }
    }
    return 0; // Item not found
}

// Function to retrieve an item by its key
item* getItem(item** collection, size_t* size, const char* key) {
    for (size_t i = 0; i < (*size); i++) {
        if (!strcmp((*collection)[i].key, key)) {
            return &(*collection)[i];
        }
    }
    return NULL; // Item not found
}

// Function to serialize the collection to a file
int serializeCollection(const item* collection, size_t size, const char* filename) {
    int fd = open(filename, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        return -1; // Failed to create file
    }

    for (size_t i = 0; i < size; i++) {
        char buffer[1024];
        sprintf(buffer, "%s|%ld|%d\n", collection[i].key, collection[i].offset, collection[i].value);
        write(fd, buffer, strlen(buffer));
    }
    close(fd);
    return 1; // Serialization successful
}

// Function to deserialize the collection from a file
int deserializeCollection(item** collection, size_t* size, const char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        return -1; // Failed to open file
    }

    *size = 0;
    item* newItem = NULL;

    while (1) {
        char buffer[1024];
        ssize_t bytesRead = read(fd, buffer, sizeof(buffer));
        if (bytesRead == 0) {
            break; // End of file
        }
        else if (bytesRead == -1) {
            close(fd);
            return -1; // Error reading from file
        }

        char* token = strtok(buffer, "|");
        if (!token) {
            continue; // Invalid line format
        }

        newItem->key = strdup(token);
        token = strtok(NULL, "|");
        newItem->offset = atoll(token);
        token = strtok(NULL, "|");
        newItem->value = atoi(token);

        (*size)++;
        (*collection) = (item*)realloc(*collection, sizeof(item) * (*size));
        if (!(*collection)) {
            free(newItem->key);
            for (size_t i = 0; i < (*size - 1); i++) {
                free(&((*collection)[i])->key);
            }
            return -1; // Out of memory
        }

        (*collection)[*size - 1] = *newItem;
    }
    close(fd);
    return 1; // Deserialization successful
}

// Function to update the item collection from an external data source
int updateCollection(item** collection, size_t* size, const char* filename) {
    // Read from file and update the collection
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        return -1; // Failed to open file
    }

    while (1) {
        char buffer[1024];
        ssize_t bytesRead = read(fd, buffer, sizeof(buffer));
        if (bytesRead == 0) {
            break; // End of file
        }
        else if (bytesRead == -1) {
            close(fd);
            return -1; // Error reading from file
        }

        char* token = strtok(buffer, "|");
        if (!token) {
            continue; // Invalid line format
        }

        item* newItem = addItem(collection, size, token, atoll(strtok(NULL, "|")), atoi(strtok(NULL, "|")));
        if (!newItem) {
            return -1; // Out of memory
        }
    }
    close(fd);
    return 1; // Update successful
}

// Function to batch serialize and deserialize the item collection
int batchSerialize(const item* collection, size_t size, const char* filename) {
    int fd = open(filename, O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd == -1) {
        return -1; // Failed to create file
    }

    for (size_t i = 0; i < size; i++) {
        char buffer[1024];
        sprintf(buffer, "%s|%ld|%d\n", collection[i].key, collection[i].offset, collection[i].value);
        write(fd, buffer, strlen(buffer));
    }
    close(fd);
    return 1; // Serialization successful
}

int batchDeserialize(item** collection, size_t* size, const char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        return -1; // Failed to open file
    }

    *size = 0;
    item* newItem = NULL;

    while (1) {
        char buffer[1024];
        ssize_t bytesRead = read(fd, buffer, sizeof(buffer));
        if (bytesRead == 0) {
            break; // End of file
        }
        else if (bytesRead == -1) {
            close(fd);
            return -1; // Error reading from file
        }

        char* token = strtok(buffer, "|");
        if (!token) {
            continue; // Invalid line format
        }

        newItem->key = strdup(token);
        token = strtok(NULL, "|");
        newItem->offset = atoll(token);
        token = strtok(NULL, "|");
        newItem->value = atoi(token);

        (*size)++;
        (*collection) = (item*)realloc(*collection, sizeof(item) * (*size));
        if (!(*collection)) {
            free(newItem->key);
            for (size_t i = 0; i < (*size - 1); i++) {
                free(&((*collection)[i])->key);
            }
            return -1; // Out of memory
        }

        (*collection)[*size - 1] = *newItem;
    }
    close(fd);
    return 1; // Deserialization successful
}

// Example usage:
int main() {
    item* collection = NULL;
    size_t size = 0;

    addItem(&collection, &size, "key1", 0, 10);
    addItem(&collection, &size, "key2", 1, 20);

    updateItem(&collection, &size, "key1", 0, 30);

    item* item = getItem(&collection, &size, "key1");
    if (item) {
        printf("%s: %ld, %d\n", item->key, item->offset, item->value);
        free(item->key);
        free(item);
    }

    serializeCollection(collection, size, "items.txt");

    // Simulate periodic updates from an external data source
    for (int i = 0; i < 5; i++) {
        updateCollection(&collection, &size, "updates.txt");
    }

    batchSerialize(collection, size, "batch_items.txt");

    return 0;
}
