```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a session
typedef struct {
    int id;
    char* ip_address;
    time_t last_active_time;
} Session;

// Define the hash table size (adjust this as needed)
#define SESSION_HASH_TABLE_SIZE 1024

// Function to create and initialize a new session
Session* create_session(int id, const char* ip_address) {
    Session* session = (Session*)malloc(sizeof(Session));
    if (!session) {
        fprintf(stderr, "Memory allocation failed for creating a new session.\n");
        return NULL;
    }
    session->id = id;
    session->ip_address = strdup(ip_address);
    session->last_active_time = time(NULL);
    return session;
}

// Function to update the last active time of a session
void update_session_last_active_time(Session* session) {
    session->last_active_time = time(NULL);
}

// Function to check if a session has expired
int is_session_expired(Session* session, int timeout_in_seconds) {
    return (time(NULL) - session->last_active_time > timeout_in_seconds);
}

// Function to find and remove an expired session from the cache
Session* remove_expired_session(Session** cache, size_t* cache_size, int timeout_in_seconds) {
    for (size_t i = 0; i < *cache_size; i++) {
        if (is_session_expired(cache[i], timeout_in_seconds)) {
            free(cache[i]->ip_address);
            free(cache[i]);
            memmove(&cache[i], &cache[i + 1], (*cache_size - i) * sizeof(Session*));
            (*cache_size)--;
            return cache[i];
        }
    }
    return NULL;
}

// Function to manage the session collection
void manage_sessions(Session** cache, size_t* cache_size, int timeout_in_seconds) {
    // Periodically clean up expired sessions
    for (int i = 0; i < *cache_size; i++) {
        Session* expired_session = remove_expired_session(cache, cache_size, timeout_in_seconds);
        if (expired_session != NULL) {
            printf("Expired session removed: ID %d, IP address %s.\n", expired_session->id, expired_session->ip_address);
            free(expired_session->ip_address);
            free(expired_session);
        }
    }
}

int main() {
    // Initialize the cache and set its size
    Session* cache[SESSION_HASH_TABLE_SIZE];
    size_t cache_size = 0;

    // Create a session with an ID of 1 and IP address "192.168.1.100"
    Session* new_session = create_session(1, "192.168.1.100");
    if (new_session != NULL) {
        printf("New session created: ID %d, IP address %s.\n", new_session->id, new_session->ip_address);

        // Update the last active time of the new session
        update_session_last_active_time(new_session);
    }

    // Manage sessions and periodically clean up expired ones
    manage_sessions(cache, &cache_size, 60); // Clean up expired sessions every minute

    return 0;
}
