} log_entry;

typedef struct {
    int ID;
    char* label;
} metadata;

typedef struct {
    int status;
    char* reason;
} audit;

void processAndAggregateData(int num_measurements) {
    srand(time(NULL));

    // Dynamically allocate memory for arrays
    double* measurements = (double*)malloc(num_measurements * sizeof(double));
    char** identifiers = (char**)malloc(num_measurements * sizeof(char*));
    time_t* timestamps = (time_t*)malloc(num_measurements * sizeof(time_t));
    event* events = (event*)malloc(num_measurements * sizeof(event));
    log_entry* log_entries = (log_entry*)malloc(num_measurements * sizeof(log_entry));
    metadata* metadata_array = (metadata*)malloc(num_measurements * sizeof(metadata));
    audit* audits = (audit*)malloc(num_measurements * sizeof(audit));

    // Initialize measurement and identifier arrays
    for (int i = 0; i < num_measurements; i++) {
        measurements[i] = i + 1.0;
        identifiers[i] = malloc(10);
        strcpy(identifiers[i], "Measurement ");
        strcat(identifiers[i], itoa(i));
    }

    // Initialize timestamp, event, log_entry, metadata, and audit arrays
    for (int i = 0; i < num_measurements; i++) {
        timestamps[i] = time(NULL) + rand() % 100;
        events[i].value = measurements[i];
        events[i].identifier = identifiers[i];
        events[i].timestamp = timestamps[i];

        log_entries[i].log_level = rand() % 3;
        log_entries[i].message = malloc(20);
        sprintf(log_entries[i].message, "Measurement %d: %.2f", i + 1, measurements[i]);
        log_entries[i].timestamp = timestamps[i];

        metadata_array[i].ID = i + 1;
        metadata_array[i].label = malloc(10);
        strcpy(metadata_array[i].label, "Label ");
        strcat(metadata_array[i].label, itoa(i));

        audits[i].status = rand() % 2;
        audits[i].reason = malloc(20);
        sprintf(audit[i].reason, "Reason %d", i + 1);
    }

    // Ensure the size of event, log_entry, metadata, and audit arrays does not exceed the sum of sizes of measurement and identifier arrays
    int max_size = num_measurements * (sizeof(event) + sizeof(log_entry) + sizeof(metadata) + sizeof(audit));
    if (max_size > num_measurements * (sizeof(double) + 10)) {
        free(measurements);
        free(identifiers);
        free(timestamps);
        free(events);
        free(log_entries);
        free(metadata_array);
        free(audits);
        printf("Array size exceeded.\n");
        return;
    }

    // Print the contents of all arrays
    for (int i = 0; i < num_measurements; i++) {
        printf("Measurement: %.2f, Identifier: %s, Timestamp: %ld\n", measurements[i], identifiers[i], timestamps[i]);
        printf("Event: Value - %.2f, Identifier - %s, Timestamp - %ld\n", events[i].value, events[i].identifier, events[i].timestamp);
        printf("Log Entry: Level - %d, Message - %s, Timestamp - %ld\n", log_entries[i].log_level, log_entries[i].message, log_entries[i].timestamp);
        printf("Metadata: ID - %d, Label - %s\n", metadata_array[i].ID, metadata_array[i].label);
        printf("Audit: Status - %d, Reason - %s\n", audits[i].status, audits[i].reason);
    }

    // Free all allocated memory
    for (int i = 0; i < num_measurements; i++) {
        free(identifiers[i]);
        free(log_entries[i].message);
        free(metadata_array[i].label);
        free(audits[i].reason);
    }
    free(measurements);
    free(identifiers);
    free(timestamps);
    free(events);
    free(log_entries);
    free(metadata_array);
    free(audits);
}
