// Initialize custom allocator with requested size and alignment
CustomAllocator* init_allocator(size_t capacity) {
    CustomAllocator* alloc = (CustomAllocator*)malloc(sizeof(CustomAllocator));
    alloc->ptr = malloc(capacity);
    alloc->capacity = capacity;
    return alloc;
}

// Deallocate memory using custom allocator
void free_allocator(CustomAllocator* alloc) {
    free(alloc->ptr);
    free(alloc);
}

// Define data structures
typedef struct {
    long offset;
} Offset;

typedef struct {
    int key;
} Key;

typedef struct {
    int value;
} Record;

typedef struct {
    char* metadata;
    int frequency;
} Metadata;

Offset* init_offsets(int count) {
    Offset* offsets = (Offset*)malloc(count * sizeof(Offset));
    for (int i = 0; i < count; i++) {
        offsets[i].offset = i;
    }
    return offsets;
}

Key* init_keys(int count) {
    Key* keys = (Key*)malloc(count * sizeof(Key));
    for (int i = 0; i < count; i++) {
        keys[i].key = i;
    }
    return keys;
}

Record* init_records(int count, int min_value, int max_value) {
    Record* records = (Record*)malloc(count * sizeof(Record));
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
    return records;
}

Metadata* init_metadata(int count, char** metadata_list) {
    Metadata* metadata = (Metadata*)malloc(count * sizeof(Metadata));
    for (int i = 0; i < count; i++) {
        metadata[i].metadata = metadata_list[i];
        metadata[i].frequency = 1;
    }
    return metadata;
}

void print_data_structures(Offset* offsets, Key* keys, Record* records, Metadata* metadata) {
    printf("Offsets: ");
    for (int i = 0; i < sizeof(offsets)/sizeof(Offset); i++) {
        printf("%ld ", offsets[i].offset);
    }
    printf("\n");
    printf("Keys: ");
    for (int i = 0; i < sizeof(keys)/sizeof(Key); i++) {
        printf("%d ", keys[i].key);
    }
    printf("\n");
    printf("Records: ");
    for (int i = 0; i < sizeof(records)/sizeof(Record); i++) {
        printf("%d ", records[i].value);
    }
    printf("\n");
    printf("Metadata: ");
    for (int i = 0; i < sizeof(metadata)/sizeof(Metadata); i++) {
        printf("%s (%d) ", metadata[i].metadata, metadata[i].frequency);
    }
    printf("\n");
}

void free_memory(Offset* offsets, Key* keys, Record* records, Metadata* metadata) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
    if (metadata) free(metadata);
}

int main() {
    // Initialize data structures
    int offset_count = 100;
    int key_count = 50;
    int record_count = 200;
    int metadata_count = 10;

    Offset* offsets = init_offsets(offset_count);
    Key* keys = init_keys(key_count);
    Record* records = init_records(record_count, 0, 100);
    Metadata* metadata = init_metadata(metadata_count, (char**)malloc(metadata_count * sizeof(char*))));

    // Initialize custom allocator for large block of memory
    CustomAllocator* alloc = init_allocator(1024 * 1024); // 1MB

    // Print data structures
    print_data_structures(offsets, keys, records, metadata);

    // Free memory
    free_memory(offsets, keys, records, metadata);
    free_allocator(alloc);

    return 0;
}
