typedef struct {
    double measurement;
    char* identifier;
    time_t timestamp;
} event;

typedef struct {
    int log_level;
    char* message;
    time_t timestamp;
} log_entry;

typedef struct {
    int min;
    int max;
    double average;
} statistics;

