void manageDataAndComputeStatistics() {
    srandlib_init();

    size_t num_measurements = 0;
    scanf("%zu", &num_measurements);

    event* measurements = (event*)malloc(num_measurements * sizeof(event));
    for(size_t i = 0; i < num_measurements; ++i) {
        scanf("%lf %s %ld",
             &measurements[i].measurement,
             &measurements[i].identifier,
             &measurements[i].timestamp);
    }

    statistics* stats = (statistics*)malloc(sizeof(statistics));
    *stats = helperComputeStatistics(measurements, num_measurements);

    log_entry* logs = (log_entry*)malloc(num_measurements * sizeof(log_entry));
    for(size_t i = 0; i < num_measurements; ++i) {
        logs[i].timestamp = time(NULL);
        printf("%ld %s\n", logs[i].timestamp, measurements[i].identifier);
    }

    // ... (rest of the code)
}

statistics* helperComputeStatistics(event* measurements, size_t num_measurements) {
    statistics* stats = (statistics*)malloc(sizeof(statistics));
    stats->min = 0;
    stats->max = 0;
    double sum = 0.0;

    for(size_t i = 0; i < num_measurements; ++i) {
        if(i == 0 || measurements[i].measurement < stats->min)
            stats->min = measurements[i].measurement;
        if(i == 0 || measurements[i].measurement > stats->max)
            stats->max = measurements[i].measurement;
        sum += measurements[i].measurement;
    }

    stats->average = sum / num_measurements;

    return stats;
}
