void init_arrays(int* offset, int** record, int** status, int** metadata, int num_records) {
    // Memory allocation
    *offset = (int*)malloc((num_records + 1) * sizeof(int));
    *record = (int**)malloc(num_records * sizeof(int*));
    *status = (int*)malloc(num_records * sizeof(int));
    *metadata = (int*)malloc(num_records * sizeof(int));

    // Initialize offset and key arrays
    for (int i = 0; i <= num_records; i++) {
        (*offset)[i] = i;
    }

    // Initialize record array with random integers
    srand(time(NULL));
    int unique_value = 1;
    for (int i = 0; i < num_records; i++) {
        int new_value = rand() % 10000 + 1;
        while (*record[i] && *record[i] == new_value) {
            new_value = rand() % 10000 + 1;
        }
        (*record)[i] = new_value;
    }

    // Initialize status array
    int fail_prob = 5; // probability of failure (in percentage)
    for (int i = 0; i < num_records; i++) {
        if ((rand() % 100) <= (fail_prob * 2)) {
            (*status)[i] = 0;
        } else {
            (*status)[i] = 1;
        }
    }

    // Initialize metadata array
    for (int i = 0; i < num_records; i++) {
        (*metadata)[i] = i;
    }

    // Check size constraint
    if (num_records > (size_t)((*offset) + (num_records * sizeof(int)) + (num_records * sizeof(int)) + (num_records * sizeof(int))) * 1.10) {
        printf("Error: Record array size exceeds allowed limit.\n");
        return;
    }

    // Print arrays for debugging
    if (!getenv("NO_DEBUG")) {
        printf("Offset array: ");
        for (int i = 0; i <= num_records; i++) {
            printf("%d ", (*offset)[i]);
        }
        printf("\n");
        printf("Record array: ");
        for (int i = 0; i < num_records; i++) {
            printf("%d ", (*record)[i]);
        }
        printf("\n");
        printf("Status array: ");
        for (int i = 0; i < num_records; i++) {
            printf("%d ", (*status)[i]);
        }
        printf("\n");
        printf("Metadata array: ");
        for (int i = 0; i < num_records; i++) {
            printf("%d ", (*metadata)[i]);
        }
        printf("\n");
    }

    // Free allocated memory
    free(*offset);
    for (int i = 0; i < num_records; i++) {
        free((*record)[i]);
    }
    free(*record);
    free(*status);
    free(*metadata);
}

int main() {
    int num_records = 10;
    init_arrays(NULL, NULL, NULL, NULL, num_records);
    return 0;
}
