use std::fs;
use std::path::PathBuf;
use rand::{Rng, SeedableRng};
use rand_chacha::ChaCha8Rng;

fn init_data_structures(config: &Config) -> (Vec<i64>, Vec<i32>, Vec<(i32, i32)>) {
    let mut rng = SeedableRng::from_entropy();
    let mut offset_vec = Vec::new();
    let mut key_vec = Vec::new();
    let mut record_vec = Vec::new();

    // Initialize 'offset' and 'key' arrays
    for _ in 0..config.max_size {
        let offset: i64 = rng.gen_range(0, config.max_size as i64);
        let key: i32 = rng.gen_range(0, config.max_size as i32);

        offset_vec.push(offset);
        key_vec.push(key);
    }

    // Initialize 'record' array
    for _ in 0..config.max_size {
        record_vec.push((rng.gen_range(0, config.max_size as i32), rng.gen_range(0, config.max_size as i32)));
    }

    // Validate the size of the 'record' array
    if offset_vec.len() + key_vec.len() < record_vec.len() {
        panic!("Record array exceeds combined size of offset and key arrays");
    }

    (offset_vec, key_vec, record_vec)
}

fn print_data_structures(offset_vec: &Vec<i64>, key_vec: &Vec<i32>, record_vec: &Vec<(i32, i32)>) {
    println!("Offset Array:");
    for val in offset_vec {
        println!("{}", val);
    }
    println!();

    println!("Key Array:");
    for val in key_vec {
        println!("{}", val);
    }
    println!();

    println!("Record Array:");
    for record in record_vec {
        println!("{:?}", record);
    }
    println!();
}

struct Config {
    max_size: usize,
    seed: u64,
    print_data: bool,
}

fn main() -> Result<(), fs::IoError> {
    let config = Config {
        max_size: 100,
        seed: 42,
        print_data: true,
    };

    let (mut offset_vec, mut key_vec, record_vec) = init_data_structures(&config);

    if config.print_data {
        print_data_structures(&offset_vec, &key_vec, &record_vec);
    }

    Ok(())
}
