#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char* str;
    int priority;
} Node;

Node* initLinkedList(int n) {
    Node* head = (Node*)malloc(sizeof(Node));
    if (!head) return NULL;
    head->str = malloc((n+1)*sizeof(char));
    strcpy(head->str, "initial_string");
    head->priority = 0;
    return head;
}

void freeLinkedList(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
}

int customHash(const char* str, int max) {
    int hash = 0;
    for (char c : str)
        hash = (hash * 31 + c) % max;
    return hash;
}

void initHashTable(Node* head, int max) {
    // assuming an external library function 'insert'
    insert("initial_string", 0);
    Node* current = head->next;
    while (current) {
        insert(current->str, current->priority);
        current = current->next;
    }
}

void freeHashTable() {
    // assuming the external library function 'delete' for hash table
    delete("initial_string");
}

int getStatus(char* str, int max) {
    Node* current = head;
    while (current) {
        if (strcmp(current->str, str) == 0)
            return 1; // presence in linked list and hash table
        current = current->next;
    }
    return 0; // absence from both structures
}

void printData() {
    Node* current = head;
    while (current) {
        printf("%s %d\n", current->str, current->priority);
        current = current->next;
    }
}

int main() {
    int max = 1000000; // available memory
    Node* head = initLinkedList(10);
    initHashTable(head, max);
    printData();
    freeLinkedList(head);
    freeHashTable();
    return 0;
}
