void manageAndAnalyzeDataWithPerformance(int n) {
    double *measurements = (double *)malloc(n * sizeof(double));
    char **identifiers = (char **)malloc(n * sizeof(char *));
    time_t *timestamps = (time_t *)malloc(n * sizeof(time_t));
    Event *events = (Event *)malloc(n * sizeof(Event));
    LogEntry *log_entries = (LogEntry *)malloc(n * sizeof(LogEntry));
    Statistics *statistics = (Statistics *)malloc(sizeof(Statistics));
    Metadata *metadata = (Metadata *)malloc(sizeof(Metadata));
    int *dependencies = (int *)malloc(sizeof(int));

