        events[i].measurement = measurements[i];
        events[i].identifier = identifiers[i];
        events[i].timestamp = timestamps[i];

        // Initialize log entries
        log_entries[i].log_level = 1;
        log_entries[i].message = malloc(50);
        sprintf(log_entries[i].message, "Log message for event %d", i);
        log_entries[i].timestamp = time(NULL);

        // Initialize statistics
        statistics->min = measurements[0];
        statistics->max = measurements[0];
        statistics->average = measurements[0];

        for (int j = 1; j < n; j++) {
            if (measurements[j] < statistics->min)
                statistics->min = measurements[j];
            else if (measurements[j] > statistics->max)
                statistics->max = measurements[j];
            statistics->average += measurements[j];
        }
        statistics->average /= n;

        // Initialize metadata
        metadata->file_name = malloc(50);
        sprintf(metadata->file_name, "file_%d.txt", i);
        metadata->version = 1;
    }

    // Calculate and print average measurement
    double total = 0.0;
    for (int i = 0; i < n; i++) {
        total += measurements[i];
    }
    printf("Average measurement: %f\n", total / n);

    // Compute MD5 hash of file specified by user
    FILE *file = fopen(metadata->file_name, "rb");
    MD5_CTX ctx;
    MD5_Init(&ctx);
    while (1) {
        uint8_t buffer[1024];
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), file);
        if (bytes_read == 0)
            break;
        MD5_Update(&ctx, buffer, bytes_read);
    }
    MD5_Final(metadata->file_hash, &ctx);

    // Free dynamically allocated memory
    free(measurements);
    for (int i = 0; i < n; i++) {
        free(identifiers[i]);
        free(log_entries[i].message);
    }
    free(identifiers);
    free(timestamps);
    free(events);
    free(log_entries);
    free(statistics);
    free(metadata);

    // Deinitialize external library
    srand(1);
}
