#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Record {
    int key;
    long offset;
    char* str;
} Record;

typedef struct HashEntry {
    Record* record;
    struct HashEntry* next;
} HashEntry;

typedef struct Database {
    HashEntry** table;
    int capacity;
    int size;
    int loadFactorThreshold;
    int maxCapacity;
} Database;

Database* createDatabase(int capacity, int loadFactorThreshold, int maxCapacity) {
    Database* db = (Database*)malloc(sizeof(Database));
    db->table = (HashEntry**)calloc(capacity, sizeof(HashEntry*));
    db->capacity = capacity;
    db->size = 0;
    db->loadFactorThreshold = loadFactorThreshold;
    db->maxCapacity = maxCapacity;
    return db;
}

void freeDatabase(Database* db) {
    for(int i = 0; i < db->capacity; i++) {
        HashEntry* current = db->table[i];
        while(current != NULL) {
            HashEntry* next = current->next;
            if(current->record != NULL) {
                free(current->record->str);
                free(current->record);
            }
            free(current);
            current = next;
        }
    }
    free(db->table);
    free(db);
}

Record* createRecord(int key, long offset, char* str) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    record->str = (char*)malloc(strlen(str) + 1);
    strcpy(record->str, str);
    return record;
}

void freeRecord(Record* record) {
    if(record != NULL) {
        free(record->str);
        free(record);
    }
}

int hashFunction(int key, int capacity) {
    return key % capacity;
}

int insertRecord(Database* db, int key, long offset, char* str) {
    Record* record = createRecord(key, offset, str);
    int index = hashFunction(key, db->capacity);
    HashEntry* current = db->table[index];
    if(current == NULL) {
        db->table[index] = (HashEntry*)malloc(sizeof(HashEntry));
        current = db->table[index];
    }
    while(current != NULL) {
        if(current->record != NULL && current->record->key == key) {
            freeRecord(record);
            return -1; // Record already exists
        }
        if(current->next != NULL) {
            current = current->next;
        } else {
            break;
        }
    }
    current->record = record;
    db->size++;
    if((float)db->size / db->capacity > db->loadFactorThreshold && db->capacity < db->maxCapacity) {
        int newCapacity = db->capacity * 2;
        Database* newDb = createDatabase(newCapacity, db->loadFactorThreshold, db->maxCapacity);
        for(int i = 0; i < db->capacity; i++) {
            HashEntry* current = db->table[i];
            while(current != NULL) {
                int newIndex = hashFunction(current->record->key, newCapacity);
                if(newDb->table[newIndex] == NULL) {
                    newDb->table[newIndex] = (HashEntry*)malloc(sizeof(HashEntry));
                }
                newDb->table[newIndex]->record = current->record;
                HashEntry* next = current->next;
                free(current);
                current = next;
            }
        }
        for(int i = 0; i < db->capacity; i++) {
            free(db->table[i]);
        }
        free(db->table);
        db = newDb;
    }
    return 0;
}

int main() {
    Database* db = createDatabase(16, 0.75, 64);

    srand(time(NULL));
    for(int i = 0; i < 10000; i++) {
        int key = rand() % 100000;
        long offset = rand() % 100000000;
        char str[20];
        sprintf(str, "Record %d", i);
        insertRecord(db, key, offset, str);
    }

    freeDatabase(db);

    return 0;
}
