            {
                using (var connection = GetConnection())
                {
                    var users = await RetrieveUsersFromApiAsync(connection, _apiEndpoint, pageIndex, pageSize);
                    return new PagedUserList(users, pageIndex, pageSize);
                }
            }
            catch (Exception ex)
            {
                LogError(ex);
                throw;
            }
        }

        private void Initialize()
        {
