#define MAX_MEASUREMENTS 1000
#define MAX_METADATA_SIZE 256

typedef struct {
    double measurement;
    char* identifier;
    time_t timestamp;
} event_t;

typedef struct {
    int index;
    char* description;
} metadata_t;

void processAndAggregateData(int numMeasurements) {
    // Initialize arrays using malloc with proper error handling
    double* measurements = (double*)malloc(numMeasurements * sizeof(double));
    char** identifiers = (char**)malloc(numMeasurements * sizeof(char*));
    time_t* timestamps = (time_t*)malloc(numMeasurements * sizeof(time_t));
    event_t* events = (event_t*)malloc(numMeasurements * sizeof(event_t));
    metadata_t* metadata = (metadata_t*)malloc(MAX_METADATA_SIZE * sizeof(metadata_t));

    // Read measurements from standard input and store them in the array
    for (int i = 0; i < numMeasurements; i++) {
        scanf("%lf", &measurements[i]);
        identifiers[i] = malloc(256);
        fgets(identifiers[i], 255, stdin);
    }

    // Initialize timestamps, event details, and metadata descriptions randomly
    srand(time(NULL));
    for (int i = 0; i < numMeasurements; i++) {
        timestamps[i] = time(NULL) + rand() % 100;
        events[i].measurement = measurements[i];
        events[i].identifier = identifiers[i];
        events[i].timestamp = timestamps[i];
        metadata[i].index = i;
        metadata[i].description = malloc(256);
        sprintf(metadata[i].description, "Metadata description %d", i);
    }

    // Check if the event array is not greater than the sum of the sizes of the other arrays
    if (numMeasurements > MAX_METADATA_SIZE) {
        printf("Error: Event array size exceeds maximum metadata size.\n");
        return;
    }

    // Print contents of all arrays for debugging purposes
    for (int i = 0; i < numMeasurements; i++) {
        printf("Measurement %lf, Identifier %s, Timestamp %lu\n", measurements[i], identifiers[i], timestamps[i]);
        printf("Event: Measurement %lf, Identifier %s, Timestamp %lu\n", events[i].measurement, events[i].identifier, events[i].timestamp);
        printf("Metadata: Index %d, Description %s\n", metadata[i].index, metadata[i].description);
    }

    // Calculate and print the average measurement in the array using a helper function
    double averageMeasurement = calculateAverage(measurements, numMeasurements);
    printf("Average Measurement: %lf\n", averageMeasurement);

    // Determine and print the maximum and minimum measurement values
    double maxMeasurement = measurements[0];
    double minMeasurement = measurements[0];
    for (int i = 1; i < numMeasurements; i++) {
        if (measurements[i] > maxMeasurement) {
            maxMeasurement = measurements[i];
        } else if (measurements[i] < minMeasurement) {
            minMeasurement = measurements[i];
        }
    }
    printf("Maximum Measurement: %lf\n", maxMeasurement);
    printf("Minimum Measurement: %lf\n", minMeasurement);

    // Free all allocated memory
    for (int i = 0; i < numMeasurements; i++) {
        free(identifiers[i]);
        free(metadata[i].description);
    }
    free(measurements);
    free(identifiers);
    free(timestamps);
    free(events);
    free(metadata);

    return;
}

double calculateAverage(double* measurements, int numMeasurements) {
    double sum = 0.0;
    for (int i = 0; i < numMeasurements; i++) {
        sum += measurements[i];
    }
    return sum / numMeasurements;
}
