// Custom memory manager for manual and automatic cleanup
void* my_malloc(size_t size) {
    // Initialize the custom memory pool
    static void* pool = NULL;
    if (!pool) {
        pool = malloc(1024 * 1024); // 1MB pool size
    }

    // Reuse existing memory from the pool
    if (size <= 1024) { // reuse up to 1KB
        return realloc(pool, size);
    } else {
        // Allocate new memory using standard malloc
        void* result = malloc(size);
        if (!result) {
            return NULL; // out of memory
        }
        // Return the newly allocated memory
