mempool* init_mempool(size_t cap) {
    mempool* mp = (mempool*)malloc(sizeof(mempool));
    mp->capacity = cap;
    mp->size = 0;
    mp->ptrs = (void**)calloc(cap, sizeof(void*));
    return mp;
}

// Dynamically allocate memory for arrays using custom pool
void init_arrays(mempool* mp) {
    // Allocate offset array
    size_t offsets_size = 5;
    long** offsets = (long**)malloc(offsets_size * sizeof(long*));
    for (int i = 0; i < offsets_size; i++) {
        offsets[i] = (long*)mp->ptrs[i % mp->capacity];
        mp->size++;
    }

    // Allocate key array
    size_t keys_size = 5;
    int** keys = (int**)malloc(keys_size * sizeof(int*));
    for (int i = 0; i < keys_size; i++) {
        keys[i] = (int*)mp->ptrs[mp->size++ % mp->capacity];
    }

    // Allocate record array
    size_t records_size = 5;
    struct { int val; }** records = (struct { int val; }**)malloc(records_size * sizeof(struct { int val; }*));
    for (int i = 0; i < records_size; i++) {
        records[i] = (struct { int val; }*)mp->ptrs[mp->size++ % mp->capacity];
        records[i]->val = rand() % 100; // Initialize with random value
    }

    // Allocate timestamp array
    time_t* timestamps = (time_t*)malloc(5 * sizeof(time_t));
    for (int i = 0; i < 5; i++) {
        timestamps[i] = time(NULL); // Initialize with current system clock
    }

    // Allocate status array
    char** statuses = (char**)malloc(5 * sizeof(char*));
    for (int i = 0; i < 5; i++) {
        statuses[i] = strdup("success"); // Initialize with predefined status string
    }
}

// Free allocated memory using custom pool
void free_arrays(mempool* mp) {
    // Free offset array
    for (int i = 0; i < mp->size; i++) {
        free(mp->ptrs[i]);
    }
    free(mp->ptrs);

    // Free key and record arrays
    for (int i = 0; i < mp->size; i++) {
        free(mp->ptrs[mp->size++ % mp->capacity]);
    }

    // Free timestamp array
    free(timestamps);

    // Free status array
    for (int i = 0; i < mp->size; i++) {
        free(statuses[i]);
    }
    free(statuses);
}

