        events[i].measurement = measurements[i];
        events[i].identifier = identifiers[i % identifier_count];
        timestamp = rand() % ((time(NULL) + 1) % (24*60*60)) + 1;
        events[i].timestamp = timestamp;

        logs[i].log_level = i % 5; // arbitrary log level
        logs[i].message = "Random message";
        logs[i].timestamp = timestamp;

        stats->min = measurements[0];
        stats->max = measurements[0];
        for(size_t j = 1; j < measurement_count; j++) {
            if(measurements[j] < stats->min)
                stats->min = measurements[j];
            else if(measurements[j] > stats->max)
                stats->max = measurements[j];
        }
        stats->average = (double)measurements[0] / measurement_count;

        meta->description = "Random metadata";
        meta->version_number = rand() % 10;

        ext->id = i;
        ext->extended_details = "Random extended details";

        audits[i].timestamp = timestamp;
        audit_records* current_audit = &audits[i];
    }

    // Free allocated memory
    free(measurements);
    for(size_t i = 0; i < identifier_count; i++) {
        free(identifiers[i]);
    }
    free(identifiers);
    return events;
}
