#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <threads.h>

// Define the structure representing a database record
typedef struct {
    long pk;
    int ts;
    char* text;
    int status;
    int last_updated;
} Record;

// Function to insert a new record into the dynamic array
void insert_record(Record** table, int* size, int* capacity, th_rdlock_t* lock) {
    // Find the first available slot in the array
    for (int i = 0; i < *size; i++) {
        if (!(*table)[i].text) {
            break;
        }
    }

    // If no slots are available, resize the array if necessary
    if (i == *size) {
        Record** new_table = realloc(*table, (*capacity + 1) * sizeof(Record*));
        *table = new_table;
        *capacity *= 2;
    }

    // Allocate space for the new record and initialize it
    Record* new_record = malloc(sizeof(Record));
    new_record->pk = 0;  // Initialize with a default PK value
    new_record->ts = time(NULL);
    new_record->text = NULL;
    new_record->status = 0;
    new_record->last_updated = time(NULL);

    (*table)[i] = *new_record;

    // Release the lock to allow other threads to access the array
    th_unlock(lock);
}

// Function to serialize the database table to a file
void serialize_table(Record** table, int size, FILE* file) {
    // Write the number of records and each record's metadata
    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        Record* record = (*table)[i];
        fwrite(&record->pk, sizeof(long), 1, file);
        fwrite(&record->ts, sizeof(int), 1, file);
        int text_len = strlen(record->text);
        fwrite(&text_len, sizeof(int), 1, file);
        fwrite(record->text, 1, text_len + 1, file);
    }
}

// Function to compact and reorganize the serialized data
void compact_data(FILE* file) {
    // Read the current number of records from the file
    int size;
    fread(&size, sizeof(int), 1, file);

    // Allocate space for a new array of records
    Record** new_table = malloc(size * sizeof(Record*));

    // Read each record's metadata and text data into the new array
    for (int i = 0; i < size; i++) {
        Record* record;
        fread(&record->pk, sizeof(long), 1, file);
        fread(&record->ts, sizeof(int), 1, file);
        int text_len;
        fread(&text_len, sizeof(int), 1, file);
        record->text = malloc(text_len + 1);
        fread(record->text, 1, text_len + 1, file);

        // Add the record to the new array
        (*new_table)[i] = *record;
    }

    // Close the original file and open a new one for writing
    fclose(file);
    FILE* new_file = fopen("data.compact", "wb");
    fwrite(&size, sizeof(int), 1, new_file);

    // Write each record's metadata to the new file
    for (int i = 0; i < size; i++) {
        Record* record = (*new_table)[i];
        fwrite(&record->pk, sizeof(long), 1, new_file);
        fwrite(&record->ts, sizeof(int), 1, new_file);
        int text_len = strlen(record->text);
        fwrite(&text_len, sizeof(int), 1, new_file);
        fwrite(record->text, 1, text_len + 1, new_file);
    }

    // Free the original array and close the files
    free(*new_table);
    fclose(new_file);
}
