import re
from collections import defaultdict
from itertools import islice

def process_log_file(log_files, module_name):
    error_counts = defaultdict(int)

    pattern = r'\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] \(.*\) (\w+): (.*)'
    error_message_pattern = re.compile(pattern)

    for log_file in log_files:
        chunk_size = 100000
        for line in islice(open(log_file, 'r'), None, None, chunk_size):
            try:
                match = error_message_pattern.search(line.decode('utf-8'))
                if match:
                    _, _, module, error_message = match.groups()
                    if module == module_name:
                        error_counts[error_message] += 1
            except UnicodeDecodeError as e:
                print(f"Error parsing log file: {e}")

    return dict(error_counts)
