typedef struct {
    time_t timestamp;
    int type;
} event_t;

void initialize_game_world(int num_records, int max_offset, int min_key, int max_key) {
    // Initialize the random number generator
    srand(time(NULL));

    // Allocate memory for arrays
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    event_t* events = (event_t*)malloc(num_records * sizeof(event_t));

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (max_offset - min_key + 1) + min_key;
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Initialize event array
    for (int i = 0; i < num_records; i++) {
        events[i].timestamp = time(NULL);
        events[i].type = rand() % 2; // 0 or 1
    }

    // Log the initialization process
    printf("Initializing game world with %d records...\n", num_records);

    // Serialize initialized state to binary format
    FILE* file = fopen("game_world.bin", "wb");
    fwrite(&num_records, sizeof(int), 1, file);
    fwrite(offsets, sizeof(long), num_records, file);
    fwrite(keys, sizeof(int), num_records, file);
    fwrite(records, sizeof(record_t), num_records, file);
    fwrite(events, sizeof(event_t), num_records, file);

    fclose(file);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(events);
}
