#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} record;

record* initialize_records(int size, int offset_array_size, int key_array_size) {
    if (size <= 0 || offset_array_size <= 0 || key_array_size <= 0) {
        return NULL; // invalid input
    }

    srand(time(NULL)); // seed random number generator

    record* records = malloc(size * sizeof(record));
    if (!records) {
        return NULL; // memory allocation failed, handle error
    }

    long* offsets = malloc(offset_array_size * sizeof(long));
    int* keys = malloc(key_array_size * sizeof(int));

    for (int i = 0; i < offset_array_size; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < key_array_size; i++) {
        keys[i] = i;
    }

    record* record_ptr = records;

    for (int i = 0; i < size; i++) {
        long offset = rand() % offset_array_size;
        int key = rand() % key_array_size;
        while (offset >= offset_array_size || key >= key_array_size) {
            offset = rand() % offset_array_size;
            key = rand() % key_array_size;
        }
        record_ptr->offset = offsets[offset];
        record_ptr->key = keys[key];
        record_ptr++;
    }

    free(offsets);
    free(keys);

    return records;
}
