void allocateMemory(int *size) {
    int maxOffsetsSize = 1000;
    int maxKeysSize = 1000;
    int maxRecordsSize = 10000;

    // Validate user-provided sizes
    if (*size > maxOffsetsSize || *size > maxKeysSize || *size * sizeof(struct record) > maxRecordsSize) {
        printf("Invalid size provided. Size must not exceed %d, %d, and %d respectively.\n", maxOffsetsSize, maxKeysSize, maxRecordsSize);
        return;
    }

    // Initialize offsets array with unique values
    int *offsets = (int *)malloc(*size * sizeof(int));
    for (int i = 0; i < *size; i++) {
        offsets[i] = i;
    }

    // Initialize keys array with unique values
    int *keys = (int *)malloc(*size * sizeof(int));
    for (int i = 0; i < *size; i++) {
        keys[i] = i;
    }

    // Initialize records array
    struct record *records = (struct record *)malloc(*size * sizeof(struct record));
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < *size; i++) {
        records[i].offset = offsets[rand() % *size];
        records[i].key = keys[rand() % *size];
    }

    free(offsets);
    free(keys);

    printf("Memory allocated successfully.\n");
}

