#include <iostream>
#include <string>
#include <fstream>
#include <mutex>
#include <thread>
#include <json/json.h>

// Logging levels
enum LogLevel {
    DEBUG = 1,
    INFO,
    WARN,
    ERROR,
    FATAL
};

// Log message structure
struct LogMessage {
    std::time_t timestamp;
    LogLevel level;
    std::string message;
};

// Thread-safe logging class
class Logger {
public:
    static Logger& getInstance() {
        static Logger instance;
        return instance;
    }

    void setLogLevel(LogLevel level) {
        logLevel = level;
    }

    void setLogFilePath(const std::string& filePath) {
        logFilePath = filePath;
    }

    void setRemoteLoggingEnabled(bool enabled) {
        remoteLoggingEnabled = enabled;
    }

    template<typename... Args>
    void log(Args&&... args) {
        LogMessage message;
        message.timestamp = std::time(nullptr);
        message.level = logLevel;
        message.message = std::forward<Args>(args)...;

        // Local logging
        if (!remoteLoggingEnabled) {
            writeLog(message);
        }
        // Remote logging
        else {
            try {
                remoteLog(message);
            } catch (const std::exception& e) {
                logError("Remote logging failed: " + e.what());
            }
        }
    }

private:
    LogLevel logLevel = INFO;
    std::string logFilePath;
    bool remoteLoggingEnabled = false;

    // Local logging
    void writeLog(const LogMessage& message) {
        std::ofstream file(logFilePath, std::ios_base::app);
        if (!file.is_open()) {
            return;  // File open failed
        }
        file << message.timestamp << " - " << getLogLevelName(message.level) << ": " << message.message << "\n";
        file.flush();
    }

    // Remote logging
    void remoteLog(const LogMessage& message) {
        // Implement your preferred remote logging mechanism here,
        // e.g., using a RESTful API, gRPC, or an existing logging service.
    }

    std::string getLogLevelName(LogLevel level) const {
        switch (level) {
            case DEBUG:
                return "DEBUG";
            case INFO:
                return "INFO";
            case WARN:
                return "WARN";
            case ERROR:
                return "ERROR";
            case FATAL:
                return "FATAL";
            default:
                return "";
        }
    }

    // Error logging
    void logError(const std::string& message) {
        writeLog({std::time(nullptr), FATAL, message});
    }
};

// JSON configuration file parser
class ConfigParser {
public:
    bool parseConfig(const std::string& configPath) {
        try {
            Json::Value root;
            Json::Reader reader;
            if (!reader.parse(configPath, root)) {
                return false;  // Parsing failed
            }

            // Parse logging level and file path from the JSON configuration
            logLevel = LogLevel(root["log_level"].asInt());
            logFilePath = root["log_file_path"].asString();

            remoteLoggingEnabled = root["remote_logging"].getAsBool();
            return true;
        } catch (const Json::Exception& e) {
            // Handle JSON parsing error
            return false;
        }
    }

private:
    LogLevel logLevel;
    std::string logFilePath;
    bool remoteLoggingEnabled;
};

int main() {
    // Initialize the logging framework with default settings
    Logger& logger = Logger::getInstance();

    // Load configuration from a file (optional)
    ConfigParser configParser;
    if (!configParser.parseConfig("logging_config.json")) {
        // Use default logging settings
    }

    // Set log level and file path dynamically
    logger.setLogLevel(LogLevel::DEBUG);
    logger.setLogFilePath("/path/to/log/file.log");

    // Enable remote logging (optional)
    logger.setRemoteLoggingEnabled(true);

    // Log messages with different levels
    logger.log("This is a debug message");
    logger.log("This is an info message");
    logger.log("Warning: Something went wrong");
    logger.log("Error: A critical error occurred");

    return 0;
}
```
Note that this code does not include the implementation of remote logging, which you would need to implement based on your specific requirements. Additionally, you will need to integrate this code with an external JSON configuration file parser and a mechanism for archiving log files.']

