logEntry* processNetworkLogs() {
    FILE *input = stdin;
    logEntry *logs = NULL;
    int logCount = 0, maxEntries = MAX_LOG_ENTRIES;
    size_t bufferLen = BUFFER_SIZE;

    struct tm *parseBuffer = (struct tm *)malloc(bufferLen * sizeof(struct tm));
    char *parseBuf = (char *)malloc(bufferLen);

    while (fgets(parseBuf, bufferLen, input) != NULL && logCount < maxEntries) {
        logEntry *log = (logEntry *)malloc(sizeof(logEntry));
        if (sscanf(parseBuf, "%s %d %s", log->srcIP, &log->dstPort, parseBuf + 16) == 3) {
            log->timestamp = time(NULL);
            logs = realloc(logs, (logCount + 1) * sizeof(logEntry));
            logs[logCount++] = *log;
        } else {
            free(log);
        }
    }

    if (logCount > 0) {
        qsort(logs, logCount, sizeof(logEntry), cmpLogEntries);
        for (int i = 0; i < logCount; i++) {
            printf("Timestamp: %ld, Source IP: %s, Destination Port: %d\n", logs[i].timestamp, logs[i].srcIP, logs[i].dstPort);
        }
    }

    double totalBytes = 0;
    for (int i = 0; i < logCount; i++) {
        // Calculate average bandwidth usage based on packet sizes and timestamps
        totalBytes += logEntry[i].packetSize; // Assuming 'packetSize' is a field in the logEntry structure
    }
    printf("Average Bandwidth Usage: %.2f MB\n", totalBytes / 1024.0);

    free(parseBuffer);
    free(parseBuffer);
    return logs;
}

int cmpLogEntries(const void *a, const void *b) {
    time_t timestampA = ((logEntry *)a)->timestamp;
    time_t timestampB = ((logEntry *)b)->timestamp;

    if (timestampA < timestampB)
        return -1;
    else if (timestampA > timestampB)
        return 1;
    else
        return 0;
}

