struct record {
    int attack;
};

class AttackManager {
public:
    AttackManager(int numAttacks) : cooldownTimer(0), lastAttack(-1), records(numAttacks, { -1 }) {}

    void updateCooldown() {
        if (cooldownTimer > 0) {
            std::this_thread::sleep_for(std::chrono::seconds(cooldownTimer));
            cooldownTimer = 0;
        }
    }

    int executeAttack(int playerStrategy) {
        // Simulate random initial strategy
        for (auto& record : records) {
            if (record.attack == -1) {
                record.attack = rand() % numAttacks;
                break;
            }
        }

        while (true) {
            if (lastAttack != -1) {
                // Check cooldown and prevent consecutive use of the same attack
                if (records[lastAttack].attack != records[playerStrategy].attack && cooldownTimer == 0) {
                    int newAttack = playerStrategy;
                    lastAttack = newAttack;
                    return newAttack;
                } else {
                    // Cooldown is not yet over, wait for it to expire
                    updateCooldown();
                }
            } else {
                // No previous attack, execute the chosen one
                return playerStrategy;
            }
        }
    }

private:
    int cooldownTimer;
    int lastAttack;
    std::vector<record> records;
};

int main() {
    AttackManager manager(4);

    while (true) {
        int playerStrategy = 0; // Your code to determine the player's strategy
        int chosenAttack = manager.executeAttack(playerStrategy);
        std::cout << "Player chose attack: " << chosenAttack << std::endl;
        // Wait for a short time before next turn
        std::this_thread::sleep_for(std::chrono::milliseconds(1000));
    }

    return 0;
}
