#include <string.h>
#include <json-c/json.h>

typedef struct {
    char* method;
    int response_time;
} Request;

int parse_json(char* json_data, Request** requests) {
    json_object *jobj = NULL;
    json_object *request_obj = NULL;
    json_object_iter iter;
    int i = 0;

    jobj = json_object_from_string(json_data);
    if (!jobj) return -1;

    json_object_iter_init(&iter, jobj);

    while (json_object_iter_next(&iter)) {
        request_obj = json_object_get(iter.key);
        requests[i] = (Request*)malloc(sizeof(Request));
        strcpy(requests[i]->method, json_object_get_string(request_obj->value));
        requests[i]->response_time = json_object_get_int(request_obj->value);
        i++;
    }

    return i;
}

double calculate_average_response_time(Request** requests, int count) {
    double total_response_time = 0;

    for (int i = 0; i < count; i++) {
        if (requests[i]->response_time > -1)
            total_response_time += requests[i]->response_time;
    }

    return total_response_time / (count > 0 ? count : 1);
}

void free_requests(Request** requests, int count) {
    for (int i = 0; i < count; i++) {
        free(requests[i]);
    }
    free(requests);
}
