    for (int i = 0; i < OFFSET_ARRAY_SIZE; i++) {
        offsets[i] = (long)i;
    }
    for (int i = 0; i < KEY_ARRAY_SIZE; i++) {
        keys[i] = (i % 100);
    }
    for (int i = 0; i < RECORD_ARRAY_SIZE; i++) {
        records[i].value = rand() % record_max_value + 1;
    }

    // Read input array from standard input
    int input_index = 0;
    while (scanf("%d", &input[input_index++]) == 1 && input_index <= INPUT_ARRAY_SIZE) {}

    // Validate input and adjust array sizes accordingly
    if (input_index > OFFSET_ARRAY_SIZE + KEY_ARRAY_SIZE + RECORD_ARRAY_SIZE) {
        printf("Error: Input size exceeds total size of other arrays.\n");
        return;
    }

    // Find largest integer in the 'input' array and print it
    printLargest(input, input_index);

    // Convert each 'record' value to a string and append it to a buffer
    char* buffer = (char*)malloc((RECORD_ARRAY_SIZE * 10) + 1);
    for (int i = 0; i < RECORD_ARRAY_SIZE; i++) {
        sprintf(buffer + strlen(buffer), "%d ", records[i].value);
    }
    printf("Record values: %s\n", buffer);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(input);
    free(buffer);

    // Log memory allocation and deallocation events
    int log_level = 3;  // Adjust log level for verbosity
    FILE* log_file = fopen("log.txt", "w");
    if (log_file) {
        fprintf(log_file, "Memory allocated: %p (%d bytes)\n", offsets, OFFSET_ARRAY_SIZE * sizeof(long));
        fprintf(log_file, "Memory allocated: %p (%d bytes)\n", keys, KEY_ARRAY_SIZE * sizeof(int));
        fprintf(log_file, "Memory allocated: %p (%d bytes)\n", records, RECORD_ARRAY_SIZE * sizeof(struct record));
        fprintf(log_file, "Memory allocated: %p (%d bytes)\n", input, INPUT_ARRAY_SIZE * sizeof(int));
        fprintf(log_file, "Memory deallocated: %p\n", offsets);
        fprintf(log_file, "Memory deallocated: %p\n", keys);
        fprintf(log_file, "Memory deallocated: %p\n", records);
        fprintf(log_file, "Memory deallocated: %p\n", input);
        fclose(log_file);
    }
}

int main() {
    int offset_size = OFFSET_ARRAY_SIZE;
    int key_size = KEY_ARRAY_SIZE;
    int record_max_value = 100;
    int config_seed = time(NULL);

    processAndAnalyzeData(offset_size, key_size, record_max_value, &config_seed);

    return 0;
}
