record* processAndFindMax(int offset_count, int key_count) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for arrays and records
    long* offsets = (long*)malloc(offset_count * sizeof(long));
    int* keys = (int*)malloc(key_count * sizeof(int));
    record* records = (record*)malloc((offset_count + key_count) * sizeof(record));

    // Initialize array values
    for (int i = 0; i < offset_count; i++) {
        offsets[i] = rand() % INT_MAX;
    }
    for (int i = 0; i < key_count; i++) {
        keys[i] = rand() % INT_MAX;
    }

    // Initialize record values
    int record_index = 0;
    for (int i = 0; i < offset_count + key_count; i++) {
        records[record_index].value = rand() % INT_MAX;
        record_index++;
    }

    // Check array sizes
    if ((offset_count + key_count) > offset_count || (offset_count + key_count) > key_count) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    int* input_array = readInputArray();
    int max_value = findMaxValue(input_array, record_index);
    printf("Maximum value: %d at index %d\n", max_value, findIndex(input_array, max_value));

    // Free allocated memory
    free(input_array);
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int* readInputArray() {
    int input_size = 0;
    printf("Enter a list of integers (separated by spaces): ");
    while (1) {
        char c = getchar();
        if (c == '\n') break;
        if (c != ' ') continue;
        int value;
        scanf("%d", &value);
        input_size++;
    }
    int* array = (int*)malloc(input_size * sizeof(int));
    int index = 0;
    while (1) {
        char c = getchar();
        if (c == '\n') break;
        if (c != ' ') continue;
        scanf("%d", &value);
        array[index++] = value;
    }
    return array;
}

int findMaxValue(int* array, int size) {
    int max_value = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max_value) max_value = array[i];
    }
    return max_value;
}

int findIndex(int* array, int value) {
    for (int i = 0; i < sizeof(array)/sizeof(array[0]); i++) {
        if (array[i] == value) return i;
    }
    return -1;
}
