#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

// Define a struct to represent the 'struct element'
typedef struct {
    long int num;
    float val;
    char *str;
} Element;

// Function prototypes
Element* parse_csv_file(const char* filename);
void free_elements(Element** elements, int num_elements);

int main() {
    // Example usage: Read and parse a CSV file named 'data.csv'
    Element* elements = parse_csv_file("data.csv");

    if (elements) {
        // Process the parsed data
        for (int i = 0; i < elements->size; i++) {
            printf("%ld, %f, %s\n", elements[i].num, elements[i].val, elements[i].str);
        }

        // Free the allocated memory
        free_elements(&elements, elements->size);
    } else {
        printf("Error: Failed to parse CSV file.\n");
    }

    return 0;
}

Element* parse_csv_file(const char* filename) {
    FILE* file = fopen(filename, "r");

    if (!file) {
        fprintf(stderr, "Error: Could not open file '%s'.\n", filename);
        return NULL;
    }

    int num_elements = 0;
    Element** elements = NULL;

    // Read the CSV file line by line
    while (1) {
        char line[1024];
        if (!fgets(line, sizeof(line), file)) break;

        // Split the line into comma-separated values (CSV)
        int num_values = 0;
        const char* value = strtok(line, ",");
        while (value && num_values < 3) {
            switch (num_values++) {
                case 0:
                    elements = realloc(elements, sizeof(Element*) * ++num_elements);
                    if (!elements) {
                        fprintf(stderr, "Error: Out of memory.\n");
                        fclose(file);
                        return NULL;
                    }
                    elements[num_elements - 1]->num = strtol(value, NULL, 10);
                    break;
                case 1:
                    elements[num_elements - 1]->val = strtof(value, NULL);
                    break;
                case 2:
                    elements[num_elements - 1]->str = malloc(strlen(value) + 1);
                    if (!elements[num_elements - 1]->str) {
                        fprintf(stderr, "Error: Out of memory.\n");
                        fclose(file);
                        return NULL;
                    }
                    strcpy(elements[num_elements - 1]->str, value);
            }
            value = strtok(NULL, ",");
        }
    }

    // Free the file pointer and return the parsed elements
    fclose(file);

    return elements ? (Element*)elements : NULL;
}

void free_elements(Element** elements, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        if (elements[i]->str) free(elements[i]->str);
        free((void*)elements[i]);
    }
    free(elements);
}
