import java.time.Instant;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;

public class TrafficLogProcessor {
    private static final int DEFAULT_SESSION_TIMEOUT_MILLISECONDS = 30000; // 30 seconds
    private static final int DEFAULT_PACKET_THRESHOLD_MILLISECONDS = 5000; // 5 seconds

    public Map<String, Session> processTrafficLogs(Stream<TrafficLog> logStream) {
        Map<String, Session> sessions = new ConcurrentHashMap<>();
        AtomicLong lastSessionTime = new AtomicLong();
        long packetThreshold = System.currentTimeMillis() - DEFAULT_PACKET_THRESHOLD_MILLISECONDS;

        logStream.forEach(log -> {
            String sessionKey = getSessionKey(log.getSourceIp(), log.getDestinationIp());
            Instant logTimestamp = log.getTimestamp();

            if (!sessions.containsKey(sessionKey)) {
                sessions.put(sessionKey, new Session(lastSessionTime.get()));
                lastSessionTime.set(logTimestamp.toEpochMillisecond());
            } else {
                long timeElapsedSinceLastPacket = logTimestamp.toEpochMillisecond() - lastSessionTime.get();
                if (timeElapsedSinceLastPacket > DEFAULT_SESSION_TIMEOUT_MILLISECONDS) {
                    sessions.remove(sessionKey);
                } else {
                    lastSessionTime.set(logTimestamp.toEpochMillisecond());
                }
            }

            Session session = sessions.getOrDefault(sessionKey, null);
            if (session != null) {
                long packetInterval = logTimestamp.toEpochMillisecond() - lastSessionTime.get();
                session.addPacket(packetInterval);
                System.out.println("Processing log: " + (System.currentTimeMillis() - log.getTimestamp().toEpochMillisecond()));
            }
        });

        return sessions;
    }

    private String getSessionKey(String sourceIp, String destinationIp) {
        return sourceIp + "_" + destinationIp;
    }

    static class Session {
        private Instant lastPacketTime = Instant.now();
        private long totalPacketInterval = 0;

        public void addPacket(long packetInterval) {
            totalPacketInterval += packetInterval;
            lastPacketTime = Instant.now();
        }
    }
}
