typedef struct {
    long* offset;
    int* key;
    char data[64];
} record;

record* init_records(int num_records, size_t max_memory_usage) {
    record* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;

    if (num_records == 0 || max_memory_usage == 0) {
        return NULL; // or handle this as an error condition
    }

    // Calculate the required memory for each array
    size_t offsets_size = num_records * sizeof(long);
    size_t keys_size = num_records * sizeof(int);
    size_t records_size = num_records * sizeof(record);

    if ((offsets = (long*)malloc(offsets_size)) == NULL ||
        (keys = (int*)malloc(keys_size)) == NULL) {
        // Handle memory allocation failure
        free(offsets);
        return NULL;
    }

    // Initialize the arrays to zero
    memset(offsets, 0, offsets_size);
    memset(keys, 0, keys_size);

    if ((records = (record*)malloc(records_size)) == NULL) {
        // Handle memory allocation failure
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize the records to zero
    memset(records, 0, records_size);

    // Assign random keys to each record
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % INT_MAX;
    }

    // Ensure no two records have the same key
    for (int i = 1; i < num_records; i++) {
        int j;
        for (j = i - 1; j >= 0 && j < num_records; j--) {
            if (keys[i] == keys[j]) {
                break;
            }
        }
        if (j > 0) {
            keys[i] = rand() % INT_MAX;
        }
    }

    // Initialize the records' offset and key pointers
    for (int i = 0; i < num_records; i++) {
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
    }

    return records;
}

void free_records(record* records, int num_records) {
    if (records != NULL) {
        // Free the arrays in reverse order to avoid dangling pointers
        free(records);
        free((long*)records->offset);
        free((int*)records->key);
    }
}
