// Function to manage the dynamic array of rows
Row **manageRows(long numRecords, long* offsets, int* keys) {
    // Initialize the dynamic array with NULL pointers
    Row **rows = (Row **)malloc((numRecords + 1) * sizeof(Row *));
    for (int i = 0; i <= numRecords; i++) rows[i] = NULL;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < numRecords; i++) {
        Row *row = (Row *)malloc(sizeof(Row));
        row->pk = offsets[i];
        row->ts = keys[i];
        row->status = 1; // Initialize status to "new"
        row->lastUpdatedTs = i;
        pthread_mutex_lock(&lock);
        rows[row->pk % numRecords] = row;
        pthread_mutex_unlock(&lock);
    }

    return rows;
}

// Function to update the timestamp of a specific record
void updateTimestamp(Row **rows, long pk, int newTs) {
    for (int i = 0; i < numRecords; i++) {
        Row *row = rows[i];
        if (row->pk == pk) {
            row->ts = newTs;
            return;
        }
    }
}

// Function to serialize the data to disk
void serializeData(Row **rows, const char* filename) {
    FILE *file = fopen(filename, "wb");
    for (int i = 0; i < numRecords; i++) {
        Row *row = rows[i];
        fwrite(&row->pk, sizeof(long), 1, file);
        fwrite(&row->ts, sizeof(int), 1, file);
        fwrite(row->data, strlen(row->data) + 1, 1, file);
    }
    fclose(file);
}

// Function to deserialize the data from disk
Row **deserializeData(const char* filename) {
    FILE *file = fopen(filename, "rb");
    long numRecords;
    fread(&numRecords, sizeof(long), 1, file);
    Row **rows = (Row **)malloc((numRecords + 1) * sizeof(Row *));
    for (int i = 0; i <= numRecords; i++) {
        Row *row = (Row *)malloc(sizeof(Row));
        fread(&row->pk, sizeof(long), 1, file);
        fread(&row->ts, sizeof(int), 1, file);
        row->data = malloc(strlen(row->data) + 1);
        fread(row->data, strlen(row->data) + 1, 1, file);
    }
    fclose(file);
    return rows;
}

