@SpringBootApplication
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }

    @Bean
    public ObjectMapper objectMapper() {
        return new ObjectMapper();
    }

    @Bean
    public Jackson2ParamJenKinsModule jackson2ParamJenKinsModule(ObjectMapper mapper) {
        return new Jackson2ParamJenKinsModule().addMixInAnnotations(Properties.class, PropertiesMixin.class);
    }

    @Configuration
    public static class AppConfig {

        @Bean
        public Environment environment() {
            return SpringApplication.run(Application.class).getEnvironment();
        }
    }

    @RestController
    public class ConfigController {

        private final Environment environment;

        public ConfigController(Environment environment) {
            this.environment = environment;
        }

        @GetMapping("/config")
        public String getConfig() {
            // Read configuration settings from JSON file
            ObjectMapper mapper = new ObjectMapper();
            try {
                return mapper.writeValueAsString(environment.getProperty("config"));
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    static class PropertiesMixin extends Properties {

        private final List<String> values;

        public PropertiesMixin(List<String> values) {
            this.values = values;
        }
    }

