#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* process_module(long offset_count, long key_count, long record_count, int min_value, int max_value, int max_offset) {
    if (offset_count < 0 || key_count < 0 || record_count < 0 || 
        min_value > max_value || max_offset <= 0) {
        return NULL;
    }

    srand(time(NULL)); // initialize random seed

    record* records = (record*)malloc(record_count * sizeof(record));
    if (!records) {
        return NULL; // memory allocation failed
    }

    for (long i = 0; i < record_count; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    long* offsets = (long*)malloc(offset_count * sizeof(long));
    if (!offsets) {
        free(records); // deallocate partially allocated memory
        return NULL; // memory allocation failed
    }

    for (long i = 0; i < offset_count; i++) {
        offsets[i] = rand() % (max_offset - 1);
        while (i > 0 && offsets[i] == offsets[i-1]) { // ensure uniqueness
            offsets[i] = rand() % (max_offset - 1);
        }
    }

    int* keys = (int*)malloc(key_count * sizeof(int));
    if (!keys) {
        free(offsets); // deallocate partially allocated memory
        free(records);
        return NULL; // memory allocation failed
    }

    for (long i = 0; i < key_count; i++) {
        keys[i] = rand() % (max_offset - 1);
    }

    // all memory allocated, now return the module
    record* module = (record*)malloc(sizeof(record) + offset_count * sizeof(long) + key_count * sizeof(int));
    if (!module) {
        free(offsets); 
        free(keys);
        free(records);
        return NULL; // memory allocation failed
    }

    module->offsets = (long*)((char*)module + sizeof(record));
    module->keys = (int*)((char*)module + sizeof(record) + offset_count * sizeof(long));

    for (long i = 0; i < record_count; i++) {
        module->records[i] = records[i];
    }

    for (long i = 0; i < offset_count; i++) {
        module->offsets[i] = offsets[i];
    }

    for (long i = 0; i < key_count; i++) {
        module->keys[i] = keys[i];
    }

    // all allocated memory is freed
    free(offsets);
    free(keys);
    free(records);

    return module;
}
