    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));
    record *records = malloc(record_max * sizeof(record));
    event *events = malloc(event_max * sizeof(event));

    if (offsets == NULL || keys == NULL || records == NULL || events == NULL) {
        fprintf(log_file, "Error allocating memory.\n");
        fclose(log_file);
        return;
    }

    // Initialize arrays based on user-provided input
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = rand() % 100 + 1;
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % 10;
    }

    // Populate the record array with random integers
