        records[i].value = rand() % 10000 + 1;
    }

    // Initialize the event array with timestamps and types
    time_t current_time = time(NULL);
    for (int i = 0; i < event_max; i++) {
        events[i].timestamp = current_time + i * 10;
        events[i].type = rand() % 2 ? 1 : 2;
    }

