        printf("%d ", records[i].value);
    }
    printf("\n");
    printf("Events: ");
    for (int i = 0; i < event_max; i++) {
        printf("%ld %d\n", events[i].timestamp, events[i].type);
    }

    // Clean up memory allocation
    free(offsets);
    free(keys);
    free(records);
    free(events);
    fclose(log_file);
