// Function to generate a random number within a given range
int rand_range(int min, int max) {
    static unsigned seed = time(NULL);
    return (rand() % (max - min + 1)) + min;
}

// Function to initialize the arrays and record structures
void init_arrays_and_records(int* num_offsets, int* num_keys) {
    // Allocate memory for offset array
    long** offsets = (long**)malloc(*num_offsets * sizeof(long*));
    for (int i = 0; i < *num_offsets; i++) {
        offsets[i] = (long*)malloc(sizeof(long));
    }

    // Allocate memory for key array
    int** keys = (int**)malloc(*num_keys * sizeof(int*));
    for (int i = 0; i < *num_keys; i++) {
        keys[i] = (int*)malloc(sizeof(int));
    }

    // Initialize the offset and key arrays
    for (int i = 0; i < *num_offsets; i++) {
        offsets[i][0] = i;
    }
    for (int i = 0; i < *num_keys; i++) {
        keys[i][0] = i;
    }

    // Allocate memory for record array
    record** records = (record**)malloc(*num_keys * sizeof(record*));
    for (int i = 0; i < *num_keys; i++) {
        records[i] = (record*)malloc(sizeof(record));
    }

    // Initialize the record array
    for (int i = 0; i < *num_keys; i++) {
        records[i]->value = rand_range(1, 100);
    }
}

// Function to handle memory deallocation
void clean_up(int* num_offsets, int* num_keys) {
    // Free the offset array
    for (int i = 0; i < *num_offsets; i++) {
        free(offsets[i]);
    }
    free((long*)offsets);

    // Free the key array
    for (int i = 0; i < *num_keys; i++) {
        free(keys[i]);
    }
    free(keys);

    // Free the record array
    for (int i = 0; i < *num_keys; i++) {
        free(records[i]);
    }
    free(records);
}

int main() {
    int num_offsets, num_keys;
    printf("Enter number of offsets: ");
