    // Validate user input to prevent buffer overflows
    if (num_offsets > 1000) {
        fprintf(stderr, "Invalid number of offsets. Max allowed is 1000.\n");
        return 1;
    }

    printf("Enter number of keys: ");
    scanf("%d", &num_keys);

    // Validate user input to prevent buffer overflows
    if (num_keys > 1000) {
        fprintf(stderr, "Invalid number of keys. Max allowed is 1000.\n");
        return 1;
    }

    init_arrays_and_records(&num_offsets, &num_keys);
    clean_up(&num_offsets, &num_keys);

    return 0;
}
