#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Custom hash function for the hash table
unsigned long custom_hash(unsigned long id) {
    return id % 1000; // Hashing the ID to a 4-digit number
}

typedef struct Entry {
    double value;
    unsigned long id;
    char name[16]; // Fixed-length string
} Entry;

typedef struct {
    pthread_mutex_t lock;
    int capacity;
    int size;
    Entry **entries;
} HashTable;

HashTable* init_hash_table(int initial_capacity) {
    HashTable *table = (HashTable*) malloc(sizeof(HashTable));
    table->capacity = initial_capacity;
    table->size = 0;
    table->entries = (Entry**) calloc(table->capacity, sizeof(Entry*));

    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void insert_entry(HashTable *table, unsigned long id, double value, char name[]) {
    int index = custom_hash(id) % table->capacity;

    pthread_mutex_lock(&table->lock);
    Entry *new_entry = (Entry*) malloc(sizeof(Entry));
    new_entry->id = id;
    new_entry->value = value;
    strcpy(new_entry->name, name);

    if (table->size == table->capacity) {
        // Rehashing mechanism to handle full capacity
        int old_capacity = table->capacity;
        table->capacity *= 2; // Double the capacity
        table->entries = (Entry**) realloc(table->entries, table->capacity * sizeof(Entry*));

        for (int i = old_capacity; i < table->capacity; i++) {
            table->entries[i] = NULL;
        }
    }

    if (table->entries[index] == NULL) {
        // Insertion into an empty slot
        table->entries[index] = new_entry;
    } else {
        // Collision, need to rehash the entry
        int j = (index + 1) % table->capacity; // Linear probing
        while (table->entries[j] != NULL) {
            j = (j + 1) % table->capacity;
        }
        table->entries[j] = new_entry;
    }

    table->size++;
    pthread_mutex_unlock(&table->lock);
}

void cleanup_hash_table(HashTable *table) {
    for (int i = 0; i < table->capacity; i++) {
        if (table->entries[i] != NULL) {
            free(table->entries[i]);
        }
    }

    free(table->entries);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

void query_hash_table(HashTable *table, unsigned long id) {
    int index = custom_hash(id) % table->capacity;
    pthread_mutex_lock(&table->lock);
    if (table->entries[index] != NULL && table->entries[index]->id == id) {
        printf("Found entry with ID %lu and value %.2lf\n", id, table->entries[index]->value);
    } else {
        printf("No entry found with ID %lu\n", id);
    }
    pthread_mutex_unlock(&table->lock);
}

int main() {
    HashTable *table = init_hash_table(10);

    // Example usage
    insert_entry(table, 1, 3.14, "John");
    insert_entry(table, 2, 4.21, "Jane");
    query_hash_table(table, 1);
    query_hash_table(table, 3); // Should print "No entry found with ID 3"

    cleanup_hash_table(table);

    return 0;
}
