#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Custom memory pool structure
typedef struct {
    void* ptr;
    size_t size;
} MemBlock;

// Initialize custom memory pool
MemBlock* init_pool(size_t max_size) {
    MemBlock* pool = (MemBlock*)malloc(sizeof(MemBlock));
    pool->ptr = NULL;
    pool->size = max_size;
    return pool;
}

// Allocate memory from custom pool
void* alloc_from_pool(MemBlock* pool, size_t size) {
    if (pool->ptr == NULL || pool->size - ((char*)pool->ptr - (char*)0) >= size) {
        void* ptr = malloc(size);
        return ptr;
    } else {
        // Reuse existing memory block
        return (void*)((char*)pool->ptr + pool->size - ((char*)pool->ptr - (char*)0));
    }
}

// Deallocate memory from custom pool
void dealloc_from_pool(MemBlock* pool, void* ptr) {
    free(ptr);
    if (pool->ptr == ptr)
        pool->ptr = NULL;
    else if ((char*)ptr + strlen((char*)ptr) > (char*)pool->ptr && (char*)pool->ptr + pool->size - ((char*)pool->ptr - (char*)0) >= strlen((char*)ptr)) {
        pool->size -= ((char*)ptr - (char*)0) - ((char*)pool->ptr - (char*)0);
        pool->ptr = ptr;
    }
}

// Record structure
typedef struct {
    int val;
} record;

record* records;

int main() {
    // Initialize memory pool and arrays
    MemBlock* mem_pool = init_pool(1024 * 1024); // 1MB custom memory pool

