    printf("Enter number of offsets: ");
    scanf("%d", &num_offsets);
    printf("Enter number of keys: ");
    scanf("%d", &num_keys);

    long* offsets = (long*)alloc_from_pool(mem_pool, num_offsets * sizeof(long));
    int* keys = (int*)alloc_from_pool(mem_pool, num_keys * sizeof(int));

    // Initialize arrays
    for (int i = 0; i < num_offsets; i++) {
