    if (!keys) {
        free(offsets);
        return NULL;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i;
    }

    // Allocate memory for records
    records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        free(offsets);
