#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Custom structure for metadata
typedef struct {
    char* key;
    int value;
} metadata;

// Hash table with chaining
typedef struct {
    int size;
    metadata** buckets;
} hash_table;

// Function to initialize the hash table
hash_table* init_hash_table(int size) {
    hash_table* table = (hash_table*)malloc(sizeof(hash_table));
    table->size = size;
    table->buckets = (metadata**)calloc(size, sizeof(metadata*));
    return table;
}

// Function to insert a record into the database
void insert_record(hash_table* table, int key, metadata* meta) {
    int index = key % table->size;
    if (!table->buckets[index]) {
        table->buckets[index] = (metadata*)malloc(sizeof(metadata));
        strcpy(table->buckets[index]->key, meta->key);
        table->buckets[index]->value = meta->value;
    } else {
        // Handle collision by chaining
        metadata* current = table->buckets[index];
        while (current) {
            if (!strcmp(current->key, meta->key)) {
                return;  // Key already exists
            }
            current = current->next;
        }
        current = (metadata*)malloc(sizeof(metadata));
        strcpy(current->key, meta->key);
        current->value = meta->value;
        current->next = table->buckets[index];
        table->buckets[index] = current;
    }
}

// Function to lookup a record in the database
metadata* lookup_record(hash_table* table, int key) {
    int index = key % table->size;
    metadata* current = table->buckets[index];
    while (current) {
        if (key == atoi(current->key)) {
            return current;
        }
        current = current->next;
    }
    return NULL;  // Record not found
}

// Function to delete a record from the database
void delete_record(hash_table* table, int key) {
    int index = key % table->size;
    metadata* current = table->buckets[index];
    metadata* prev = NULL;
    while (current) {
        if (key == atoi(current->key)) {
            if (!prev) {
                table->buckets[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            return;  // Record deleted
        }
        prev = current;
        current = current->next;
    }
}

// Function to free the hash table and its contents
void free_hash_table(hash_table* table) {
    for (int i = 0; i < table->size; i++) {
        metadata* current = table->buckets[i];
        while (current) {
            metadata* next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    free(table);
}
