typedef struct {
    int value;
    char* identifier;
} record_t;

void manage_memory(int offset, int key) {
    record_t* records = (record_t*)malloc(MAX_RECORDS * sizeof(record_t));
    if (!records) {
        LOG_ERROR("Memory allocation failed");
        return;
    }

    for (int i = 0; i < offset; i++) {
        char* identifier = (char*)malloc(MAX_STRING_LENGTH);
        if (!identifier) {
            LOG_ERROR("Memory allocation failed");
            free(records);
            return;
        }
        // Initialize the record and identifier
        records[i].value = key + i;
        sprintf(identifier, "record_%d", i);
        records[i].identifier = identifier;
    }

    // Log memory usage statistics
    LOG_INFO("Total allocated memory: %zu bytes", offset * (sizeof(record_t) + MAX_STRING_LENGTH));

    // Free the memory when done
    for (int i = 0; i < offset; i++) {
        free(records[i].identifier);
    }
    free(records);

    clock_t end = clock();
    double runtime = (double)(end - clock()) / CLOCKS_PER_SEC;
    if (runtime > 2) {
        LOG_WARNING("Function took %.2f seconds to complete", runtime);
    }
}

