#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure definition for record data
typedef struct {
    int key;
    long offset;
} Record;

// Function to read CSV file and allocate memory for arrays
Record** read_csv_file(const char* filename) {
    // Open the file for reading
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        return NULL;
    }

    // Initialize counters and arrays
    int record_count = 0;
    long* offsets = NULL;
    int* keys = NULL;
    Record** records = NULL;

    // Read the CSV file line by line
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Split the line into two integers using sscanf()
        int key, offset;
        if (sscanf(line, "%d,%ld", &key, &offset) == 2) {
            // Allocate memory for new record
            Record* new_record = (Record*)malloc(sizeof(Record));
            if (!new_record) {
                fclose(file);
                fprintf(stderr, "Memory allocation failed\n");
                return NULL;
            }
            new_record->key = key;
            new_record->offset = offset;

            // Update counters and arrays
            record_count++;
            offsets = (long*)realloc(offsets, sizeof(long) * record_count);
            keys = (int*)realloc(keys, sizeof(int) * record_count);
            records = (Record**)realloc(records, sizeof(Record*) * record_count);

            if (!offsets || !keys || !records) {
                fclose(file);
                fprintf(stderr, "Memory allocation failed\n");
                return NULL;
            }

            offsets[record_count - 1] = offset;
            keys[record_count - 1] = key;
            records[record_count - 1] = new_record;
        }
    }

    // Close the file
    fclose(file);

    if (record_count == 0) {
        fprintf(stderr, "No data found in CSV file\n");
        return NULL;
    }

    // Check for memory efficiency and adjust accordingly
    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        for (int i = 0; i < record_count; i++) {
            free(records[i]);
        }
        free(records);
        return NULL;
    }

    // Return pointers to initialized arrays
    return records;
}
