// Function to dynamically allocate memory for 'record' instances within a pool
int* manageMemory(int numRecords, int rangeStart, int rangeEnd) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for the record array with initial values
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->id = rand() % (rangeEnd - rangeStart + 1) + rangeStart;
    }

    // Return the record array
    return (int*)records[0];
}

// Function to free allocated memory and clean up
void cleanupMemory(int* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free((void*)records[i]);
    }
    free((void*)records);
}
