    } else {
        key_len = AES_384_KEYBIT;
        iv_len = AES_BLOCK_SIZE;
    }

    // Derive encryption key from password using KDF
    unsigned char* key = (unsigned char*)malloc(key_len);
    unsigned char* salt = (unsigned char*)malloc(8);
    int kdf_result = EVP_KDF(password, strlen(password), NULL, 0, salt, 8, key_len, key);
    if (kdf_result != 1) {
        // Handle KDF failure
    }

    // Initialize AES-256-CBC cipher with derived key and IV
    AES_KEY aes_key;
    EVP_DecodeBlock(&aes_key, key, key_len);
    unsigned char iv[AES_BLOCK_SIZE];
    int iv_result = RAND_bytes(iv, AES_BLOCK_SIZE);
    if (iv_result != 1) {
        // Handle IV generation failure
    }
    cipher_ctx->ctx = AES_new();
    AES_set_encrypt_key(&aes_key, key_len, cipher_ctx->ctx);
    AES_set_iv(cipher_ctx->ctx, iv);

    // Initialize lock for concurrent access
    pthread_mutex_init(&cipher_ctx->lock, NULL);

    return cipher_ctx;
}

void clean_up_cipher(CipherContext* cipher_ctx) {
    if (cipher_ctx != NULL) {
        AES_free(cipher_ctx->ctx);
        free(cipher_ctx);
    }
}
