long processAndFindMax(int offset_length, int key_length, int record_length) {
    long *offset = (long *)malloc(offset_length * sizeof(long));
    if (!offset) return -1; // Handle memory allocation error
    int i;
    for (i = 0; i < offset_length; i++) {
        offset[i] = i * 2;
    }

    int *key = (int *)malloc(key_length * sizeof(int));
    if (!key) return -1; // Handle memory allocation error
    for (i = 0; i < key_length; i++) {
        key[i] = i * 3;
    }

    record_t *record = (record_t *)malloc(record_length * sizeof(record_t));
    if (!record) return -1; // Handle memory allocation error

    int input_length = offset_length + key_length + record_length;
    int *input = (int *)malloc(input_length * sizeof(int));
    if (!input) return -1; // Handle memory allocation error
    for (i = 0; i < input_length; i++) {
        input[i] = rand() % 100;
    }

    printf("offset: ");
    for (i = 0; i < offset_length; i++) {
        printf("%ld ", offset[i]);
    }
    printf("\n");
    printf("key: ");
    for (i = 0; i < key_length; i++) {
        printf("%d ", key[i]);
    }
    printf("\n");
    printf("record: ");
    for (i = 0; i < record_length; i++) {
        printf("%d ", record[i].value);
    }
    printf("\n");
    printf("input: ");
    for (i = 0; i < input_length; i++) {
        printf("%d ", input[i]);
    }
    printf("\n");

    int max_input = findMax(input, input_length);
    free(offset);
    free(key);
    free(record);
    free(input);

    return max_input;
}

int findMax(int *arr, int length) {
    int max = arr[0];
    for (int i = 1; i < length; i++) {
        if (arr[i] > max) max = arr[i];
    }
    return max;
}
