#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MIN_RANDOM_VALUE 1
#define MAX_RANDOM_VALUE 1000
#define ERROR_CODE -1

typedef struct {
    int key;
} record_t;

int load_resource_bundle(const char *file_path, int **offsets, int ***keys) {
    FILE *fp = fopen(file_path, "rb");
    if (!fp) {
        return ERROR_CODE; // File not found
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    rewind(fp);

    *offsets = (int *)malloc(MAX_RECORDS * sizeof(int));
    *keys = (int **)malloc(MAX_RECORDS * sizeof(int *));
    for (int i = 0; i < MAX_RECORDS; i++) {
        (*keys)[i] = (int *)malloc(sizeof(int));
    }

    int num_records = file_size / sizeof(record_t);
    if (!num_records) {
        return ERROR_CODE; // File is corrupted
    }

    for (int i = 0; i < num_records; i++) {
        record_t rec;
        fread(&rec, sizeof(rec), 1, fp);

        (*offsets)[i] = rec.key;

        srand(time(NULL)); // Initialize random seed
        int random_value = (rand() % (MAX_RANDOM_VALUE - MIN_RANDOM_VALUE + 1)) + MIN_RANDOM_VALUE;
        (*keys)[i][0] = random_value;
    }

    fclose(fp);
    return num_records;
}
