record* init_memory(int n, long* offsets, int* keys, int min_val, int max_val) {
    if (n <= 0 || min_val > max_val) {
        return NULL;
    }

    // Initialize configuration settings
    int config_min_val = get_config_min_val();
    int config_max_val = get_config_max_val();

    // Check for updates every 60 seconds and reload settings if necessary
    while (config_min_val != min_val || config_max_val != max_val) {
        sleep(60);
        config_min_val = get_config_min_val();
        config_max_val = get_config_max_val();
    }

    // Allocate memory for arrays
    record* records = malloc(n * sizeof(record));
    offsets = malloc(n * sizeof(long));
    keys = malloc(n * sizeof(int));

    if (records == NULL || offsets == NULL || keys == NULL) {
        return NULL;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        record temp_record;
        temp_record.val = rand() % ((max_val - min_val + 1)) + min_val;
        records[i] = temp_record;

        offsets[i] = i;
        keys[i] = i;
    }

    // Log initialization process
    FILE* log_file = fopen("init_log.txt", "w");
    if (log_file == NULL) {
        return NULL;
    }
    for (int i = 0; i < n; i++) {
        fprintf(log_file, "Record %d: %d\n", i, records[i].val);
    }
    fclose(log_file);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}
