#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    char* label;
    double scale_factor;
    bool flag;
} ConfigEntry;

int load_config(char* json_file, ConfigEntry** config_entries) {
    json_object* json_obj = json_load_file(json_file, JSON_OPTION_NULL_ON_ERROR);
    if (!json_obj) {
        return -1; // Error reading JSON file
    }

    int num_entries = 0;
    char** labels = NULL;
    double* scale_factors = NULL;
    bool* flags = NULL;

    // Allocate memory for arrays
    while (1) {
        json_object* entry_obj = json_object_object_get(json_obj, "entry");
        if (!entry_obj) break; // End of array

        char* label = json_object_get_string(entry_obj, "label");
        double scale_factor = json_object_get_double(entry_obj, "scale_factor");
        bool flag = json_object_get_bool(entry_obj, "flag");

        // Check for duplicate labels
        int i;
        for (i = 0; i < num_entries; i++) {
            if (!strcmp(labels[i], label)) {
                free(label);
                break;
            }
        }

        if (i == num_entries) { // New unique label
            num_entries++;
            labels = realloc(labels, sizeof(char*) * num_entries);
            scale_factors = realloc(scale_factors, sizeof(double) * num_entries);
            flags = realloc(flags, sizeof(bool) * num_entries);

            labels[num_entries - 1] = strdup(label);
            scale_factors[num_entries - 1] = scale_factor;
            flags[num_entries - 1] = flag;
        }

        json_object_object_item_free(entry_obj);
    }

    // Free remaining JSON objects
    while (json_object_object_item(json_obj)) {
        json_object_object_item_free(json_object_object_item(json_obj));
    }
    json_object_free(json_obj);

    *config_entries = malloc(sizeof(ConfigEntry) * num_entries);
    for (int i = 0; i < num_entries; i++) {
        (*config_entries)[i].label = labels[i];
        (*config_entries)[i].scale_factor = scale_factors[i];
        (*config_entries)[i].flag = flags[i];
    }

    return num_entries;
}
