#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <random>

// Define the maximum number of records in a bundle
#define MAX_RECORDS 1000

// Define the maximum size of a record
#define RECORD_SIZE sizeof(int)

// Define the error codes for the function
#define OK 0
#define MEMORY_ERROR 1
#define FILE_ERROR 2
#define PARSE_ERROR 3

long offsets[MAX_RECORDS];
int keys[MAX_RECORDS];

// Function to dynamically load a resource bundle from a specified file and return the number of items in the bundle.
int loadResourceBundle(const char *filename) {
    int i, j;
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", filename);
        return MEMORY_ERROR;
    }

    // Initialize the arrays
    for (i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = -1;
        keys[i] = rand() % 10000; // Generate a random key value within a specified range
    }

    int count = 0;
    char buffer[RECORD_SIZE];

    while (fgets(buffer, RECORD_SIZE, file) != NULL && count < MAX_RECORDS) {
        int offset = ftell(file);
        if (sscanf(buffer, "%d", &keys[count]) == 1) {
            offsets[count] = offset;
            count++;
        } else {
            printf("Error parsing record at offset %ld\n", offset);
            fclose(file);
            return PARSE_ERROR;
        }
    }

    fclose(file);

    // If the number of records exceeds the initial allocated capacity, dynamically resize the arrays
    if (count > MAX_RECORDS) {
        offsets = (long *)realloc(offsets, sizeof(long) * count);
        keys = (int *)realloc(keys, sizeof(int) * count);
        printf("Dynamically resized arrays to accommodate %d records\n", count);
    }

    return OK;
}
