void processAndFindMax(int offset_size, int key_size, int record_size, FILE *file) {
    srand(time(NULL));

    long *offset = (long *)malloc(offset_size * sizeof(long));
    for (int i = 0; i < offset_size; i++) {
        offset[i] = i;
    }

    int *key = (int *)malloc(key_size * sizeof(int));
    for (int i = 0; i < key_size; i++) {
        key[i] = i + 1;
    }

    record *record_arr = (record *)malloc(record_size * sizeof(record));
    for (int i = 0; i < record_size; i++) {
        record_arr[i].value = rand() % 100;
    }

    int *input = (int *)malloc(sizeof(int));
    *input = 10;

    int max_input = findMax(input);
    printf("Maximum input: %d\n", max_input);

    double avg_input = calculateAverage(input, file);
    printf("Average input: %.2f\n", avg_input);

    free(offset);
    free(key);
    free(record_arr);
    free(input);
}

int findMax(int *arr) {
    int max = arr[0];
    for (int i = 1; i < 100; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

double calculateAverage(int *arr, FILE *file) {
    int sum = 0;
    int count = 0;

    while(fscanf(file, "%d", &arr[count]) == 1) {
        sum += arr[count];
        count++;
    }

    double avg = (double)sum / count;
    return avg;
}
