    if (file == NULL) {
        printf("Error opening file: %s\n", config->input_file);
        return NULL;
    }

    int num_records = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        ++num_records;
    }
    rewind(file);

    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));

    for (int i = 0; i < num_records; i++) {
        if (!fgets(line, sizeof(line), file)) break;

        char *token = strtok(line, ",");
        if (token == NULL) continue;
        keys[i] = atoi(token);

        token = strtok(NULL, ",");
        if (token == NULL) continue;
        offsets[i] = atoll(token);
    }

    fclose(file);

    record *records = malloc(num_records * sizeof(record));
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    return records;
}

