#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long offset;
} record;

void* memory_init(int offsets_size, int keys_size, int records_size, int max_offset_value, int max_key_value, int seed) {
    srand(seed);

    // Initialize arrays
    long* offsets = (long*)malloc(offsets_size * sizeof(long));
    if (!offsets) return NULL;

    int* keys = (int*)malloc(keys_size * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record* records = (record*)malloc(records_size * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize arrays with random values
    for (int i = 0; i < offsets_size; i++) {
        offsets[i] = rand() % max_offset_value;
    }

    for (int i = 0; i < keys_size; i++) {
        int offset_idx = i % offsets_size;
        keys[i] = (rand() % max_key_value) ^ (long)offsets[offset_idx];
    }

    for (int i = 0; i < records_size; i++) {
        record* current_record = &records[i];
        current_record->value = rand() % max_offset_value;
        current_record->offset = offsets[rand() % offsets_size];
    }

    return records;
}

void memory_free(void* ptr) {
    if (!ptr) return;

    record* records = (record*)ptr;
    free(records);
}
