        strcpy(descriptions[idCount], description);

        totalAmount += amount;

        idCount++;

        if (idCount >= batchSize) {
            // Process the batch
            break;
        }
    }

    // Free allocated memory
    for (int i = 0; i < idCount; i++) {
        delete[] descriptions[i];
    }

    if (totalAmount > 100000.0) {
        // Handle large transaction amount
    }

    // Print array contents for debugging
    for (int i = 0; i < idCount; i++) {
        printf("Transaction ID: %ld, Amount: %f, Description: %s\n", transactionIDs[i], amounts[i], descriptions[i]);
    }
