Python Class:
```python
import json
import logging

class RecordManager:
    def __init__(self):
        self.factory_registry = {}
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    def add_factory(self, id, factory_func):
        if id not in self.factory_registry:
            self.factory_registry[id] = factory_func
        else:
            self.logger.warning(f"Factory function for ID {id} already registered.")

    def create_instance(self, json_data, id):
        try:
            data = json.loads(json_data)
            factory_func = self.factory_registry.get(id)
            if not factory_func:
                raise ValueError(f"No factory function found for ID {id}")
            return factory_func(data)
        except (json.JSONDecodeError, KeyError) as e:
            self.logger.error(f"Failed to deserialize JSON: {e}")
            return None

    def serialize(self, records):
        data = []
        for record in records:
            data.append({"key": record.key, "offset": record.offset})
        return json.dumps(data)

    def deserialize(self, json_data):
        try:
            data = json.loads(json_data)
            if not isinstance(data, list):
                raise ValueError("Invalid JSON format")
            return [record_t(**record) for record in data]
        except (json.JSONDecodeError, KeyError) as e:
            self.logger.error(f"Failed to deserialize JSON: {e}")
            return None
```

