record* create_record(int val) {
    record* new_rec = (record*)malloc(sizeof(record));
    if (!new_rec) return NULL; // Handle allocation failure
    new_rec->value = val;
    new_rec->offset = NULL;
    return new_rec;
}

int main() {
    int num_records = 1000;
    long* offset_arr = (long*)calloc(num_records, sizeof(long));
    int* key_arr = (int*)calloc(num_records, sizeof(int));
    record** records = (record**)calloc(num_records, sizeof(record*));

    // Initialize random seed
    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        record* rec = create_record(rand() % 100 + 1);
        if (!rec) break;
        offset_arr[i] = (long)i;
        key_arr[i] = rand() % 10 + 1;
        records[i] = &rec;
    }

    // Insert and delete records based on keys
    for (int i = 0; i < num_records; i++) {
        if (key_arr[i] == 5) {
            // Delete record with key 5
            int j;
            for (j = i; j < num_records - 1; j++) {
                offset_arr[j] = offset_arr[j + 1];
                key_arr[j] = key_arr[j + 1];
                records[j] = records[j + 1];
            }
            free(records[j]->offset);
            free(records[j]);
            num_records--;
        } else if (key_arr[i] == 7) {
            // Insert record with key 7
            record* rec = create_record(rand() % 100 + 1);
            int j;
            for (j = num_records; j > i; j--) {
                offset_arr[j] = offset_arr[j - 1];
                key_arr[j] = key_arr[j - 1];
                records[j] = records[j - 1];
            }
            offset_arr[i] = (long)i;
            key_arr[i] = 7;
            records[i] = &rec;
        }
    }

    // Free allocated memory
    for (int i = 0; i < num_records; i++) {
        free(records[i]->offset);
        free(records[i]);
    }
    free(offset_arr);
    free(key_arr);
    free(records);

    return 0;
}
