import json
from abc import ABCMeta, abstractmethod

class Record(metaclass=ABCMeta):
    def __init__(self, key, offset):
        self.key = key
        self.offset = offset

class RecordManager:
    _registry = {}
    _lock = threading.Lock()

    @classmethod
    def add_factory(cls, id, factory):
        cls._registry[id] = factory

    @classmethod
    def get_record(cls, id):
        return cls._registry[id]().record

    @classmethod
    def serialize_records(cls, records):
        return json.dumps([{"key": r.key, "offset": r.offset} for r in records])

    @classmethod
    def deserialize_records(cls, serialized_data):
        data = json.loads(serialized_data)
        return [Record(record["key"], record["offset"]) for record in data]

# Example usage:
record_manager = RecordManager()

# Add a factory function for a specific record type
