    int* data = (int*)malloc(dataSize * sizeof(int));
    int* index = (int*)malloc(indexSize * sizeof(int));
    int* value = (int*)malloc(valueRange * sizeof(int));

    // Initialize index and data arrays with specific values
    for (int i = 0; i < dataSize; i++) {
        data[i] = i;
    }
    for (int i = 0; i < indexSize; i++) {
        index[i] = i;
