    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, valueRange);

    for (int i = 0; i < valueRange; i++) {
        value[i] = dis(gen);
    }

    // Verify total size of value array does not exceed combined size of data and index arrays
