Records* initRecords(size_t initialCapacity) {
    Records* records = (Records*)malloc(sizeof(Records));
    records->capacity = initialCapacity;
    records->size = 0;
    records->records = (Record*)calloc(initialCapacity, sizeof(Record));
    return records;
}

void freeRecords(Records* records) {
    if (records != NULL) {
        free(records->records);
        free(records);
    }
}

int addRecord(Records* records, int offset, char key[]) {
    if (records == NULL || records->size >= records->capacity) {
        return -1; // error: out of memory or record limit reached
    }

    Record* newRecord = &records->records[records->size];
    newRecord->offset = offset;
    strcpy(newRecord->key, key);

    records->size++;

    if (records->size >= records->capacity * 0.7) {
        // resize array to double the capacity
        records->capacity *= 2;
        records->records = (Record*)realloc(records->records, records->capacity * sizeof(Record));
    }

    return 0; // success
}

int loadResourceBundle(Records* records, char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // error: file not found or failed to open
    }

    fseek(file, 0L, SEEK_END);
    size_t fileSize = ftell(file);
    rewind(file);

    char* buffer = (char*)malloc(fileSize);
    fread(buffer, 1, fileSize, file);
    fclose(file);

    // parse the resource bundle data...

    return 0; // success
}

int main() {
    Records* records = initRecords(10);
    addRecord(records, 42, "my_key");
    // ...
    freeRecords(records);
    return 0;
}
