    Record* record = (Record*)malloc(sizeof(Record) * offset_size);
    for (int i = 0; i < offset_size; i++) {
        record[i].value = rand() % 100;
    }

    // Caching strategy for frequently accessed random numbers
    int cache_size = 10;
    int* cache = (int*)malloc(sizeof(int) * cache_size);
    for (int i = 0; i < cache_size; i++) {
        cache[i] = record[rand() % offset_size].value;
