typedef struct {
    double sensor_reading;
    int timestamp;
    char unit[50];
} measurement;

measurement* allocate_and_init_measurements(int num_measurements) {
    measurement* measurements = (measurement*)malloc(num_measurements * sizeof(measurement));

    if (!measurements) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_measurements; i++) {
        measurement* current_measurement = &measurements[i];

        current_measurement->sensor_reading = ((double)rand()) / RAND_MAX * 100.0;
        current_measurement->timestamp = rand() % 86400;

        for (int j = 0; j < 50; j++) {
            measurements[i].unit[j] = 'C';
        }
        measurements[i].unit[49] = '\0'; // Null terminate the string

        if (current_measurement->sensor_reading < 10.0 || current_measurement->sensor_reading > 90.0) {
            free(measurements);
            return NULL;
        }
    }

    return measurements;
}

void filter_measurements(measurement* measurements, int num_measurements) {
    for (int i = 0; i < num_measurements; i++) {
        if (measurements[i].sensor_reading < 10.0 || measurements[i].sensor_reading > 90.0) {
            // Exclude measurements with sensor readings outside the range
            for (int j = i + 1; j < num_measurements; j++) {
                measurements[j - 1] = measurements[j];
            }
            num_measurements--;
            i--;
        }
    }
}

void sort_measurements(measurement* measurements, int num_measurements) {
    qsort(measurements, num_measurements, sizeof(measurement), (int (*)(const void*, const void*))compare_measurements);
}

int compare_measurements(const void* a, const void* b) {
    measurement* measurement_a = (measurement*)a;
    measurement* measurement_b = (measurement*)b;

    return measurement_a->timestamp - measurement_b->timestamp;
}
