from collections import defaultdict

class ConfigManager:
    def __init__(self):
        self.config_file = 'config.txt'
        self.placeholder_dict = {}

    def enhance_config(self, placeholders):
        self.placeholder_dict.update(placeholders)

        with open(self.config_file, 'r') as f:
            config_text = f.read()

        updated_text = ''
        for line in config_text.split('\n'):
            if '{' in line:
                placeholder_name = line.split('{')[1].split('}')[0]
                value = self.placeholder_dict.get(placeholder_name)
                if value is not None:
                    updated_text += line.format(value) + '\n'
                else:
                    updated_text += line + '\n'
            else:
                updated_text += line + '\n'

        with open(self.config_file, 'w') as f:
            f.write(updated_text)

    def add_hashed_password(self):
        hashed_password = hashlib.sha256(str(random.getrandbits(128)).encode()).hexdigest()
        with open('config.txt', 'a') as f:
            f.write(f'hashed_password={hashed_password}\n')

