                for j in range(i+1, len(self.record)):
                    if self.record[j] % 2 == 0:
                        # Perform disjoint pair check using Union-Find data structure
                        pass
        end_time = time.time()
        print("Time taken to process disjoint pairs:", (end_time - start_time) * 1000, "milliseconds")

    def main(self):
        self.offset = [malloc(sizeof(int) * len(self.record)) for _ in range(len(self.key))]
        self.key = list(range(len(self.record)))
        self.record = [random.randint(1, 100) for _ in range(len(self.record))]

