// Define the structure to represent an edge
typedef struct {
    int source;
    int destination;
    int weight;
} Edge;

// Define the structure to represent a graph using adjacency list representation
typedef struct {
    int* vertex_ids;
    int* edge_weights;
    Edge** edges;
    int num_vertices;
    int num_edges;
} Graph;

// Function to manage memory for and initialize an adjacency list representation of a graph
Graph* init_graph(int num_vertices, int num_edges) {
    // Dynamically allocate memory for all necessary arrays
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->vertex_ids = (int*)malloc(num_vertices * sizeof(int));
    graph->edge_weights = (int*)malloc(num_edges * sizeof(int));
    graph->edges = (Edge**)malloc(num_edges * sizeof(Edge*));

    // Initialize the vertex ID and edge weight arrays
    for (int i = 0; i < num_vertices; i++) {
        graph->vertex_ids[i] = i;
    }
    for (int i = 0; i < num_edges; i++) {
        graph->edge_weights[i] = rand();
    }

    // Populate the adjacency list with a specified number of vertices and edges
    for (int i = 0; i < num_edges; i++) {
        graph->edges[i] = (Edge*)malloc(sizeof(Edge));
        graph->edges[i]->source = rand() % num_vertices;
        graph->edges[i]->destination = rand() % num_vertices;
        graph->edges[i]->weight = rand();
    }

    // Validate the size of the arrays
    if ((num_vertices * sizeof(int)) + (num_edges * sizeof(int)) > (num_vertices + num_edges) * sizeof(int)) {
        printf("Error: Memory overflow\n");
        return NULL;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Return the initialized graph structure
    return graph;
}

// Function to print the contents of all arrays in the graph
void print_graph(Graph* graph) {
    for (int i = 0; i < graph->num_vertices; i++) {
        printf("Vertex %d: ", i);
        for (int j = 0; j < graph->num_edges; j++) {
            if (graph->edges[j]->source == i) {
                printf("%d -> %d, weight: %d\n", i, graph->edges[j]->destination, graph->edges[j]->weight);
            }
        }
    }
}

// Function to free the memory allocated for a graph
void free_graph(Graph* graph) {
    if (graph == NULL) return;

    // Free the arrays
    free(graph->vertex_ids);
    free(graph->edge_weights);
    for (int i = 0; i < graph->num_edges; i++) {
        free(graph->edges[i]);
    }
    free(graph->edges);

    // Free the graph structure itself
    free(graph);
}

int main() {
    Graph* graph = init_graph(5, 10);
    print_graph(graph);
    free_graph(graph);
    return 0;
}
