#include <string.h>
#include <stdbool.h>

typedef struct Node {
    char* string;
    int priority;
} Node;

Node* load_config(const char* filename) {
    // Initialize linked list
    Node* head = NULL;
    Node* tail = NULL;
    int num_entries = 0;

    // Initialize hash table
    size_t table_size = 16;
    size_t* table = (size_t*)calloc(table_size, sizeof(size_t));

    // Initialize status array
    bool* status = (bool*)calloc(256, sizeof(bool));

    FILE* file = fopen(filename, "r");
    if (!file) {
        // Handle error
    }

    while (fgets(line, 1024, file)) {
        char* token = strtok(line, "=");
        if (!token) continue;

        Node* node = (Node*)malloc(sizeof(Node));
        node->string = strdup(token);

        token = strtok(NULL, ",");
        if (token) {
            int priority;
            sscanf(token, "%d", &priority);
            node->priority = priority;
        } else {
            // Handle error
        }

        if (!head) head = node; else tail->next = node;

        // Update hash table and status array
        size_t hash = my_hash_function(node->string);
        table[hash % table_size] = (size_t)node;
        status[(int)(node->priority)] = true;

        num_entries++;
    }

    fclose(file);

    // Free memory when done
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current->string);
        free(current);
        current = next;
    }
    free(table);
    free(status);

    return head;
}

size_t my_hash_function(const char* str) {
    size_t hash = 0;
    for (const char* p = str; *p; p++) {
        hash += *p;
    }
    return hash;
}
