#include <time.h>

typedef struct {
    long offset;
    int key;
} record;

record** records = NULL;
int capacity = 0;
int size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_records(int initial_capacity) {
    if (initial_capacity <= 0) return;

    capacity = initial_capacity;
    records = (record**)malloc(initial_capacity * sizeof(record*));
    for (int i = 0; i < capacity; i++) {
        records[i] = (record*)malloc(sizeof(record));
        records[i]->offset = rand() % 1000000;
        records[i]->key = rand() % 1000;
    }
}

void add_record(long offset, int key) {
    pthread_mutex_lock(&lock);

    if (size >= capacity) {
        capacity *= 2;
        record** new_records = (record**)realloc(records, capacity * sizeof(record*));
        for (int i = size; i < capacity; i++) {
            new_records[i] = (record*)malloc(sizeof(record));
            new_records[i]->offset = rand() % 1000000;
            new_records[i]->key = rand() % 1000;
        }
        records = new_records;
    }

    record* new_record = (record*)malloc(sizeof(record));
    new_record->offset = offset;
    new_record->key = key;

    int i = size++;
    for (; i > 0; i--) {
        record* temp = records[i - 1];
        records[i] = temp;
    }
    records[0] = new_record;

    pthread_mutex_unlock(&lock);
}

void remove_record(int index) {
    pthread_mutex_lock(&lock);

    if (index < 0 || index >= size) return;

    int i = index;
    for (; i < size - 1; i++) {
        record* temp = records[i + 1];
        records[i] = temp;
    }

    free(records[size - 1]);
    size--;
    pthread_mutex_unlock(&lock);
}

void iterate_records(void (*callback)(long, int, int)) {
    for (int i = 0; i < size; i++) {
        callback(records[i]->offset, records[i]->key, i);
    }
}
