long** initOffsets(int numOffsets) {
    long** offsets = (long**)malloc(numOffsets * sizeof(long*));
    for(int i=0; i<numOffsets; i++) {
        offsets[i] = (long*)malloc(sizeof(long));
        *offsets[i] = rand() % 10000;
    }
    return offsets;
}

int** initKeys(int numKeys) {
    int** keys = (int**)malloc(numKeys * sizeof(int*));
    for(int i=0; i<numKeys; i++) {
        keys[i] = (int*)malloc(sizeof(int));
        *keys[i] = rand() % 10000;
    }
    return keys;
}

double calculateAverageLatency(const char* filename, long** offsets, int** keys) {
    FILE* file = fopen(filename, "r");
    if(file == NULL) {
        return -1.0; // Error opening file
    }

    double sum = 0.0;
    int count = 0;

    while(fscanf(file, "%ld %d\n", offsets[count], keys[count]) != 2) {
        fclose(file);
        free(offsets);
        free(keys);
        return -1.0; // Error parsing file
    }

    for(int i=0; i<count; i++) {
        sum += *offsets[i] + *keys[i];
    }

    fclose(file);

    return sum / count;
}

int main() {
    int numOffsets = 100;
    int numKeys = 50;

    long** offsets = initOffsets(numOffsets);
    int** keys = initKeys(numKeys);

