// Function to resize the memory allocation if initial capacity is exceeded
void* record_reallocator(void* ptr, int new_capacity) {
    // Get the original array of records
    Record **records = (Record **)ptr;

    // Calculate the difference between old and new capacities
    int diff = new_capacity - sizeof(Record *) / sizeof(Record *);

    // Reallocate memory for the new array of records
    void *new_ptr = realloc(records, new_capacity * sizeof(Record *));

    // Return the new pointer
    return new_ptr;
}

// Function to initialize and add a record with random values
void record_init(void* ptr, int index) {
    Record **records = (Record **)ptr;
    Record *record = (Record *)malloc(sizeof(Record));

    // Set offset and key to random values within specified ranges
    record->offset = rand() % 1000000;
    record->key = rand() % 100;

    // Generate a random string with variable length up to 100 characters
    char *str = (char *)malloc((rand() % 100 + 1) * sizeof(char));
    for (int i = 0; i < strlen(str); i++) {
        str[i] = (char)(rand() % 256);
    }

    record->str = str;

    // Add the new record to the array
    records[index] = record;
}

// Function to iterate over records and perform custom operation using callback function
void record_iterate(void* ptr, void (*callback)(Record *, int)) {
    Record **records = (Record **)ptr;
    for (int i = 0; i < sizeof(Record) / sizeof(Record); i++) {
        callback(records[i], i);
    }
}

// Function to release all allocated memory
void record_free(void* ptr) {
    // Free individual records and their strings
    Record **records = (Record **)ptr;
    for (int i = 0; i < sizeof(Record) / sizeof(Record); i++) {
        free(records[i]->str);
        free(records[i]);
    }

    // Free the dynamic array of records
    free(ptr);
}

// Function to search for a specific key and return the corresponding record structure
Record* record_search(void* ptr, int key) {
    Record **records = (Record **)ptr;
    for (int i = 0; i < sizeof(Record) / sizeof(Record); i++) {
        if (records[i]->key == key) {
            return records[i];
        }
    }

    // Return NULL if the record is not found
    return NULL;
}
