typedef struct document {
    size_t length;
    const char* content;
    uint32_t version;
} Document;

void init_documents(Document** docs, size_t num_docs) {
    for (size_t i = 0; i < num_docs; i++) {
        Document* doc = malloc(sizeof(Document));
        doc->length = rand() % 100 + 1;
        char* content = alloca(doc->length);
        sprintf(content, "Document %zu: %s", i, random_string(doc->length));
        doc->content = content;
        doc->version = rand() % 1000;
        *(docs + i) = doc;
    }
}

void apply_operation(const Document* doc, void (*callback)(size_t, const char*, uint32_t, size_t)) {
    callback(doc->length, doc->content, doc->version, doc->length);
}

void iterate_documents(Document** docs, size_t num_docs, bool reverse) {
    for (size_t i = 0; i < num_docs; i++) {
        Document* doc = *(docs + i);
        if (reverse) {
            apply_operation(doc, &callback_reverse);
        } else {
            apply_operation(doc, &callback_forward);
        }
    }
}

void callback_forward(size_t length, const char* content, uint32_t version, size_t index) {
    printf("Forward iteration: Document %zu - Length: %zu, Content: %s, Version: %u\n", index, length, content, version);
}

void callback_reverse(size_t length, const char* content, uint32_t version, size_t index) {
    printf("Reverse iteration: Document %zu - Length: %zu, Content: %s, Version: %u\n", index, length, content, version);
}

char* random_string(size_t len) {
    static char buffer[1024];
    for (size_t i = 0; i < len; i++) {
        buffer[i] = (rand() % 26) + 'a';
    }
    buffer[len] = '\0';
    return buffer;
}

void free_documents(Document** docs, size_t num_docs) {
    for (size_t i = 0; i < num_docs; i++) {
        Document* doc = *(docs + i);
        if (doc->content != NULL) {
            free((void*) doc->content);
        }
        free(doc);
    }
}

int main() {
    size_t num_docs = 10;
    Document** docs = malloc(num_docs * sizeof(Document*));
    init_documents(docs, num_docs);

    printf("Initial documents:\n");
    iterate_documents(docs, num_docs, false);

    // Process some documents
    for (size_t i = 0; i < num_docs / 2; i++) {
        Document* doc = *(docs + i);
        // Modify the content or version here...
        apply_operation(doc, &callback_forward);
    }

    printf("Processed documents:\n");
    iterate_documents(docs, num_docs, false);

    free_documents(docs, num_docs);

    return 0;
}
