void initialize_graph(int num_vertices, int num_edges) {
    // Dynamically allocate memory for vertex IDs and edge weights
    int* vertex_ids = (int*)malloc(num_vertices * sizeof(int));
    if (!vertex_ids) {
        printf("Memory allocation failed for vertex IDs.\n");
        return;
    }

    double* edge_weights = (double*)malloc(num_edges * sizeof(double));
    if (!edge_weights) {
        printf("Memory allocation failed for edge weights.\n");
        free(vertex_ids);
        return;
    }

    // Initialize vertex ID array
    for (int i = 0; i < num_vertices; i++) {
        vertex_ids[i] = i; // Initialize with sequential IDs
    }

    // Initialize edge weight array
    for (int i = 0; i < num_edges; i++) {
        edge_weights[i] = (double)rand() / RAND_MAX; // Random weights between 0 and 1
    }

    // Dynamically allocate memory for adjacency list structure
    struct Edge* edges = (struct Edge*)malloc(num_edges * sizeof(struct Edge));
    if (!edges) {
        printf("Memory allocation failed for adjacency list.\n");
        free(vertex_ids);
        free(edge_weights);
        return;
    }

    // Populate adjacency list with random edges and weights
    for (int i = 0; i < num_edges; i++) {
        int source = rand() % num_vertices;
        int destination = rand() % num_vertices;
        while (destination == source) {
            destination = rand() % num_vertices;
        }
        double weight = edge_weights[i];
        edges[i].source = source;
        edges[i].destination = destination;
        edges[i].weight = weight;
    }

    // Validate adjacency list structure
    if ((num_edges * sizeof(struct Edge)) + (num_vertices * sizeof(int)) > (1 << 30)) {
        printf("Memory overflow detected.\n");
    }

    // Print adjacency list representation (debugging purposes)
    for (int i = 0; i < num_edges; i++) {
        printf("%d -> %d with weight %.2f\n", edges[i].source, edges[i].destination, edges[i].weight);
    }
}
