#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    int eventId;
    char *message;
} Event;

Event **eventLog = NULL;
int logSize = 0;
int maxLogSize = 0;

void initEventLog(int initialSize, int maxSize) {
    if (initialSize > maxSize || initialSize < 1) return; // validation
    maxLogSize = maxSize;
    eventLog = malloc(initialSize * sizeof(Event *));
    for (int i = 0; i < initialSize; i++) {
        eventLog[i] = malloc(sizeof(Event));
        eventLog[i]->timestamp = time(NULL);
        eventLog[i]->eventId = -1; // default event ID
        eventLog[i]->message = NULL;
    }
    logSize = initialSize;
}

void addEvent(Event *event) {
    if (logSize >= maxLogSize) {
        // resize the log
        Event **newLog = realloc(eventLog, (maxLogSize + 1) * sizeof(Event *));
        for (int i = 0; i < maxLogSize; i++) {
            newLog[i] = eventLog[i];
        }
        eventLog = newLog;
        maxLogSize++;
    }
    eventLog[logSize] = event;
    logSize++;
}

void removeEvent(int index) {
    if (index >= logSize) return;
    free(eventLog[index]->message);
    free(eventLog[index]);
    memmove(eventLog + index, eventLog + index + 1, (logSize - index - 1) * sizeof(Event *));
    logSize--;
}

void serializeEventLog(FILE *file) {
    for (int i = 0; i < logSize; i++) {
        fwrite(&eventLog[i]->timestamp, sizeof(time_t), 1, file);
        fwrite(&eventLog[i]->eventId, sizeof(int), 1, file);
        size_t messageLen = strlen(eventLog[i]->message);
        fwrite(&messageLen, sizeof(size_t), 1, file);
        fwrite(eventLog[i]->message, 1, messageLen + 1, file); // includes null terminator
    }
}

int deserializeEventLog(FILE *file) {
    Event **newLog = malloc(logSize * sizeof(Event *));
    for (int i = 0; i < logSize; i++) {
        time_t timestamp;
        int eventId;
        size_t messageLen;
        fread(&timestamp, sizeof(time_t), 1, file);
        fread(&eventId, sizeof(int), 1, file);
        eventLog[i]->timestamp = timestamp;
        eventLog[i]->eventId = eventId;
        eventLog[i]->message = malloc(messageLen + 1);
        fread(eventLog[i]->message, 1, messageLen, file); // includes null terminator
    }
    free(eventLog);
    eventLog = newLog;
}

void cleanup() {
    for (int i = 0; i < logSize; i++) {
        free(eventLog[i]->message);
        free(eventLog[i]);
    }
    free(eventLog);
}
