typedef struct {
    size_t capacity;
    size_t size;
    entry_t** entries;
    pthread_mutex_t mutex;
} collection_t;

collection_t* create_collection(size_t initial_capacity) {
    collection_t* coll = (collection_t*)malloc(sizeof(collection_t));
    coll->capacity = initial_capacity;
    coll->size = 0;
    coll->entries = (entry_t**)calloc(initial_capacity, sizeof(entry_t*));
    pthread_mutex_init(&coll->mutex, NULL);
    return coll;
}

void destroy_collection(collection_t* coll) {
    for (int i = 0; i < coll->size; i++) {
        free(coll->entries[i]->key);
        free(coll->entries[i]);
    }
    free(coll->entries);
    pthread_mutex_destroy(&coll->mutex);
    free(coll);
}

void resize_collection(collection_t* coll) {
    size_t new_capacity = coll->capacity * 2;
    entry_t** new_entries = (entry_t**)calloc(new_capacity, sizeof(entry_t*));
    for (int i = 0; i < coll->size; i++) {
        new_entries[i] = coll->entries[i];
    }
    free(coll->entries);
    coll->capacity = new_capacity;
    coll->entries = new_entries;
}

void update_collection(collection_t* coll, void (*update_func)(entry_t*)) {
    pthread_mutex_lock(&coll->mutex);
    for (int i = 0; i < coll->size; i++) {
        update_func(coll->entries[i]);
    }
    pthread_mutex_unlock(&coll->mutex);
}
