#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

// Define error codes
typedef enum {
    JSON_PARSE_ERROR,
    JSON_VALIDATION_ERROR,
    REQUEST_PROCESSING_ERROR,
    RATE_LIMIT_EXCEEDED
} ErrorCode;

// Define a struct to represent an HTTP request
typedef struct {
    char* method;
    char* url;
    int http_version;
    int response_code;
    double response_time;
} Request;

// Function to parse and validate JSON input representing a series of HTTP requests
double process_requests(const json_object* config) {
    // Initialize variables
    ErrorCode error = 0;
    int num_requests = json_object_array_size(config);
    double total_response_time = 0.0;
    int count = 0;

    // Iterate over each request in the configuration file
    for (int i = 0; i < num_requests; i++) {
        const json_object* request = json_object_array_get(config, i);
        Request req;

        // Parse and validate request data
        if (!json_object_object_get_ex(request, "method", &req.method) ||
            !json_object_object_get_ex(request, "url", &req.url) ||
            !json_object_object_get_ex(request, "http_version", (void*)&req.http_version)) {
            error = JSON_PARSE_ERROR;
            break;
        }

        // Calculate response time and total
        req.response_code = json_object_array_size(request);
        for (int j = 0; j < req.response_code; j++) {
            const json_object* response = json_object_array_get(request, j);
            int code = json_object_get_int(response, "code");
            double time = json_object_get_double(response, "time");

            if (code >= 500) {
                // Mark as failed
                continue;
            }

            total_response_time += time;
            count++;
        }
    }

    // Handle errors and rate limiting
    if (error) {
        // Log error and handle accordingly
    } else if (count == 0) {
        return -1.0; // No valid requests processed
    } else {
        return total_response_time / count;
    }
}

int main() {
    // Read JSON configuration file
    json_object* config = json_object_from_file("config.json");

    // Process each request entry sequentially
    double average_response_time = process_requests(config);

    printf("Average response time: %.2f seconds\n", average_response_time);

    return 0;
}
