        int field_count = 1;
        for (char* token = strtok(line, ","); token != NULL; token = strtok(NULL, ",")) {
            if (sscanf(token, "%lf", &avg) == 1) {
                break;
            }
            field_count++;
        }

        Entry* entry = malloc(sizeof(Entry));
        entry->key = strdup(filename);
        entry->value = avg;
        pthread_mutex_lock(&lock);
        if (entry_count >= max_entries) {
            // Resize the collection
            max_entries *= 2;
            entries = realloc(entries, sizeof(Entry) * max_entries);
        }
        entries[entry_count] = *entry;
        entry_count++;
        pthread_mutex_unlock(&lock);

        // Caching mechanism
        if (cache_size < LRU_CACHE_SIZE) {
            lru_cache[cache_size++] = entry;
        } else {
            for (int i = 1; i < cache_size; i++) {
                lru_cache[i - 1] = lru_cache[i];
            }
            lru_cache[--cache_size] = entry;
        }
    }

    fclose(file);
}

void process_directory(char* directory) {
    DIR* dirp = opendir(directory);
    if (dirp == NULL) {
        return;
    }

    struct dirent* ent;
    while ((ent = readdir(dirp)) != NULL) {
        if (!strcmp(ent->d_name, ".") || !strcmp(ent->d_name, "..")) {
            continue;
        }
        process_file(strcat(directory, "/", ent->d_name), dirp);
    }

    closedir(dirp);
}

int main() {
    char* directory = "path/to/directory";

    if (!mkdir(directory, S_IRWXU)) {
        // Directory exists or was created
    } else {
        printf("Error: Unable to create directory.\n");
        return 1;
    }

    process_directory(directory);

    for (int i = 0; i < entry_count; i++) {
        update_entry_value(entries[i].value);
    }

    for (int i = 0; i < entry_count; i++) {
        free(entries[i].key);
        free(entries[i]);
    }
    free(entries);

    return 0;
}
