typedef struct {
    int index;
    char* str;
} element;

element* process_string(char* src, int max) {
    int len = strlen(src);
    if (len <= 0 || max <= 0) return NULL;

    // dynamically allocate memory for arrays
    double* doubles = (double*)malloc(max * sizeof(double));
    char** chars = (char**)malloc(max * sizeof(char*));
    element* structs = (element*)malloc(max * sizeof(element));

    if (!doubles || !chars || !structs) {
        free(doubles);
        free(chars);
        free(structs);
        return NULL;
    }

    // initialize arrays
    for (int i = 0; i < max; i++) {
        doubles[i] = i * 1.5;  // assign some arbitrary values to 'double' array
        chars[i] = strndup(src + i, len - i > 1 ? 2 : 1);  // assign unique substrings
        structs[i].index = i + 1;
        structs[i].str = chars[i];
    }

    return structs;
}
