using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Threading.Tasks;
using System.Security.Claims;
using System.IdentityModel.Tokens.Jwt;
using System.Text;
using Microsoft.Extensions.Configuration;

namespace UserProfileAPI.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class UsersController : ControllerBase
    {
        private readonly MyDbContext _dbContext;
        private readonly ITokenService _tokenService;
        private readonly INotificationService _notificationService;
        private readonly IRecommendationGenerator _recommendationGenerator;

        public UsersController(MyDbContext dbContext, ITokenService tokenService, INotificationService notificationService, IRecommendationGenerator recommendationGenerator)
        {
            _dbContext = dbContext;
            _tokenService = tokenService;
            _notificationService = notificationService;
            _recommendationGenerator = recommendationGenerator;
        }

        // Create
        [HttpPost]
        public async Task<ActionResult> CreateUser([FromBody]UserModel model)
        {
            if (!await ValidateInput(model))
                return BadRequest("Invalid input");

            var user = new User { Name = model.Name, Email = model.Email };
            _dbContext.Users.Add(user);
            await _dbContext.SaveChangesAsync();

            return CreatedAtAction(nameof(GetUser), new { id = user.Id }, user);
        }

        // Read
        [HttpGet]
        public async Task<ActionResult> GetUser([FromQuery] int userId)
        {
            var user = await _dbContext.Users.FindAsync(userId);

            if (user == null)
                return NotFound("User not found");

            return Ok(user);
        }

        // Update
        [HttpPut]
        public async Task<ActionResult> UpdateUser([FromBody]UpdateUserModel model, [FromQuery] int userId)
        {
            var user = await _dbContext.Users.FindAsync(userId);

            if (user == null)
                return NotFound("User not found");

            try
            {
                // Validate input and update fields
                await ValidateInput(model);
                user.Name = model.Name;
                user.Email = model.Email;

                // Generate recommendation suggestions in background
                await _recommendationGenerator.GenerateSuggestions(user);

                await _dbContext.SaveChangesAsync();
            }
            catch (Exception ex)
            {
                return StatusCode(500, "Error updating user");
            }

            return Ok("User updated successfully");
        }

        // Delete
        [HttpDelete]
        public async Task<ActionResult> DeleteUser([FromQuery] int userId)
        {
            var user = await _dbContext.Users.FindAsync(userId);

            if (user == null)
                return NotFound("User not found");

            try
            {
                // Cancel any pending notifications and scheduled tasks
                await _notificationService.CancelNotifications(user);
                await _dbContext.SaveChangesAsync();

                // Remove the user
                _dbContext.Users.Remove(user);
                await _dbContext.SaveChangesAsync();
            }
            catch (Exception ex)
            {
                return StatusCode(500, "Error deleting user");
            }

            return Ok("User deleted successfully");
        }

        // Password Reset
        [HttpPost("password/reset")]
        public async Task<ActionResult> ResetPassword([FromBody]ResetPasswordModel model)
        {
            var user = await _dbContext.Users.FindAsync(model.UserId);

            if (user == null)
                return NotFound("User not found");

            // Generate token and send email link
            var token = await _tokenService.GenerateToken(user);
            await _notificationService.SendEmailLink(user, token);

            return Ok("Password reset link sent successfully");
        }

        // Handle password reset token
        [HttpPost("password/reset/handle")]
        public async Task<ActionResult> HandleResetToken([FromBody]HandleResetTokenModel model)
        {
            var user = await _dbContext.Users.FindAsync(model.UserId);
            var token = model.Token;

            if (user == null || !await _tokenService.VerifyToken(user, token))
                return Unauthorized("Invalid token");

            // Update password
            await _dbContext.SaveChangesAsync();

            return Ok("Password reset successfully");
        }

        // Audit logging
        private void LogAuditEvent(string operation, int userId)
        {
            // Log the event securely and efficiently queryable for auditing purposes
        }
    }
}
