int initialize_arrays(int offset_size, int key_count, int record_count) {
    long* offset_array = (long*)malloc(offset_size * sizeof(long));
    if (!offset_array) {
        fprintf(stderr, "Failed to allocate memory for offset array.\n");
        return -1;
    }

    int* key_array = (int*)malloc(key_count * sizeof(int));
    if (!key_array) {
        free(offset_array);
        fprintf(stderr, "Failed to allocate memory for key array.\n");
        return -2;
    }

    struct record* record_array = (struct record*)malloc(record_count * sizeof(struct record));
    if (!record_array) {
        free(offset_array);
        free(key_array);
        fprintf(stderr, "Failed to allocate memory for record array.\n");
        return -3;
    }

    // Initialize offset array
    long offset = 0;
    for (int i = 0; i < offset_size; i++) {
        offset_array[i] = offset++;
    }

    // Initialize key array
    int key = 0;
    for (int i = 0; i < key_count; i++) {
        key_array[i] = key++;
    }

    // Populate record array
    for (int i = 0; i < record_count; i++) {
        record_array[i].key = key_array[i % key_count];
        record_array[i].offset = &offset_array[i % offset_size];
    }

    // Validate bounds and handle potential memory allocation failures
    if (!offset_array || !key_array || !record_array) {
        free(offset_array);
        free(key_array);
        return -4;
    }

    printf("Arrays initialized successfully.\n");

    // Free allocated memory
    free(offset_array);
    free(key_array);
    free(record_array);

    return 0;
}

struct record {
    long* offset;
    int key;
};

