def process_activity_logs(json_file_path: str, config_file_path: str) -> dict:
    with open(json_file_path, 'rb') as f:
        file_contents = f.read()

    expected_checksum = "your_expected_checksum_here"
    actual_checksum = hashlib.md5(file_contents).hexdigest()

    if actual_checksum != expected_checksum:
        return {"error": "Invalid checksum"}

    try:
        config = yaml.safe_load(open(config_file_path, 'r'))
    except Exception as e:
        logging.error(f"Error loading YAML configuration: {e}")
        return {"error": "Invalid YAML configuration"}

    if not isinstance(config, dict):
        return {"error": "Invalid YAML configuration format"}

    client_configs = {}
    for client_id, config in config.items():
        try:
            client_configs[client_id] = {
                'time_zone': config['time_zone'],
                'window_duration': int(config['window_duration']),
            }
        except Exception as e:
            logging.error(f"Error parsing YAML configuration for client {client_id}: {e}")

    aggregated_data = {}
    with open(json_file_path, 'r') as f:
        logs = json.load(f)

        for log in logs:
            timestamp = int(log['timestamp'])
            user_id = log['user_id']

            if not isinstance(timestamp, int) or not isinstance(user_id, str):
                continue

            time_zone_adjustment = client_configs.get(log['client_id'], {}).get('time_zone', 0)
            window_start = timestamp - (timestamp % client_configs[log['client_id']]['window_duration'])

            aggregated_data.setdefault(window_start, {})[user_id] = True

