#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

// Define the structure to represent a node
typedef struct {
    char* identifier;
    float metric;
} Node;

// Define the collection type and its associated operations
typedef struct {
    int capacity;
    int size;
    Node** nodes;
} NodeCollection;

NodeCollection* nodeCollectionCreate(int capacity) {
    NodeCollection* collection = malloc(sizeof(NodeCollection));
    collection->capacity = capacity;
    collection->size = 0;
    collection->nodes = malloc(capacity * sizeof(Node*));

    return collection;
}

void nodeCollectionFree(NodeCollection* collection) {
    for (int i = 0; i < collection->size; i++) {
        free(collection->nodes[i]->identifier);
        free(collection->nodes[i]);
    }
    free(collection->nodes);
    free(collection);
}

void nodeCollectionAdd(NodeCollection* collection, char* identifier, float metric) {
    if (collection->size >= collection->capacity) {
        // Reallocate memory to double the capacity
        NodeCollection* newCollection = nodeCollectionCreate(collection->capacity * 2);
        for (int i = 0; i < collection->size; i++) {
            newCollection->nodes[i] = collection->nodes[i];
        }
        free(collection->nodes);
        collection = newCollection;
    }

    Node* newNode = malloc(sizeof(Node));
    newNode->identifier = strdup(identifier);
    newNode->metric = metric;

    collection->nodes[collection->size++] = newNode;
}

void nodeCollectionTransformMetrics(NodeCollection* collection, float (*operation)(float)) {
    for (int i = 0; i < collection->size; i++) {
        Node* node = collection->nodes[i];
        node->metric = operation(node->metric);
    }
}

void nodeCollectionSerializeToJson(NodeCollection* collection, FILE* file) {
    json_object* root = json_object_new();
    for (int i = 0; i < collection->size; i++) {
        Node* node = collection->nodes[i];
        json_object* obj = json_object_new();
        json_object_set_string(obj, "identifier", node->identifier);
        json_object_set_double(obj, "metric", node->metric);

        if (i > 0) {
            json_object_array_add(root, obj);
        } else {
            root = obj;
        }
    }

    json_object_to_file(file, root);
    json_destruct(root);
}

// Example usage
int main() {
    NodeCollection* collection = nodeCollectionCreate(10);

    // Add nodes to the collection
    nodeCollectionAdd(collection, "node1", 5.0f);
    nodeCollectionAdd(collection, "node2", 3.0f);
    nodeCollectionAdd(collection, "node3", 7.0f);

    // Transform metrics using a scaling operation
    float (*scale)(float) = (float (*)(float))(&sqrt);
    nodeCollectionTransformMetrics(collection, scale);

    // Serialize the collection to JSON
    FILE* jsonFile = fopen("collection.json", "w");
    nodeCollectionSerializeToJson(collection, jsonFile);
    fclose(jsonFile);

    return 0;
}
