typedef struct {
    int offset;
    int key;
} Record;

Record* allocateRecords(int numRecords) {
    if (numRecords > 1024 / sizeof(Record)) return NULL; // Check for memory overflow

    Record* records = (Record*)malloc(numRecords * sizeof(Record));

    if (!records) return NULL; // Handle memory allocation failure

    int* offsets = (int*)malloc(numRecords * sizeof(int)); // Allocate offset array
    if (!offsets) {
        free(records);
        return NULL;
    }

    int* keys = (int*)malloc(numRecords * sizeof(int)); // Allocate key array
    if (!keys) {
        free(records);
        free(offsets);
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        records[i].offset = rand();
        records[i].key = rand() % 100; // Random integer within range [0, 100)

        offsets[i] = i * sizeof(Record);
        keys[i] = records[i].key;
    }

    free(offsets);
    free(keys);

    return records;
}

void printRecordsInReverseOrder(Record* records, int numRecords) {
    for (int i = numRecords - 1; i >= 0; i--) {
        printf("%d %d\n", records[i].offset, records[i].key);
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    int numRecords = 10;

    Record* records = allocateRecords(numRecords);

    if (records) {
        printRecordsInReverseOrder(records, numRecords);

        free(records);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}

