    char* message;
    int length;
} LogEntry;

void handleFileOperations() {
    FILE* configFile = fopen("config.txt", "r");
    FILE* logFile = fopen("log.txt", "r");

    if (configFile == NULL || logFile == NULL) {
        printf("Error opening files.\n");
        return;
    }

    // Read configuration settings
    ConfigSetting* configSettings = malloc(MAX_CONFIG_SIZE * sizeof(ConfigSetting));
    int configCount = 0;
    char line[MAX_CONFIG_SIZE];
    while (fgets(line, MAX_CONFIG_SIZE, configFile)) {
        // Initialize configuration settings with predefined values based on file content
        ConfigSetting setting;
        sscanf(line, "%s %d", &setting.key, &setting.value);
        configSettings[configCount++] = setting;
    }

    fclose(configFile);

    // Read log entries and store them in an array
    LogEntry* logEntries = malloc(MAX_LOG_ENTRIES * sizeof(LogEntry));
    int logCount = 0;
    char line2[MAX_LOG_ENTRY_LENGTH];
    while (fgets(line2, MAX_LOG_ENTRY_LENGTH, logFile)) {
        LogEntry entry;
        // Randomly generate strings within a specified length range
        srand(time(NULL));
        int len = rand() % (MAX_LOG_ENTRY_LENGTH - 1) + 1;
        char* message = malloc(len * sizeof(char));
        for (int i = 0; i < len; i++) {
            message[i] = 'a' + rand() % 26;
        }
        entry.message = message;
        entry.length = len;
        logEntries[logCount++] = entry;
    }

    fclose(logFile);

    // Print configuration settings
    for (int i = 0; i < configCount; i++) {
        printf("Key: %s, Value: %d\n", configSettings[i].key, configSettings[i].value);
    }

    // Find and print the longest log message
    LogEntry* longestLogMessage = NULL;
    int maxLength = 0;
    for (int i = 0; i < logCount; i++) {
        if (logEntries[i].length > maxLength) {
            maxLength = logEntries[i].length;
            longestLogMessage = &logEntries[i];
        }
    }
    printf("Longest Log Message: %s\n", longestLogMessage->message);

    // Calculate the average length of log messages
    int totalLength = 0;
    for (int i = 0; i < logCount; i++) {
        totalLength += logEntries[i].length;
    }
    printf("Average Length: %.2f\n", (double)totalLength / logCount);

    // Free allocated memory
    free(configSettings);
    free(logEntries);
}
