#ifndef RANDOMLIB_H
#define RANDOMLIB_H

#include <random>
#include <string>
#include <vector>

namespace RandomLib {

class RandomGenerator {
public:
    RandomGenerator() : generator_(std::mt19937()) {}

    void setSeed(unsigned long seed) { generator_.seed(seed); }

    unsigned int getSeed() const { return generator_.getSeed(); }

    template<typename T>
    T generateRandom(T min, T max) {
        std::uniform_int_distribution<T> distribution(min, max);
        return distribution(generator_);
    }

    double generateRandomDouble(double min, double max) {
        std::uniform_real_distribution<double> distribution(min, max);
        return distribution(generator_);
    }

    std::string generateRandomString(const std::string& chars, int length) {
        std::vector<char> buffer(chars.begin(), chars.end());
        for (int i = 0; i < length; ++i) {
            buffer.push_back(buffer[generateRandom(0, buffer.size() - 1)]);
        }
        return std::string(buffer.begin(), buffer.end());
    }

private:
    std::mt19937 generator_;
};

} // namespace RandomLib

#endif // RANDOMLIB_H
