    // Output array
    int* outputs = (int*)malloc(inputFileSize * sizeof(int));
    for (int i = 0; i < inputFileSize; i++) {
        outputs[i] = inputs[i] * 2;
    }

    // Find and print the largest integer in the input array
    int maxInput = findMax(inputs, inputFileSize);
    printf("Largest input: %d\n", maxInput);

    // Calculate and print the average of the input integers
    float avgInput = calculateAverage(inputs, inputFileSize);
    printf("Average input: %.2f\n", avgInput);

    free(offsets);
    free(keys);
    free(records);
    free(inputs);
    free(outputs);
}

int findMax(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

float calculateAverage(int* arr, int size) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += arr[i];
    }
    return sum / size;
}
