    for (int i = 0; i < num_records; i++) {
        offset_array[i] = i;
        key_array[i] = i % 100;
    }

    // Populate record array with random integers within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i] = (record_t *)malloc(sizeof(record_t));
        records[i]->value = rand() % ((max_range - min_range) + 1) + min_range;
