#include <stdlib.h>
#include <stdio.h>
#include "memlib.h"

typedef struct {
    int value;
} record_t;

record_t* batchProcessRecords(int num_records, long* offset_array, int* key_array) {
    // Initialize memory for arrays and structures
    record_t** records = (record_t**)malloc(num_records * sizeof(record_t*));
    for (int i = 0; i < num_records; i++) {
        records[i] = (record_t*)malloc(sizeof(record_t));
    }
    long* offset_array_ptr = (long*)malloc((num_records + 1) * sizeof(long));
    int* key_array_ptr = (int*)malloc(num_records * sizeof(int));

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        records[i]->value = rand() % INT_MAX;
        key_array_ptr[i] = rand() % INT_MAX;
        offset_array_ptr[i] = (long)i;
    }
    offset_array_ptr[num_records] = (long)num_records;

    // Initialize linked list
    record_t* head = NULL;
    for (int i = 0; i < num_records; i++) {
        record_t* new_record = records[i];
        if (!head) {
            head = new_record;
        } else {
            record_t* current = head;
            while (current->value <= key_array_ptr[i]) {
                current = current->next;
            }
            new_record->next = current;
            if (!current) {
                head = new_record;
            } else {
                record_t* prev = NULL;
                while (current && current->value < key_array_ptr[i]) {
                    prev = current;
                    current = current->next;
                }
                if (prev) {
                    prev->next = new_record;
                } else {
                    head = new_record;
                }
            }
        }
    }

    // Free memory
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);
    free(offset_array_ptr);
    free(key_array_ptr);

    return head;
}
