void processAndAggregateDataWithAdvancedIntegration(int numRecords, int rangeMin, int rangeMax) {
    // Initialize random number generator
    srand(time(NULL));

    // Initialize data structures
    long* offset = malloc(numRecords * sizeof(long));
    int* key = malloc(numRecords * sizeof(int));
    struct record {
        int value;
    }* record = malloc(numRecords * sizeof(struct record));
    char* chunkId = malloc(32);

    // Initialize arrays
    for (int i = 0; i < numRecords; i++) {
        offset[i] = i;
        key[i] = rand() % rangeMax - rangeMin + 1;
        record[i].value = rand() % rangeMax - rangeMin + 1;
    }

    int maxVal = findLargest(record, numRecords);
    printf("Maximum value: %d\n", maxVal);

    // Serialize data structures
    FILE* file = fopen("data.bin", "wb");
    fwrite(offset, sizeof(long), numRecords, file);
    fwrite(key, sizeof(int), numRecords, file);
    fwrite(&record, sizeof(struct record), numRecords, file);
    fclose(file);

    // Deserialize data structures
    long* offsetDeserialized;
    int* keyDeserialized;
    struct record* recordDeserialized;

    file = fopen("data.bin", "rb");
    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);
    offsetDeserialized = malloc(fileSize / sizeof(long));
    keyDeserialized = malloc(fileSize / sizeof(int));
    recordDeserialized = malloc(fileSize / sizeof(struct record));
    fread(offsetDeserialized, sizeof(long), numRecords, file);
    fread(keyDeserialized, sizeof(int), numRecords, file);
    fread(recordDeserialized, sizeof(struct record), numRecords, file);
    fclose(file);

    // Print deserialized data
    for (int i = 0; i < numRecords; i++) {
        printf("Offset: %ld, Key: %d, Record Value: %d\n", offsetDeserialized[i], keyDeserialized[i], recordDeserialized[i].value);
    }

    // Free allocated memory
    free(offset);
    free(key);
    free(record);
    free(chunkId);

    // Deinitialize random number generator
    srand(0);
}

int findLargest(struct record* records, int numRecords) {
    int maxVal = 0;
    for (int i = 0; i < numRecords; i++) {
        if (records[i].value > maxVal) {
            maxVal = records[i].value;
        }
    }
    return maxVal;
}
