record_t* processAndAggregateData(int numRecords, int rangeStart, int rangeEnd) {
    // Calculate the size of arrays based on input parameters
    int offsetSize = numRecords * sizeof(long);
    int keySize = numRecords * sizeof(int);
    int flagSize = numRecords * sizeof(short);
    int recordSize = numRecords * sizeof(record_t);
    int labelSize = numRecords * sizeof(char);

    // Allocate memory for arrays using malloc
    long* offset = (long*)malloc(offsetSize);
    int* key = (int*)malloc(keySize);
    short* flag = (short*)malloc(flagSize);
    record_t* record = (record_t*)malloc(recordSize);
    char* label = (char*)malloc(labelSize);

    // Initialize arrays with specific values
    for (int i = 0; i < numRecords; i++) {
        offset[i] = i * rangeStart;
        key[i] = i % 10;
        flag[i] = i % 2;

        // Generate random integer within the specified range and store it in the record array
        int randomInt = (rand() % (rangeEnd - rangeStart + 1)) + rangeStart;
        record[i].value = randomInt;

        // Convert integer to ASCII label and store it in the label array
        sprintf(label + i, "%d", randomInt);
    }

    // Ensure total size of record and label arrays does not exceed sum of sizes of offset, key, and flag arrays
    if (recordSize + labelSize > offsetSize + keySize + flagSize) {
        printf("Error: Total size of record and label arrays exceeds the sum of sizes of offset, key, and flag arrays.\n");
        exit(1);
    }

    // Free allocated memory
    free(offset);
    free(key);
    free(flag);
    free(record);
    free(label);

    return NULL;
}
