#include <iostream>
#include <fstream>
#include <vector>
#include <sstream>
#include <memory>

using namespace std;

struct Attack {
    string name;
    int damage;
    int cooldown;
};

unique_ptr<vector<Attack>> loadAttacksFromConfig(const char* filename) {
    ifstream file(filename);
    if (!file.is_open()) {
        return nullptr;
    }

    unique_ptr<vector<Attack>> attacks(new vector<Attack>());

    string line;
    while (getline(file, line)) {
        stringstream ss(line);
        Attack attack;

        if (!(ss >> attack.name >> attack.damage >> attack.cooldown)) {
            // Handle invalid config file format
            return nullptr;
        }

        attacks->push_back(move(attack));
    }

    return move(attacks);
}

void selectAndExecuteAttackWithCooldown() {
    unique_ptr<vector<Attack>> attacks = loadAttacksFromConfig("attacks.config");

    if (!attacks) {
        // Handle error loading config file
        return;
    }

    int currentCooldown = 0;

    while (true) {
        Attack* attack = nullptr;

        for (const auto& a : *attacks) {
            if (a.cooldown > currentCooldown) {
                attack = &a;
                break;
            }
        }

        if (!attack) {
            // No attacks available, wait for cooldown
            currentCooldown++;
            continue;
        }

        cout << "Executing: " << attack->name << endl;

        currentCooldown += attack->cooldown;
    }
}

int main() {
    selectAndExecuteAttackWithCooldown();
    return 0;
}
