// Define a structure for the indexed record
typedef struct {
    int key;
    long offset;
    int value;
} Record;

// Custom memory pool allocator
struct MemoryPool {
    void* base;
    size_t size;
    size_t used;
};

void* malloc_custom(size_t size) {
    static struct MemoryPool mp = {NULL, 0, 0};

    if (mp.base == NULL || mp.used + size > mp.size) {
        int fd = shm_open("/memory_pool", O_RDWR | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
        if (fd < 0) return NULL;

        ftruncate(fd, size);
        void* ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        close(fd);
        shm_unlink("/memory_pool");

        mp.base = ptr;
        mp.size = size;
        mp.used = 0;
    }

    return (void*)((char*)mp.base + mp.used);
}

// Initialize records with unique integer keys and random values
int initialize_records(int start, int end) {
    // Generate a set of unique random numbers for the range [start, end]
    srand(time(NULL));
    int* random_numbers = (int*)malloc_custom((end - start + 1) * sizeof(int));

    for (int i = start; i <= end; i++) {
        Record record;
        record.key = i;
        record.value = random_numbers[i - start];

        // Store the record in the memory pool
        void* ptr = malloc_custom(sizeof(Record));
        memcpy(ptr, &record, sizeof(record));
    }

    free(random_numbers);
}

// Function to manage a large-scale distributed data indexing system
int main() {
    initialize_records(0, 10000000); // Initialize records for the range [0, 10 million]

    return 0;
}
