void efficientResourceManagement(int data_size, int index_size, int offset_size, int record_size, int min_range, int max_range) {
    // Dynamically allocate memory for all arrays
    int* data = (int*)malloc(data_size * sizeof(int));
    int* index = (int*)malloc(index_size * sizeof(int));
    int* offset = (int*)malloc(offset_size * sizeof(int));
    int* record = (int*)malloc(record_size * sizeof(int));

    // Initialize the 'offset' and 'index' arrays with specific values
    for (int i = 0; i < index_size; i++) {
        index[i] = i;
    }
    for (int i = 0; i < offset_size; i++) {
        offset[i] = i * 2;
    }

    // Initialize the 'record' array with random integers
    srand(time(NULL));
    for (int i = 0; i < record_size; i++) {
        record[i] = rand() % (max_range - min_range + 1) + min_range;
    }

    // Ensure the total size of the 'record' array does not exceed the combined size
    if (record_size > data_size || record_size > index_size || record_size > offset_size) {
        printf("Error: Record array size exceeds allocated memory.\n");
        return;
    }

    // Free all allocated resources upon returning
    free(data);
    free(index);
    free(offset);
    free(record);

    // Implement a quota system to control the maximum allowed size dynamically
    int max_allowed_size = data_size + index_size + offset_size;
    if (record_size > max_allowed_size) {
        printf("Error: Record array size exceeds quota.\n");
        return;
    }

    // Print the contents of all arrays for debugging purposes
    printf("Data Array: ");
    for (int i = 0; i < data_size; i++) {
        printf("%d ", *(data + i));
    }
    printf("\n");

    printf("Index Array: ");
    for (int i = 0; i < index_size; i++) {
        printf("%d ", *(index + i));
    }
    printf("\n");

