#include <string.h>

char* modify_filename(char* filename) {
    int i, j;
    char temp[256], *token = strtok(filename, ".");
    if (token == NULL) {
        token = filename;
    }

    for (i = 0; i < strlen(token); i++) {
        if (!isalnum((unsigned char)token[i])) {
            temp[i] = '_';
        } else {
            temp[i] = token[i];
        }
    }

    int len = strlen(temp);
    for (j = len - 1; j >= 0 && !isdigit((unsigned char)temp[j]); j--);
    if (j < 0) {
        // No digits found
        for (i = 0; i < 8; i++) {
            temp[len++] = '0' + rand() % 10;
        }
    } else {
        // Extract the number of digits
        int count = j - len + 1;
        // Create a new sequence
        for (i = 0; i < 3 && i < count; i++) {
            temp[len++] = '0' + rand() % 10;
        }
    }

    temp[len] = '\0';

    if (strchr(temp, '.') != NULL) {
        // Extension already present, no need to modify
        return token;
    } else {
        char* new_filename = malloc(strlen(token) + len + 1);
        strcpy(new_filename, token);
        strcat(new_filename, ".");
        strcat(new_filename, temp);

        free(temp);
        return new_filename;
    }
}
