void init_collections(size_t offset_count, size_t key_count, size_t record_count, size_t document_count) {
    // Initialize collections
    Offset** offsets = (Offset**)malloc(offset_count * sizeof(Offset));
    for (size_t i = 0; i < offset_count; i++) {
        offsets[i] = (Offset*)malloc(sizeof(Offset));
        offsets[i]->offset = i;
    }

    Key** keys = (Key**)malloc(key_count * sizeof(Key));
    for (size_t i = 0; i < key_count; i++) {
        keys[i] = (Key*)malloc(sizeof(Key));
        keys[i]->key = i;
    }

    Record** records = (Record**)malloc(record_count * sizeof(Record));
    for (size_t i = 0; i < record_count; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->value = i;
    }

    Document** documents = (Document**)malloc(document_count * sizeof(Document));
    for (size_t i = 0; i < document_count; i++) {
        documents[i] = (Document*)malloc(sizeof(Document));
        // Initialize random text content and version number
        char* content = (char*)malloc(rand() % 100 + 1);
        strcpy(content, "Random Text ");
        int version = rand() % 10;
        documents[i]->length = strlen(content) + 1;
        documents[i]->content = content;
        documents[i]->version = version;
    }

    Metadata** metadata = (Metadata**)malloc(5 * sizeof(Metadata));
    for (size_t i = 0; i < 5; i++) {
        metadata[i] = (Metadata*)malloc(sizeof(Metadata));
        metadata[i]->key = "Key";
        metadata[i]->value = NULL;
    }

    // Check total size of document and record collections
    size_t total_size = sizeof(Offset) * offset_count + sizeof(Key) * key_count + sizeof(Record) * record_count +
                        sizeof(Document) * document_count + sizeof(Metadata) * 5;
    for (size_t i = 0; i < document_count; i++) {
        total_size += documents[i]->length;
    }
    if (total_size > offset_count * sizeof(Offset) + key_count * sizeof(Key) + record_count * sizeof(Record) + 5 * sizeof(Metadata)) {
        printf("Error: Total size exceeds sum of sizes.\n");
    }

    // Free all allocated memory
    for (size_t i = 0; i < offset_count; i++) {
        free(offsets[i]);
    }
    free(offsets);
    for (size_t i = 0; i < key_count; i++) {
        free(keys[i]);
    }
    free(keys);
    for (size_t i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(records);
    for (size_t i = 0; i < document_count; i++) {
        free(documents[i]->content);
        free(documents[i]);
    }
    free(documents);
    for (size_t i = 0; i < 5; i++) {
        free(metadata[i]);
    }
    free(metadata);
}

int main() {
