#include <time.h>

typedef struct {
    double value;
    int metadata1;
    int metadata2;
} record;

// Function to manage memory for three data structures: an array of long offset values, 
// an array of int keys, and an array of record structures
void* memManager(int maxThreshold, int* offsets, int* keys, record** records, int size) {
    // Memory allocation for offset values
    int* offsetsPtr = (int*)malloc(size * sizeof(int));
    if (!offsetsPtr) {
        printf("Error: Failed to allocate memory for offset values.\n");
        return NULL;
    }

    // Memory allocation for keys
    int* keysPtr = (int*)malloc(size * sizeof(int));
    if (!keysPtr) {
        printf("Error: Failed to allocate memory for keys.\n");
        free(offsetsPtr);
        return NULL;
    }

    // Memory allocation for records
    record** recordsPtr = (record**)malloc(size * sizeof(record*));
    if (!recordsPtr) {
        printf("Error: Failed to allocate memory for records.\n");
        free(offsetsPtr);
        free(keysPtr);
        return NULL;
    }

    // Populate records using a weighted random distribution
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        record* r = (record*)malloc(sizeof(record));
        if (!r) {
            printf("Error: Failed to allocate memory for record.\n");
            free(offsetsPtr);
            free(keysPtr);
            for (int j = 0; j <= i; j++)
                free(recordsPtr[j]);
            free(recordsPtr);
            return NULL;
        }
        r->value = ((double)rand() / RAND_MAX * maxThreshold);
        r->metadata1 = rand() % 100;
        r->metadata2 = rand() % 100;
        recordsPtr[i] = r;
    }

    // Serialization to binary file format
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        printf("Error: Failed to open file for serialization.\n");
        free(offsetsPtr);
        free(keysPtr);
        for (int i = 0; i < size; i++)
            free(recordsPtr[i]);
        free(recordsPtr);
        return NULL;
    }
    fwrite(&size, sizeof(int), 1, file);
    fwrite(offsetsPtr, sizeof(int), size, file);
    fwrite(keysPtr, sizeof(int), size, file);
    for (int i = 0; i < size; i++) {
        fwrite(&recordsPtr[i]->value, sizeof(double), 1, file);
        fwrite(&recordsPtr[i]->metadata1, sizeof(int), 1, file);
        fwrite(&recordsPtr[i]->metadata2, sizeof(int), 1, file);
    }
    fclose(file);

    // Deserialization from binary file format
    file = fopen("data.bin", "rb");
    if (!file) {
        printf("Error: Failed to open file for deserialization.\n");
        free(offsetsPtr);
        free(keysPtr);
        for (int i = 0; i < size; i++)
            free(recordsPtr[i]);
        free(recordsPtr);
        return NULL;
    }
    int fileSize;
    fread(&fileSize, sizeof(int), 1, file);
    offsetsPtr = (int*)realloc(offsetsPtr, fileSize * sizeof(int));
    keysPtr = (int*)realloc(keysPtr, fileSize * sizeof(int));
    for (int i = 0; i < fileSize; i++) {
        recordsPtr[i] = (record*)malloc(sizeof(record));
        fread(&recordsPtr[i]->value, sizeof(double), 1, file);
        fread(&recordsPtr[i]->metadata1, sizeof(int), 1, file);
        fread(&recordsPtr[i]->metadata2, sizeof(int), 1, file);
    }
    fclose(file);

    return recordsPtr;
}
