#include <stdlib.h>
#include <string.h>

typedef struct {
    int key;
} record;

record* create_collection(size_t initial_capacity) {
    return (record*)malloc((initial_capacity + 1) * sizeof(record));
}

void insert_record(record** collection, long* offsets, size_t* capacity, int key, void* data) {
    // Find the next available slot for the new record
    size_t i;
    for (i = 0; i < *capacity; i++) {
        if ((*collection)[i].key == -1) break;
    }

    // If no slots are available, reallocate memory to accommodate more records
    if (i >= *capacity) {
        *capacity *= 2;
        record* new_collection = (record*)realloc(*collection, (*capacity + 1) * sizeof(record));
        long* new_offsets = (long*)realloc(offsets, (*capacity + 1) * sizeof(long));
        *collection = new_collection;
        offsets = new_offsets;
    }

    // Initialize the new record and update the offset
    (*collection)[i].key = key;
    offsets[i] = (long)data;
}

record* get_record(record** collection, long* offsets, size_t capacity, int key) {
    for (size_t i = 0; i < capacity; i++) {
        if ((*collection)[i].key == key) return &(*collection)[i];
    }
    return NULL;
}

void delete_record(record** collection, long* offsets, size_t* capacity, int key) {
    // Find the record to be deleted
    size_t i;
    for (i = 0; i < *capacity; i++) {
        if ((*collection)[i].key == key) break;
    }

    // If the record is not found, return early
    if (i >= *capacity) return;

    // Shift all records after the deleted one to fill the gap
    for (; i + 1 < *capacity; i++) {
        (*collection)[i] = (*collection)[i + 1];
        offsets[i] = offsets[i + 1];
    }

    // Reduce the collection's capacity
    *capacity--;
}

void free_collection(record** collection, long* offsets, size_t capacity) {
    free(*collection);
    free(offsets);
}
