    free(ptr);
}

void manageMemory() {
    if (!arrayRecords || arrayRecords->length >= MAX_RECORDS) {
        // Dynamically resize the data structure
        record** newRecords = (record**)allocateMemory(sizeof(record*) * 2 * MAX_RECORDS);
        for (int i = 0; i < arrayRecords->length; i++) {
            newRecords[i] = arrayRecords[i];
        }
        deallocateMemory(arrayRecords);
        arrayRecords = newRecords;
    }
}

void populateRecords() {
    srand(time(NULL));
    // Populating records with values derived from a weighted random distribution
    for (int i = 0; i < arrayRecords->length; i++) {
        record* currentRecord = &arrayRecords[i];
        currentRecord->value = (double)rand() / RAND_MAX * MAX_DOUBLE_VALUE;
        // Additional metadata fields
        currentRecord->metadata1 = rand();
        currentRecord->metadata2 = rand();
    }
}

void serializeData(const char* filename) {
