    if (!file) {
        printf("Error opening file.\n");
        return;
    }

    // Serialize the data structures
    fwrite(&arrayRecords->length, sizeof(int), 1, file);
    for (int i = 0; i < arrayRecords->length; i++) {
        record* currentRecord = &arrayRecords[i];
        fwrite(&currentRecord->value, sizeof(double), 1, file);
        fwrite(&currentRecord->metadata1, sizeof(int), 1, file);
        fwrite(&currentRecord->metadata2, sizeof(int), 1, file);
    }
}

void deserializeData(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file.\n");
        return;
    }

    // Deserialize the data structures
    int recordCount;
    fread(&recordCount, sizeof(int), 1, file);
    arrayRecords = (record*)allocateMemory(sizeof(record) * recordCount);
    for (int i = 0; i < recordCount; i++) {
        record* currentRecord = &arrayRecords[i];
        fread(&currentRecord->value, sizeof(double), 1, file);
        fread(&currentRecord->metadata1, sizeof(int), 1, file);
        fread(&currentRecord->metadata2, sizeof(int), 1, file);
    }
}

void printData() {
    // Print the data structures
    for (int i = 0; i < arrayRecords->length; i++) {
        record* currentRecord = &arrayRecords[i];
        printf("Value: %f, Metadata1: %d, Metadata2: %d\n", currentRecord->value, currentRecord->metadata1, currentRecord->metadata2);
    }
}

int main() {
    // Initialize the data structures
    arrayRecords = (record*)allocateMemory(sizeof(record) * MAX_RECORDS);
    offsetArray = (long*)allocateMemory(sizeof(long) * MAX_RECORDS);
    keyArray = (int*)allocateMemory(sizeof(int) * MAX_RECORDS);

    pthread_t thread;
    pthread_create(&thread, NULL, &populateRecords, NULL);

    // Wait for the population to finish
    pthread_join(thread, NULL);

    // Serialize and deserialize the data structures
    serializeData("data.bin");
    deserializeData("data.bin");

