void populate_data(long** offsets, int** keys, record** records, double max_threshold) {
    // Initialize sum of values
    double total_sum = 0.0;

    // Populate arrays within specified threshold
    for (int i = 0; i < 100; i++) {
        long offset = rand() % 100;
        int key = rand() % 100;
        record* record_ptr = &(*records)[i];

        // Ensure total sum of values does not exceed the maximum threshold
