void serialize_data(const long* offsets, const int* keys, const record* records, FILE* output_file) {
    // Write array sizes and counts to file
    fwrite(&sizeof(long), 1, sizeof(long), output_file);
    fwrite(&sizeof(int), 1, sizeof(int), output_file);
    fwrite(&sizeof(record), 1, sizeof(record), output_file);

    // Serialize arrays
    fwrite(offsets, sizeof(long), 100, output_file);
    fwrite(keys, sizeof(int), 100, output_file);
    fwrite(records, sizeof(record), 100, output_file);
}

