void deserialize_data(FILE* input_file, long** offsets, int** keys, record** records) {
    // Read array sizes and counts
    fseek(input_file, 0, SEEK_SET);
    fread(offsets, sizeof(long), 1, input_file);
    fread(keys, sizeof(int), 1, input_file);
    fread(records, sizeof(record), 1, input_file);

    // Deserialize arrays
