#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

void rename_file(char *filename, char *dir_path) {
    // Extract the main part of the filename (excluding extensions)
    char *main_part = strrchr(filename, '.');
    if (main_part == NULL || *(main_part - 1) == '.') {
        main_part = filename;
    } else {
        *main_part = '\0';
    }

    // Determine the number of digits as the count of vowels in the main part
    int vowel_count = 0;
    for (int i = 0; i < strlen(main_part); i++) {
        char c = tolower(main_part[i]);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            vowel_count++;
        }
    }

    // Determine the file type based on the last character of the main part
    char *file_type;
    switch (main_part[strlen(main_part) - 1]) {
        case 'x':
        case 'X':
            file_type = "txt";
            break;
        case 'b':
        case 'B':
            file_type = "bin";
            break;
        default:
            file_type = "cfg";
    }

    // Generate the timestamp for the filename
    time_t now = time(NULL);
    struct tm *ts = localtime(&now);
    char timestamp[20];
    strftime(timestamp, 20, "%Y%m%d-%H%M%S", ts);

    // Create the new filename with the updated information
    int len = strlen(dir_path) + strlen(file_type) + strlen(main_part) + strlen(timestamp) + 1;
    char *new_filename = (char *)malloc(len);
    strcpy(new_filename, dir_path);
    strcat(new_filename, "/");
    strcat(new_filename, main_part);
    strcat(new_filename, "-";
    strcat(new_filename, timestamp);
    strcat(new_filename, ".");
    strcat(new_filename, file_type);

    // Check if the new filename exceeds 256 characters
    if (strlen(new_filename) > 255) {
        printf("Error: New filename exceeds 256 characters.\n");
        return;
    }

    // Perform a dry run to detect and handle concurrent renaming operations
    char *temp_filename = (char *)malloc(len);
    strcpy(temp_filename, new_filename);
    rename(filename, temp_filename);

    free(new_filename);
    free(temp_filename);
}
