const fetchValidationRules = async (resourceID, url) => {
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(response.statusText);
    return await response.json();
  } catch (error) {
    console.warn(`Failed to load validation rules for ${resourceID}: ${error.message}`);
  }
};

const validateFormFields = async (resourceID, url, config) => {
  const pendingFields = [];
  const cachedValidationRules = {};
  let lastAttemptedFetchTime = null;

  const fetchAndValidate = async () => {
    if (lastAttemptedFetchTime && Date.now() - lastAttemptedFetchTime < 1000) {
      return cachedValidationRules;
    }

    try {
      const validationRules = await fetchValidationRules(resourceID, url);
      cachedValidationRules[resourceID] = validationRules;
      lastAttemptedFetchTime = Date.now();
    } catch (error) {
      if (error.name === 'TimeoutError') {
        console.error(`Failed to load validation rules for ${resourceID}: Timeout`);
        await new Promise((resolve) => setTimeout(resolve, 2000));
        return fetchAndValidate();
      }
      throw error;
    }

    return cachedValidationRules[resourceID];
  };

  const validateField = (fieldName) => {
    if (!cachedValidationRules[resourceID]) return;

    const validationRule = cachedValidationRules[resourceID][fieldName];
    if (!validationRule) return;

    try {
      await validationRule();
    } catch (error) {
      // Send error message to parent component
    }
  };

  return { validateField, pendingFields };
};
