["```javascript
function modifyExtension(filename) {
    const regex = /\d+/g;
    let sequences = filename.match(regex);
    if (sequences) {
        let maxLength = Math.max(...sequences.map(x => x.length));
        filename += '.' + '0'.repeat(maxLength) + '.txt';
    } else {
        filename += '.' + '0'.repeat(3) + '.txt';
    }
    return filename;
}

function loadFiles(files, retryCount = 3) {
    const cache = {};
    let loadedFiles = [];
    files.forEach(file => {
        file = modifyExtension(file);
        if (!cache[file]) {
            for (let i = 0; i <= retryCount; i++) {
                try {
                    const script = document.createElement('script');
                    script.src = `https://example.com/${file}`;
                    script.onload = () => {
                        cache[file] = true;
                        loadedFiles.push(file);
                    };
                    script.onerror = () => {
                        if (i < retryCount) {
                            setTimeout(() => loadFiles([file], retryCount - 1), 1000);
                        } else {
                            console.error(`Failed to load ${file}`);
                        }
                    };
                    document.head.appendChild(script);
                } catch (e) {
                    console.error(e);
                }
            }
        } else {
            loadedFiles.push(file);
        }
    });
    return loadedFiles;
}

function getMetadata(file) {
    // Call the external API to fetch metadata
    // For simplicity, assume this function returns a promise that resolves with an object
    return fetch(`https://api.example.com/${file}`)
        .then(response => response.json())
        .catch(error => console.error(error));
}

const files = ['file1.js', 'file2.txt', 'file3.js'];
loadFiles(files)
    .then(loadedFiles => {
        loadedFiles.forEach(file => getMetadata(file).then(metadata => console.log(metadata)));
    })
    .catch(error => console.error(error));"]

