function combineRandomStringAndFileContents($length, $characterSet, $filePath) {
    $randomString = generateRandomString($length, $characterSet);
    $fileContents = readFileContents($filePath);
    return hash($randomString) . $fileContents;
}

function generateRandomString($length, $characterSet) {
    $string = '';
    for ($i = 0; i < $length; $i++) {
        $string .= random_char();
    }
    return $string;

    function random_char() {
        $char = chr(rand(32, 126));
        return $char;
    }
}

function readFileContents($filePath) {
    $fileHandle = fopen($filePath, 'r');
    if (!$fileHandle) {
        return '';
    }
    $contents = '';
    while (!feof($fileHandle)) {
        $contents .= fread($fileHandle, 1024);
    }
    fclose($fileHandle);
    return $contents;
}

function hash($string) {
    return sha1($string);
}
