void processAndAnalyzeLogs(int numEntries) {
    if (numEntries <= 0) {
        return;
    }

    // Initialize arrays
    int* logLevel = malloc(sizeof(int));
    char** logMessage = malloc(sizeof(char*));
    LogEvent* logEvents = malloc(numEntries * sizeof(LogEvent));

    // Set initial values for log level and message arrays
    *logLevel = 0;
    *logMessage = "";

    for (int i = 0; i < numEntries; i++) {
        // Read log entries from standard input
        char buffer[1024];
        fgets(buffer, sizeof(buffer), stdin);

        LogEvent event;
        event.level = *logLevel;
        event.message = malloc(strlen(buffer) + 1);
        strcpy(event.message, buffer);
        event.timestamp = time(NULL);

        logEvents[i] = event;

        // Update log level and message arrays
        (*logLevel)++;
        *logMessage = realloc(*logMessage, strlen(buffer) + 1);
        strcat(*logMessage, buffer);
    }

    // Check for array size consistency
    if (numEntries > 0 && sizeof(LogEvent) * numEntries > sizeof(int) * 2) {
        printf("Error: Log event array size exceeds log level and message arrays.\n");
    }

    // Print contents of all arrays
    printf("Log Level: %d\n", *logLevel);
    printf("Log Message: %s\n", *logMessage);
    for (int i = 0; i < numEntries; i++) {
        printf("Event %d:\n", i + 1);
        printf("\tLevel: %d\n", logEvents[i].level);
        printf("\tMessage: %s\n", logEvents[i].message);
        printf("\tTimestamp: %ld\n", logEvents[i].timestamp);
