#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include "randlib.h"

typedef struct {
    int i;
    float f;
} record_t;

record_t* processAndTransformFile(const char* inputFile, const char* outputFile, const char* transformationRules, int thresholdSize, int loggingLevel) {
    // Initialize random number generation
    srand(time(NULL));

    // Open input and output files
    FILE* fileInput = fopen(inputFile, "rb");
    FILE* fileOutput = fopen(outputFile, "wb");

    // Check for errors
    if (!fileInput || !fileOutput) {
        fprintf(stderr, "Failed to open files.\n");
        return NULL;
    }

    // Read input file and process data
    long offsetCount = 0;
    int* offsets = NULL;
    int* keys = NULL;
    record_t* records = NULL;

    fseek(fileInput, 0, SEEK_END);
    long fileSize = ftell(fileInput);
    rewind(fileInput);

    if (fileSize > thresholdSize) {
        // Allocate memory for offset array
        offsets = (int*)malloc((fileSize / sizeof(long)) * sizeof(int));

        // Read and process data in chunks
        int chunkSize = thresholdSize;
        long currentOffset = 0;
        while (currentOffset < fileSize) {
            fseek(fileInput, currentOffset, SEEK_SET);
            int bytesRead = fread(&offsets[offsetCount], 1, chunkSize, fileInput);
            if (bytesRead != chunkSize) break;
            offsetCount += bytesRead / sizeof(long);
            currentOffset += bytesRead;
        }

        // Allocate memory for key array
        keys = (int*)malloc((offsetCount) * sizeof(int));
        int keyIndex = 0;
        for (long i = 0; i < offsetCount; i++) {
            fseek(fileInput, offsets[i] * sizeof(long), SEEK_SET);
            int bytesRead = fread(&keys[keyIndex], 1, sizeof(int), fileInput);
            if (bytesRead != sizeof(int)) break;
            keyIndex++;
        }

        // Allocate memory for record array
        records = (record_t*)malloc(keyIndex * sizeof(record_t));
        for (int i = 0; i < keyIndex; i++) {
            int bytesRead = fread(&records[i], 1, sizeof(record_t), fileInput);
            if (bytesRead != sizeof(record_t)) break;
        }
    } else {
        // Read entire file
        long* offsets = (long*)malloc(fileSize * sizeof(long));
        int* keys = (int*)malloc(fileSize * sizeof(int));
        record_t* records = (record_t*)malloc(fileSize * sizeof(record_t));

        fread(offsets, 1, fileSize * sizeof(long), fileInput);
        fread(keys, 1, fileSize * sizeof(int), fileInput);
        fread(records, 1, fileSize * sizeof(record_t), fileInput);
    }

    // Process and transform data
    for (int i = 0; i < offsetCount; i++) {
        records[i].i = rand() % 100;
        records[i].f = (float)rand() / RAND_MAX;
    }

    // Write processed data to output file
    fwrite(records, 1, offsetCount * sizeof(record_t), fileOutput);

    // Deallocate memory and close files
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
    fclose(fileInput);
    fclose(fileOutput);

    return records;
}
