            read(fd, &commands[i-1][0], strlen(commands[i-1]) + 1);
            commands[i] = (char*)malloc(strlen(commands[i-1]) + 2);
            strcpy(commands[i], "command ");
            strcat(commands[i], &commands[i-1][0]);
        } else {
            commands[0] = NULL;
        }
    }

    if (*size > 0) {
        for (int i = 0; i < *size - 1; i++) {
            if (strcmp(commands[i], commands[i+1]) > 0) {
