#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <stdint.h>

#define MAX_PACKETS 1000
#define MAX_PAYLOAD_SIZE 1024

struct packet_header {
    uint32_t source_port;
    uint32_t destination_port;
    size_t payload_length;
};

struct packet_data {
    char* payload;
    size_t checksum;
};

struct connection_status {
    bool is_active;
    time_t last_active_time;
};

void handleNetworkTraffic() {
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }

    struct packet_header* packet_headers = (struct packet_header*)malloc(MAX_PACKETS * sizeof(struct packet_header));
    struct packet_data* packet_data = (struct packet_data*)malloc(MAX_PACKETS * sizeof(struct packet_data));
    struct connection_status* connection_statuses = (struct connection_status*)malloc(MAX_PACKETS * sizeof(struct connection_status));

    int i = 0;
    while (fscanf(file, "%u %u %zu\n", &packet_headers[i].source_port, &packet_headers[i].destination_port, &packet_headers[i].payload_length) == 3) {
        packet_data[i].payload = (char*)malloc(packet_headers[i].payload_length + 1);
        fscanf(file, "%s\n", packet_data[i].payload);
        packet_data[i].checksum = rand() % (MAX_PAYLOAD_SIZE - 1);

        connection_statuses[i].is_active = i > 0;
        connection_statuses[i].last_active_time = time(NULL) - rand() % (int)time(NULL);

        printf("Packet %d: Source Port %u, Destination Port %u, Payload Length %zu, Payload %s, Checksum %zu, Is Active %d, Last Active Time %ld\n", i, packet_headers[i].source_port, packet_headers[i].destination_port, packet_headers[i].payload_length, packet_data[i].payload, packet_data[i].checksum, connection_statuses[i].is_active, connection_statuses[i].last_active_time);

        free(packet_data[i].payload);
        i++;
    }

    fclose(file);

    for (int j = 0; j < i; j++) {
        free((void*)packet_headers[j].payload);
    }

    free(packet_headers);
    free(packet_data);
    free(connection_statuses);
}

int main() {
    handleNetworkTraffic();
    return 0;
}
