// Define a struct to hold start and end times
typedef struct {
    time_t start;
    time_t end;
} timestamp;

void processAndComputeStatistics(int fd) {
    // Initialize arrays
    double* measurements = (double*)malloc(sizeof(double));
    timestamp* timestamps = (timestamp*)malloc(sizeof(timestamp));

    int numMeasurements = 0;

    // Read measurements from file and initialize array
    while (1) {
        double measurement;
        if (read(fd, &measurement, sizeof(measurement)) != sizeof(measurement)) {
            break;
        }
        *++measurements = measurement;
        numMeasurements++;
    }

    // Initialize timestamps with current system time
    for (int i = 0; i < numMeasurements; i++) {
        timestamp t;
        t.start = time(NULL);
        t.end = time(NULL);
        *++timestamps = t;
    }

    // Free memory when done
    free(measurements);
    free(timestamps);

    // Compute statistics
    double sum = 0.0, avg = 0.0;
    for (int i = 0; i < numMeasurements; i++) {
        sum += measurements[i];
    }
    avg = sum / numMeasurements;

    printf("Mean: %f\n", avg);

    // Calculate median
    double med[] = {avg};
    if (numMeasurements % 2 == 1) {
        int idx = numMeasurements / 2;
        for (int i = 0; i < idx; i++) {
            med[i] = measurements[i];
        }
    } else {
        int idx = numMeasurements / 2 - 1;
        for (int i = 0; i <= idx; i++) {
            med[i] = measurements[i];
        }
    }

    // Calculate standard deviation
    double stdev = 0.0;
    for (int i = 0; i < numMeasurements; i++) {
        stdev += pow(measurements[i] - avg, 2);
    }
    stdev /= numMeasurements;

    printf("Median: %f\n", med[numMeasurements / 2]);
    printf("Standard Deviation: %f\n", sqrt(stdev));

    // Compute moving average
    int windowSize = 10;
    double* movingAverage = (double*)malloc(sizeof(double) * windowSize);
    for (int i = 0; i < windowSize; i++) {
        movingAverage[i] = measurements[numMeasurements - windowSize + i];
    }

    printf("Moving Average: ");
    for (int i = 0; i < windowSize; i++) {
        printf("%f ", movingAverage[i]);
    }
    printf("\n");

    // Free memory
    free(movingAverage);
}
