    pthread_t thread;
    pthread_create(&thread, NULL, process_records, (void*)num_records);
    pthread_join(thread);

    // Release memory
    for(int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);

    return 0;
}
