void manageSensorData(int debug_mode) {
    int max_size = 1000; // Predefined maximum size
    float* sensor = (float*)malloc(max_size * sizeof(float));
    time_t* timestamp = (time_t*)malloc(max_size * sizeof(time_t));
    int* aggregated = (int*)malloc(max_size * sizeof(int));

    FILE* file = fopen("sensor_data.txt", "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    int i = 0;
    while (fscanf(file, "%f %ld %d", &sensor[i], &timestamp[i], &aggregated[i]) != 3 && i < max_size) {
        i++;
    }
    fclose(file);

    // Calculate average, min and max sensor readings
    float sum = 0.0;
    int min_val = INT_MAX;
    int max_val = INT_MIN;
    for (int j = 0; j < i; j++) {
        sum += sensor[j];
        if (sensor[j] < min_val) min_val = sensor[j];
        if (sensor[j] > max_val) max_val = sensor[j];
    }
    float avg = sum / i;

    // Print calculated values
    printf("Average: %f\n", avg);
    printf("Min: %d\n", min_val);
    printf("Max: %d\n", max_val);

    if (debug_mode) {
        for (int j = 0; j < i; j++) {
            printf("Sensor reading: %f at timestamp %ld with status %d\n", sensor[j], timestamp[j], aggregated[j]);
        }
    }

    // Free memory
    for (int j = 0; j < i; j++) {
        free(sensor);
        free(timestamp);
        free(aggregated);
    }
}

