        rec[i].value = rand() % record_range + 1;
    }

    // Read integers from standard input and store in 'input' array
    int input_size = 0;
    while (scanf("%d", &input[input_size]) == 1) {
        input_size++;
    }
    input = (int*)realloc(input, (input_size + 1) * sizeof(int));
    input[input_size] = '\0';

    // Check if 'record' array size is not greater than sum of sizes
    if (record_size > offset_size + key_size + input_size) {
        printf("Error: Record array size exceeds maximum allowed.\n");
        return;
