    }
    printf("\n");

    printf("Input array:\n");
    for (int i = 0; i < input_size; i++) {
        printf("%d ", input[i]);
    }
    printf("\n");

    // Find and print largest integer in 'input' array
    int max_input = findMax(input, input_size);
    printf("Maximum value in input array: %d\n", max_input);

    // Free allocated memory when done
    free(offset);
    free(key);
    free(rec);
    free(input);

    return;
}

int findMax(int* arr, int size) {
    if (size == 0)
        return -1;

    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void dns_resolution(char* hostname) {
    struct addrinfo hints, *res;
    int s;
    char ip[INET6_ADDRSTRLEN];

    // Initialize hints
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = 0; // Any protocol
    hints.ai_flags = AI_CANONNAME | AI_NUMERICHOST;

    // Resolve hostname to IP address
    s = getaddrinfo(hostname, NULL, &hints, &res);
    if (s != 0) {
        printf("Error: %s\n", gai_strerror(s));
        return;
    }

    // Get the first result
    struct addrinfo* ptr = res;
    while (ptr && ptr->ai_addr) {
        // Convert IPv4 and IPv6 addresses to ASCII strings
        inet_ntop(ptr->ai_family, &((struct sockaddr_in*)ptr->ai_addr)->sin_addr, ip, sizeof(ip));
        printf("IP address: %s\n", ip);
        break;
    }

    // Free memory
    freeaddrinfo(res);

    return;
}

int main() {
    processAndFindMaxWithExternalData(4, 3, 100);
    dns_resolution("www.example.com");
    return 0;
}
