// Define a struct for timestamps
typedef struct {
    time_t start;
    time_t end;
} timestamp;

// Function to process and compute statistics
void processAndComputeStatistics(int fd, int window_size, int valid_range_start, int valid_range_end) {
    // Dynamically allocate memory for arrays
    double* measurements = (double*)malloc(sizeof(double));
    timestamp* timestamps = (timestamp*)malloc(sizeof(timestamp));
    int* moving_averages = (int*)malloc(sizeof(int));

    // Initialize arrays
    measurements[0] = 0.0; // Read from file descriptor and initialize array
    timestamps[0].start = 0; 
    timestamps[0].end = 0;
    for (int i = 1; ; i++) {
        // Read next measurement from file descriptor
        if (fscanf(fd, "%lf", &measurements[i]) != 1) break;

        // Calculate timestamp based on current system time
        timestamps[i].start = clock();
        timestamps[i].end = clock();

        // Initialize moving average
        moving_averages[i] = 0;
    }

    // Free allocated memory when done
    free(measurements);
    free(timestamps);
    free(moving_averages);

    // Compute statistical measures (mean, median, std dev) and print them
    double mean = 0.0; 
    for (int i = 0; ; i++) {
        if (i >= window_size) break;
        mean += measurements[i];
    }
    printf("Mean: %.2lf\n", mean / window_size);

    // Compute median
    qsort(measurements, window_size, sizeof(double), &compare_double);
    printf("Median: %.2lf\n", measurements[window_size/2]);

    // Compute standard deviation
    double std_dev = 0.0;
    for (int i = 0; ; i++) {
        if (i >= window_size) break;
        std_dev += pow(measurements[i] - mean, 2);
    }
    printf("Standard Deviation: %.2lf\n", sqrt(std_dev / window_size));

    // Return valid moving averages
    for (int i = 0; ; i++) {
        if (i >= window_size) break;
        int avg = 0;
        for (int j = 0; j < window_size; j++) {
            avg += measurements[j];
        }
        avg /= window_size;
        if (avg >= valid_range_start && avg <= valid_range_end)
            printf("Moving Average: %d\n", avg);
    }

    // Deinitialize external time library
    // Handle potential integer overflow robustly across different platforms
    return;
}

// Helper function to compare double values for qsort
int compare_double(const void* a, const void* b) {
    double x = *(const double*)a;
    double y = *(const double*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}
