    double* measurements = (double*)malloc(numMeasurements * sizeof(double));
    char** identifiers = (char**)malloc(numMeasurements * sizeof(char*));
    time_t* timestamps = (time_t*)malloc(numMeasurements * sizeof(time_t));
    struct event* events = (struct event*)malloc(numMeasurements * sizeof(struct event));
    log_entry* logs = (log_entry*)malloc(numMeasurements * sizeof(log_entry));

