    for (int i = 0; i < numMeasurements; i++) {
        measurements[i] = i;
        identifiers[i] = "Measurement";
    }

    // Initialize timestamp, event, and log arrays with random data
    for (int i = 0; i < numMeasurements; i++) {
        timestamps[i] = time(NULL) + rand() % 10000;
        events[i].measurement = measurements[i];
        events[i].identifier = identifiers[i];
        events[i].timestamp = timestamps[i];
        logs[i].timestamp = timestamps[i];
        logs[i].status_code = rand() % 5;
    }

    // Check if event array size exceeds measurement and identifier array sizes
    if (numMeasurements > sizeof(measurements) / sizeof(measurements[0]) + sizeof(identifiers) / sizeof(identifiers[0])) {
        printf("Error: Event array size exceeds measurement and identifier array sizes.\n");
    }

