int processAndFindMaxAdvanced(int nRecords, int nKeys, int nOffsets) {
    // Initialize variables
    srand(time(NULL)); // seed for random number generation
    long* offsetArray = (long*)malloc(nOffsets * sizeof(long));
    int* keyArray = (int*)malloc(nKeys * sizeof(int));
    Record** recordArray1 = (Record**)malloc(nRecords * sizeof(Record*));
    Record** recordArray2 = (Record**)malloc(nRecords * sizeof(Record*));

    // Initialize offset and key arrays
    for (int i = 0; i < nOffsets; i++) {
        offsetArray[i] = generateRandomLong(-10000000, 10000000);
    }
    for (int i = 0; i < nKeys; i++) {
        keyArray[i] = rand() % 100;
    }

    // Initialize record arrays
    for (int i = 0; i < nRecords; i++) {
        recordArray1[i] = (Record*)malloc(sizeof(Record));
        recordArray2[i] = (Record*)malloc(sizeof(Record));

        if (rand() % 2 == 0) { // 50% chance of single int value
            recordArray1[i]->key = rand() % 100;
            recordArray1[i]->offset = 0;
            recordArray1[i]->timestamp = 0.0;
        } else {
            recordArray1[i]->key = generateRandomLong(-10000000, 10000000);
            recordArray1[i]->offset = generateRandomLong(-10000000, 10000000);
            recordArray1[i]->timestamp = (double)rand() / RAND_MAX;
        }

        if (rand() % 2 == 0) { // 50% chance of single int value
            recordArray2[i]->key = rand() % 100;
            recordArray2[i]->offset = 0;
            recordArray2[i]->timestamp = 0.0;
        } else {
            recordArray2[i]->key = generateRandomLong(-10000000, 10000000);
            recordArray2[i]->offset = generateRandomLong(-10000000, 10000000);
            recordArray2[i]->timestamp = (double)rand() / RAND_MAX;
        }
    }

    // Check for memory leaks
    if (!recordArray1 || !recordArray2 || !offsetArray || !keyArray) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Print contents of arrays for debugging purposes
    for (int i = 0; i < nRecords; i++) {
        printf("Record %d: key=%d, offset=%ld, timestamp=%.2f\n",
               i, recordArray1[i]->key, recordArray1[i]->offset,
               recordArray1[i]->timestamp);
    }

    // Free all allocated memory when the function returns
    for (int i = 0; i < nRecords; i++) {
        free(recordArray1[i]);
        free(recordArray2[i]);
    }
    free(offsetArray);
    free(keyArray);

    return 0;
}

int main() {
    int nRecords, nKeys, nOffsets;
    printf("Enter the number of records, keys, and offsets: ");
    scanf("%d %d %d", &nRecords, &nKeys, &nOffsets);

    processAndFindMaxAdvanced(nRecords, nKeys, nOffsets);
}
