#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define INITIAL_CAPACITY 16
#define MAX_CAPACITY 64
#define LOAD_FACTOR_THRESHOLD 0.75
#define VALUE_RANGE 100

typedef struct {
    int key;
    long offset;
    struct record_value {
        int value;
        char *str;
    } *value;
} Record;

Record **hash_table;
int table_size;
int num_records;

void init_hash_table() {
    hash_table = (Record **)malloc(INITIAL_CAPACITY * sizeof(Record *));
    if (!hash_table) return; // Handle memory allocation failure
    for (int i = 0; i < INITIAL_CAPACITY; i++) hash_table[i] = NULL;
    table_size = INITIAL_CAPACITY;
}

void resize_hash_table() {
    int new_size = table_size * 2;
    Record **new_table = (Record **)realloc(hash_table, new_size * sizeof(Record *));
    if (!new_table) return; // Handle memory allocation failure
    hash_table = new_table;
    for (int i = table_size; i < new_size; i++) hash_table[i] = NULL;
    table_size = new_size;
}

long polynomial_hash(int key) {
    long hash = 0;
    for (int i = 0; i < 32 && i < sizeof(int); i++) {
        hash = (hash << 1) | (key & 1);
        key >>= 1;
    }
    return hash % table_size;
}

void add_record(int key, long offset, int value) {
    Record *record = (Record *)malloc(sizeof(Record));
    if (!record) return; // Handle memory allocation failure
    record->key = key;
    record->offset = offset;
    record->value = (struct record_value *)malloc(sizeof(struct record_value));
    if (!record->value) return; // Handle memory allocation failure
    record->value->value = value;
    record->value->str = NULL;
    int index = polynomial_hash(key);
    while (hash_table[index]) {
        // Collision resolution using separate chaining
        index = (index + 1) % table_size;
    }
    hash_table[index] = record;
}

Record *get_record(int key) {
    int index = polynomial_hash(key);
    Record *current = hash_table[index];
    while (current) {
        if (current->key == key) return current;
        current = current->value->str ? NULL : current + 1;
    }
    return NULL; // Key not found
}

void remove_record(int key) {
    int index = polynomial_hash(key);
    Record *current = hash_table[index];
    while (current) {
        if (current->key == key) {
            free(current->value);
            free(current);
            hash_table[index] = current->value ? NULL : current + 1;
            return;
        }
        current = current->value->str ? NULL : current + 1;
    }
}

void free_hash_table() {
    for (int i = 0; i < table_size; i++) {
        Record *current = hash_table[i];
        while (current) {
            Record *next = current->value->str ? NULL : current + 1;
            free(current->value);
            free(current);
            current = next;
        }
    }
    free(hash_table);
}

int main() {
    srand(time(NULL));
    init_hash_table();
    // Initialize records with random keys and values
    for (num_records = 0; num_records < table_size * LOAD_FACTOR_THRESHOLD; num_records++) {
        int key = rand() % INT_MAX;
        long offset = rand() % LONG_MAX;
        int value = rand() % VALUE_RANGE;
        add_record(key, offset, value);
    }
    // Perform operations to demonstrate the hash table
    Record *record = get_record(42);
    if (record) printf("Found record with key 42 and offset %ld\n", record->offset);
    else printf("Record not found with key 42\n");
    remove_record(0);
    free_hash_table();
    return 0;
}
