    // Initialize arrays with static values
    int* logLevels = (int*)malloc(sizeof(int) * 3);
    char** logMessages = (char**)malloc(sizeof(char*) * 3);
    ExtendedLogEvent* extendedEvents = (ExtendedLogEvent*)malloc(sizeof(ExtendedLogEvent) * numStaticEntries);

    // Initialize arrays with user-provided data
    int* userInputLevels = (int*)malloc(sizeof(int));
    char** userInputMessages = (char**)malloc(sizeof(char*));
    int userInputNumEntries = 0;

    while (fscanf(stdin, "%d %s", &(*userInputLevels), (*userInputMessages)) == 2) {
        extendedEvents[userInputNumEntries].priority = *userInputLevels;
        extendedEvents[userInputNumEntries].duration = rand() % 100; // Initialize with random duration
        userInputNumEntries++;
    }

    // Calculate frequency of each log level
    int* logLevelCounts = (int*)malloc(sizeof(int) * 3);
    for (int i = 0; i < numStaticEntries + userInputNumEntries; i++) {
        if (extendedEvents[i].priority >= minPriority && extendedEvents[i].logMessage != NULL) {
            logLevelCounts[extendedEvents[i].priority]++;
        }
    }

    // Serialize log data to JSON file
    FILE* jsonFile = fopen("log_data.json", "w");
    for (int i = 0; i < numStaticEntries + userInputNumEntries; i++) {
        if (extendedEvents[i].priority >= minPriority && extendedEvents[i].logMessage != NULL) {
            fprintf(jsonFile, "{\"priority\": %d, \"duration\": %d}\n", extendedEvents[i].priority, extendedEvents[i].duration);
        }
    }

    // Free allocated memory
    free(logLevels);
    free(logMessages);
    free(extendedEvents);
    free(userInputLevels);
    free(*userInputMessages);
    free(logLevelCounts);

    fclose(jsonFile);
}
