// Define the custom structure for time-series data points
typedef struct {
    int value;
} TimeSeriesPoint;

// Define the hash table entry structure
typedef struct {
    char* key;
    TimeSeriesPoint* point;
} HTableEntry;

// Function to initialize and manage two hash tables
void initHashTables(int numEntries, int maxEntries) {
    // Initialize the hash tables
    HTable* ht1 = htable_init(maxEntries);
    HTable* ht2 = htable_init(maxEntries);

    // Initialize random seed for time-series data points
    srand(time(NULL));

    // Insert entries into hash tables
    for (int i = 0; i < numEntries; i++) {
        char key[256];
        sprintf(key, "Key_%d", i);

        TimeSeriesPoint* point = malloc(sizeof(TimeSeriesPoint));
        point->value = rand() % 100;

        HTableEntry entry = {key, point};
        htable_insert(ht1, &entry);
        htable_insert(ht2, &entry);
    }

    // Deinitialize the hash tables
    htable_deinit(ht1);
    htable_deinit(ht2);

    // Free memory allocated for time-series data points
    for (int i = 0; i < numEntries; i++) {
        free(htable_get(ht1, "Key_%d")->point);
        free(htable_get(ht2, "Key_%d")->point);
    }
}

int main() {
    initHashTables(100, 500);
    return 0;
}
