#include <stdlib.h>
#include <stdio.h>

// Structure representing a node in the linked list
typedef struct {
    int *array; // Dynamic array of integers
    int size; // Size of the array
    struct Node* prev;
    struct Node* next;
} Node;

// Function to initialize and manage memory for a doubly linked list
Node* initLinkedList(int maxElements, int maxArraySize) {
    Node* head = (Node*)malloc(sizeof(Node));
    if (!head) {
        return NULL; // Handle malloc error
    }

    head->array = (int*)malloc(maxArraySize * sizeof(int));
    head->size = 0;
    head->prev = head;
    head->next = head;

    int totalElements = 0;
    while (totalElements < maxElements) {
        // Initialize the array with specific values
        for (int i = 0; i < maxArraySize; i++) {
            head->array[i] = i;
        }
        head->size = maxArraySize;

        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            return NULL; // Handle malloc error
        }

        newNode->array = (int*)malloc(maxArraySize * sizeof(int));
        newNode->size = 0;
        newNode->prev = head;
        newNode->next = head->next;

        head->next->prev = newNode;
        head->next = newNode;
        head = newNode;

        totalElements++;
    }

    return head;
}

// Function to free all allocated memory
void freeLinkedList(Node* head) {
    Node* current = head;
    while (current != head) {
        Node* next = current->next;
        free(current->array);
        free(current);
        current = next;
    }
    free(head->array);
    free(head);
}
