using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;

namespace UserManagementSystem
{
    [ApiController]
    [Route("api/[controller]")]
    public class UserController : ControllerBase
    {
        private readonly IAuthenticationService _authenticationService;
        private readonly ILogger<UserController> _logger;

        public UserController(IAuthenticationService authenticationService, ILogger<UserController> logger)
        {
            _authenticationService = authenticationService;
            _logger = logger;
        }

        [HttpPost("register")]
        public async Task<IActionResult> RegisterUser([FromBody]RegisterUserRequest request)
        {
            if (!await ValidateSessionToken(request.SessionToken))
                return BadRequest("Invalid or expired session token");

            var username = request.Username;
            var password = request.Password;

            // Check for empty credentials
            if (string.IsNullOrEmpty(username) || string.IsNullOrEmpty(password))
                return BadRequest("Username and password are required");

            // Implement complexity requirements check

            // Check for existing user
            if (await _authenticationService.UserExists(username))
                return Conflict($"User '{username}' already exists. Please update the username or create a new account");

            try
            {
                await _authenticationService.RegisterUser(username, password);
                // Set default roles and retrieve additional user information from external service
                await _authenticationService.SetDefaultRolesAndRetrieveUserInfo();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error registering user");
                return StatusCode(500, "Internal Server Error");
            }

            return Ok("User registered successfully");
        }

        private async Task<bool> ValidateSessionToken(string sessionToken)
        {
            try
            {
                // Check if the token is valid and not expired
                await _authenticationService.ValidateSessionToken(sessionToken);
                return true;
            }
            catch (Exception ex)
            {
                // Handle invalid or expired token gracefully
                _logger.LogError(ex, "Error validating session token");
                return false;
            }
        }
    }

    public class RegisterUserRequest
    {
        public string Username { get; set; }
        public string Password { get; set; }
        public string SessionToken { get; set; }
    }
}
