void processAndAggregateData() {
    FILE *config_file = stdin;
    int num_measurements, num_events, i;
    double measurements[MAX_MEASUREMENTS];
    char* identifiers[MAX_MEASUREMENTS];
    time_t timestamps[MAX_MEASUREMENTS];
    Event events[MAX_EVENTS];
    User users[5];

    srand(time(NULL));

    // Read configuration file and initialize arrays
    fscanf(config_file, "%d %d", &num_measurements, &num_events);

    for (i = 0; i < num_measurements; i++) {
        fscanf(config_file, "%lf %s", &measurements[i], identifiers[i]);
    }

    // Initialize random timestamps and event details
