        events[i].measurement = measurements[rand() % num_measurements];
        events[i].identifier = identifiers[rand() % num_measurements];
        events[i].timestamp = rand() % time(NULL);
    }

    // Initialize random user profiles
    for (i = 0; i < 5; i++) {
        users[i].username = (char*)malloc(10 * sizeof(char));
        strcpy(users[i].username, "User");
        users[i].user_id = rand() % 100;
    }

