    if (num_events > num_measurements + num_events) {
        printf("Error: event size exceeds measurement and identifier sizes.\n");
        return;
    }

    // Print arrays for debugging
    for (i = 0; i < num_measurements; i++) {
        printf("Measurement %d: %.2f, Identifier: %s\n", i, measurements[i], identifiers[i]);
    }
    for (i = 0; i < num_events; i++) {
        printf("Event %d: Measurement %.2f, Identifier %s, Timestamp %ld\n", i, events[i].measurement, events[i].identifier, events[i].timestamp);
    }

    // Free allocated memory
    for (i = 0; i < num_measurements; i++) {
        free(identifiers[i]);
    }
    for (i = 0; i < 5; i++) {
        free(users[i].username);
    }

    fclose(config_file);
}

int main() {
    processAndAggregateData();
    return 0;
}
