        timestamps[i] = rand() % (time(NULL) + 1);
        events[i].measurement = measurements[i];
        events[i].identifier = identifiers[i];
        events[i].timestamp = timestamps[i];
    }

    // Check if the 'event' array size exceeds the sum of 'measurement' and 'identifier' sizes
    if (numMeasurements > sizeof(double) * numMeasurements + sizeof(char*) * numMeasurements) {
