    for (int i = 0; i < numMeasurements; i++) {
        printf("%lu\n", timestamps[i]);
    }
    printf("Events:\n");
    for (int i = 0; i < numMeasurements; i++) {
        printf("(%f, %s, %lu)\n", events[i].measurement, events[i].identifier, events[i].timestamp);
    }

    // Calculate and print the average measurement in the array
    double averageMeasurement = 0.0;
    for (int i = 0; i < numMeasurements; i++) {
        averageMeasurement += measurements[i];
    }
    printf("Average Measurement: %f\n", averageMeasurement / numMeasurements);

    // Free all allocated memory when the function returns
    for (int i = 0; i < numMeasurements; i++) {
        free(identifiers[i]);
    }
    free(identifiers);
    free(timestamps);
    free(events);
    free(measurements);
}

// Helper function to read a list of measurements from standard input and calculate the average measurement
double readAndCalculateAverage(int numMeasurements) {
    double* measurements = (double*)malloc(numMeasurements * sizeof(double));
    for (int i = 0; i < numMeasurements; i++) {
        scanf("%lf", &measurements[i]);
    }
    double averageMeasurement = 0.0;
    for (int i = 0; i < numMeasurements; i++) {
        averageMeasurement += measurements[i];
    }
    free(measurements);
    return averageMeasurement / numMeasurements;
}

// Function to print the contents of an array
void printArray(double* arr, int size) {
    for (int i = 0; i < size; i++) {
        printf("%f\n", arr[i]);
    }
}
