} Entry;

void* allocate_memory(int num_entries, int max_timestamp, int max_payload) {
    void* memory = NULL;

    // Allocate memory pool for array of 'offset' integers
    size_t offset_size = num_entries * sizeof(int);
    int* offsets = (int*)malloc(offset_size);
    if (!offsets) return NULL; // handle allocation failure

    // Allocate memory pool for array of 'key' integers
    size_t key_size = num_entries * sizeof(int);
    int* keys = (int*)malloc(key_size);
    if (!keys) {
        free(offsets); // deallocate previous memory
        return NULL;
    }

    // Allocate memory pool for array of 'entry' structures
    size_t entry_size = num_entries * sizeof(Entry);
    Entry* entries = (Entry*)malloc(entry_size);
    if (!entries) {
        free(keys); // deallocate previous memories
        free(offsets);
        return NULL;
    }

    // Initialize memory pool
    memory = (void*)malloc(sizeof(void*));
    *(int*)memory = num_entries; // store number of entries in the first int

    return memory;
}

void deallocate_memory(void* memory) {
    if (!memory) return; // handle null pointer

    int* num_entries = (int*)memory;
    int n = *num_entries;

    // Deallocate array of 'offset' integers
    free((int*)(((char*)memory) + sizeof(int)));

    // Deallocate array of 'key' integers
    free((int*)(((char*)memory) + 2 * sizeof(int)));

    // Deallocate array of 'entry' structures
    free((Entry*)(((char*)memory) + 3 * sizeof(int)));

    free(memory); // deallocate memory pool
}
