void hash_table_print(const hash_table_t* table);

hash_table_t* hash_table_new(size_t capacity) {
    hash_table_t* table = malloc(sizeof(hash_table_t));
    if (!table) return NULL;

    table->records = calloc(capacity, RECORD_SIZE);
    if (!table->records) {
        free(table);
        return NULL;
    }

    table->capacity = capacity;
    table->count = 0;

    return table;
}

void hash_table_init(hash_table_t* table, size_t initial_capacity) {
    table->records = calloc(initial_capacity, RECORD_SIZE);
    if (!table->records) {
        free(table);
        return;
    }

    table->capacity = initial_capacity;
    table->count = 0;
}

void hash_table_insert(hash_table_t* table, int key, long value) {
    // Implement your own hash function or use a library
    size_t index = (size_t)(key % table->capacity);

    if (table->records[index].key == -1) {
        record_t* new_record = &table->records[index];
        new_record->key = key;
        new_record->value = value;
        table->count++;

        // Resize the hash table when necessary
        if ((float)table->count / table->capacity > GROWTH_THRESHOLD) {
            size_t new_capacity = (size_t)(table->capacity * 2);
            hash_table_t* new_table = malloc(sizeof(hash_table_t));
            new_table->records = realloc(table->records, new_capacity * RECORD_SIZE);
            new_table->capacity = new_capacity;
            new_table->count = table->count;

            // Rehash all existing records
            for (size_t i = 0; i < table->capacity; i++) {
                if (table->records[i].key != -1) {
                    hash_table_insert(new_table, table->records[i].key, table->records[i].value);
                }
            }

            free(table->records);
            *table = *new_table;
        }
    } else {
        printf("Key already exists: %d\n", key);
    }
}

record_t* hash_table_find(hash_table_t* table, int key) {
    size_t index = (size_t)(key % table->capacity);

    if (table->records[index].key == key) {
        return &table->records[index];
    }

    for (size_t i = 0; i < table->capacity; i++) {
        if (table->records[i].key == key) {
            return &table->records[i];
        }
    }

    return NULL;
}

void hash_table_print(const hash_table_t* table) {
    printf("Hash Table Contents:\n");
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->records[i].key != -1) {
            printf("%d: %ld\n", table->records[i].key, table->records[i].value);
        }
    }
}
