// Define a custom hash table data structure
typedef struct {
    int key;
    int value;
} record;

typedef struct {
    int size;
    record **buckets;
} hash_table;

void init_hash_table(hash_table *table, int initial_size) {
    table->size = initial_size;
    table->buckets = (record **)malloc(initial_size * sizeof(record *));
    for (int i = 0; i < initial_size; i++) {
        table->buckets[i] = NULL;
    }
}

void resize_hash_table(hash_table *table, int new_size) {
    record **new_buckets = (record **)malloc(new_size * sizeof(record *));
    for (int i = 0; i < new_size; i++) {
        new_buckets[i] = NULL;
    }

    for (int i = 0; i < table->size; i++) {
        if (table->buckets[i]) {
            int idx = i % new_size;
            while (new_buckets[idx]) {
                idx = (idx + 1) % new_size;
            }
            new_buckets[idx] = table->buckets[i];
        }
    }

    free(table->buckets);
    table->size = new_size;
    table->buckets = new_buckets;
}

int hash(record *key, int size) {
    return key->key % size;
}

record *find_in_hash_table(hash_table *table, int key) {
    int idx = hash(&key, table->size);
    while (table->buckets[idx]) {
        if (table->buckets[idx]->key == key) {
            return table->buckets[idx];
        }
        idx = (idx + 1) % table->size;
    }
    return NULL;
}

void insert_into_hash_table(hash_table *table, record *new_record) {
    int idx = hash(&new_record->key, table->size);
    while (table->buckets[idx]) {
        if (table->buckets[idx]->key == new_record->key) {
            // Handle duplicate key
            return;
        }
        idx = (idx + 1) % table->size;
    }
    table->buckets[idx] = new_record;
    if (table->size * 2 > 100000) { // Check for resizing criteria
        resize_hash_table(table, table->size * 2);
    }
}

void free_unused_memory() {
    // TO DO: Implement a garbage collection mechanism to free unused memory
}

int main() {
    // Initialize the hash table with an initial size of 16
    hash_table log_system;
    init_hash_table(&log_system, 16);

    // Insert records into the hash table
    record *record1 = (record *)malloc(sizeof(record));
    record1->key = 1;
    record1->value = 10;

    record *record2 = (record *)malloc(sizeof(record));
    record2->key = 2;
    record2->value = 20;

    // ...

    insert_into_hash_table(&log_system, record1);
    insert_into_hash_table(&log_system, record2);

    // Perform lookups in the hash table
    int key = 1;
    record *found_record = find_in_hash_table(&log_system, key);
    if (found_record) {
        printf("Found record with key %d: value %d\n", key, found_record->value);
    } else {
        printf("Record not found with key %d\n", key);
    }

    // Free unused memory
    free_unused_memory();

    return 0;
}
