    free(measurements);
}

void logOperation(int log_level, char *message) {
    // Record operation log
    log_entry *log_entry = (log_entry *)malloc(sizeof(log_entry));
    log_entry->log_level = log_level;
    log_entry->message = (char *)malloc(strlen(message) + 1);
    strcpy(log_entry->message, message);
    log_entry->timestamp = time(NULL);

    // Add log entry to array
    log_entries[num_measurements++] = *log_entry;

    free(log_entry->message);
    free(log_entry);
}

int main() {
    processAndAggregateDataAdvanced(9);
    readMeasurements(5);
    return 0;
}
