element* create_node(int id, double value) {
    element* new_element = (element*)malloc(sizeof(element));
    if (!new_element) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }
    new_element->id = id;
    new_element->value = value;
    return new_element;
}

void free_node(element* node) {
    free(node);
}

int main() {
    int num_elements = 10; // change this to the desired number of elements
    element** nodes = (element**)malloc(num_elements * sizeof(element*));
    if (!nodes) {
        printf("Error: Memory allocation failed.\n");
        return -1;
    }

    for (int i = 0; i < num_elements; i++) {
        int id = rand() % 100; // random ID
        double value = (double)rand() / RAND_MAX * 10.0 + 5.0; // random floating-point value between 5 and 15
        nodes[i] = create_node(id, value);
    }

    for (int i = 0; i < num_elements - 1; i++) {
        nodes[i]->next = nodes[i+1];
    }
    nodes[num_elements-1]->next = NULL;

    // handle the linked list of elements
    element* current = nodes[0];
    while (current) {
        printf("ID: %d, Value: %f\n", current->id, current->value);
        current = current->next;
    }

    for (int i = 0; i < num_elements; i++) {
        free_node(nodes[i]);
    }
    free(nodes);

    return 0;
}
