void* manage_memory(int capacity) {
    // Initialize arrays of offset_t, uint32_t keys, and data_entry structures
    offset_t* offsets = (offset_t*)malloc(capacity * sizeof(offset_t));
    uint32_t* keys = (uint32_t*)malloc(capacity * sizeof(uint32_t));
