    // Initialize hash table with a dynamically resizing capacity
    hash_table* ht = init_hash_table(capacity);

    // Set configuration limits for the system
    int max_capacity = 100000;
    int limit_exceeded = 0;

    while (1) {
        // Perform periodic maintenance tasks, such as cleaning up unused entries
        clean_up_unused_entries(entries, capacity);

        // Allocate memory for new data entries and update hash table
        int num_new_entries = get_new_entry_count();
        offset_t* new_offsets = (offset_t*)malloc(num_new_entries * sizeof(offset_t));
        uint32_t* new_keys = (uint32_t*)malloc(num_new_entries * sizeof(uint32_t));
        data_entry* new_entries = (data_entry*)malloc(num_new_entries * sizeof(data_entry));

