            new_entries[i].timestamp = time(NULL);
            new_entries[i].value = rand() / (double)RAND_MAX;
            new_entries[i].node = insert_into_hash_table(ht, new_keys[i], &new_entries[i]);
        }

        // Check if the system has exceeded its capacity limit
        int total_size = get_total_size(entries, keys, offsets, ht);
        if (total_size > max_capacity) {
            printf("Warning: System capacity exceeded!\n");
            limit_exceeded = 1;
        } else {
            limit_exceeded = 0;
        }

        // Log system operations and errors using the external logging service
        log_system_operations(limit_exceeded);

        // Free memory allocated for new entries
        free(new_offsets);
        free(new_keys);
        free(new_entries);

        // Check if the system needs to be resized based on the growth rate of key lookups
        if (get_key_lookup_rate() > 0.10) {
            capacity *= 1.1;
            ht = resize_hash_table(ht, capacity);
        }
    }

    return NULL;
}
