    *entries_array = (data_entry**)malloc(MAX_ENTRIES * sizeof(data_entry*));
    for (i = 0; i < MAX_ENTRIES; i++) {
        (*entries_array)[i] = (data_entry*)malloc(sizeof(data_entry));
        if ((*entries_array)[i] == NULL) {
            free(*offset_t_array);
            free(*keys_array);
            return -1;
