    static int mem_pool_id = 0;
    static void** mem_pool = NULL;

    // Initialize memory pool if not already done
    if (mem_pool == NULL) {
        mem_pool = (void**)malloc(16 * sizeof(void*));
        for (int i = 0; i < 16; i++) {
            mem_pool[i] = NULL;
        }
        mem_pool_id++;
    }

    // Find a free memory block
    int pool_idx = -1;
    for (int i = 0; i < 16; i++) {
        if (mem_pool[i] == NULL) {
