import re
import gzip
import heapq
from collections import defaultdict
from functools import lru_cache

def process_log_file(log_file_path: str, module_pattern: str, ignore_pattern: str) -> dict:
    @lru_cache(maxsize=None)
    def parse_chunk(chunk):
        errors = defaultdict(int)
        for line in chunk.decode().splitlines():
            if re.fullmatch(module_pattern, line):
                error_message = re.sub(module_pattern, '', line).strip()
                errors[error_message] += 1
        return dict(errors)

    try:
        with open(log_file_path, 'rb') as file:
            with gzip.open(file.name + '.gz', 'wb') as gz_file:
                chunk_size = 1024 * 1024  # process in chunks of 1MB
                error_counts = defaultdict(int)
                for i in range(0, file.size, chunk_size):
                    file.seek(i)
                    chunk = bytearray(chunk_size)
                    file.readinto(chunk)
                    if not gz_file:
                        yield from parse_chunk(chunk)
                    else:
                        with gzip.open(file.name + '.gz', 'wb') as gz_file:
                            gz_file.write(chunk)

    except Exception as e:
        print(f"Error processing log file: {e}")
