#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double x, y;
    int z;
    char c;
} Vector;

void init_resources() {
    // Dynamic memory allocation for data structures
    double* doubles = (double*)malloc(7 * sizeof(double));
    Vector* vectors = (Vector*)malloc(7 * sizeof(Vector));
    char** strings = (char**)malloc(7 * sizeof(char*));
    int* statuses = (int*)malloc(7 * sizeof(int));
    time_t* timestamps = (time_t*)malloc(7 * sizeof(time_t));
    struct tm* events[7];
    int* resource_limits[7];

    // Initialize 'doubles' array from configuration file
    FILE* config_file = fopen("config.txt", "r");
    if (config_file) {
        char line[1024], *token;
        int i = 0;
        while (fgets(line, sizeof(line), config_file)) {
            token = strtok(line, " ");
            for (; token; token = strtok(NULL, " ")) {
                doubles[i++] = atof(token);
            }
        }
        fclose(config_file);
    }

    // Populate 'vectors' array with random vectors
    srand(time(NULL));
    for (int i = 0; i < 7; i++) {
        Vector* vector = &vectors[i];
        vector->x = rand() / (double)RAND_MAX;
        vector->y = rand() / (double)RAND_MAX;
        vector->z = rand();
        vector->c = rand() % 26 + 'a';
    }

    // Initialize 'strings' pointers by allocating memory and copying data
    FILE* strings_file = fopen("strings.txt", "r");
    if (strings_file) {
        char line[1024];
        int i = 0;
        while (fgets(line, sizeof(line), strings_file)) {
            strings[i] = (char*)malloc(strlen(line) + 1);
            strcpy(strings[i], line);
            i++;
        }
        fclose(strings_file);
    }

    // Initialize 'statuses' flags based on configuration file
    FILE* status_file = fopen("status.txt", "r");
    if (status_file) {
        char line[1024];
        while (fgets(line, sizeof(line), status_file)) {
            int value;
            sscanf(line, "%d", &value);
            statuses[i++] = value;
        }
        fclose(status_file);
    }

    // Initialize 'timestamps' and 'events'
    for (int i = 0; i < 7; i++) {
        timestamps[i] = time(NULL);
        events[i] = localtime(&timestamps[i]);
    }

    // Initialize 'resource_limits'
    for (int i = 0; i < 7; i++) {
        resource_limits[i] = (int*)malloc(7 * sizeof(int));
        for (int j = 0; j < 7; j++)
            resource_limits[i][j] = rand() % 100;
    }

    // Free allocated memory
    free(doubles);
    free(vectors);
    for (char** string : strings)
        free(*string);
    for (time_t* timestamp : timestamps)
        free(timestamp);
    for (int* status : statuses)
        free(status);

    // Serialize data structures to file
    FILE* output_file = fopen("state.txt", "w");
    if (output_file) {
        fwrite(doubles, sizeof(double), 7, output_file);
        fwrite(vectors, sizeof(Vector), 7, output_file);
        for (char** string : strings)
            fwrite(string, strlen(*string) + 1, 1, output_file);
        for (int* status : statuses)
            fwrite(&status, sizeof(int), 1, output_file);
        fclose(output_file);
    }
}

int main() {
    init_resources();
    return 0;
}
