cipher* init_cipher(int offset_array_size, int key_array_size, int record_array_size, const char* filename) {
    cipher* cipher = (cipher*)malloc(sizeof(cipher));

    // Allocate and initialize offset array
    cipher->offsets = (long*)malloc(offset_array_size * sizeof(long));
    for (int i = 0; i < offset_array_size; i++) {
        cipher->offsets[i] = i;
    }

    // Allocate and initialize key array
    cipher->keys = (int*)malloc(key_array_size * sizeof(int));
    for (int i = 0; i < key_array_size; i++) {
        cipher->keys[i] = i % 256;
    }

    // Initialize record array with random values
    srand(time(NULL));
    cipher->records = (record*)malloc(record_array_size * sizeof(record));
    for (int i = 0; i < record_array_size; i++) {
        cipher->records[i].value = rand() % 1000;
    }

    // Initialize filename buffer
    cipher->filename = (char*)malloc(strlen(filename) + 1);
    strcpy(cipher->filename, filename);

    return cipher;
