typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    Record* data;
    size_t capacity, size;
    pthread_mutex_t lock;
} HashTable;

HashTable* hash_table_create(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) return NULL;  // handle memory allocation failure
    table->data = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!table->data) {
        free(table); return NULL;
    }
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void hash_table_insert(HashTable* table, Record record) {
    size_t index = record.key % table->capacity;
    for (int i = 0; i < table->size; i++) {
        if (table->data[index].key == record.key) { // key collision
            while (1) {
                record.key++;
                index = record.key % table->capacity;
                if (i >= table->size) break;  // new slot available
            }
        }
    }
    if (table->size == table->capacity) {  // resize when full
        size_t new_capacity = table->capacity * 2;
        Record* newData = (Record*)realloc(table->data, new_capacity * sizeof(Record));
        if (!newData) {
            printf("Memory allocation failed!\n");
            return;  // handle memory allocation failure
        }
        table->data = newData;
        table->capacity = new_capacity;
    }
    table->data[index] = record;
    table->size++;
}

void hash_table_free(HashTable* table) {
    pthread_mutex_unlock(&table->lock);
    free(table->data);
    free(table);
}
