Record* processAndAggregateData(int numNodes, int numRecords) {
    // Initialize the collection
    int numRecordsTotal = numNodes * numRecords;
    Record* records = (Record*)malloc(numRecordsTotal * sizeof(Record));
    for (int i = 0; i < numRecordsTotal; i++) {
        // Initialize random key and timestamp
        int key = rand() % INT_MAX;
        long offset = rand() % LONG_MAX;

        // Insert record
        Record* currentRecord = &records[i];
        currentRecord->offset = offset;
        currentRecord->key = key;

        // Check for duplicate keys
        int j = 0;
        while (j < i) {
            if (records[j].key == key) {
                // Find unique key by incrementing the current value until a free slot is available
                do {
                    key++;
                } while ((j = findFreeSlot(records, numRecordsTotal)) != -1);
            }
            j++;
        }

        // Update the record with the new key
        currentRecord->key = key;
    }

    return records;
}

int findFreeSlot(Record* records, int size) {
    for (int i = 0; i < size; i++) {
        if (records[i].key == -1) {
            return i;
        }
    }
    return -1;
}
