int generate_random_value(int min, int max) {
    static const double random_weight = 0.5; // Weighted random distribution coefficient
    static const double max_sum = 100000; // Maximum allowed sum of integer values

    int value;
    do {
        value = (int)((rand() / (double)RAND_MAX) * (max - min + 1)) + min;
        if ((value > 0 && rand() % (int)(random_weight * RAND_MAX)) == 0)
            value = max; // Ensure sum is not exceeded
    } while (((value > 0) && (rand() / (double)RAND_MAX * (max_sum - value) < RAND_MAX)));

    return value;
}

Record* create_records(int num_records, int** offset_array, int** key_array, int target_sum) {
    Record* records = NULL;
    Record* current_record = NULL;

    // Calculate total memory needed for records
    size_t total_memory_needed = sizeof(Record) * num_records;

    if ((records = (Record*)custom_malloc(total_memory_needed)) == NULL) {
        // Log error and handle allocation failure
        printf("Error: Failed to allocate memory for records.\n");
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        current_record->offset = offset_array[i][0];
        current_record->key = key_array[i][0];

        // Generate random value within specified range and ensure sum does not exceed target
        int random_value = generate_random_value(1, target_sum);
        while (random_value > 0 && (rand() / (double)RAND_MAX * (target_sum - random_value) < RAND_MAX))
            random_value = generate_random_value(1, target_sum);

        current_record->value = random_value;

        // Check for edge cases
        if (current_record->offset < 0 || current_record->key < 0)
            printf("Error: Invalid offset or key value.\n");

        if (current_record->key != i)
            printf("Error: Duplicate key found.\n");

        if (current_record->value <= 0) {
            // Handle edge case of zero or null pointer for offset or key arrays
            printf("Error: Invalid record values.\n");
            free(records);
            return NULL;
        }

        current_record++;
    }

    // Free allocated memory upon successful completion
    free(records);

    return records;
}
