typedef struct {
    int size;
    Record** records;
} HashTable;

HashTable* hash_table_create(int initial_size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = initial_size;
    table->records = (Record**)calloc(table->size, sizeof(Record*));
    return table;
}

void hash_table_destroy(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        free(table->records[i]);
    }
    free(table->records);
    free(table);
}

int hash_function(int key, int size) {
    return key % size;
}

void resize_table(HashTable* table, int new_size) {
    HashTable* temp = (HashTable*)malloc(sizeof(HashTable));
    temp->size = new_size;
    temp->records = (Record**)calloc(temp->size, sizeof(Record*));

    for (int i = 0; i < table->size; i++) {
        if (table->records[i] != NULL) {
            int index = hash_function(table->records[i]->key, new_size);
            temp->records[index] = (Record*)malloc(sizeof(Record));
            memcpy(&temp->records[index]->key, &table->records[i]->key, sizeof(int));
            temp->records[index]->offset = table->records[i]->offset;
        }
    }

    for (int i = 0; i < table->size; i++) {
        free(table->records[i]);
    }
    free(table->records);
    free(table);

    *table = *temp;
    free(temp);
}

void insert_record(HashTable* table, int key, long offset) {
    int index = hash_function(key, table->size);
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;

    if (table->records[index] == NULL || strcmp(&table->records[index]->key, &record->key) != 0) {
        table->records[index] = record;
    } else {
        free(record);
    }
}

Record* lookup_record(HashTable* table, int key) {
    int index = hash_function(key, table->size);

    if (table->records[index] != NULL && table->records[index]->key == key) {
        return table->records[index];
    }

    return NULL;
}
