#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure for record type
typedef enum {
    INT_RECORD,
    LONG_RECORD,
    STRING_RECORD
} RecordType;

// Structure for record
typedef struct {
    int key;
    long offset;
    char* value;
    RecordType type;
} Record;

// Hash table structure
typedef struct {
    size_t capacity;
    size_t size;
    float loadFactor;
    void** buckets;
} HashTable;

// Function to initialize hash table with initial capacity and load factor
HashTable* initHashTable(size_t capacity, float loadFactor) {
    HashTable* hashTable = (HashTable*)malloc(sizeof(HashTable));
    hashTable->capacity = capacity;
    hashTable->size = 0;
    hashTable->loadFactor = loadFactor;
    hashTable->buckets = (void**)calloc(capacity, sizeof(void*));
    return hashTable;
}

// Function to resize the hash table when the load factor exceeds a certain threshold
void resizeHashTable(HashTable* hashTable) {
    size_t newCapacity = hashTable->capacity * 2;
    void** newBuckets = (void*)realloc(hashTable->buckets, newCapacity * sizeof(void*));
    hashTable->buckets = newBuckets;
    hashTable->capacity = newCapacity;
}

// Function to insert a record into the hash table
int insertRecord(HashTable* hashTable, Record* record) {
    size_t index = (size_t)(record->key % hashTable->capacity);
    for (size_t i = 0; i < hashTable->capacity; i++) {
        void* currentBucket = hashTable->buckets[index];
        if (!currentBucket) {
            break;
        }
        Record* currentRecord = (Record*)currentBucket;
        if (currentRecord->key == record->key) {
            return -1; // Key collision
        }
        index++;
    }
    hashTable->size++;
    size_t newIndex = (size_t)(record->key % hashTable->capacity);
    hashTable->buckets[newIndex] = (void*)record;
    return 0;
}

// Function to serialize the records in the hash table to a file
int serializeRecords(HashTable* hashTable, FILE* file) {
    fwrite(&hashTable->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < hashTable->capacity; i++) {
        void* currentBucket = hashTable->buckets[i];
        if (!currentBucket) continue;
        Record* record = (Record*)currentBucket;
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->offset, sizeof(long), 1, file);
        size_t valueLength = strlen(record->value);
        fwrite(&valueLength, sizeof(size_t), 1, file);
        fwrite(record->value, 1, valueLength, file);
    }
    return 0;
}

// Function to deserialize the records from a file into the hash table
int deserializeRecords(HashTable* hashTable, FILE* file) {
    size_t fileSize = (size_t)ftell(file);
    rewind(file);
    fread(&hashTable->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < hashTable->capacity; i++) {
        void* currentBucket;
        for (size_t j = 0; j < hashTable->capacity; j++) {
            fread(&currentBucket, sizeof(void*), 1, file);
            if (!currentBucket) break;
            Record* record = (Record*)currentBucket;
            fread(&record->key, sizeof(int), 1, file);
            fread(&record->offset, sizeof(long), 1, file);
            size_t valueLength;
            fread(&valueLength, sizeof(size_t), 1, file);
            char* value = (char*)malloc(valueLength + 1);
            fread(value, 1, valueLength, file);
            value[valueLength] = '\0';
            record->value = value;
        }
    }
    return 0;
}

// Example usage
int main() {
    HashTable* hashTable = initHashTable(1000, 0.75f);

    Record records[3];
    records[0].key = 1;
    records[0].offset = 123456789;
    records[0].value = "Value 1";
    records[0].type = INT_RECORD;

    records[1].key = 2;
    records[1].offset = -987654321;
    records[1].value = "Value 2";
    records[1].type = LONG_RECORD;

    records[2].key = 3;
    records[2].offset = 0;
    records[2].value = "Value 3";
    records[2].type = STRING_RECORD;

    for (size_t i = 0; i < sizeof(records) / sizeof(Record); i++) {
        if (insertRecord(hashTable, &records[i]) == -1) {
            printf("Key collision at key %d\n", records[i].key);
        }
    }

    FILE* file = fopen("records.bin", "wb");
    serializeRecords(hashTable, file);

    fclose(file);

    return 0;
}
