typedef struct {
    char* key;
    long offset;
    int value;
} item;

typedef struct node {
    item data;
    struct node* next;
} node;

node* head = NULL;
node* tail = NULL;

void add_item(char* key, long offset, int value) {
    node* new_node = (node*)malloc(sizeof(node));
    new_node->data.key = strdup(key);
    new_node->data.offset = offset;
    new_node->data.value = value;
    new_node->next = NULL;

    if(head == NULL) {
        head = tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }
}

int update_item(char* key, long offset, int value) {
    node* current = head;
    while(current != NULL) {
        if(strcmp(current->data.key, key) == 0 && current->data.offset == offset) {
            current->data.value = value;
            return 1; // item updated
        }
        current = current->next;
    }
    return 0; // item not found
}

item* get_item(char* key, long offset) {
    node* current = head;
    while(current != NULL) {
        if(strcmp(current->data.key, key) == 0 && current->data.offset == offset) {
            return &current->data;
        }
        current = current->next;
    }
    return NULL; // item not found
}

void serialize_to_file(char* filename) {
    FILE* file = fopen(filename, "wb");
    if(file == NULL) {
        printf("Error opening file for writing.\n");
        return;
    }

    node* current = head;
    while(current != NULL) {
        fwrite(&current->data, sizeof(item), 1, file);
        current = current->next;
    }
    fclose(file);
}

void deserialize_from_file(char* filename) {
    FILE* file = fopen(filename, "rb");
    if(file == NULL) {
        printf("Error opening file for reading.\n");
        return;
    }

    node* current = head = tail = NULL;
    item temp;

    while(fread(&temp, sizeof(item), 1, file) == 1) {
        node* new_node = (node*)malloc(sizeof(node));
        new_node->data.key = strdup(temp.key);
        new_node->data.offset = temp.offset;
        new_node->data.value = temp.value;
        new_node->next = NULL;

        if(head == NULL) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            tail = new_node;
        }
    }
    fclose(file);
}

void set_random_value(node* current, int min, int max) {
    while(current != NULL) {
        current->data.value = rand() % (max - min + 1) + min;
        current = current->next;
    }
}
