#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the custom hash table
typedef struct {
    int capacity;
    int size;
    Record **records;
    unsigned long *hashes;
} HashTable;

HashTable* create_hash_table(int initial_capacity) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->capacity = initial_capacity;
    ht->size = 0;
    ht->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    ht->hashes = (unsigned long*)calloc(initial_capacity, sizeof(unsigned long));
    return ht;
}

void hash_table_resize(HashTable* ht) {
    int new_capacity = ht->capacity * 2;
    Record** new_records = (Record**)realloc(ht->records, new_capacity * sizeof(Record*));
    unsigned long* new_hashes = (unsigned long*)realloc(ht->hashes, new_capacity * sizeof(unsigned long));
    ht->capacity = new_capacity;
    ht->records = new_records;
    ht->hashes = new_hashes;
}

int hash(int key, int capacity) {
    return key % capacity;
}

void insert_record(HashTable* ht, Record record) {
    int index = hash(record.key, ht->capacity);
    while (ht->records[index] != NULL && ht->records[index]->key != record.key) {
        index = (index + 1) % ht->capacity;
    }
    if (ht->records[index] == NULL || ht->records[index]->key == record.key) {
        ht->records[index] = &record;
        ht->size++;
    } else {
        // Handle collision
    }
}

Record* lookup_record(HashTable* ht, int key) {
    int index = hash(key, ht->capacity);
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
        index = (index + 1) % ht->capacity;
    }
    if (ht->records[index] == NULL || ht->records[index]->key == key) {
        return &ht->records[index]->offset;
    } else {
        // Handle collision
    }
}

void delete_record(HashTable* ht, int key) {
    int index = hash(key, ht->capacity);
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
        index = (index + 1) % ht->capacity;
    }
    if (ht->records[index] != NULL && ht->records[index]->key == key) {
        ht->records[index] = NULL;
        ht->size--;
    } else {
        // Handle collision
    }
}

void serialize(HashTable* ht, FILE* file) {
    fwrite(&ht->capacity, sizeof(int), 1, file);
    fwrite(&ht->size, sizeof(int), 1, file);
    for (int i = 0; i < ht->capacity; i++) {
        if (ht->records[i] != NULL) {
            fwrite(&ht->records[i]->key, sizeof(int), 1, file);
            fwrite(&ht->records[i]->offset, sizeof(long), 1, file);
        }
    }
}

HashTable* deserialize(FILE* file) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    int capacity;
    fread(&capacity, sizeof(int), 1, file);
    int size;
    fread(&size, sizeof(int), 1, file);
    ht->records = (Record**)calloc(capacity, sizeof(Record*));
    for (int i = 0; i < capacity; i++) {
        Record* record;
        if (fread(&record->key, sizeof(int), 1, file) == 0) break;
        if (fread(&record->offset, sizeof(long), 1, file) == 0) break;
        ht->records[i] = record;
    }
    ht->capacity = capacity;
    ht->size = size;
    return ht;
}

void init_records(HashTable* ht) {
    srand(time(NULL));
    for (int i = 0; i < ht->size; i++) {
        Record* record = &ht->records[i];
        record->key = rand() % 100 + 1;
        record->offset = (long)i * 10000000;
    }
}

void logging(HashTable* ht, char* operation) {
    // Implement logging mechanism
}

int main() {
    HashTable* ht = create_hash_table(16);
    int num_records = 10;
    for (int i = 0; i < num_records; i++) {
        Record record;
        record.key = rand() % 100 + 1;
