```c
#include <stdlib.h>
#include <stdio.h>

// Define the record structure
typedef struct {
    int key;
    long offset;
} Record;

// Define the hash table structure
typedef struct {
    size_t size; // Current size of the hash table
    size_t capacity; // Maximum capacity of the hash table
    Record **buckets; // Array of buckets (each bucket is a linked list of records)
    double load_factor; // Load factor for resizing the hash table
} HashTable;

// Function to create a new hash table with initial capacity and load factor
HashTable *create_hash_table(size_t initial_capacity, double load_factor) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->size = 0;
    ht->capacity = initial_capacity;
    ht->buckets = malloc(initial_capacity * sizeof(Record *));
    for (size_t i = 0; i < initial_capacity; i++) {
        ht->buckets[i] = NULL;
    }
    ht->load_factor = load_factor;
    return ht;
}

// Function to insert a new record into the hash table
void insert_record(HashTable *ht, int key, long offset) {
    size_t index = key % ht->capacity;
    Record *record = malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = record;
    } else {
        Record *curr = ht->buckets[index];
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = record;
    }
    ht->size++;
}

// Function to look up a record by its key in the hash table
Record *lookup_record(HashTable *ht, int key) {
    size_t index = key % ht->capacity;
    Record *curr = ht->buckets[index];
    while (curr != NULL && curr->key != key) {
        curr = curr->next;
    }
    return curr;
}

// Function to remove a record by its key from the hash table
void remove_record(HashTable *ht, int key) {
    size_t index = key % ht->capacity;
    Record *curr = ht->buckets[index];
    Record *prev = NULL;
    while (curr != NULL && curr->key != key) {
        prev = curr;
        curr = curr->next;
    }
    if (curr == NULL) return; // Key not found
    if (prev == NULL) {
        ht->buckets[index] = curr->next;
    } else {
        prev->next = curr->next;
    }
    free(curr);
    ht->size--;
}

// Function to serialize the hash table to a file
void serialize_hash_table(HashTable *ht, FILE *file) {
    fwrite(&ht->size, sizeof(size_t), 1, file);
    fwrite(&ht->capacity, sizeof(size_t), 1, file);
    fwrite(&ht->load_factor, sizeof(double), 1, file);
    for (size_t i = 0; i < ht->capacity; i++) {
        Record *curr = ht->buckets[i];
        while (curr != NULL) {
            fwrite(&curr->key, sizeof(int), 1, file);
            fwrite(&curr->offset, sizeof(long), 1, file);
            curr = curr->next;
        }
    }
}

// Function to deserialize the hash table from a file
HashTable *deserialize_hash_table(FILE *file) {
    HashTable *ht = malloc(sizeof(HashTable));
    fread(&ht->size, sizeof(size_t), 1, file);
    fread(&ht->capacity, sizeof(size_t), 1, file);
    fread(&ht->load_factor, sizeof(double), 1, file);
    ht->buckets = malloc(ht->capacity * sizeof(Record *));
    for (size_t i = 0; i < ht->capacity; i++) {
        Record *curr = NULL;
        while (fread(&curr->key, sizeof(int), 1, file) == 1 &&
               fread(&curr->offset, sizeof(long), 1, file) == 1) {
            curr->next = ht->buckets[i];
            ht->buckets[i] = curr;
            curr = NULL;
        }
    }
    return ht;
}

// Function to track the age of each record and expire old records
void expire_records(HashTable *ht, int max_age) {
    size_t i;
    for (i = 0; i < ht->capacity; i++) {
        Record *curr = ht->buckets[i];
        while (curr != NULL) {
            if (curr->offset <= 0) { // Expired record
                remove_record(ht, curr->key);
            } else {
                curr->offset--;
            }
            curr = curr->next;
        }
    }
}

// Function to dynamically adjust the hash table's bucket size based on load factor
void resize_hash_table(HashTable *ht) {
    if (ht->size / ht->capacity > ht->load_factor) {
        // Resize the hash table when the load factor exceeds the threshold
        size_t new_capacity = ht->capacity * 2;
        HashTable *new_ht = create_hash_table(new_capacity, ht->load_factor);
        for (size_t i = 0; i < ht->capacity; i++) {
            Record *curr = ht->buckets[i];
            while (curr != NULL) {
                int key = curr->key;
                long offset = curr->offset;
                Record *new_curr = malloc(sizeof(Record));
                new_curr->key = key;
                new_curr->offset = offset;
                size_t index = key % new_capacity;
                if (new_ht->buckets[index] == NULL) {
                    new_ht->buckets[index] = new_curr;
                } else {
                    Record *prev = new_ht->buckets[index];
                    while (prev->next != NULL) {
                        prev = prev->next;
                    }
                    prev->next = new_curr;
                }
                free(curr);
                curr = NULL;
            }
        }
        free(ht->buckets);
        ht->buckets = new_ht->buckets;
        ht->capacity = new_capacity;
    }
}

int main() {
    // Create a new hash table with initial capacity and load factor
    HashTable *ht = create_hash_table(16, 0.75);

    // Insert some records into the hash table
    insert_record(ht, 1, 100);
    insert_record(ht, 2, 200);
    insert_record(ht, 3, 300);
    ...

    // Look up a record by its key in the hash table
    Record *record = lookup_record(ht, 2);

    // Remove a record from the hash table
    remove_record(ht, 1);

    // Serialize the hash table to a file
    FILE *file = fopen("database.bin", "wb");
    serialize_hash_table(ht, file);
    fclose(file);

    // Deserialize the hash table from a file
    file = fopen("database.bin", "rb");
    HashTable *new_ht = deserialize_hash_table(file);
    fclose(file);

    // Track the age of each record and expire old records
    expire_records(new_ht, 1000);

    // Dynamically adjust the hash table's bucket size based on load factor
    resize_hash_table(new_ht);

    return 0;
}
