    for (int i = 0; i < numPaths; i++) {
        free((void *)offsets + sizeof(size_t) * i);
    }
    free(offsets);
    for (int i = 0; i < numPaths; i++) {
        free(records + sizeof(struct DataRecord) * i);
    }
    free(records);

    // Deinitialize the external library
    // ...
}

// Helper function to find and print the latest timestamp among the records
time_t findLatestTimestamp(struct DataRecord *records, int numRows) {
    time_t latestTimestamp = records[0].timestamp;
    for (int i = 1; i < numRows; i++) {
        if (records[i].timestamp > latestTimestamp) {
            latestTimestamp = records[i].timestamp;
        }
    }
    return latestTimestamp;
}

// Read a list of file paths from standard input and store them in an array
void readFilePaths(int numPaths, char ***paths) {
    for (int i = 0; i < numPaths; i++) {
        fgets(paths[i], 256, stdin);
        // Handle potential integer overflow robustly across different platforms
        int len = strlen(paths[i]);
        paths[i][len - 1] = '\0';
    }
}

// Print the latest timestamp among the records using a helper function
void printLatestTimestamp(time_t latestTimestamp) {
    printf("Latest Timestamp: %ld\n", latestTimestamp);
}
