<?php
function updatePassword(int $userId, string $oldPassword, string $newPassword): array {
    $strengthCriteria = [
        'length' => 8,
        'uppercase' => true,
        'lowercase' => true,
        'digits' => true,
        'specialChars' => true
    ];

    if (!validatePasswordStrength($newPassword, $strengthCriteria)) {
        return ['status' => 400, 'message' => 'New password does not meet strength criteria'];
    }

    try {
        // Initialize retry counter and maximum attempts
        $retryCount = 0;
        $maxAttempts = 3;

        while ($retryCount < $maxAttempts) {
            try {
                // Call external authentication service for password validation
                $response = authenticateService()->validatePassword($userId, $oldPassword);

                if (!$response['valid']) {
                    return ['status' => 401, 'message' => 'Invalid old password'];
                }

                break;
            } catch (Exception $e) {
                // Handle transient errors and retry
                $retryCount++;
                sleep(1); // Wait for a second before retrying
            }
        }

        if ($retryCount >= $maxAttempts) {
            return ['status' => 500, 'message' => 'Failed to validate old password after maximum attempts'];
        }

        // Hash new password using standard library cryptographic hash function (e.g., Argon2id)
        $hashedNewPassword = hash_password($newPassword);

        // Update user's password in the database
        updateUserPasswordInDatabase($userId, $hashedNewPassword);

        return ['status' => 200, 'message' => 'Password updated successfully'];

    } catch (Exception $e) {
        // Log detailed audit trails for failures
        logAuditTrail('Failed to update password: ' . $e->getMessage());

        return ['status' => 500, 'message' => 'Internal server error'];
    }
}

function validatePasswordStrength(string $password, array $strengthCriteria): bool {
    if (strlen($password) < $strengthCriteria['length']) {
        return false;
    }

    if (!preg_match('/[A-Z]/', $password) && $strengthCriteria['uppercase']) {
        return false;
    }

    if (!preg_match('/[a-z]/', $password) && $strengthCriteria['lowercase']) {
        return false;
    }

    if (!preg_match('/\d/', $password) && $strengthCriteria['digits']) {
        return false;
    }

    if (!preg_match('/[^A-Za-z0-9]/', $password) && $strengthCriteria['specialChars']) {
        return false;
    }

    return true;
}

function authenticateService(): object {
    // Implement the external authentication service integration
    return new AuthService();
}

function updateUserPasswordInDatabase(int $userId, string $hashedNewPassword): void {
