#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <limits.h>
#include <unistd.h>

// Assume an external library for random number generation is used.
extern "C" int initializeRandomLib(void);
extern "C" void deinitializeRandomLib(void);
extern "C" uint32_t getRandomNumber(void);

typedef struct {
    int value;
    uint64_t timestamp;
} Record;

void* processAndFindMax(int offsetSize, int keySize, int maxRecords) {
    // Initialize random number generator
    if(initializeRandomLib() != 0){
        return NULL;
    }

    pthread_mutex_init(&mutex, NULL);

    // Allocate memory for record array
    Record *records = (Record *)malloc(maxRecords * sizeof(Record));
    if (!records) {
        deinitializeRandomLib();
        return NULL;
    }

    int currentOffset = 0;
    uint64_t currentTime = time(NULL);

    // Process records in a loop until the end of the time window
    while(currentTime - records[0].timestamp < TIME_WINDOW){

        pthread_mutex_lock(&mutex);

        for (int i = 0; i < maxRecords && currentOffset < offsetSize; i++) {
            records[i].value = getRandomNumber();
            records[i].timestamp = currentTime;
            currentOffset++;
        }

        // Check if we've exceeded the maximum number of records
        if(currentOffset >= offsetSize){
            break;
        }

        pthread_mutex_unlock(&mutex);

        usleep(1 * 1000); // Pause for a second
        currentTime = time(NULL);
    }

    deinitializeRandomLib();

    free(records);

    return NULL;
}

int main() {
    processAndFindMax(1024, 64, 1024);
    return 0;
}
