// Define data structures
typedef struct {
    int process_id;
    double cpu_usage;
    double memory_usage;
} ProcessData;

typedef struct {
    pthread_t thread_id;
    int process_dependency;
} ThreadData;

typedef struct {
    char event_type[20];
    int event_count;
} EventLog;

// Function prototypes
void* collectMetrics(void*);
int compare(const void*, const void*);

// Global variables
ProcessData* processes = NULL;
ThreadData* threads = NULL;
EventLog* events = NULL;
int process_count = 0;
int thread_count = 0;
int event_log_size = 0;

// Function to monitor system performance
void monitorSystemPerformance() {
    // Initialize data structures
    processes = (ProcessData*)malloc(sizeof(ProcessData) * 100);
    threads = (ThreadData*)malloc(sizeof(ThreadData) * 100);
    events = (EventLog*)malloc(sizeof(EventLog) * 100);

    // Define sampling interval and report frequency
    int sample_interval = 1000; // in milliseconds
    int report_frequency = 10;

    while(1) {
        // Collect metrics from processes and threads
        pthread_t thread;
        for(int i = 0; i < process_count; i++) {
            ProcessData* process = &processes[i];
            process->cpu_usage = get_cpu_usage();
            process->memory_usage = get_memory_usage();

            if(process->cpu_usage > 80 || process->memory_usage > 90) {
                // Log high CPU or memory usage
                EventLog* event = events + (event_log_size++);
                strcpy(event->event_type, "High_CPU_Usage");
                event->event_count = 1;
            }
        }

        for(int i = 0; i < thread_count; i++) {
            ThreadData* thread_data = &threads[i];
            int process_dependency = get_process_dependency(thread_data->thread_id);
            // Log dependency information
            EventLog* event = events + (event_log_size++);
            strcpy(event->event_type, "Process_Dependency");
            event->event_count = 1;
        }

        // Report metrics at specified frequency
        if((++sample_interval) % report_frequency == 0) {
            // Generate detailed reports for processes and threads
            printf("Process Metrics:\n");
            for(int i = 0; i < process_count; i++) {
                ProcessData* process = &processes[i];
                printf("%d: CPU Usage - %.2f, Memory Usage - %.2f\n", 
                    process->process_id, process->cpu_usage, process->memory_usage);
            }

            printf("Thread Metrics:\n");
            for(int i = 0; i < thread_count; i++) {
                ThreadData* thread_data = &threads[i];
                printf("%ld: Process Dependency - %d\n", 
                    thread_data->thread_id, thread_data->process_dependency);
            }
        }

        // Sleep for sample interval
        usleep(sample_interval * 1000);
    }
}

// Helper function to sort processes and threads based on CPU usage or memory usage
int compare(const void* a, const void* b) {
    ProcessData* pa = (ProcessData*)a;
    ProcessData* pb = (ProcessData*)b;

    if(pa->cpu_usage < pb->cpu_usage) return -1;
    else if(pa->cpu_usage > pb->cpu_usage) return 1;
    else if(pa->memory_usage < pb->memory_usage) return -1;
    else if(pa->memory_usage > pb->memory_usage) return 1;

    return 0;
}

