    char** label_array = (char**)malloc(numMetrics * sizeof(char*));
    struct timeval* timestamp_array = (struct timeval*)malloc(numMetrics * sizeof(struct timeval));
    struct_metrics_event* event_array = (struct_metrics_event*)malloc(numMetrics * sizeof(struct_metrics_event));
    struct_metrics_info* info_array = (struct_metrics_info*)malloc(numMetrics * sizeof(struct_metrics_info));

