        for(int i = 0; i < numMetrics; i++) {
            sum += metrics[i];
        }
        return (double)sum / numMetrics;
    }

    // Read a list of metrics from standard input and calculate the average metric value
    int readMetrics(int* metrics, int numMetrics) {
        int i = 0;
        while(i < numMetrics) {
            printf("Enter metric %d: ", i);
            scanf("%d", &metrics[i]);
            i++;
        }
        return numMetrics;
    }

