        if (!(*log_message)[i]) {
            return -3; // memory allocation failure
        }
        sprintf((*log_message)[i], "Log level: %d, timestamp: %lu", *log_level, **timestamp);
    }

    int* offsets;
    int* keys;
    int num_items = loadResourceBundle(resource_file, &offsets, &keys);

    if (num_items < 0) {
        return -4; // error loading resource bundle
    }

    free(offsets);
    free(keys);

    // calculate frequency of each log level
    int* freq = (int*)malloc(num_entries * sizeof(int));
    for (int i = 0; i < num_entries; i++) {
        freq[i] = 1;
    }
    int max_freq = findMaxFrequency(freq, num_entries);
    free(freq);

    return num_items;
}
