void processAndAggregateData(int measurements_size, int identifiers_size) {
    srand(time(NULL));

    measurement_t* measurements = (measurement_t*)malloc(measurements_size * sizeof(measurement_t));
    char** identifiers = (char**)malloc(identifiers_size * sizeof(char*));
    for (int i = 0; i < identifiers_size; i++) {
        identifiers[i] = (char*)malloc(17); // +1 for null-terminator
        strcpy(identifiers[i], "Identifier_");
        itoa(i, identifiers[i]+11, 10);
    }

    event_t* events = (event_t*)calloc(measurements_size, sizeof(event_t));
    log_entry_t* log_entries = (log_entry_t*)malloc(measurements_size * sizeof(log_entry_t));
    statistics_t* statistics = (statistics_t*)malloc(sizeof(statistics_t));

    metadata_t* metadata = (metadata_t*)malloc(sizeof(metadata_t));
    metadata->version = 1;
    strcpy(metadata->descriptive_info, "This is a metadata description");

    dependency_t* dependencies = NULL;

    error_t* errors = NULL;

    // Initialize arrays
    for (int i = 0; i < measurements_size; i++) {
        measurements[i].measurement = i;
        measurements[i].identifier = identifiers[i];
        measurements[i].timestamp = time(NULL);
    }

    // Calculate statistics
    double sum = 0.0;
    for (int i = 0; i < measurements_size; i++) {
        sum += measurements[i].measurement;
    }
    statistics->min = measurements[0].measurement;
    statistics->max = measurements[0].measurement;
    statistics->avg = sum / measurements_size;

    // Free allocated memory
    for (int i = 0; i < identifiers_size; i++) {
        free(identifiers[i]);
    }
    free(identifiers);
    free(events);
    free(log_entries);
    free(statistics);

    // Read measurements from standard input and calculate average
    int measurement;
    double sum_avg = 0.0;
    while (scanf("%d", &measurement) == 1) {
        sum_avg += measurement;
    }
    printf("Average measurement: %f\n", sum_avg / measurements_size);

    // Implement MD5 hash calculation for a file
    const char* filePath = "path_to_file";
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        return;
    }

    MD5_CTX ctx;
    MD5_Init(&ctx);
    size_t bytesRead;
    uint8_t buffer[1024];
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5_Update(&ctx, buffer, bytesRead);
    }
    MD5_Final(&ctx);

    unsigned char* hashBytes = (unsigned char*)malloc(MD5_DIGEST_LENGTH * sizeof(unsigned char));
    memcpy(hashBytes, ctx.md5, MD5_DIGEST_LENGTH);
    fclose(file);

    // Print the MD5 hash
    printf("MD5 Hash: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        printf("%02x", hashBytes[i]);
    }
    printf("\n");

    free(hashBytes);
}
