typedef struct {
    long offset;
    int key;
} NFAPI_CRC_INDICATION_PDU_T;

void manage_memory(int* size, int** offsets, int** keys, NFAPI_CRC_INDICATION_PDU_T** records) {
    int max_size = 1000; // predefined maximum size limit
    int seed = 42; // default seed value

    srand(seed);

    *size = (int)sqrt(*max_size); // determine size based on user input
    *offsets = (long*)malloc(*size * sizeof(long));
    *keys = (int*)malloc(*size * sizeof(int));

    if (*offsets == NULL || *keys == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // initialize offset and key arrays
    for (int i = 0; i < *size; i++) {
        (*offsets)[i] = i * (max_size / *size);
        (*keys)[i] = i % max_size;
    }

    int num_records = *size; // number of records to allocate

    *records = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_records * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (*records == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        NFAPI_CRC_INDICATION_PDU_T record;

        record.RX_UE_INFORMATION_TAG = rand() % max_size;
        record.RNTI = rand() % max_size;
        record.CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;

        (*records)[i] = record;
    }

    // monitor and report memory consumption
    printf("Memory usage: %.2f MB\n", (double)sizeof(long) * *size + sizeof(int) * *size + sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_records / 1024 / 1024);

    // free dynamically allocated memory upon function completion
    free(*offsets);
    free(*keys);
    free(*records);
}

int main() {
    int size;
    long* offsets;
    int* keys;
    NFAPI_CRC_INDICATION_PDU_T* records;

    manage_memory(&size, &offsets, &keys, &records);

    return 0;
}
