#define MAX_HOSTNAME_LENGTH 256
#define MAX_TRANSACTION_ID 1024

typedef struct {
    int age;
    int num_transactions;
    double weighted_sum;
} Transaction;

Transaction* filter_transactions(Transaction transactions[], int num_transactions, int age, int num_recent_transactions) {
    Transaction* filtered_transactions = (Transaction*)malloc((num_transactions - num_recent_transactions + 1) * sizeof(Transaction));
    int i, j = 0;
    for(i = 0; i < num_transactions; i++) {
        if(transactions[i].age <= age && transactions[i].num_transactions <= num_recent_transactions) {
            filtered_transactions[j] = transactions[i];
            j++;
        }
    }
    return filtered_transactions;
}

double get_weighted_sum(Transaction transaction) {
    // implement your weighted sum calculation here
    return 0.5 * (transaction.age + transaction.num_transactions);
}

int get_max_weighted_sum(Transaction* transactions, int num_transactions) {
    int i;
    double max_weighted_sum = -1;
    for(i = 0; i < num_transactions; i++) {
        if(transactions[i].weighted_sum > max_weighted_sum) {
            max_weighted_sum = transactions[i].weighted_sum;
        }
    }
    return max_weighted_sum;
}

int get_max_weighted_sum_index(Transaction* transactions, int num_transactions) {
    int i;
    double max_weighted_sum = -1;
    int index = 0;
    for(i = 0; i < num_transactions; i++) {
        if(transactions[i].weighted_sum > max_weighted_sum) {
            max_weighted_sum = transactions[i].weighted_sum;
            index = i;
        }
    }
    return index;
}

int resolve_dns_query(char* hostname, Transaction transactions[], int num_transactions) {
    struct sockaddr_in serv_addr;
    struct hostent *he;

    // Resolve DNS query
    he = gethostbyname(hostname);
    if(he == NULL) {
        printf("Error: %s\n", "DNS resolution failed");
        return -1;
    }

    // Perform transaction filtering and metric updates
    Transaction* filtered_transactions = filter_transactions(transactions, num_transactions, 3, 10);

    // Get the maximum weighted sum and its index
    double max_weighted_sum = get_max_weighted_sum(filtered_transactions, num_transactions);
    int max_weighted_sum_index = get_max_weighted_sum_index(filtered_transactions, num_transactions);

    free(filtered_transactions);

    return max_weighted_sum;
}

int main() {
    // Example usage:
    char* hostname = "example.com";
    Transaction transactions[] = {
        {1, 2, 0.5},
        {3, 4, 0.7},
        {5, 6, 0.9}
    };
    int num_transactions = sizeof(transactions) / sizeof(transactions[0]);

    double max_weighted_sum = resolve_dns_query(hostname, transactions, num_transactions);

    printf("Maximum weighted sum: %.2f\n", max_weighted_sum);
    printf("Transaction ID: %d\n", max_weighted_sum_index);

    return 0;
}
