// Function to find and print the largest integer in the 'inputs' array
int findLargestInput(Record *records, int n) {
    int max = records[0].value;
    for (int i = 1; i < n; i++) {
        if (records[i].value > max)
            max = records[i].value;
    }
    return max;
}

// DataHandler function to manage memory and initialize arrays
void dataHandler(int *offset, int *keys, unsigned long *recordIdentifiers, Record **records, int *statuses, int *priorities, int *inputs, int *outputs) {
    // Initialize variables
    int n = 0;  // Actual number of records (dynamically allocated)
    size_t cacheSize = 1024 * 1024 * 10;  // Initial memory pool size in bytes
    size_t blockSize = sizeof(Record);      // Block size for dynamic allocation

    // Custom memory pool to optimize allocation efficiency
    void **cache = malloc(cacheSize);
    int cacheHead = 0;
    int cacheTail = 0;

    // Allocate memory for arrays
    offset = malloc(sizeof(long));
    keys = malloc(sizeof(int) * n);
    recordIdentifiers = malloc(sizeof(unsigned long) * n);
    records = (Record **)malloc(blockSize);
    statuses = malloc(sizeof(int) * n);
    priorities = malloc(sizeof(int) * n);
    inputs = malloc(sizeof(int));
    outputs = malloc(sizeof(int));

    // Initialize memory pool
    for (int i = 0; i < cacheHead; i++)
        free(cache[i]);

    while (n < 10000000) {
        int blockSize = sizeof(Record);
        if ((cacheTail + blockSize > cacheSize) && (cacheHead - cacheTail >= blockSize)) {
            // Evict blocks from the front of the pool
            for (int i = 0; i < blockSize; i++) {
                free(cache[cacheTail]);
                cacheTail++;
            }
            if (cacheHead == cacheTail)
                break;
        } else if ((cacheSize - cacheTail) >= blockSize) {
            // Allocate new block from the end of the pool
            cache[cacheTail] = malloc(blockSize);
            cacheTail += blockSize;
        } else {
            // Increase memory pool size if necessary
            cacheSize *= 2;
            cache = realloc(cache, cacheSize);
            for (int i = cacheHead; i < cacheTail; i++) {
                free(cache[i]);
            }
            cacheTail = 0;
            cacheHead = 0;
        }
    }

    // Initialize arrays with default values
    *offset = 0;
    *keys = 0;
    *recordIdentifiers = 0;
    for (int i = 0; i < n; i++) {
        records[i].value = 0;
        statuses[i] = 0;
        priorities[i] = 0;
    }

    // Read integers from standard input and store in 'inputs' array
    int input;
    while (scanf("%d", &input) == 1) {
        inputs[*(int *)inputs + 1] = input;
    }

    // Print the largest integer found in 'inputs' array
    int largestInput = findLargestInput(records, n);
    printf("%d\n", largestInput);

    // Clean up and deallocate memory
    for (int i = 0; i < cacheHead; i++)
        free(cache[i]);
    free(cache);
    free(offset);
    free(keys);
    free(recordIdentifiers);
    free(records);
    free(statuses);
    free(priorities);
    free(inputs);
    free(outputs);

    return;
}
