#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

#define RECORD_MAX_LENGTH 256

typedef struct {
    char* str;
    int num;
    double dbl;
} Record;

void processRecordStream() {
    // Initialize array of records
    Record** records = NULL;
    size_t recordCount = 0;

    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        perror("Error opening input file");
        return;
    }

    // Read records from file, dynamically allocating memory as needed
    char line[RECORD_MAX_LENGTH];
    while (fgets(line, RECORD_MAX_LENGTH, file)) {
        Record* record = malloc(sizeof(Record));
        if (record == NULL) {
            perror("Error allocating memory");
            return;
        }

        // Parse and validate record format
        record->str = strtok(line, ",");  // Assuming comma-separated values
        if (!record->str) {
            printf("Invalid record format: %s\n", line);
            free(record);
            continue;  // Skip malformed records
        }
        record->num = atoi(strtok(NULL, ","));
        record->dbl = atof(strtok(NULL, ","));

        // Append new record to the array
        records = realloc(records, (recordCount + 1) * sizeof(Record*));
        if (records == NULL) {
            perror("Error reallocated memory");
            return;
        }
        records[recordCount] = record;
        recordCount++;
    }

    fclose(file);

    // Process and compress the record stream
    FILE* compressedFile = fopen("output.txt", "wb");
    if (compressedFile == NULL) {
        perror("Error opening output file");
        return;
    }

    // Compress records using an external library (e.g., zlib)
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    int compressionLevel = 6;  // Default compression level
    deflateInit2(&strm, compressionLevel, Z_DEFAULT_COMPRESSION, Z_DEFAULT_STRATEGY);

    for (size_t i = 0; i < recordCount; i++) {
        // Serialize and compress each record
        char buffer[RECORD_MAX_LENGTH];
        sprintf(buffer, "%s,%d,%lf", records[i]->str, records[i]->num, records[i]->dbl);
        int bufferLen = strlen(buffer);

        strm.avail_in = bufferLen;
        strm.next_in = (Bytef*)buffer;

        do {
            strm.avail_out = Z_BUFSIZE;
            strm.next_out = (Bytef*)outputBuffer;
            deflate(&strm, Z_DEFAULT_COMPRESSION);
            fwrite(outputBuffer, 1, Z_BUFSIZE - strm.avail_out, compressedFile);
        } while (strm.avail_in > 0);

        // Clean up and free resources
        deflateEnd(&strm);
    }

    fclose(compressedFile);

    // Logging mechanism
    FILE* logFile = fopen("log.txt", "a");
    if (logFile == NULL) {
        perror("Error opening log file");
        return;
    }

    for (size_t i = 0; i < recordCount; i++) {
        fprintf(logFile, "Record processed: %s,%d,%lf\n", records[i]->str, records[i]->num, records[i]->dbl);
    }
    fclose(logFile);

    // Free resources and close the file
    for (size_t i = 0; i < recordCount; i++) {
        free(records[i]->str);
        free(records[i]);
    }
    free(records);
}

int main() {
    processRecordStream();
    return 0;
}
