        *maxRecordValue = maxRecordValueLocal;
    }
    pthread_mutex_unlock(&mutex);

    free(values);
    for(int i=0; i<recordCount; i++){
        free(records[i]);
    }
    free(records);

    fclose(file);

    return NULL;
}

int main(int argc, char* argv[]){
    if(argc != 3){
        printf("Usage: %s <seed> <file_path>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    int seed = atoi(argv[1]);

    initialize_file_io_library();

    pthread_t threads[argc-2];

    for(int i=1; i<argc-1; i++){
        FILE* file = fopen(argv[i], "r");
        if(file == NULL){
            printf("Error opening file %s\n", argv[i]);
            deinitialize_file_io_library();
            exit(EXIT_FAILURE);
        }
        pthread_create(&threads[i-1], NULL, processFile, (void*)file);
    }

    for(int i=0; i<argc-2; i++){
        pthread_join(threads[i], NULL);
    }

    deinitialize_file_io_library();

    return 0;
}

