#include <string.h>

typedef struct {
    int bits_per_sample;
    int samples_per_pixel;
    int extra_samples;
    int *extra_samples_offset;
    char *error_message;
} TIFFImageInfo;

TIFFImageInfo* parse_tiff_image(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL;
    }

    TIFFImageInfo *image_info = (TIFFImageInfo*)malloc(sizeof(TIFFImageInfo));
    image_info->bits_per_sample = 0;
    image_info->samples_per_pixel = 0;
    image_info->extra_samples = 0;
    image_info->extra_samples_offset = NULL;

    unsigned char tag[2];
    fread(tag, 1, 2, file);
    uint16_t tag_value = ((uint16_t)tag[0] << 8) | (uint16_t)tag[1];

    if (tag_value == 0x100 || tag_value == 0x102 || tag_value == 0x103) {
        fread(tag, 1, 2, file);
        uint16_t value = ((uint16_t)tag[0] << 8) | (uint16_t)tag[1];
        if (value < 1 || value > 16) {
            image_info->error_message = "Unsupported bits per sample";
            fclose(file);
            free(image_info);
            return NULL;
        }
        image_info->bits_per_sample = value;

        fread(tag, 1, 2, file);
        value = ((uint16_t)tag[0] << 8) | (uint16_t)tag[1];
        if (value < 1 || value > 4) {
            image_info->error_message = "Unsupported samples per pixel";
            fclose(file);
            free(image_info);
            return NULL;
        }
        image_info->samples_per_pixel = value;

        int extra_samples_count = 0;
        uint16_t *extra_samples_offset = (uint16_t*)malloc(sizeof(uint16_t));
        while (fread(tag, 1, 2, file) == 2) {
            value = ((uint16_t)tag[0] << 8) | (uint16_t)tag[1];
            if (value == 0x200 || value == 0x202 || value == 0x203) {
                extra_samples_count++;
                extra_samples_offset = (uint16_t*)realloc(extra_samples_offset, sizeof(uint16_t) * (extra_samples_count + 1));
                fread(&extra_samples_offset[extra_samples_count - 1], 2, file);
            }
        }

        image_info->extra_samples = extra_samples_count;
        image_info->extra_samples_offset = extra_samples_offset;

        fclose(file);

        return image_info;
    } else {
        image_info->error_message = "Invalid TIFF header";
        fclose(file);
        free(image_info);
        return NULL;
    }
}

char* generate_md5_hash(const char *input, int length) {
    uint8_t *digest = (uint8_t*)malloc(16);
    SHA_CTX ctx;
    SHA1_Init(&ctx);

    for (int i = 0; i < length; i += 64) {
        unsigned char chunk[64];
        int remaining = length - i;

        if (remaining > 64) {
            memcpy(chunk, &input[i], 64);
        } else {
            memcpy(chunk, &input[i], remaining);
        }

        SHA1_Update(&ctx, chunk, remaining);
    }

    SHA1_Final(digest, &ctx);

    char *hash = (char*)malloc(33);
    sprintf(hash, "%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x", digest[0], digest[1], digest[2], digest[3], digest[4], digest[5], digest[6], digest[7], digest[8], digest[9], digest[10], digest[11], digest[12], digest[13], digest[14], digest[15]);

    free(digest);

    return hash;
}
