void processDataStreams(size_t num_streams) {
    // Initialize offset, key, and record identifier arrays
    long* offsets = mempool_allocate(num_streams * sizeof(long));
    int* keys = mempool_allocate(num_streams * sizeof(int));
    unsigned long* record_identifiers = mempool_allocate(num_streams * sizeof(unsigned long));

    // Initialize record array with random integers within a specified range
    int* records = mempool_allocate(num_streams * 1000 * sizeof(int));
    for (size_t i = 0; i < num_streams; ++i) {
        for (int j = 0; j < 1000; ++j) {
            records[i * 1000 + j] = rand();
        }
    }

    // Initialize timestamp array with current system time
    timestamp* timestamps = mempool_allocate(num_streams * sizeof(timestamp));
    for (size_t i = 0; i < num_streams; ++i) {
        timestamps[i] = get_current_timestamp();
    }

    // Initialize status array with default values indicating the initial state
    int* statuses = mempool_allocate(num_streams * sizeof(int));
    for (size_t i = 0; i < num_streams; ++i) {
        statuses[i] = INITIAL_STATE;
    }

    // Initialize string array with random character strings
    char** strings = mempool_allocate(num_streams * sizeof(char*));
    for (size_t i = 0; i < num_streams; ++i) {
        strings[i] = generate_random_string(100);
    }

    // Find and print the largest integer in the input array for each stream
    for (size_t i = 0; i < num_streams; ++i) {
        int max_integer = find_largest_integer(records + i * 1000, 1000);
        log_message("Stream %zu: Largest integer is %d", i, max_integer);

        // Find and print the largest string length in the string array
        int max_string_length = find_largest_string_length(strings[i], 100);
        log_message("Stream %zu: Largest string length is %d", i, max_string_length);
    }

    // Release all allocated memory upon returning
    mempool_release(offsets);
    mempool_release(keys);
    mempool_release(record_identifiers);
    mempool_release(records);
    mempool_release(timestamps);
    mempool_release(statuses);
    mempool_release(strings);

    // Reset used resources such as random number generators and hash maps
    reset_random_number_generator();
    reset_hash_map();

    // Ensure that the record and record identifier arrays do not exceed 30% of the combined size of the offset, key, and timestamp arrays
    assert((records + record_identifiers) / (offsets + keys + timestamps) <= 0.3);
}
