int processAndTransform(const char* source_path, const char* output_dir, const char* target_format, const char* config_json, int enable_high_quality) {
    // Read the JSON configuration
    json_object* config = json_object_from_string(config_json);
    if (!config) return -1; // Invalid JSON format

    // Load the source image using the imaging library
    Image* src_image = load_image(source_path);
    if (!src_image) return -1; // Unable to load the image

    // Resize and transform the image according to the target format and quality settings
    Image* transformed_image = transform_image(src_image, target_format, enable_high_quality ? HIGH_QUALITY : LOW_QUALITY);
    free_image(src_image); // Release resources for the original image
    if (!transformed_image) return -1; // Transformation failed

    // Save the transformed image to the output directory
    int save_result = save_image(transformed_image, output_dir, target_format);
    free_image(transformed_image); // Release resources for the transformed image
    if (save_result < 0) return -1; // Unable to save the image

    // Extract metadata about the transformed image
    ImageMetadata meta;
    meta.width = transformed_image->width;
    meta.height = transformed_image->height;
    meta.quality_metric = calculate_quality_metric(transformed_image);
    free_image(transformed_image); // Release resources for the transformed image

    // Save the metadata as a JSON object
    json_object* meta_json = json_object_new_object();
    json_object_object_add(meta_json, "width", json_object_new_int(meta.width));
    json_object_object_add(meta_json, "height", json_object_new_int(meta.height));
    json_object_object_add(meta_json, "quality_metric", json_object_new_double(meta.quality_metric));

    // Return 0 if both operations succeed
    return 0;
}
