        free(offsets);
        free(keys);
        printf("Memory allocation failed for 'records'.\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1000000; // Initialize random value
        keys[i] = rand() % 1000; // Initialize random value

        records[i].offset = &offsets[i];
        records[i].key = &keys[i];

        int value = rand() % 100;
        records[i].value = value;

        pthread_mutex_lock(&mutex);
        printf("Record %d: offset=%ld, key=%d, value=%d\n", i + 1, offsets[i], keys[i], value);
        pthread_mutex_unlock(&mutex);
    }

    free(offsets);
    free(keys);

    return records;
}

void cleanup(record* records, int num_records) {
    if (!records) return;

    free(records);
    printf("Memory cleaned up successfully.\n");
}

int main() {
    srand(time(NULL));

    int num_records = 0;
    long total_memory_limit = 0;

    while (num_records < 1 || num_records > MAX_RECORDS || total_memory_limit > MAX_MEMORY) {
        printf("Enter the number of records: ");
        scanf("%d", &num_records);

        if (total_memory_limit == 0) {
            printf("Enter the maximum memory limit in MB: ");
            scanf("%ld", &total_memory_limit);
        }
    }

    record* records = create_records(num_records);

    if (!records) {
        return -1;
    }

    int num_success = 0;

    for (int i = 0; i < num_records; i++) {
        // Validate the number of successfully created records
        if (records[i].offset && records[i].key) {
            num_success++;
        }
    }

    printf("Total memory consumed: %ld bytes\n", num_records * sizeof(record));
    printf("Number of successful records: %d\n", num_success);

    cleanup(records, num_records);

    return 0;
}
