#define TABLE_SIZE 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    int value;
    char* string;
    char* timestamp;
} record;

record** hashTable = NULL;

void initHashTable() {
    if (hashTable != NULL) return;
    hashTable = (record**)malloc(TABLE_SIZE * sizeof(record*));
    for (int i = 0; i < TABLE_SIZE; i++) {
        hashTable[i] = NULL;
    }
}

int hashFunction(int key) {
    return key % TABLE_SIZE;
}

void resizeHashTable() {
    int newSize = TABLE_SIZE * 2;
    record** newHashTable = (record**)malloc(newSize * sizeof(record*));
    for (int i = 0; i < newSize; i++) {
        newHashTable[i] = NULL;
    }

    for (int i = 0; i < TABLE_SIZE; i++) {
        record* currentRecord = hashTable[i];
        while (currentRecord != NULL) {
            int index = hashFunction(currentRecord->value);
            if (newHashTable[index] == NULL || newHashTable[index]->string != currentRecord->string || strcmp(newHashTable[index]->timestamp, currentRecord->timestamp) != 0) {
                // Error: duplicate record detected
                printf("Error: Duplicate record detected during resizing. Please handle this situation accordingly.\n");
                return;
            }
            newHashTable[index] = currentRecord;
            currentRecord = currentRecord->next;
        }
    }

    free(hashTable);
    hashTable = newHashTable;
}

void insertRecord(int key, int value) {
    if (hashTable == NULL || hashTable[0] == NULL) initHashTable();

    int index = hashFunction(key);
    record* currentRecord = hashTable[index];
    while (currentRecord != NULL) {
        if (currentRecord->value == key) {
            // Update existing record
            printf("Updating existing record with value %d and string '%s' at index %d.\n", value, currentRecord->string, index);
            currentRecord->value = value;
            return;
        }
        currentRecord = currentRecord->next;
    }

    // Create new record
    record* newRecord = (record*)malloc(sizeof(record));
    newRecord->value = key;
    char* stringID = malloc((strlen("record_") + 10) * sizeof(char)); strcpy(stringID, "record_"); itoa(key, &stringID[6], 10); newRecord->string = stringID;
    char* timestamp = malloc(12 * sizeof(char)); strftime(timestamp, 12, "%Y-%m-%d %H:%M:%S", NULL); newRecord->timestamp = timestamp;

    record* nextRecord = hashTable[index];
    hashTable[index] = newRecord;
    if (nextRecord != NULL) {
        while (nextRecord->next != NULL) nextRecord = nextRecord->next;
        nextRecord->next = newRecord;
    } else {
        hashTable[index] = newRecord;
    }

    // Check load factor and resize if necessary
    float loadFactor = 1.0 * (float)(record*)hashTable[i] / TABLE_SIZE;
    if (loadFactor > LOAD_FACTOR_THRESHOLD) {
        printf("Load factor exceeds threshold (%f). Resizing hash table.\n", loadFactor);
        resizeHashTable();
    }
}

void lookupRecord(int key) {
    if (hashTable == NULL || hashTable[0] == NULL) initHashTable();

    int index = hashFunction(key);
    record* currentRecord = hashTable[index];
    while (currentRecord != NULL) {
        if (currentRecord->value == key) {
            printf("Found record with value %d, string '%s', and timestamp '%s' at index %d.\n", currentRecord->value, currentRecord->string, currentRecord->timestamp, index);
            free(currentRecord->string); free(currentRecord->timestamp);
            return;
        }
        currentRecord = currentRecord->next;
    }

    printf("Record not found with key %d.\n", key);
}

void freeHashTable() {
    for (int i = 0; i < TABLE_SIZE; i++) {
        record* currentRecord = hashTable[i];
        while (currentRecord != NULL) {
            record* nextRecord = currentRecord->next;
            free(currentRecord->string); free(currentRecord->timestamp);
            free(currentRecord);
            currentRecord = nextRecord;
        }
    }
    free(hashTable);
}

int main() {
    // Initialize hash table
    initHashTable();

    // Insert records
    insertRecord(1, 5);
    insertRecord(2, 10);
    insertRecord(3, 15);

    // Lookup records
    lookupRecord(1);
    lookupRecord(2);
    lookupRecord(3);

    return 0;
}

