record* createRecords(int count) {
    if (count < 1 || count > 1000) {
        printf("Invalid input. Count must be between 1 and 1000.\n");
        return NULL;
    }

    record* records = (record*)malloc(count * sizeof(record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        records[i].o = (offset*)malloc(sizeof(offset));
        if (!records[i].o) {
            printf("Memory allocation failed.\n");
            free(records);
            return NULL;
        }
        records[i].k = (key*)malloc(sizeof(key));
        if (!records[i].k) {
            printf("Memory allocation failed.\n");
            for (int j = 0; j < i; j++) {
                free(records[j].o);
                free(records[j].k);
            }
            free(records);
            return NULL;
        }
        records[i].value = rand() % 1000 + 1;
    }

    printf("Records created: %d\n", count);
    return records;
}

void freeRecords(record* records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i].o);
        free(records[i].k);
    }
    free(records);
}
