    // Define the maximum record value
    int maxRecordValue = INT_MIN;

    // Create a custom allocator to optimize memory allocation for cache locality
    void* allocator = malloc(1024 * 1024); // Allocate 1MB of memory

    // Initialize the Record array with dynamic memory allocation using the custom allocator
    size_t recordCount;
    int** records = (int**)malloc(sizeof(int*) * recordCount);

    // Read a list of integers from a specified file and process these integers
    FILE* file = fopen("input.txt", "r");
    if (!file) {
        perror("Error opening the input file");
        return NULL;
    }

    int offset = 0;
    while (fscanf(file, "%d", &records[offset]) == 1) {
        // Populate the key field with unique values from a large, externally provided list of integers
        records[offset]->key = rand() % (1 << 31);

        // Populate the value field with random integers within a specified range
        records[offset]->value = rand() % 100;

        // Update the maximum record value if necessary
        if (records[offset]->value > maxRecordValue) {
            maxRecordValue = records[offset]->value;
        }

        offset++;
    }

    fclose(file);

    // Handle cases where the file might contain invalid data or be empty, providing appropriate error handling
    if (ferror(file)) {
        perror("Error reading from the input file");
    } else if (!feof(file)) {
        printf("File is not properly terminated\n");
    }

    // Free all allocated memory at the end of the function to avoid memory leaks
    free(allocator);
    for (int i = 0; i < recordCount; i++) {
        free(records[i]);
    }
    free(records);

    return NULL;
}

int main() {
    int numThreads = 4;

    pthread_t threads[numThreads];
    Record* records[numThreads];

    // Create multiple threads concurrently
    for (int i = 0; i < numThreads; i++) {
        pthread_create(&threads[i], NULL, processAndFindMax, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
