int load_key_iv(char* config_file_path, unsigned char** key, unsigned char** iv) {
    // Load the AES-256 encrypted configuration file using a secure key management service (KMS)
    int ret = system("openssl aes-256-cbc -in config_file.txt -out decrypted_config.txt -d");
