public class Md5HashCalculator
{
    private const int TimeOutInMilliseconds = 5000; // 5 seconds timeout
    private readonly object _lockObject = new object();
    private readonly int _maxRetries = 3;

    public string CalculateMd5(string input, string referenceHash)
    {
        byte[] hashBytes;
        using (var md5 = MD5.Create())
        {
            var buffer = Encoding.UTF8.GetBytes(input);
            hashBytes = md5.ComputeHash(buffer);
        }

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }

    public bool VerifyMd5(string input, string referenceHash)
    {
        try
        {
            string computedHash = CalculateMd5(input, referenceHash);

            // Simulate network latency and potential failures
            int retries = 0;
            while (true)
            {
                if (!NetworkCall(referenceHash)) return false; // hash retrieval failed
                retries++;
                if (retries >= _maxRetries) break; // maximum retries exceeded
            }

            return computedHash == referenceHash;
        }
        catch (Exception ex)
        {
            LogError(ex);
            return false;
        }
    }

    private bool NetworkCall(string referenceHash)
    {
        Thread.Sleep(TimeOutInMilliseconds); // simulate network latency

        // Simulate a transient failure
        if (new Random().Next(0, 10) > 7) throw new Exception("Network failure");

        return true; // hash retrieval successful
    }

    private void LogError(Exception ex)
    {
        // Implement logging mechanism here
        Console.WriteLine($"Error: {ex.Message}");
    }
}
