    return arr;
}

void populateRecordArray(record_t* records, int size, int minVal, int maxVal) {
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (maxVal - minVal + 1) + minVal;
    }
}

typedef struct _node {
    record_t* data;
    struct _node* next;
} node_t;

void insertNode(node_t** head, int key) {
    node_t* newNode = (node_t*)malloc(sizeof(node_t));
    newNode->data = NULL;
    newNode->next = *head;
    *head = newNode;
}

void deleteNode(node_t** head, int key) {
    if (*head == NULL)
        return;

    if ((*head)->data->value == key) {
        node_t* temp = *head;
        *head = (*head)->next;
        free(temp);
        return;
    }

    node_t* current = *head;
    while (current && current->next && current->next->data->value != key)
        current = current->next;

    if (current && current->next) {
        node_t* temp = current->next;
        current->next = current->next->next;
        free(temp);
    }
}

void printRecordArray(record_t* records, int size) {
    for (int i = 0; i < size; i++) {
        printf("%d\n", records[i].value);
    }
}
