typedef enum {
    LogLevel_Info,
    LogLevel_Warning,
    LogLevel_Error
} LogLevel;

// Function to generate random timestamps
time_t generateRandomTimestamp() {
    return time(NULL);
}

// Function to generate random log messages
char* generateRandomLogMessage(int length) {
    char* message = (char*)malloc(length + 1);
    for(int i = 0; i < length; i++) {
        message[i] = 'x' + rand() % 26;
    }
    message[length] = '\0';
    return message;
}

// Function to print array contents
void printArray(char* name, void* arr, int size) {
    printf("%s: ", name);
    for(int i = 0; i < size; i++) {
        printf("%p ", (void*)arr + i * sizeof(*arr));
    }
    printf("\n");
}

// Function to calculate and print frequency of each log type
void printLogFrequency(int* logTypes, int size) {
    int frequencies[LOG_TYPES_ARRAY_SIZE];
    for(int i = 0; i < LOG_TYPES_ARRAY_SIZE; i++) {
        frequencies[i] = 0;
    }
    for(int i = 0; i < size; i++) {
        frequencies[(int)logTypes[i]]++;
    }
    for(int i = 0; i < LOG_TYPES_ARRAY_SIZE; i++) {
        printf("Log Type %d: %d occurrences\n", i, frequencies[i]);
    }
}

// Initialize memory and initialize arrays
void* initArrays() {
    void* arr[7];

    // Offset array
    long* offsetArr = (long*)malloc(OFFSET_ARRAY_SIZE * sizeof(long));
    for(int i = 0; i < OFFSET_ARRAY_SIZE; i++) {
        offsetArr[i] = i;
    }
    arr[0] = offsetArr;

    // Key array
    int* keyArr = (int*)malloc(KEY_ARRAY_SIZE * sizeof(int));
    for(int i = 0; i < KEY_ARRAY_SIZE; i++) {
        keyArr[i] = i;
    }
    arr[1] = keyArr;

    // Log Level array
    LogLevel* logLevelArr = (LogLevel*)malloc(LOG_LEVEL_ARRAY_SIZE * sizeof(LogLevel));
    for(int i = 0; i < LOG_LEVEL_ARRAY_SIZE; i++) {
        logLevelArr[i] = (i % 3 == 0) ? LogLevel_Info : ((i % 3 == 1) ? LogLevel_Warning : LogLevel_Error);
    }
    arr[2] = logLevelArr;

    // Record array
    record* recordArr = (record*)malloc(RECORD_ARRAY_SIZE * sizeof(record));
    for(int i = 0; i < RECORD_ARRAY_SIZE; i++) {
        recordArr[i].value = rand() % 100;
    }
    arr[3] = recordArr;

    // LogEvent array
    LogEvent* logEventArr = (LogEvent*)malloc(RECORD_ARRAY_SIZE * sizeof(LogEvent));
    for(int i = 0; i < RECORD_ARRAY_SIZE; i++) {
        logEventArr[i].value = rand() % 100;
        logEventArr[i].timestamp = generateRandomTimestamp();
        logEventArr[i].logMessage = generateRandomLogMessage(10);
    }
    arr[4] = logEventArr;

    // Timestamp array
    time_t* timestampArr = (time_t*)malloc(TIMESTAMP_ARRAY_SIZE * sizeof(time_t));
    for(int i = 0; i < TIMESTAMP_ARRAY_SIZE; i++) {
        timestampArr[i] = generateRandomTimestamp();
    }
    arr[5] = timestampArr;

    // LogType array
    LogLevel* logTypeArr = (LogLevel*)malloc(LOG_TYPES_ARRAY_SIZE * sizeof(LogLevel));
    for(int i = 0; i < LOG_TYPES_ARRAY_SIZE; i++) {
        logTypeArr[i] = (i % 3 == 0) ? LogLevel_Info : ((i % 3 == 1) ? LogLevel_Warning : LogLevel_Error);
    }
    arr[6] = logTypeArr;

    return arr;
}

// Free allocated memory
void freeArrays(void* arr[]) {
    for(int i = 0; i < 7; i++) {
        if(arr[i] != NULL) {
            switch(i) {
                case 0:
                    free((long*)arr[i]);
                    break;
                case 1:
                    free((int*)arr[i]);
                    break;
                case 2:
                    free((LogLevel*)arr[i]);
                    break;
                case 3:
                    free((record*)arr[i]);
                    break;
                case 4:
                    for(int j = 0; j < RECORD_ARRAY_SIZE; j++) {
                        free(((LogEvent*)arr[i])->logMessage);
                    }
                    free(arr[i]);
                    break;
                case 5:
                    free((time_t*)arr[i]);
                    break;
                case 6:
                    free((LogLevel*)arr[i]);
                    break;
            }
        }
    }
}

// Main function
int main() {
    void* arrays[] = initArrays();

    // Print array contents for debugging purposes
    printArray("Offset", arrays[0], OFFSET_ARRAY_SIZE);
    printArray("Key", arrays[1], KEY_ARRAY_SIZE);
    printArray("Log Level", arrays[2], LOG_LEVEL_ARRAY_SIZE);
    printArray("Record", arrays[3], RECORD_ARRAY_SIZE);
    printArray("LogEvent", arrays[4], RECORD_ARRAY_SIZE);
    printArray("Timestamp", arrays[5], TIMESTAMP_ARRAY_SIZE);
    printArray("LogType", arrays[6], LOG_TYPES_ARRAY_SIZE);

    // Calculate and print frequency of each log type
    printLogFrequency((int*)arrays[6], RECORD_ARRAY_SIZE);

    freeArrays(arrays);

    return 0;
}
