#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

typedef struct Node {
    int64_t key;
    uint32_t index;
    struct Node* next;
} Node;

Node* processAndAnalyzeData() {
    FILE* file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return NULL;
    }

    Node* head = NULL;
    uint32_t maxIndex = 0;
    int64_t largestNum = INT64_MIN;

    while (!feof(file)) {
        int num;
        fscanf(file, "%d", &num);
        if (feof(file)) break;

        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->key = num;
        newNode->index = maxIndex++;
        newNode->next = head;
        head = newNode;

        // handle external data source failures and network latency
        if (ferror(file) || fgetpos(file, &maxIndex)) {
            fclose(file);
            return NULL;
        }
    }

    fclose(file);

    // print the largest integer across all processed streams
    Node* current = head;
    while (current != NULL) {
        if (current->key > largestNum) largestNum = current->key;
        current = current->next;
    }

    printf("Largest number: %ld\n", largestNum);

    return head;
}
