struct RandomValue {
    int min;
    int max;

    int RandomInt() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(min, max);
        return dis(gen);
    }

    float RandomFloat() {
        return (float)RandomInt() / (max - min + 1);
    }

    const char* ToString() {
        return printf("Random value between %d and %d\n", min, max).ToString();
    }
};

void processAndFindMax(int offset_size, int key_size, int record_size, int input_size) {
    srand(time(NULL));
    RandomValue random;

    int* offsets = (int*)malloc(offset_size * sizeof(int));
    int* keys = (int*)malloc(key_size * sizeof(int));

    // Initialize 'offset' and 'key' arrays
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = i;
    }
    for (int i = 0; i < key_size; i++) {
        keys[i] = i * 2;
    }

    struct record* records = (struct record*)malloc(record_size * sizeof(struct record));
    int* inputs = (int*)malloc(input_size * sizeof(int));

    // Initialize 'record' and 'input' arrays
    for (int i = 0; i < record_size; i++) {
        records[i].value = random.RandomInt();
    }
    for (int i = 0; i < input_size; i++) {
        inputs[i] = random.RandomInt();
    }

    // Check if 'record' array size exceeds the sum of the sizes
    if (record_size > offset_size + key_size + input_size) {
        printf("Error: Record array size exceeded.\n");
        return;
    }

    // Print contents of all arrays for debugging
    for (int i = 0; i < offset_size; i++) {
        printf("Offset %d: %d\n", i, offsets[i]);
    }
    for (int i = 0; i < key_size; i++) {
        printf("Key %d: %d\n", i, keys[i]);
    }
    for (int i = 0; i < record_size; i++) {
        printf("Record %d: %d\n", i, records[i].value);
    }
    for (int i = 0; i < input_size; i++) {
        printf("Input %d: %d\n", i, inputs[i]);
    }

    // Find and print the largest integer in the array
    int max_input = findMax(inputs, input_size);

    printf("Largest input value: %d\n", max_input);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);
    free(inputs);

    return;
}

int findMax(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}
