        // Initialize arrays
        for (int i = 0; i < num_offsets; i++) {
            offsets[i] = rand();
        }
        for (int i = 0; i < num_keys; i++) {
            keys[i] = rand();
        }
    } else {
        printf("Invalid configuration: Adjust the command line arguments.\n");
        return NULL;
    }

    record **records = NULL;
    if (num_records > 0) {
        records = malloc(num_records * sizeof(record *));
        for (int i = 0; i < num_records; i++) {
            record *rec = malloc(sizeof(record));
            rec->value = rand();
            records[i] = rec;
        }
    } else {
        printf("Invalid configuration: Adjust the command line arguments.\n");
        return NULL;
    }

    cipher *cipher_obj = malloc(sizeof(cipher));

    cipher_obj->offsets = offsets;
    cipher_obj->keys = keys;
    cipher_obj->records = records;

    // Initialize cryptographic operation
    if (argc > 4 && strcmp(argv[4], "-aes-256-cbc") == 0) {
        cipher_obj->crypt_op = &AES_encrypt;
    } else if (argc > 4 && strcmp(argv[4], "-rsa-2048-oaep") == 0) {
        cipher_obj->crypt_op = &RSA_encrypt;
    } else {
        printf("Invalid cryptographic operation. Defaulting to none.\n");
        cipher_obj->crypt_op = NULL;
    }

    return cipher_obj;
}

void free_cipher(cipher *cipher_obj) {
    if (cipher_obj) {
        if (cipher_obj->offsets)
            free(cipher_obj->offsets);
        if (cipher_obj->keys)
            free(cipher_obj->keys);
        for (int i = 0; i < cipher_obj->num_records; i++) {
            if (cipher_obj->records[i])
                free(cipher_obj->records[i]);
        }
        if (cipher_obj->records)
            free(cipher_obj->records);

        free(cipher_obj);
    }
}
