#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_CAPACITY 64
#define LOAD_FACTOR_THRESHOLD 0.75
#define INITIAL_CAPACITY 16

typedef struct {
    int key;
    long long offset;
    char* data;
} Record;

typedef struct {
    int size;
    Record** records;
} HashTable;

HashTable* init_hash_table(int capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = 0;
    table->records = (Record**)calloc(capacity, sizeof(Record*));
    return table;
}

void free_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        free(table->records[i]->data);
        free(table->records[i]);
    }
    free(table->records);
    free(table);
}

int hash_function(int key, int capacity) {
    return key % capacity;
}

void add_record(HashTable* table, Record* record) {
    int index = hash_function(record->key, table->size);
    if (table->records[index] == NULL) {
        table->records[index] = record;
    } else {
        for (int i = 0; i < table->size; i++) {
            if (table->records[i]->key == record->key) {
                free(record->data);
                return;
            }
        }
        table->records[index] = record;
    }
}

Record* retrieve_record(HashTable* table, int key) {
    int index = hash_function(key, table->size);
    for (int i = 0; i < table->size; i++) {
        if (table->records[i]->key == key) {
            return table->records[i];
        }
    }
    return NULL;
}

void remove_record(HashTable* table, int key) {
    int index = hash_function(key, table->size);
    for (int i = 0; i < table->size; i++) {
        if (table->records[i]->key == key) {
            free(table->records[i]->data);
            free(table->records[i]);
            table->records[i] = NULL;
            return;
        }
    }
}

void rehash_table(HashTable* table, int capacity) {
    HashTable* new_table = init_hash_table(capacity);
    for (int i = 0; i < table->size; i++) {
        Record* record = table->records[i];
        if (record != NULL) {
            int index = hash_function(record->key, capacity);
            record->data = (char*)realloc(record->data, (new_table->size + 1) * sizeof(char));
            new_table->records[index] = record;
        }
    }
    free_hash_table(table);
    table = new_table;
}

void print_records(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        if (table->records[i] != NULL) {
            printf("%d %lld %s\n", table->records[i]->key, table->records[i]->offset, table->records[i]->data);
        }
    }
}

