    file_entry** file_entries;
    int num_files;
    access_info* access_info_list;
    int num_accesses;
    error* error_info;
    pthread_mutex_t mutex;
} shared_data;

void manageAndProcessFileMetaData() {
    int i, j;
    char line[1024];
    FILE* input = stdin;

    // Initialize structures
    file_entry* files = NULL;
    access_info* access_info_list = NULL;
    error* error_info = NULL;
    shared_data* shared_data_ptr = NULL;

    while (fgets(line, 1024, input)) {
        // Tokenize line into file path and size
        char* token1 = strtok(line, ":");
        char* token2 = strtok(NULL, "\n");

        // Allocate memory for new file entry
        file_entry* new_file = (file_entry*)malloc(sizeof(file_entry));
        if (!new_file) {
            printf("Memory allocation failed!\n");
            exit(1);
        }
        new_file->file_path = token1;
        new_file->file_size = atoi(token2);

        // Calculate checksum using external hashing library
        uint128_t checksum = hash_token(new_file->file_path, strlen(new_file->file_path));
        new_file->checksum = checksum;

        // Add to file array and update num_files count
        if (!files) {
            files = (file_entry*)malloc(sizeof(file_entry) * 2);
            if (!files) {
                printf("Memory allocation failed!\n");
                exit(1);
            }
            files[0] = *new_file;
            files[1].file_path = NULL;
            files[1].file_size = 0;
            files[1].checksum = 0;
            num_files = 2;
        } else {
            file_entry* temp = (file_entry*)realloc(files, sizeof(file_entry) * (num_files + 1));
            if (!temp) {
                printf("Memory reallocation failed!\n");
                exit(1);
            }
            files = temp;
            files[num_files++] = *new_file;
        }
    }

    // Initialize error structure and set error code to 0
    error_info->error_code = 0;
    error_info->error_message = NULL;

    // Deallocate memory for file entries, access info list, and error info
    for (i = 0; i < num_files; i++) {
        free(files[i].file_path);
        free(files[i]);
    }
    free(files);

    for (j = 0; j < num_accesses; j++) {
        free(access_info_list[j].access_thread_id);
    }
    free(access_info_list);

    if (error_info->error_code) {
        printf("Error code: %d\n", error_info->error_code);
        printf("Error message: %s\n", error_info->error_message);
    }

    // Deinitialize external hashing library
    deinit_hashing_library();

    // Close input file stream
    fclose(input);

    return;
}
