typedef struct {
    double value;
    char* string;
} item_t;

typedef struct {
    int numItems;
    double* values;
    item_t** items;
    char** metadata;
} metadata_t;

void parseAndAggregateData(int argc, char** argv) {
    int linesRead = 0;
    int maxItems = 1000; // assume at most 1000 items
    int metadataSize = 1024; // adjust as needed

    // Initialize arrays
    double* values = (double*)malloc(maxItems * sizeof(double));
    item_t** items = (item_t**)malloc(maxItems * sizeof(item_t*));
    char** metadata = (char*)malloc(metadataSize * sizeof(char));

    metadata_t metadataStruct;
    metadataStruct.numItems = 0;
    metadataStruct.values = values;
    metadataStruct.items = items;
    metadataStruct.metadata = NULL;

    // Initialize file processing library
    extern void initLib();
    extern void deinitLib();

    int initialized = 0;

    FILE* file = fopen(argv[1], "r");
    if (file != NULL) {
        char line[1024];
        while (fgets(line, sizeof(line), file)) {
            // Parse and process each line
            double val;
            char* str;
            item_t* item = (item_t*)malloc(sizeof(item_t));

            sscanf(line, "%lf %s", &val, str);
            item->value = val;
            item->string = str;

            items[metadataStruct.numItems] = item;

            metadata[metadataStruct.numItems * 1024] = line; // or copy relevant data

            if (initialized == 0) {
                initLib();
                initialized = 1;
            }

            linesRead++;
        }
    }

    fclose(file);

    int largestValueIndex = 0;
    for (int i = 0; i < metadataStruct.numItems; i++) {
        if (values[i] > values[largestValueIndex]) {
            largestValueIndex = i;
        }
    }

    // Check size constraints
    if (metadataStruct.numItems > maxItems || linesRead > maxItems) {
        printf("Error: exceeded maximum item count\n");
        return;
    }

    // Print arrays for debugging
    for (int i = 0; i < metadataStruct.numItems; i++) {
        printf("%lf %s\n", values[i], items[i]->string);
    }
    printf("\nLargest value: %lf\n", values[largestValueIndex]);
    printf("Metadata: %s\n", metadata);

    // Deinitialize file processing library
    deinitLib();

    // Free allocated memory
    for (int i = 0; i < metadataStruct.numItems; i++) {
        free(items[i]->string);
        free(items[i]);
    }
    free(metadata);
    free(values);
    free(items);
}

int main(int argc, char** argv) {
    parseAndAggregateData(argc, argv);
    return 0;
}
