    for (int i = 0; i < n; i++) {
        int value = rand() % 1000 + 1;
        long* offset = &offsets[i];
        records[i].value = value;
        records[i].offset = offset;
    }

    // Clean up function to free allocated memory
    void cleanup(int* keys, long* offsets, record* records) {
        free(keys);
        free(offsets);
        free(records);
    }

    // Error checking for n being zero or negative
    if (n <= 0) {
        printf("Error: Invalid input. n must be positive.\n");
    } else {
        // Perform operations on allocated memory...
    }
}

// Helper function to check if a number is prime
int is_prime(int num) {
    if (num < 2) {
        return 0;
    }
    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            return 0;
        }
    }
    return 1;
}
