    if (record_count < MAX_RECORDS) {
        printf("Memory allocation limit reached.\n");
    } else {
        printf("Total memory used: %ld bytes\n", total_memory_usage(records, record_count));
    }

    // Free all allocated memory
    for (int i = 0; i < record_count; i++) {
        free(records[i].string);
    }
    free(records);

    return 0;
}

size_t total_memory_usage(record_t* records, int count) {
    size_t total_memory = sizeof(record_t) * count;

    for (int i = 0; i < count; i++) {
        total_memory += strlen(records[i].string) + 1;
    }

    return total_memory;
}

size_t total_value(record_t* records, int count) {
