            child->next = (*nodes)[i].children;
            (*nodes)[i].children = child;
        }
    }
}

void free_node_array(Node** nodes, int size) {
    for (int i = 0; i < size; i++) {
        if ((*nodes)[i].string != NULL) {
            free((*nodes)[i].string);
        }
        if ((*nodes)[i].children != NULL) {
            ChildNode* current = (*nodes)[i].children;
            while (current != NULL) {
                ChildNode* next = current->next;
                free(current);
                current = next;
            }
        }
    }
    for (int i = 0; i < size; i++) {
        if ((*nodes)[i] != NULL) {
            free((*nodes)[i]);
        }
