typedef struct {
    int value;
} record;

void processAndComputeStatistics(int fd, int offsetSize, int keySize, int recordSize, int windowSize) {
    // Initialize moving average buffer with default size
    int* movingAverage = (int*)malloc(windowSize * sizeof(int));
    if (!movingAverage) {
        printf("Error allocating memory for moving averages\n");
        return;
    }

    // Initialize record array with random values
    record* records = (record*)malloc(offsetSize * sizeof(record));
    if (!records) {
        printf("Error allocating memory for records\n");
        free(movingAverage);
        return;
    }
    for (int i = 0; i < offsetSize; i++) {
        records[i].value = rand() % 100;
    }

    // Read measurements from file and compute statistics
    long* offsets = (long*)malloc(offsetSize * sizeof(long));
    int* keys = (int*)malloc(keySize * sizeof(int));
    if (!offsets || !keys) {
        printf("Error allocating memory for offsets and keys\n");
        free(movingAverage);
        free(records);
        return;
    }
    FILE* file = fopen("measurements.txt", "r");
    if (file == NULL) {
        printf("Error opening file\n");
        free(offsets);
        free(keys);
        free(movingAverage);
        free(records);
        return;
    }
    int bytesRead = fread((void*)offsets, sizeof(long), offsetSize, file);
    if (bytesRead != offsetSize) {
        printf("Error reading offsets from file\n");
        fclose(file);
        free(offsets);
        free(keys);
        free(movingAverage);
        free(records);
        return;
    }
    bytesRead = fread((void*)keys, sizeof(int), keySize, file);
    if (bytesRead != keySize) {
        printf("Error reading keys from file\n");
        fclose(file);
        free(offsets);
        free(keys);
        free(movingAverage);
        free(records);
        return;
    }
    fclose(file);

    // Compute statistics
    double mean = 0.0, median = 0.0, stdDev = 0.0;
    int sum = 0;
    for (int i = 0; i < offsetSize; i++) {
        sum += offsets[i];
    }
    mean = (double)sum / offsetSize;

    // Print statistics
    printf("Mean: %f\n", mean);
    printf("Median: %f\n", median);
    printf("Standard Deviation: %f\n", stdDev);

    // Compute moving averages
    int movingAverageIndex = 0;
    for (int i = 0; i < offsetSize; i++) {
        if (i >= windowSize) {
            movingAverage[movingAverageIndex] = (int)mean;
            movingAverageIndex++;
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(movingAverage);
    free(records);

    return;
}

