        do {
            key = rand() % 99 + 1;
        } while (!is_prime(key));
        keys[i] = key;
    }

    // allocate memory for records and initialize integer values
    record *records = malloc(n * sizeof(record));
    for (int i = 0; i < n; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets + i;
    }

    // clean up
    free(keys);

    return records;
}

void cleanup(record *records, int n) {
    if (records != NULL) {
        for (int i = 0; i < n; i++) {
            free(records[i].offset);
        }
        free(records);
    }
}

