#include <string.h>

typedef struct {
    double value;
    char* metadata;
} item;

typedef struct {
    item* ptr;
} metadata;

double processAndAggregateData(int fileSize, const char* filePath) {
    int i = 0;
    size_t capacity = 1024; // Initial capacity
    double* values = (double*)malloc(capacity * sizeof(double));
    char** metadataPointers = (char**)malloc(capacity * sizeof(char*));
    item* items = (item*)malloc(capacity * sizeof(item));
    metadata* metadataArray = (metadata*)malloc(capacity * sizeof(metadata));

    FILE* file = fopen(filePath, "r");
    if (!file) {
        fprintf(stderr, "Error opening file.\n");
        return -1.0;
    }

    char line[1024];
    while (fgets(line, 1024, file)) {
        // Parse the line and populate items and metadata
        double value = atof(strtok(line, ","));
        char* metadataStr = strtok(NULL, ",");
        item* itemStruct = &items[i];
        itemStruct->value = value;
        itemStruct->metadata = malloc(strlen(metadataStr) + 1);
        strcpy(itemStruct->metadata, metadataStr);

        metadataArray[i].ptr = &itemStruct;

        if (i >= capacity) {
            // Reallocate memory for arrays
            capacity *= 2; // Double the capacity
            values = (double*)realloc(values, capacity * sizeof(double));
            metadataPointers = (char**)realloc(metadataPointers, capacity * sizeof(char*));
            items = (item*)realloc(items, capacity * sizeof(item));
            metadataArray = (metadata*)realloc(metadataArray, capacity * sizeof(metadata));

            // Reinitialise arrays
            for (int j = i; j < capacity; j++) {
                values[j] = 0.0;
                metadataPointers[j] = NULL;
                items[j].value = 0.0;
                items[j].metadata = NULL;
                metadataArray[j].ptr = NULL;
            }
        }

        i++;
    }

    fclose(file);

    // Extract the largest double value
    double maxValue = *std::max_element(values, values + i);

    // Concatenate all strings in metadata array
    char result[1024];
    strcpy(result, "");
    for (int j = 0; j < i; j++) {
        strcat(result, items[j].metadata);
        free(items[j].metadata); // Free the allocated memory
    }

    // Deallocate remaining arrays
    for (int j = i; j < capacity; j++) {
        if (values[j] != 0.0) {
            values[j] = 0.0;
        }
        if (metadataPointers[j]) {
            free(metadataPointers[j]);
        }
        if (items[j].value != 0.0) {
            items[j].value = 0.0;
        }
        if (items[j].metadata) {
            free(items[j].metadata);
        }
        if (metadataArray[j].ptr) {
            metadataArray[j].ptr = NULL;
        }
    }

    // Deallocate arrays
    free(values);
    for (int j = 0; j < i; j++) {
        free(metadataPointers[j]);
    }
    free(metadataPointers);
    free(items);
    free(metadataArray);

    return maxValue;
}

