#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a struct to represent a message event
typedef struct {
    int timestamp;
    char* body;
    int type;
} MessageEvent;

// Initialize the random number generator
srand(time(NULL));

// Function to handle the message stream
void handleMessageStream(int numHeaders, int numEvents) {
    // Allocate memory for headers and priorities arrays
    int** headers = (int**)malloc(numHeaders * sizeof(int*));
    int* priorities = (int*)malloc(numHeaders * sizeof(int));

    // Initialize the headers and priorities arrays
    for (int i = 0; i < numHeaders; i++) {
        headers[i] = (int*)malloc(sizeof(int));
        priorities[i] = rand() % 100;
    }

    // Allocate memory for event array
    MessageEvent* events = (MessageEvent*)malloc(numEvents * sizeof(MessageEvent));

    // Populate the event array with randomly generated timestamps, event types, and message bodies
    for (int i = 0; i < numEvents; i++) {
        events[i].timestamp = rand() % 100000;
        events[i].body = (char*)malloc((rand() % 50) + 1);
        sprintf(events[i].body, "Message body %d", i);
        events[i].type = rand() % 2;
    }

    // Calculate the average length of message headers
    int sum = 0;
    for (int i = 0; i < numHeaders; i++) {
        sum += strlen((char*)headers[i]);
    }
    printf("Average header length: %.2f\n", (double)sum / numHeaders);

    // Free all allocated memory
    for (int i = 0; i < numHeaders; i++) {
        free(headers[i]);
    }
    free(headers);
    free(priorities);
    for (int i = 0; i < numEvents; i++) {
        free(events[i].body);
    }
    free(events);

    // Log the operation
    FILE* logFile = fopen("operation.log", "a");
    if (logFile != NULL) {
        fprintf(logFile, "Message stream handled successfully\n");
        fclose(logFile);
    } else {
        printf("Error opening log file\n");
    }
}

int main() {
    int numHeaders = 10;
    int numEvents = 50;
    handleMessageStream(numHeaders, numEvents);
    return 0;
}
