void init_arrays(long offset_values_size, int key_sizes_sum, long record_values_size) {
    // Dynamically allocate memory for arrays
    long *offset_values = (long *)malloc(offset_values_size * sizeof(long));
    int *keys = (int *)malloc(key_sizes_sum * sizeof(int));
    Record *records = (Record *)malloc(record_values_size * sizeof(Record));
    Metadata *metadata = (Metadata *)malloc((key_sizes_sum + offset_values_size) * sizeof(Metadata));

    // Initialize arrays
    for (long i = 0; i < offset_values_size; i++) {
        offset_values[i] = i;
    }
    for (int i = 0; i < key_sizes_sum; i++) {
        keys[i] = i;
    }
    for (long i = 0; i < record_values_size; i++) {
        records[i].value = i;
    }

    // Initialize metadata array
    for (long i = 0; i < key_sizes_sum + offset_values_size; i++) {
        Metadata *metadata_ptr = &metadata[i];
        Record record = records[i % record_values_size];
        long offset_value = offset_values[i % offset_values_size];
        char string[10];
        sprintf(string, "Record %ld", record.value);
        metadata_ptr->string = malloc(strlen(string) + 1);
        strcpy(metadata_ptr->string, string);
        metadata_ptr->value = (double)record.value / offset_value;
    }

    // Free allocated memory
    for (long i = 0; i < key_sizes_sum + offset_values_size; i++) {
        free(metadata[i].string);
    }
    free(metadata);
    free(records);
    free(keys);
    free(offset_values);

    // Print array contents for debugging
    printf("Offset values: ");
    for (long i = 0; i < offset_values_size; i++) {
        printf("%ld ", offset_values[i]);
    }
    printf("\n");
    printf("Keys: ");
    for (int i = 0; i < key_sizes_sum; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");
    printf("Records: ");
    for (long i = 0; i < record_values_size; i++) {
        printf("%d ", records[i].value);
    }
    printf("\n");
    printf("Metadata strings: ");
    for (long i = 0; i < key_sizes_sum + offset_values_size; i++) {
        printf("%s ", metadata[i].string);
    }
    printf("\n");

    // Print metadata values
    printf("Metadata values: ");
    for (long i = 0; i < key_sizes_sum + offset_values_size; i++) {
        printf("%f ", metadata[i].value);
    }
    printf("\n");
}

int main() {
    init_arrays(100, 50, 20);
