import java.util.*;
import java.text.*;
import java.time.*;

public class NetworkTrafficAnalyzer {
    private static final int DEFAULT_SESSION_TIMEOUT = 30000; // 30 seconds
    private static final int DEFAULT_PACKET_THRESHOLD = 5;

    private Map<String, Session> sessions;
    private SortedMap<Long, Long> timestampToSessionId;
    private int sessionTimeout;
    private int packetThreshold;

    public NetworkTrafficAnalyzer() {
        this.sessions = new HashMap<>();
        this.timestampToSessionId = new TreeMap<>();
        this.sessionTimeout = DEFAULT_SESSION_TIMEOUT;
        this.packetThreshold = DEFAULT_PACKET_THRESHOLD;
    }

    public void analyzeLogEntry(String timestamp, String sourceIP, String destIP) throws Exception {
        long timestampLong = Long.parseLong(timestamp);
        Session session = sessions.get(sourceIP + "_" + destIP);

        if (session == null) {
            session = new Session(sourceIP, destIP);
            sessions.put(sourceIP + "_" + destIP, session);
        }

        int packetInterval = calculatePacketInterval(session, timestampLong);

        if (packetInterval < 0) {
            // timeout
            session.endTime = timestampLong;
        } else {
            session.addPacket(timestampLong, packetInterval);
        }

        printProcessingTime(timestampLong);
    }

    private int calculatePacketInterval(Session session, long timestamp) throws Exception {
        if (timestampToSessionId.containsKey(timestamp)) {
            Session previousSession = sessions.get((String) timestampToSessionId.get(timestamp));
            if (previousSession != null && !session.equals(previousSession)) {
                // overlapping session boundaries
                return -1;
            }
        }

        long earliestPacketTime = session.earliestPacketTime();
        int packetInterval = (int) (timestamp - earliestPacketTime);

        if (packetInterval > sessionTimeout) {
            // timeout
            return -1;
        } else if (session.getPackets() < packetThreshold) {
            // new packet, update session start time
            session.startTime = timestamp;
            session.endTime = timestamp;
        }

        return packetInterval;
    }

    private void printProcessingTime(long timestamp) throws Exception {
        long now = System.currentTimeMillis();
        System.out.println("Processed log entry at " + DateFormat.getDateTimeInstance().format(new Date(now)) + ": " + timestamp);
    }

    public Map<String, SessionSummary> getSessionSummaries() {
        Map<String, SessionSummary> summaries = new HashMap<>();
        for (Session session : sessions.values()) {
            summaries.put(session.getSourceIP() + "_" + session.getDestIP(), session.getSummary());
        }
        return summaries;
    }

    public static class Session {
        private String sourceIP;
        private String destIP;
        private long startTime;
        private long endTime;
        private List<Long> packetTimes;

        public Session(String sourceIP, String destIP) {
            this.sourceIP = sourceIP;
            this.destIP = destIP;
            this.startTime = System.currentTimeMillis();
            this.endTime = startTime;
            this.packetTimes = new ArrayList<>();
        }

        public int getPackets() {
            return packetTimes.size();
        }

        public long getEarliestPacketTime() {
            if (packetTimes.isEmpty()) {
                return startTime;
            }
            return packetTimes.get(0);
        }

        public void addPacket(long time, int interval) {
            packetTimes.add(time);
        }

        public String getSourceIP() {
            return sourceIP;
        }

        public String getDestIP() {
            return destIP;
        }

        public long getStartTime() {
            return startTime;
        }

        public long getEndTime() {
            return endTime;
        }

        public SessionSummary getSummary() {
            int packetCount = getPackets();
            long averagePacketInterval = (long) packetTimes.stream().mapToLong(t -> t).average().orElse(0);
            return new SessionSummary(packetCount, averagePacketInterval);
        }
    }

    public static class SessionSummary {
        private int packetCount;
        private long averagePacketInterval;

        public SessionSummary(int packetCount, long averagePacketInterval) {
            this.packetCount = packetCount;
            this.averagePacketInterval = averagePacketInterval;
        }

        // getters and setters
    }
}
