        if (rand() % 2) {
            (*status)[i] = 1;
        } else {
            (*status)[i] = 0;
        }
        (*priority)[i] = rand() % 100;
    }
}

void cleanup_arrays(int** key, int*** record, int** status, int** priority) {
    for (int i = 0; i < *key != NULL ? *key : 0; i++) {
        free(((*record))[i]);
    }
    free(*key);
    free(*record);
    free(*status);
    free(*priority);
}

void print_arrays(int* offset, int* key, record_t* record, int* status, int* priority) {
