// Custom random number generator structure
typedef struct {
    uint32_t seed;
} custom_rng_t;

// Record structure
typedef struct {
    int value;
} record_t;

// Custom memory pool structure
typedef struct {
    void* base;
    size_t size;
    size_t used;
} memory_pool_t;

memory_pool_t* create_memory_pool(size_t initial_size);
void* allocate_memory(memory_pool_t* pool, size_t size);
void deallocate_memory(memory_pool_t* pool, void* ptr);

void init_data_structures() {
    // Input parameters
    int num_records = 100;
    int min_key_value = 0;
    int max_key_value = 100;

    // Create memory pool
    memory_pool_t* pool = create_memory_pool(1024 * 1024); // Initialize with 1MB

    // Allocate arrays
    long* offset_array = allocate_memory(pool, num_records * sizeof(long));
    int* key_array = allocate_memory(pool, num_records * sizeof(int));
    record_t* record_array = allocate_memory(pool, num_records * sizeof(record_t));
    uint64_t* timestamp_array = allocate_memory(pool, num_records * sizeof(uint64_t));

    // Initialize arrays
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = i;
        key_array[i] = rand() % (max_key_value - min_key_value + 1) + min_key_value;
        record_array[i].value = rand();
        timestamp_array[i] = time(NULL);
    }

    // Serialize data structures to file
    FILE* file = fopen("data.bin", "wb");
    fwrite(offset_array, sizeof(long), num_records, file);
    fwrite(key_array, sizeof(int), num_records, file);
    fwrite(record_array, sizeof(record_t), num_records, file);
    fwrite(timestamp_array, sizeof(uint64_t), num_records, file);
    fclose(file);

    // Deallocate memory
    deallocate_memory(pool, offset_array);
    deallocate_memory(pool, key_array);
    deallocate_memory(pool, record_array);
    deallocate_memory(pool, timestamp_array);
    destroy_memory_pool(pool);
}

memory_pool_t* create_memory_pool(size_t initial_size) {
    // Initialize memory pool
    memory_pool_t* pool = malloc(sizeof(memory_pool_t));
    pool->base = malloc(initial_size);
    pool->size = initial_size;
    pool->used = 0;

    return pool;
}

void* allocate_memory(memory_pool_t* pool, size_t size) {
    void* ptr = NULL;

    if (pool->used + size <= pool->size) {
        ptr = pool->base + pool->used;
        pool->used += size;
    } else {
        // Reallocate memory pool if necessary
        size_t new_size = pool->size * 2;
        void* new_base = realloc(pool->base, new_size);
        if (new_base == NULL) {
            printf("Memory allocation failure\n");
            return NULL;
        }
        pool->base = new_base;
        pool->size = new_size;
    }

    return ptr;
}

void deallocate_memory(memory_pool_t* pool, void* ptr) {
    // Deallocate memory
    if (pool != NULL && ptr != NULL) {
        size_t size = strlen(ptr);
        pool->used -= size;
        free(ptr);
    }
}

void destroy_memory_pool(memory_pool_t* pool) {
    // Destroy memory pool
    free(pool->base);
    free(pool);
}
