#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure representing an item in the inventory
typedef struct {
    int id;
    char *description;
} Item;

// Dynamic list of items, implemented as a doubly-linked list
typedef struct Node {
    Item *item;
    struct Node *prev;
    struct Node *next;
} Node;

// Function to create a new node for the dynamic list
Node* create_node(Item *item) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->item = item;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to add an item to the end of the dynamic list
void add_item(Node **head, Item *item) {
    Node *new_node = create_node(item);
    if (*head == NULL) {
        *head = new_node;
    } else {
        (*head)->next->prev = new_node;
        new_node->next = (*head)->next;
        (*head)->next = new_node;
    }
}

// Function to remove an item from the dynamic list
void remove_item(Node **head, int id) {
    Node *curr = *head;
    while (curr != NULL && curr->item->id != id) {
        curr = curr->next;
    }
    if (curr == NULL) return; // Item not found

    if (curr->prev != NULL) {
        curr->prev->next = curr->next;
    } else {
        *head = curr->next;
    }
    if (curr->next != NULL) {
        curr->next->prev = curr->prev;
    }

    free(curr->item);
    free(curr);

    // Update the head pointer to the new first item
    while (*head && (*head)->item->id > id) {
        Node *temp = *head;
        *head = (*head)->next;
        temp->next->prev = NULL;
        temp->next = temp->prev;
        free(temp);
    }
}

// Function to search for an item by ID
Item* search_item(Node *head, int id) {
    Node *curr = head;
    while (curr != NULL) {
        if (curr->item->id == id) return curr->item;
        curr = curr->next;
    }
    return NULL; // Item not found
}

// Function to update an item's description atomically
void update_item_description(Node **head, int id, char *new_desc) {
    Node *curr = *head;
    while (curr != NULL && curr->item->id != id) {
        curr = curr->next;
    }
    if (curr == NULL) return; // Item not found

    char *temp = curr->item->description;
    curr->item->description = new_desc;

    free(temp);

    pthread_mutex_unlock(&mutex);
}

// Function to free all memory allocated for the dynamic list
void free_list(Node **head) {
    Node *curr = *head;
    while (curr != NULL) {
        Node *next = curr->next;
        free(curr->item->description);
        free(curr->item);
        free(curr);
        curr = next;
    }
    *head = NULL;
}
