#include <string.h>
#include <pthread.h>

#define MAX_ENTRIES 1000
#define STRING_POOL_SIZE 256

typedef struct {
    char* key;
    size_t length;
    double value;
} entry;

entry** array = NULL;
size_t capacity = 0;
size_t count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
char* string_pool[STRING_POOL_SIZE] = {0};

entry* create_entry(char* key, size_t length, double value) {
    entry* new_entry = (entry*)malloc(sizeof(entry));
    if (!new_entry) return NULL;

    new_entry->key = key;
    new_entry->length = length;
    new_entry->value = value;
    return new_entry;
}

void resize_array() {
    pthread_mutex_lock(&mutex);

    size_t new_capacity = capacity * 2;
    entry** new_array = (entry**)realloc(array, sizeof(entry*) * new_capacity);
    if (!new_array) {
        free(array);
        array = NULL;
        capacity = 0;
        count = 0;
        pthread_mutex_unlock(&mutex);
        return;
    }

    for (size_t i = capacity; i < new_capacity; i++) {
        new_array[i] = NULL;
    }
    array = new_array;
    capacity = new_capacity;

    pthread_mutex_unlock(&mutex);
}

entry* add_entry(char* key) {
    if (!key) return NULL;

    entry* new_entry = create_entry(key, strlen(key), 0.0);

    if (new_entry) {
        pthread_mutex_lock(&mutex);
        if (count >= capacity) resize_array();
        array[count] = new_entry;
        count++;
        pthread_mutex_unlock(&mutex);
    }

    return new_entry;
}

entry* get_entry(char* key) {
    for (size_t i = 0; i < count; i++) {
        entry* current_entry = array[i];
        if (!current_entry->key || strcmp(current_entry->key, key) == 0) {
            return current_entry;
        }
    }

    return NULL;
}

void free_entries() {
    for (size_t i = 0; i < count; i++) {
        entry* current_entry = array[i];
        if (current_entry) {
            free(current_entry->key);
            free(current_entry);
        }
    }

    free(array);
}

int main() {
    add_entry("key1");
    add_entry("key2");
    // ...
    return 0;
}
