```cpp
#include <iostream>
#include <map>
#include <string>
#include <memory>
#include <mutex>
#include <thread>

class Resource {
public:
    int id;
    float availability;
    std::shared_ptr<std::string> type;

    Resource(int _id, float _availability, const std::string& _type)
        : id(_id), availability(_availability), type(std::make_shared<std::string>(_type)) {}
};

class ResourceManager {
public:
    std::map<int, Resource*> resources;
    mutable std::mutex mtx;
    size_t limit = 10000;

    void addResource(int id, float availability, const std::string& type) {
        std::lock_guard<std::mutex> lock(mtx);
        if (resources.size() < limit) {
            resources[id] = new Resource(id, availability, type);
        } else {
            // handle overflow
        }
    }

    void removeResource(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = resources.find(id);
        if (it != resources.end()) {
            delete it->second;
            resources.erase(it);
        }
    }

    Resource* getResource(int id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = resources.find(id);
        return it != resources.end() ? it->second : nullptr;
    }

    void updateResource(int id, float availability) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = resources.find(id);
        if (it != resources.end()) {
            it->second->availability = availability;
        }
    }
};

int main() {
    ResourceManager rm;

    // Add some resources
    for (int i = 0; i < 5; ++i) {
        rm.addResource(i, 1.0f, "CPU");
    }

    // Remove a resource
    rm.removeResource(2);

    // Update the availability of a resource
    rm.updateResource(1, 0.8f);

    return 0;
}
