// Function to initialize and manage memory for four data structures
void init_memory(int offset_size, int key_size, int record_count) {
    // Initialize random number generator
    srand(time(NULL));

    // Dynamically allocate memory for offset values
    long* offsets = (long*)calloc(offset_size, sizeof(long));
    if (!offsets) {
        printf("Error: Unable to allocate memory for offset values.\n");
        return;
    }

    // Initialize offset values with specific values based on input parameters
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = i * i;
    }

    // Dynamically allocate memory for int keys
    int* keys = (int*)calloc(key_size, sizeof(int));
    if (!keys) {
        printf("Error: Unable to allocate memory for int keys.\n");
        free(offsets);
        return;
    }

    // Initialize int keys with specific values based on input parameters
    for (int i = 0; i < key_size; i++) {
        keys[i] = i * i + 1;
    }

    // Dynamically allocate memory for record structures
    record_t* records = (record_t*)calloc(record_count, sizeof(record_t));
    if (!records) {
        printf("Error: Unable to allocate memory for record structures.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize record structures with random integers within a specified range
    for (int i = 0; i < record_count; i++) {
        records[i].value = rand() % 100;
    }

    // Dynamically allocate memory for metadata strings
    char** metadata = (char**)calloc(record_count, sizeof(char*));
    if (!metadata) {
        printf("Error: Unable to allocate memory for metadata strings.\n");
        free(offsets);
        free(keys);
        free(records);
        return;
    }

    // Initialize metadata strings with unique identifiers
    for (int i = 0; i < record_count; i++) {
        metadata[i] = strdup(metadata_strings[rand() % 4]);
    }

    // Print contents of all data structures for debugging purposes
    printf("Timestamp: %f\n", time(NULL));
    printf("Offset values:\n");
    for (int i = 0; i < offset_size; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");

    printf("Int keys:\n");
    for (int i = 0; i < key_size; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");

    printf("Record structures:\n");
    for (int i = 0; i < record_count; i++) {
        printf("%d %s\n", records[i].value, metadata[i]);
    }

    // Free all allocated memory when the function returns
    free(offsets);
    free(keys);
    for (int i = 0; i < record_count; i++) {
        free(metadata[i]);
    }
    free(metadata);

    return;
}

int main() {
    init_memory(10, 5, 4);
    return 0;
}
