#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <crypt.h>

void processAndAggregateData(char* sourceString, int maxElements, int readFromStdin) {
    srand(time(NULL));

    // Allocate memory for arrays
    double* measurements = (double*)malloc(maxElements * sizeof(double));
    char** identifiers = (char**)malloc(maxElements * sizeof(char*));
    time_t* timestamps = (time_t*)malloc(maxElements * sizeof(time_t));
    struct {
        double measurement;
        char* identifier;
        time_t timestamp;
    }* events = (struct{}*)malloc(maxElements * sizeof(struct {}));
    struct {
        int min;
        int max;
        double average;
    }* statistics = (struct{}*)malloc((maxElements / 2) * sizeof(struct {}));

    // Initialize arrays
    for(int i = 0; i < maxElements; i++) {
        measurements[i] = (double)i;
        identifiers[i] = "Identifier";
        timestamps[i] = time(NULL);
        events[i].measurement = (double)i;
        events[i].identifier = "Event Identifier";
        events[i].timestamp = time(NULL);

        if(i % 2 == 0) {
            statistics[i/2].min = (int)measurements[i];
            statistics[i/2].max = (int)measurements[i];
            statistics[i/2].average = measurements[i];
        }
    }

    // Read data from standard input
    if(readFromStdin) {
        FILE* file = fopen(sourceString, "r");
        char line[1024];
        int elementCount = 0;

        while(fgets(line, sizeof(line), file)) {
            double measurement;
            sscanf(line, "%lf", &measurement);
            measurements[elementCount] = measurement;
            identifiers[elementCount] = "Identifier";
            timestamps[elementCount] = time(NULL);

            if(elementCount % 2 == 0) {
                statistics[elementCount/2].min = (int)measurement;
                statistics[elementCount/2].max = (int)measurement;
                statistics[elementCount/2].average = measurement;
            }

            elementCount++;
        }

        fclose(file);
    }

    // Calculate average measurement
    double averageMeasurement = 0.0;

    for(int i = 0; i < maxElements; i++) {
        averageMeasurement += measurements[i];
    }

    averageMeasurement /= maxElements;

    printf("Average Measurement: %f\n", averageMeasurement);

    // Print contents of arrays
    if(debugMode) {
        printf("Measurements:\n");
        for(int i = 0; i < maxElements; i++) {
            printf("%f ", measurements[i]);
        }
        printf("\n");

        printf("Identifiers:\n");
        for(int i = 0; i < maxElements; i++) {
            printf("%s ", identifiers[i]);
        }
        printf("\n");

        printf("Timestamps:\n");
        for(int i = 0; i < maxElements; i++) {
            printf("%ld ", timestamps[i]);
        }
        printf("\n");

        printf("Events:\n");
        for(int i = 0; i < maxElements; i++) {
            printf("(%f, %s, %ld) ", events[i].measurement, events[i].identifier, events[i].timestamp);
        }
        printf("\n");

        printf("Statistics:\n");
        for(int i = 0; i < (maxElements / 2); i++) {
            printf("(%d, %d, %f) ", statistics[i].min, statistics[i].max, statistics[i].average);
        }
        printf("\n");
    }

    // Free memory
    free(measurements);
    free(identifiers);
    free(timestamps);
    free(events);
    free(statistics);

    if(readFromStdin) {
        fclose(file);
    }
}

int main() {
    char* sourceString = "source.txt";
    int maxElements = 10;
    int readFromStdin = 1;

    processAndAggregateData(sourceString, maxElements, readFromStdin);

    return 0;
}
