#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define TIMESTAMP_SIZE 1000
#define SENSOR_READING_SIZE 1000
#define SENSOR_DATA_SIZE 5000
#define CACHE_LINE_SIZE 64
#define MAX_ACTIVE_THREADS 8

typedef struct {
    int timestamp;
    float sensor_reading;
} SensorReading;

typedef struct Node {
    SensorReading data;
    struct Node* next;
    struct Node* prev;
} Node;

void initSensorData(Node** head, Node** tail, int num_records) {
    *head = NULL;
    *tail = NULL;
    for (int i = 0; i < num_records; i++) {
        SensorReading data = {i, (float)i};
        Node* node = (Node*)malloc(sizeof(Node));
        node->data = data;
        node->next = NULL;
        node->prev = NULL;

        if (*head == NULL) {
            *head = node;
            *tail = node;
        } else {
            (*tail)->next = node;
            node->prev = *tail;
            *tail = node;
        }
    }
}

void serializeData(Node* head, FILE* file) {
    fwrite(&head, sizeof(Node), 1, file);
    while (head != NULL) {
        SensorReading data = head->data;
        fwrite(&data.timestamp, sizeof(int), 1, file);
        fwrite(&data.sensor_reading, sizeof(float), 1, file);
        Node* next = head->next;
        free(head);
        head = next;
    }
}

void deserializeData(Node** head, FILE* file) {
    Node* node = (Node*)malloc(sizeof(Node));
    fread(&node, sizeof(Node), 1, file);

    *head = node;

    while (fread(&node->data, sizeof(SensorReading), 1, file)) {
        Node* next = (Node*)malloc(sizeof(Node));
        fread(&next->data, sizeof(SensorReading), 1, file);
        node->next = next;
        next->prev = node;
        node = next;
    }
}

void sensorDataInit(int num_records) {
    srand(time(NULL));

    Node* head = NULL;
    Node* tail = NULL;

    initSensorData(&head, &tail, num_records);

    FILE* file = fopen("data.bin", "wb");
    serializeData(head, file);
    fclose(file);

    free(head);
}

int main() {
    int num_records = 1000;
    sensorDataInit(num_records);

    return 0;
}
