#define MAX_STRING_POOL 1024
#define MIN_GROWTH 16
#define SHRINKAGE_THRESHOLD 0.2f
#define ALLOCATE_FLAG 1
#define DEALLOCATE_FLAG 2

typedef struct {
    char* data;
} node;

node* string_pool = NULL;
int pool_size = 0;
int max_pool_size = MAX_STRING_POOL;
int shrinkage_threshold = SHRINKAGE_THRESHOLD * max_pool_size;

void* my_malloc(size_t size) {
    return malloc(size);
}

void my_free(void* ptr) {
    free(ptr);
}

node* add_string_to_pool(char* new_string, int new_length) {
    if (pool_size + new_length > max_pool_size) {
        // Reallocate the pool to accommodate the new string
        node* temp = realloc(string_pool, sizeof(node) * (max_pool_size += MIN_GROWTH));
        if (!temp) return NULL;
        string_pool = temp;
    }

    node* new_node = my_malloc(sizeof(node));
    new_node->data = my_malloc(new_length + 1);
    strcpy(new_node->data, new_string);

    // Update the pool and node references
    if (pool_size > 0) {
        string_pool[pool_size - 1].data = new_node->data;
    }
    pool_size++;

    return new_node;
}

void remove_nodes_from_pool(int start, int end) {
    for (int i = start; i <= end; i++) {
        my_free(string_pool[i].data);
        my_free(&string_pool[i]);
    }
    memmove(string_pool, string_pool + end + 1, (pool_size - end - 1) * sizeof(node));
    pool_size -= end - start + 1;
}

void deallocate_pool(int flag) {
    if (flag == DEALLOCATE_FLAG) {
        remove_nodes_from_pool(0, pool_size - 1);
    }
}
