#define MAX_RECORDS 1000 // Define the maximum number of records
#define RECORD_SIZE sizeof(record) // Size of a record structure
#define TABLE_SIZE 1024 // Define the initial size of the hash table

typedef struct {
    int value; // Store an integer value in each record
} record;

// Define the hash table structure
typedef struct {
    long *offsets;
    int *keys;
    record **records;
} hashtable;

hashtable *create_hashtable(int initial_size) {
    hashtable *table = (hashtable *)malloc(sizeof(hashtable));
    if (!table) return NULL; // Handle memory allocation failure

    table->offsets = (long *)malloc(initial_size * sizeof(long));
    table->keys = (int *)malloc(initial_size * sizeof(int));
    table->records = (record **)malloc(initial_size * sizeof(record *));
    if (!table->offsets || !table->keys || !table->records) {
        free(table->offsets);
        free(table->keys);
        free(table->records);
        return NULL; // Handle memory allocation failure
    }

    table->offsets[0] = 0; // Initialize the first offset
    table->keys[0] = -1; // Initialize the first key
    return table;
}

void insert_hashtable(hashtable *table, int key, record *record) {
    long index = key % TABLE_SIZE; // Calculate the hash value

    if (table->offsets[index] + RECORD_SIZE > table->keys[index]) { // Rehash if necessary
        int new_size = 2 * TABLE_SIZE;
        hashtable *new_table = create_hashtable(new_size);
        memcpy(new_table->offsets, table->offsets, TABLE_SIZE * sizeof(long));
        memcpy(new_table->keys, table->keys, TABLE_SIZE * sizeof(int));
        for (int i = 0; i < TABLE_SIZE; i++) {
            if (table->records[i]) {
                record *tmp = table->records[i];
                int j = i;
                while (new_table->offsets[j] > new_table->keys[j]) j++;
                new_table->keys[j] = key;
                new_table->offsets[j] += RECORD_SIZE;
                new_table->records[j] = tmp;
            }
        }
        free(table);
        table = new_table;
    }

    if (table->offsets[index] + RECORD_SIZE > table->keys[index]) { // Handle collision
        int collision_index = index;
        while (table->offsets[collision_index] + RECORD_SIZE <= table->keys[collision_index]) {
            collision_index = (collision_index + 1) % TABLE_SIZE;
        }
        table->keys[collision_index] = key;
        table->offsets[collision_index] += RECORD_SIZE;
        table->records[collision_index] = record;
    } else {
        table->keys[index] = key;
        table->offsets[index] += RECORD_SIZE;
        table->records[index] = record;
    }
}

void delete_hashtable(hashtable *table, int key) {
    long index = key % TABLE_SIZE; // Calculate the hash value

    if (table->keys[index] == key) { // Key found in the current bucket
        table->offsets[index] -= RECORD_SIZE;
        table->keys[index] = -1;
    } else {
        int collision_index = index;
        while (table->keys[collision_index] != key && table->keys[collision_index] != -1) {
            collision_index = (collision_index + 1) % TABLE_SIZE;
        }
        if (table->keys[collision_index] == key) { // Key found in a collision bucket
            table->offsets[collision_index] -= RECORD_SIZE;
            table->keys[collision_index] = -1;
        } else {
            printf("Key not found!\n");
        }
    }
}

record *lookup_hashtable(hashtable *table, int key) {
    long index = key % TABLE_SIZE; // Calculate the hash value

    if (table->keys[index] == key) { // Key found in the current bucket
        return table->records[index];
    } else {
        int collision_index = index;
        while (table->keys[collision_index] != key && table->keys[collision_index] != -1) {
            collision_index = (collision_index + 1) % TABLE_SIZE;
        }
        if (table->keys[collision_index] == key) { // Key found in a collision bucket
            return table->records[collision_index];
        } else {
            printf("Key not found!\n");
            return NULL; // Return null on key not found
        }
    }
}

int main() {
    srand(time(NULL)); // Initialize random seed

    hashtable *table = create_hashtable(TABLE_SIZE);
    for (int i = 0; i < MAX_RECORDS; i++) {
        record *record = (record *)malloc(RECORD_SIZE);
        record->value = rand() % 100;
        insert_hashtable(table, i, record); // Insert records into the hash table
    }

    record *target_record = lookup_hashtable(table, 5); // Look up a specific key
    if (target_record) {
        printf("Record found! Value: %d\n", target_record->value);
    } else {
        printf("Record not found!\n");
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        record *record = lookup_hashtable(table, i); // Look up all records
        if (record) {
            printf("Record %d: Value = %d\n", i, record->value);
        }
    }

    return 0;
}
