int manage_memory(int n, int m) {
    long* long_integers = NULL;
    int* keys = NULL;
    Record** records = NULL;

    // Step 1: Allocate memory for 'n' long integers and initialize them with sequential values starting from 0
    if ((long_integers = (long*)malloc(n * sizeof(long))) == NULL) {
        printf("Memory allocation failed for long integers.\n");
        return -1;
    }
    for (int i = 0; i < n; i++) {
        long_integers[i] = i;
    }

    // Step 2: Allocate memory for 'm' int keys, initializing each key with a unique value between 1 and 1000
    if ((keys = (int*)malloc(m * sizeof(int))) == NULL) {
        printf("Memory allocation failed for keys.\n");
        free(long_integers);
        return -1;
    }
    srand(time(NULL));
    for (int i = 0; i < m; i++) {
        keys[i] = rand() % 1000 + 1;
    }

    // Step 3: Allocate memory for an array of 'Record', and initialize each Record with a random value within the specified range
    if ((records = (Record**)malloc(m * sizeof(Record*))) == NULL) {
        printf("Memory allocation failed for Records.\n");
        free(long_integers);
        free(keys);
        return -1;
    }
    for (int i = 0; i < m; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (records[i] == NULL) {
            printf("Memory allocation failed for Records.\n");
            for (int j = 0; j < i; j++) {
                free(records[j]->offset);
                free(records[j]);
            }
            free(long_integers);
            free(keys);
            return -1;
        }
        records[i]->value = rand() % 100 + 1;
        records[i]->offset = &long_integers[records[i]->value];
    }

    // Return the total number of successfully allocated 'Record' structures
    int record_count = m;
    free(long_integers);
    for (int i = 0; i < m; i++) {
        free(keys + i);
    }
    return record_count;
}
