#include <string.h>
#include <pthread.h>

typedef struct {
    char* data;
} node;

node* string_pool = NULL;
size_t pool_size = 0;
size_t max_pool_size = 1000000; // adjust this as needed
int unique_strings_limit = 50000; // adjust this as needed

// thread-safe lock for accessing the string pool
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

node* add_string_to_pool(const char* str) {
    pthread_mutex_lock(&pool_lock);

    // check if the string already exists in the pool
    node* current_node = string_pool;
    while (current_node != NULL) {
        if (strcmp(current_node->data, str) == 0) {
            pthread_mutex_unlock(&pool_lock);
            return current_node; // reuse existing string
        }
        current_node = current_node->next;
    }

    // create a new node for the string and add it to the pool
    node* new_node = (node*)malloc(sizeof(node));
    if (new_node == NULL) {
        pthread_mutex_unlock(&pool_lock);
        return NULL; // out of memory
    }
    new_node->data = strdup(str);

    if (string_pool == NULL || pool_size >= max_pool_size - 1) { // adjust the condition as needed for memory management
        // add a new node to the beginning of the list
        new_node->next = string_pool;
        string_pool = new_node;
    } else {
        // append the new node to the end of the list
        node* current_node = string_pool;
        while (current_node->next != NULL) {
            current_node = current_node->next;
        }
        current_node->next = new_node;
    }

    pool_size++;

    pthread_mutex_unlock(&pool_lock);
    return new_node;
}

void update_string_reference(node* node, const char* str) {
    pthread_mutex_lock(&pool_lock);

    // find the string in the pool and update its reference
    node* current_node = string_pool;
    while (current_node != NULL) {
        if (strcmp(current_node->data, str) == 0) {
            current_node->next = node; // update the reference
            pthread_mutex_unlock(&pool_lock);
            return;
        }
        current_node = current_node->next;
    }

    pthread_mutex_unlock(&pool_lock);
}

void free_string_pool() {
    pthread_mutex_lock(&pool_lock);

    node* current_node = string_pool;
    node* next_node = NULL;

    while (current_node != NULL) {
        next_node = current_node->next;
        free(current_node->data); // free the string
        free(current_node); // free the node
        current_node = next_node;
    }

    pool_size = 0; // reset the pool size

    pthread_mutex_unlock(&pool_lock);
}
