['```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* data;
} node_t;

node_t* string_pool = NULL;
size_t pool_size = 0;
size_t max_pool_size = 1024; // initial maximum size
size_t min_pool_size = 64; // minimum shrinkage limit

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* string_allocate(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        LOG_ERROR("Memory allocation failed");
        return NULL;
    }
    return ptr;
}

void string_free(void* ptr, size_t size) {
    free(ptr);
}

node_t* node_new(char* str) {
    node_t* node = string_allocate(sizeof(node_t));
    if (!node) {
        return NULL;
    }
    node->data = str;
    return node;
}

int pool_grow(size_t new_size) {
    if (new_size > max_pool_size || new_size < min_pool_size) {
        LOG_ERROR("Invalid growth/shrinkage limit");
        return -1;
    }
    size_t diff = new_size - pool_size;
    char** new_strings = string_allocate((diff + 1) * sizeof(char*));
    if (!new_strings) {
        return -1;
    }
    // copy existing strings
    for (size_t i = 0; i < pool_size; i++) {
        new_strings[i] = string_pool[i].data;
    }
    // reallocate the pool
    free(string_pool);
    string_pool = new_strings;
    pool_size = new_size;
    return 0;
}

int pool_shrink(size_t new_size) {
    if (new_size > pool_size || new_size < min_pool_size) {
        LOG_ERROR("Invalid shrinkage limit");
        return -1;
    }
    size_t diff = pool_size - new_size;
    char** old_strings = string_pool + new_size;
    for (size_t i = 0; i < diff; i++) {
        string_free(old_strings[i], strlen(old_strings[i]) + 1);
    }
    free(old_strings);
    pool_size = new_size;
    return 0;
}

int add_node(node_t* node) {
    pthread_mutex_lock(&lock);
    // grow the pool if necessary
    if (pool_size >= max_pool_size * 2 && max_pool_size < INT_MAX / sizeof(char*)) {
        size_t new_max = max_pool_size * 2;
        if (pool_grow(new_max)) {
            LOG_ERROR("Pool growth failed");
            return -1;
        }
        max_pool_size = new_max;
    }
    // add the node to the pool
    string_pool[pool_size] = node->data;
    pool_size++;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);
    return 0;
}

void remove_node(node_t* node) {
    pthread_mutex_lock(&lock);
    // shrink the pool if necessary
    if (pool_size < min_pool_size * 2) {
        size_t new_min = min_pool_size / 2;
        if (pool_shrink(new_min)) {
            LOG_ERROR("Pool shrinkage failed");
        }
        min_pool_size = new_min;
    }
    // remove the node from the pool
    for (size_t i = 0; i < pool_size - 1; i++) {
        string_pool[i] = string_pool[i + 1];
    }
    pool_size--;
    pthread_mutex_unlock(&lock);
}

void log_memory_metrics() {
    LOG_INFO("Memory usage: %zu/%zu (%.2f%%)", pool_size * sizeof(node_t) + pool_size * strlen(string_pool[0].data), max_pool_size * sizeof(char*));
}
