    for (int i = 0; i <= m; i++) {
        records[i].key = rand() % (100000 - 1) + 1;
        if (records[i].key > 100000)
            records[i].key -= 100000;
        records[i].ptr = &longs[records[i].key];
    }

    return records;
}

