#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* key;
    int value;
} kvpair_t;

typedef struct {
    size_t capacity;
    size_t size;
    float load_factor;
    int** table;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} hash_table_t;

hash_table_t* create_hash_table(size_t initial_capacity, float load_factor) {
    hash_table_t* ht = (hash_table_t*)malloc(sizeof(hash_table_t));
    ht->capacity = initial_capacity;
    ht->size = 0;
    ht->load_factor = load_factor;
    ht->table = (int**)calloc(initial_capacity, sizeof(int*));
    pthread_mutex_init(&ht->lock, NULL);
    pthread_cond_init(&ht->cond, NULL);
    return ht;
}

void insert_hash_table(hash_table_t* ht, char* key, int value) {
    size_t index = hash(key) % ht->capacity;
    while (ht->table[index] != NULL && strcmp(ht->table[index]->key, key) != 0) {
        index = (index + 1) % ht->capacity;
    }
    if (ht->table[index] == NULL || strcmp(ht->table[index]->key, key) != 0) {
        ht->table[index] = (int*)malloc(sizeof(int));
        ht->table[index]->key = strdup(key);
        ht->table[index]->value = value;
        ht->size++;
    }
}

int get_hash_table_value(hash_table_t* ht, char* key) {
    size_t index = hash(key) % ht->capacity;
    while (ht->table[index] != NULL && strcmp(ht->table[index]->key, key) != 0) {
        index = (index + 1) % ht->capacity;
    }
    if (ht->table[index] == NULL || strcmp(ht->table[index]->key, key) != 0) {
        return -1; // not found
    }
    return ht->table[index]->value;
}

void* iterate_hash_table(void* arg) {
    hash_table_t* ht = (hash_table_t*)arg;
    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->table[i] != NULL) {
            printf("%s: %d\n", ht->table[i]->key, ht->table[i]->value);
        }
    }
    return NULL;
}

void free_hash_table(hash_table_t* ht) {
    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->table[i] != NULL) {
            free(ht->table[i]->key);
            free(ht->table[i]);
        }
    }
    free(ht->table);
    free(ht);
}

int main() {
    hash_table_t* ht = create_hash_table(16, 0.7f);
    insert_hash_table(ht, "hello", 42);
    insert_hash_table(ht, "world", 21);
    printf("%d\n", get_hash_table_value(ht, "hello"));
    pthread_t thread;
    pthread_create(&thread, NULL, iterate_hash_table, ht);
    pthread_join(thread, NULL);
    free_hash_table(ht);
    return 0;
}
