    printf("\n");
    printf("InputInts array: ");
    for (int i = 0; i < MAX_INPUTS; i++) {
        printf("%d ", inputInts[i]);
    }
    printf("\n");

    // Find and print the largest integer in record and inputInts arrays
    int max_record = findMax(&record, record_size);
    int max_inputInts = findMax(inputInts, MAX_INPUTS);

    printf("Largest integer in record array: %d\n", max_record);
    printf("Largest integer in inputInts array: %d\n", max_inputInts);

    // Free allocated memory
    free(offset);
    free(key);
    free(record);
    free(inputInts);
}

int findMax(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
