#define MEMORY_POOL_SIZE 1024

typedef struct {
    int key;
    char *buffer;
} Record;

typedef struct _hash_table {
    int size;
    Record **buckets;
    int memory_pool_size;
} HashTable;

HashTable *create_hash_table(int initial_size) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->size = initial_size;
    table->memory_pool_size = MEMORY_POOL_SIZE;
    table->buckets = (Record **)calloc(table->size, sizeof(Record *));
    return table;
}

void free_hash_table(HashTable *table) {
    for (int i = 0; i < table->size; i++) {
        if (table->buckets[i] != NULL) {
            Record *record = table->buckets[i];
            while (record != NULL) {
                Record *next = record->buffer;
                free(record->buffer);
                free(record);
                record = next;
            }
        }
    }
    free(table->buckets);
    free(table);
}

int hash_function(int key, int table_size) {
    return key % table_size;
}

void insert_record(HashTable *table, Record *record) {
    int index = hash_function(record->key, table->size);
    record->buffer = (char *)malloc(MEMORY_POOL_SIZE);
    if (table->buckets[index] == NULL) {
        table->buckets[index] = record;
    } else {
        Record *prev = table->buckets[index];
        while (prev->next != NULL) prev = prev->next;
        prev->next = record;
    }
}

Record *remove_record(HashTable *table, int key) {
    int index = hash_function(key, table->size);
    for (Record **p = &table->buckets[index]; *p != NULL; p = &(*p)->next) {
        if ((*p)->key == key) {
            Record *record = *p;
            *p = (*p)->next;
            free(record->buffer);
            free(record);
            return record;
        }
    }
    return NULL;
}

void iterate_records(HashTable *table, void (*callback)(Record *)) {
    for (int i = 0; i < table->size; i++) {
        Record *record = table->buckets[i];
        while (record != NULL) {
            callback(record);
            record = record->next;
        }
    }
}

void monitor_and_log(HashTable *table, int *collisions, long *memory_usage) {
