    if (!tasks) {
        printf("Error allocating memory for task array\n");
        return NULL;
    }

    for (int i = 0; i < numTasks; i++) {
        tasks[i] = (Task*)malloc(sizeof(Task));
        if (!tasks[i]) {
            printf("Error allocating memory for task %d\n", i);
            // Free previously allocated memory
            for (int j = 0; j < i; j++)
                free(tasks[j]);
            free(tasks);
            return NULL;
        }

        tasks[i]->name = strdup("Task Name"); // Initialize name with default value
        tasks[i]->priority = 1;
        tasks[i]->status = PENDING;
    }

    return tasks;
}

void addTask(Task** tasks, int taskIndex) {
    if (taskIndex >= 0 && taskIndex < strlen(tasks)) {
        tasks[taskIndex] = (Task*)malloc(sizeof(Task));
        if (!tasks[taskIndex]) {
            printf("Error allocating memory for task\n");
            // Free previously allocated memory
            for (int i = 0; i <= taskIndex; i++)
                free(tasks[i]);
            free(tasks);
            return;
        }

        tasks[taskIndex]->name = strdup("New Task Name"); 
        tasks[taskIndex]->priority = 1;
        tasks[taskIndex]->status = PENDING;
    }
}

void updateTaskStatus(Task** tasks, int taskIndex) {
    if (taskIndex >= 0 && taskIndex < strlen(tasks)) {
        tasks[taskIndex]->status = (tasks[taskIndex]->priority > 3) ? COMPLETED : IN_PROGRESS;
    }
}

void displayTasks(Task** tasks, int numTasks) {
    for (int i = 0; i < numTasks; i++) {
        printf("Task %d: Name - %s, Priority - %d, Status - %s\n", 
               i+1, tasks[i]->name, tasks[i]->priority, 
               ((tasks[i]->status == PENDING) ? "Pending" : 
                ((tasks[i]->status == IN_PROGRESS) ? "In Progress" : "Completed")));
    }
}

void freeTasks(Task** tasks, int numTasks) {
    for (int i = 0; i < numTasks; i++) {
        free(tasks[i]->name);
        free(tasks[i]);
    }
    free(tasks);
}
