#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum { PHASE_INIT, PHASE_PROGRESS, PHASE_COMPLETE } Phase;

struct Project {
    char* title;
    float budget;
    struct tm deadline;
    Phase phase;
};

void initProjectList(struct Project** projects) {
    *projects = NULL;
}

int addProject(struct Project** projects, const char* title, float budget, const struct tm* deadline, Phase phase) {
    struct Project* newProject = malloc(sizeof(struct Project));
    if (!newProject) return -1; // allocation failed

    size_t titleLen = strlen(title);
    newProject->title = malloc(titleLen + 1);
    if (!newProject->title) {
        free(newProject);
        return -2; // memory allocation for title failed
    }
    strcpy(newProject->title, title);

    newProject->budget = budget;
    *newProject->deadline = *deadline;
    newProject->phase = phase;

    struct Project* currentHead = *projects;
    if (!currentHead) {
        *projects = newProject;
    } else {
        while (currentHead->next) currentHead = currentHead->next;
        currentHead->next = newProject;
    }
    return 0; // success
}

void updatePhase(struct Project** projects) {
    struct Project* currProj = *projects;
    while (currProj) {
        time_t deadlineTime = mktime(&currProj->deadline);
        time_t now = time(NULL);
        if ((now - deadlineTime) <= 86400) { // within a day of deadline
            currProj->phase = PHASE_PROGRESS;
        } else if ((now - deadlineTime) > 604800) { // more than a week past deadline
            currProj->phase = PHASE_COMPLETE;
        }
        currProj = currProj->next;
    }
}

void freeProjectList(struct Project** projects) {
    struct Project* currProj = *projects;
    struct Project* nextProj;

    while (currProj) {
        nextProj = currProj->next;
        free(currProj->title);
        free(currProj);
        currProj = nextProj;
    }
    *projects = NULL;
}

int main() {
    // Example usage:
    struct Project* projectList = NULL;
    int ret = addProject(&projectList, "Project 1", 100000.0f, (struct tm){2023, 2, 15, 12, 0, 0}, PHASE_INIT);
    if (ret) printf("Error adding project: %d\n", ret);

    // Update phase of all projects
    updatePhase(&projectList);

    // Free allocated memory
    freeProjectList(&projectList);

    return 0;
}
