#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    char* name;
    int priority;
    enum status { PENDING, IN_PROGRESS, COMPLETED } status;
    struct Task** dependencies;
} Task;

void manageTasks(int numTasks) {
    Task** tasks = (Task**)malloc(numTasks * sizeof(Task*));
    for (int i = 0; i < numTasks; i++) {
        tasks[i] = (Task*)malloc(sizeof(Task));
        // Initialize task fields
        strcpy(tasks[i]->name, "Task ");
        tasks[i]->priority = i;
        tasks[i]->status = PENDING;
        tasks[i]->dependencies = NULL;
    }

    // Add new tasks
    void addTask(char* name) {
        Task* newTask = (Task*)malloc(sizeof(Task));
        strcpy(newTask->name, name);
        newTask->priority = numTasks++;
        newTask->status = PENDING;
        newTask->dependencies = NULL;
        for (int i = 0; i < numTasks - 1; i++) {
            if (tasks[i]->status == COMPLETED) {
                tasks[i]->dependencies = appendDependency(tasks[i], newTask);
            }
        }
    }

    // Update task status based on priority and dependencies
    void updateStatus() {
        for (int i = 0; i < numTasks; i++) {
            if (tasks[i]->status == PENDING && tasks[i]->priority > 0) {
                tasks[i]->status = IN_PROGRESS;
            } else if (tasks[i]->status == IN_PROGRESS && tasks[i]->dependencies != NULL) {
                tasks[i]->status = COMPLETED;
            }
        }
    }

    // Display task details
    void displayTasks() {
        for (int i = 0; i < numTasks; i++) {
            printf("Task %d: Name - %s, Priority - %d, Status - %s\n", i + 1, tasks[i]->name, tasks[i]->priority, enumToString(tasks[i]->status));
        }
    }

    // Helper function to copy task name
    void copyName(Task* task) {
        task->name = (char*)malloc(strlen(task->name) + 1);
        strcpy(task->name, task->name);
    }

    free(tasks);
}

int main() {
    manageTasks(5);
    addTask("New Task");
    updateStatus();
    displayTasks();
    return 0;
}
