    free(keys);
    free(records);
    free(weights);
    free(inputInts);
}

int findMaxValue(int* array, int size) {
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

double calculateWeightedAverage(struct { int value; }* records, double* weights, int recordSize) {
    double sum = 0.0;
    for (int i = 0; i < recordSize; i++) {
        sum += records[i].value * weights[i];
    }
    return sum / recordSize;
}
