#define RECORDS_MAX 1024
#define STATUS_SUCCESS 0
#define STATUS_FAILURE 1
#define VERBOSE_LOGGING 1
#define SILENT_LOGGING 0

typedef struct {
    int value;
} record;

record* create_collection(int num_records, int min_key, int max_key) {
    int i;
    srand(time(NULL));

    // Create a new collection with 'num_records' elements
    record* collection = (record*)malloc(sizeof(record)*num_records);
    if (!collection) return NULL; // Error: memory allocation failed

    for (i=0; i<num_records; i++) {
        record r;
        r.value = min_key + rand() % (max_key - min_key + 1);
        collection[i] = r;
    }

    return collection;
}

void serialize_collection(record* collection, FILE* file) {
    // Serialize the state of the 'collection' array
    fwrite(&collection->value, sizeof(int), RECORDS_MAX, file);
}
