        log_error("Invalid offset size");
        return;
    }
    if (record_size < 1 || record_size > MAX_RECORD_SIZE) {
        log_error("Invalid record size");
        return;
    }

    // Dynamically allocate memory for arrays
    int* key_array_ptr = malloc(offset_size * sizeof(int));
    if (!key_array_ptr) {
        log_error("Failed to allocate memory for 'key' array");
        return;
    }
    *key_array = key_array_ptr;

    record_array = (int*)malloc(record_size * sizeof(int));
    if (!record_array) {
        log_error("Failed to allocate memory for 'record' array");
        free(key_array_ptr);
        return;
    }

    // Initialize 'offset' and 'key' arrays
    for (int i = 0; i < offset_size; i++) {
        key_array[i] = i;
    }
    for (int i = 0; i < record_size; i++) {
        record_array[i] = random_integer_range(1, MAX_RECORD_VALUE);
    }

    // Initialize linked list
    struct node* head = NULL;
    for (int i = 0; i < record_size; i++) {
        struct node* new_node = malloc(sizeof(struct node));
        new_node->key = record_array[i];
        new_node->record = &record_array[i];
        if (!head) {
            head = new_node;
        } else {
            struct node* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_node;
        }
    }

    // Handle potential integer overflow
    if (record_array[0] > INT_MAX / 2) {
        log_warning("Potential integer overflow detected");
    }

    // Clean up memory management library
    if (finalize_memory_management() != 0) {
        log_error("Failed to finalize memory management library");
    }
}
