#include "log_handler/log_handler.h"

#define MAX_EVENTS 1000

typedef struct {
    char* logLevel;
    time_t timestamp;
} Log;

typedef struct {
    char message[256];
    int severity;
} EventDetails;

void processAndSendLogs(int numEvents, const char** messages, int* severities) {
    if (numEvents > MAX_EVENTS) {
        printf("Error: Exceeded maximum number of events.\n");
        return;
    }

    Log* log = malloc(sizeof(Log));
    if (!log) {
        printf("Error: Failed to allocate memory for log structure.\n");
        return;
    }
    log->logLevel = "INFO";
    log->timestamp = time(NULL);

    EventDetails** eventDetails = malloc(numEvents * sizeof(EventDetails*));
    if (!eventDetails) {
        free(log);
        printf("Error: Failed to allocate memory for event details structures.\n");
        return;
    }

    for (int i = 0; i < numEvents; i++) {
        EventDetails* detail = malloc(sizeof(EventDetails));
        if (!detail) {
            for (int j = 0; j < i; j++) {
                free(eventDetails[j]);
            }
            free(eventDetails);
            free(log);
            printf("Error: Failed to allocate memory for event details.\n");
            return;
        }
        strcpy(detail->message, messages[i]);
        detail->severity = severities[i];
        eventDetails[i] = detail;
    }

    // Print log contents for debugging
    printf("Log Level: %s\n", log->logLevel);
    printf("Timestamp: %ld\n", log->timestamp);

    for (int i = 0; i < numEvents; i++) {
        printf("Event Details:\n");
        printf("Message: %s\n", eventDetails[i]->message);
        printf("Severity: %d\n", eventDetails[i]->severity);
    }

    // Free allocated memory
    for (int i = 0; i < numEvents; i++) {
        free(eventDetails[i]);
    }
    free(eventDetails);
    free(log);

    // Export log data to JSON format and send to external logging service endpoint
    char* jsonData = json_util_serialize_event_log(numEvents, eventDetails);
    if (jsonData) {
        // Send JSON data via HTTPS POST to the logging service endpoint
        int result = send_json_to_logging_service(jsonData);
        free(jsonData);

        if (result != 0) {
            printf("Error: Failed to send log data to the logging service.\n");
        }
    } else {
        printf("Error: Failed to generate JSON log data.\n");
    }

    // Log processing metrics
    log_handler_log_metric("Processing Time", 0.5);
    log_handler_log_metric("Memory Usage", 100);

    if (log_handler_get_verbosity() > 1) {
        // Print detailed logs for debugging
        printf("Timestamp: %ld\n", time(NULL));
        printf("Function Call: processAndSendLogs\n");
        printf("Metrics:\n");
        printf("Processing Time: 0.5 seconds\n");
        printf("Memory Usage: 100%\n");
    }
}
