record_t* initialize_records(int limit, size_t count) {
    record_t* records = NULL;
    int total_value = 0;

    while (total_value <= limit) {
        records = realloc(records, (count + 1) * sizeof(record_t));
        if (!records) return NULL; // Handle memory allocation failure

        for (size_t i = 0; i < count; i++) {
            record_t* record = &records[i];
            record->value = /* calculate value */;
            record->offset = /* allocate and initialize offset */;
            record->key = /* allocate and initialize key */;
            total_value += record->value;
        }

        return records;
    }

    // If the limit is exceeded, re-calculate values until the condition is met
    while (total_value > limit) {
        for (size_t i = 0; i < count; i++) {
            record_t* record = &records[i];
            record->value -= total_value - limit;
            if (record->value <= 0) {
                free(record->offset);
                free(record->key);
                memmove(&records[i], &records[i + 1], sizeof(record_t) * (count - i));
                count--;
                break;
            }
        }
    }

    return records;
}
