["Here is the C code for managing and initializing an array of 'record' structures:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
    int* offset;
    char* key;
} record_t;

void initialize_records(record_t** records, size_t num_records, int max_sum) {
    // Initialize records array
    *records = (record_t*)malloc(num_records * sizeof(record_t));

    for(size_t i = 0; i < num_records; i++) {
        (*records)[i].value = 0;
        (*records)[i].offset = NULL;
        (*records)[i].key = NULL;
    }

    // Calculate sum of record values
    int total_sum = 0;
    for(size_t i = 0; i < num_records; i++) {
        total_sum += (*records)[i].value;
    }

    while(total_sum > max_sum) {
        // Recalculate record values until the condition is met
        for(size_t i = 0; i < num_records; i++) {
            (*records)[i].value /= 2;
            total_sum -= (*records)[i].value;
        }
    }
}

void adjust_max_sum(int* max_sum, int load_metrics) {
    // Adjust maximum allowed sum based on real-time load metrics
    *max_sum = *max_sum - (load_metrics / 10);

    if(*max_sum < 0) {
        *max_sum = 0;
    }
}

int main() {
    size_t num_records = 1000;
    int max_sum = 10000;

    record_t* records = NULL;
    initialize_records(&records, num_records, max_sum);

    // Example usage: Adjust maximum allowed sum based on load metrics
    adjust_max_sum(&max_sum, 80);

    free(records);

    return 0;
}
