        if (feof(stdin)) break;
        measurement_size++;
        measurements = realloc(measurements, sizeof(Measurement) * (measurement_size + 1));
        measurements[measurement_size - 1] = measurement;
    }

    // Calculate and print the average measurement
    calculateAverage(measurements, measurement_size);

    // Deallocate memory
    free(measurements);
