#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

typedef struct {
    int offset;
    double key;
    double record;
} Record;

Record* initializeDataStructure(int capacity) {
    Record* records = (Record*) malloc(capacity * sizeof(Record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < capacity; i++) {
        // Set record values to random numbers within a specified range
        records[i].offset = i;
        records[i].key = (double) rand() / RAND_MAX;
        double value;
        do {
            value = (double) rand() / RAND_MAX * 100.0; // Random value between 0 and 100
        } while (value > 50); // Ensure the total sum does not exceed a specified maximum threshold
        records[i].record = value;
    }

    return records;
}

void finalizeDataStructure(Record* records, int capacity) {
    if (!records)
        return;

    free(records);
}

int serializeDataStructure(Record* records, int capacity, FILE* file) {
    // Serialize the initialized data structure into a binary format
    fwrite(&capacity, sizeof(int), 1, file); // Write the capacity of the data structure
    for (int i = 0; i < capacity; i++) {
        fwrite(&(records[i]), sizeof(Record), 1, file); // Write each record to the file
    }

    return 0;
}

int deserializeDataStructure(FILE* file, Record** records) {
    int capacity;
    fread(&capacity, sizeof(int), 1, file); // Read the capacity of the data structure from the file

    *records = (Record*) malloc(capacity * sizeof(Record));
    if (!(*records)) {
        printf("Memory allocation failed.\n");
        return -1; // Error: memory allocation failure
    }

    for (int i = 0; i < capacity; i++) {
        fread(&((*records)[i]), sizeof(Record), 1, file); // Read each record from the file
    }

    return 0;
}

void printRecords(Record* records, int capacity) {
    for (int i = 0; i < capacity; i++) {
        printf("Offset: %d, Key: %.2f, Record: %.2f\n", records[i].offset, records[i].key, records[i].record);
    }
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int capacity = 10; // Initialize with a capacity of 10
    Record* records = initializeDataStructure(capacity);

    if (!records) {
        printf("Initialization failed.\n");
        return -1; // Error: initialization failure
    }

    printRecords(records, capacity); // Print the initialized data structure

    FILE* file = fopen("data.bin", "wb"); // Open a binary file for serialization
    serializeDataStructure(records, capacity, file);
    fclose(file);

    Record* deserializedRecords;
    int result = deserializeDataStructure(fopen("data.bin", "rb"), &deserializedRecords); // Deserialize the data structure from the file
    if (result < 0) {
        printf("Deserialization failed.\n");
        return -1; // Error: deserialization failure
    }

    printRecords(deserializedRecords, capacity);

    finalizeDataStructure(records, capacity);
    free(deserializedRecords);

    return 0;
}
