    int value;
};

struct event {
    time_t timestamp;
    event_type type;
};

void initialize_data_structures() {
    // Initialize offset array with values 0 to 999
    long* offsets = (long*)malloc(OFFSET_ARRAY_SIZE * sizeof(long));
    for (int i = 0; i < OFFSET_ARRAY_SIZE; i++) {
        offsets[i] = i;
    }

    // Initialize key array with values 1 to 99
    int* keys = (int*)malloc(KEY_ARRAY_SIZE * sizeof(int));
    for (int i = 0; i < KEY_ARRAY_SIZE; i++) {
        keys[i] = i + 1;
    }

    // Populate record array with random integers
    struct record* records = (struct record*)malloc(RECORD_ARRAY_SIZE * sizeof(struct record));
    srand(time(NULL));
    for (int i = 0; i < RECORD_ARRAY_SIZE; i++) {
        records[i].value = rand() % 100;
    }

    // Initialize event array with random timestamps and event types
    struct event* events = (struct event*)malloc(EVENT_ARRAY_SIZE * sizeof(struct event));
    srand(time(NULL));
    for (int i = 0; i < EVENT_ARRAY_SIZE; i++) {
        time_t timestamp = time(NULL) + i;
        event_type type = rand() % 3;
        events[i].timestamp = timestamp;
        events[i].type = type;
    }

    // Clean up memory
    free(offsets);
    free(keys);
    free(records);
    free(events);

    // Print data structures for verification (debug mode)
    printf("Offsets: ");
    for (int i = 0; i < OFFSET_ARRAY_SIZE; i++) {
        printf("%ld ", offsets[i]);
    }
    printf("\n");
    printf("Keys: ");
    for (int i = 0; i < KEY_ARRAY_SIZE; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");
    printf("Records: ");
    for (int i = 0; i < RECORD_ARRAY_SIZE; i++) {
        printf("%d ", records[i].value);
    }
    printf("\n");
    printf("Events: ");
    for (int i = 0; i < EVENT_ARRAY_SIZE; i++) {
        printf("%ld %s\n", events[i].timestamp, type_to_string(events[i].type));
    }

    // Validate event structures
    for (int i = 0; i < EVENT_ARRAY_SIZE; i++) {
        if (events[i].timestamp > time(NULL)) {
            printf("Invalid timestamp at index %d!\n", i);
        }
    }
}

void* type_to_string(event_type type) {
    switch (type) {
        case TYPE_A:
            return "Type A";
        case TYPE_B:
            return "Type B";
        case TYPE_C:
            return "Type C";
        default:
            return NULL;
    }
}
