#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    double value;
} Entry;

typedef struct {
    Entry* entries;
    int count;
    int capacity;
} DynamicList;

DynamicList* dynamicListCreate(int initialCapacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->entries = (Entry*)calloc(initialCapacity, sizeof(Entry));
    if (!list->entries) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initialCapacity;

    return list;
}

void dynamicListDestroy(DynamicList* list) {
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].key) free(list->entries[i].key);
    }

    free(list->entries);
    free(list);
}

Entry* dynamicListGet(DynamicList* list, char* key) {
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->entries[i].key, key) == 0)
            return &list->entries[i];
    }

    return NULL;
}

void dynamicListAdd(DynamicList* list, Entry newEntry) {
    if (list->count >= list->capacity * 2) {
        int newSize = list->capacity * 2;
        Entry* newEntries = (Entry*)realloc(list->entries, newSize * sizeof(Entry));
        if (!newEntries) return;

        list->entries = newEntries;
        list->capacity = newSize;
    }

    list->entries[list->count] = newEntry;
    list->count++;
}

void dynamicListUpdate(DynamicList* list, char* key, double newValue) {
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->entries[i].key, key) == 0) {
            list->entries[i].value = newValue;
            return;
        }
    }
}

void dynamicListClear(DynamicList* list) {
    for (int i = 0; i < list->count; i++) {
        if (list->entries[i].key) free(list->entries[i].key);
    }

    list->count = 0;
}

// Example usage:
int main() {
    DynamicList* myList = dynamicListCreate(10);

    Entry newEntry1 = {"A", 2.5};
    Entry newEntry2 = {"B", 3.8};
    Entry newEntry3 = {"C", 4.2};

    dynamicListAdd(myList, newEntry1);
    dynamicListAdd(myList, newEntry2);
    dynamicListAdd(myList, newEntry3);

    Entry* entry = dynamicListGet(myList, "A");
    if (entry) printf("Value for key 'A' is: %.2f\n", entry->value);

    dynamicListUpdate(myList, "B", 5.1);
    entry = dynamicListGet(myList, "B");
    if (entry) printf("Updated value for key 'B' is: %.2f\n", entry->value);

    dynamicListClear(myList);
    return 0;
}
