typedef struct {
    int protocol;
    int size;
} Packet;

Packet* create_packet(int size) {
    Packet* packet = (Packet*)malloc(sizeof(Packet));
    if (!packet) return NULL; // Handle allocation failure
    packet->protocol = rand() % 2; // Randomly select protocol type
    packet->size = rand() % 1501; // Randomly generate payload size
    return packet;
}

void* manage_packets(void* arg) {
    int num_packets = *(int*)arg;
    Packet** packets = (Packet**)malloc(num_packets * sizeof(Packet*));
    if (!packets) return NULL; // Handle allocation failure

    for (int i = 0; i < num_packets; i++) {
        packets[i] = create_packet(1500); // Allocate packet with random size
    }

    // Add synchronization mechanism to handle concurrent access
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    for (int i = 0; i < num_packets; i++) {
        pthread_mutex_lock(&lock);
        printf("Packet %d: protocol=%d, size=%d\n", i, packets[i]->protocol, packets[i]->size);
        pthread_mutex_unlock(&lock);
    }

    // Free allocated memory
    for (int i = 0; i < num_packets; i++) {
        free(packets[i]);
    }
    free(packets);

    return NULL;
}

int main() {
    int num_packets = 10;
    pthread_t threads[num_packets];
    int* packet_counts = (int*)malloc(num_packets * sizeof(int));

    for (int i = 0; i < num_packets; i++) {
        packet_counts[i] = i + 1;
        pthread_create(&threads[i], NULL, manage_packets, &packet_counts[i]);
    }

    // Wait for all threads to complete
    for (int i = 0; i < num_packets; i++) {
        pthread_join(threads[i], NULL);
    }

    free(packet_counts);

    return 0;
}
