#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} Record;

Record** allocateRecords(int initialSize, int maxSize) {
    Record** records = (Record**)malloc(initialSize * sizeof(Record*));
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < initialSize; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            free(records);
            return NULL;
        }
    }

    return records;
}

void resizeRecords(Record** records, int newSize, Record** oldRecords) {
    Record** newRecords = allocateRecords(newSize, newSize);
    if (newRecords == NULL) {
        // Handle allocation failure
        printf("Failed to allocate memory for resizing.\n");
        free(oldRecords);
        return;
    }

    for (int i = 0; i < newSize && i < oldRecords[0]->value; i++) {
        newRecords[i] = oldRecords[i];
    }

    for (int i = 0; i < oldRecords[0]->value; i++) {
        free(oldRecords[i]);
    }

    free(oldRecords);
    *records = newRecords;
}

