FileMetadata** file_metadata_array_init(int initial_size, int max_size) {
    FileMetadata** array = (FileMetadata**)malloc(initial_size * sizeof(FileMetadata*));
    if (!array) {
        printf("Memory allocation failed for initial array.\n");
        return NULL;
    }

    for (int i = 0; i < initial_size; i++) {
        array[i] = (FileMetadata*)malloc(sizeof(FileMetadata));
        if (!array[i]) {
            printf("Memory allocation failed for file metadata %d.\n", i);
            for (int j = 0; j < i; j++)
                free(array[j]);
            free(array);
            return NULL;
        }
    }

    array[initial_size] = NULL; // sentinel value to indicate end of array

    return array;
}

void file_metadata_array_resize(FileMetadata** array, int new_capacity) {
    FileMetadata** new_array = (FileMetadata**)realloc(array, new_capacity * sizeof(FileMetadata*));
    if (!new_array) {
        printf("Memory allocation failed for resized array.\n");
        return;
    }

    for (int i = new_capacity; i > 0; i--) {
        new_array[i] = NULL;
        for (int j = initial_size; j > i; j--) {
            new_array[j - 1] = array[j];
            free(array[j]);
        }
    }

    for (int i = 0; i < initial_size; i++)
        free(array[i]);

    free(array);

    array = new_array;
}

FileMetadata** file_metadata_array_free(FileMetadata** array) {
    for (int i = 0; i < initial_size; i++) {
        free(array[i]);
    }

    free(array);

    return NULL;
}
