    // Initialize arrays with specific values
    for(int i=0; i<max_offset; i++) {
        data->offsets[i] = i;
    }
    for(int i=0; i<max_key; i++) {
        data->keys[i] = i;
    }
    for(int i=0; i<(max_offset/2); i++) {
        record_t r = {rand() % 100};
        data->records[i] = r;
    }
    for(int i=0; i<max_key; i++) {
