        if(data->dependencies[i] == NULL) {
            printf("Error: Dependency at index %d is null.\n", i);
            return;
        }
    }

    // Print contents of all structures (debug)
    int level = 1;
    print_data_structures(level, data);

    // Deallocate memory
    deallocate_memory(data);
}

void deallocate_memory(data_structures_t *data) {
    free(data->offsets);
    free(data->keys);
    free(data->records);
    free(data->metadata);
    free(data->dependencies);
    free(data);
}

void print_data_structures(int level, data_structures_t *data) {
    // Print offsets
    printf("Offsets (level %d):\n", level);
    for(int i=0; i<sizeof(data->offsets)/sizeof(int); i++) {
        printf("%d ", data->offsets[i]);
    }
    printf("\n");

    // Print keys
    printf("Keys (level %d):\n", level);
    for(int i=0; i<sizeof(data->keys)/sizeof(int); i++) {
        printf("%d ", data->keys[i]);
    }
    printf("\n");

    // Print records
    printf("Records (level %d):\n", level);
    for(int i=0; i<sizeof(data->records)/sizeof(record_t); i++) {
        record_t r = data->records[i];
        printf("%d ", r.value);
    }
    printf("\n");

    // Print metadata
    printf("Metadata (level %d):\n", level);
    for(int i=0; i<sizeof(data->metadata)/sizeof(metadata_t); i++) {
        metadata_t m = data->metadata[i];
        printf("%d '%c'\n", m.flag, m.status);
    }

    // Print dependencies
    printf("Dependencies (level %d):\n", level);
    for(int i=0; i<sizeof(data->dependencies)/sizeof(void*); i++) {
        void *dep = data->dependencies[i];
        printf("%p ", dep);
    }
    printf("\n");
}
