#include <stdbool.h>

typedef struct {
    long offset;
    int key;
    float data;
} Record;

typedef struct {
    Record* records;
    int capacity;
    int size;
    int history_size;
    Record** history;
} Collection;

void collection_init(Collection* self, int max_size) {
    self->records = (Record*)malloc(max_size * sizeof(Record));
    self->capacity = max_size;
    self->size = 0;
    self->history_size = 0;
    self->history = (Record**)malloc(max_size * sizeof(Record*));
}

void collection_insert(Collection* self, Record record) {
    if (self->size >= self->capacity / 2) {
        printf("Collection is nearing its capacity.\n");
    }

    if (self->size == self->capacity) {
        printf("Collection has reached its maximum size. Please consider resizing.\n");
        return;
    }

    self->records[self->size] = record;
    self->history[self->history_size++] = &record;
    self->size++;
}

void collection_remove(Collection* self, int index) {
    if (index < 0 || index >= self->size) {
        printf("Invalid index. Cannot remove a non-existent record.\n");
        return;
    }

    Record* temp = self->records[index];
    self->history[self->history_size++] = temp;

    for (int i = index; i < self->size - 1; i++) {
        self->records[i] = self->records[i + 1];
    }

    self->size--;
}

Record* collection_get(Collection* self, int index) {
    if (index < 0 || index >= self->size) {
        printf("Invalid index. Cannot retrieve a non-existent record.\n");
        return NULL;
    }

    return &self->records[index];
}

void collection_free(Collection* self) {
    free(self->records);
    for (int i = 0; i < self->history_size; i++) {
        free(self->history[i]);
    }
    free(self->history);
}
