typedef struct {
    char* name;
    int priority;
    Date dueDate;
} Project;

// Function to manage dynamic list of projects
Project** manageProjects() {
    // Initialize head and current pointer for linked list
    Project** head = NULL;
    Project** current = &head;

    // Function to add a new project
    void addProject(Project** head, char* name, int priority, Date dueDate) {
        Project* newProject = (Project*) malloc(sizeof(Project));
        if (!newProject) {
            printf("Error: Unable to allocate memory for new project.\n");
            return;
        }

        // Initialize new project
        newProject->name = (char*) malloc(strlen(name) + 1);
        strcpy(newProject->name, name);
        newProject->priority = priority;
        newProject->dueDate = dueDate;

        // Add new project to the list
        newProject->next = *head;
        *head = newProject;
    }

    // Function to remove a project by its name
    void removeProject(Project** head, char* projectName) {
        Project** temp = &head;
        while (*temp && strcmp((*temp)->name, projectName) != 0) {
            temp = &(*temp)->next;
        }

        if (*temp) {
            // Free memory allocated for the project
            free((*temp)->name);
            free(*temp);
            *temp = (*temp)->next;
        } else {
            printf("Error: Project not found.\n");
        }
    }

    // Function to list all projects sorted by priority
    void listProjects(Project** head) {
        Project* current = *head;
        Project* previous = NULL;

        while (current) {
            // Print project details
            printf("%s - Priority: %d, Due Date: %d/%d/%d\n", 
                   current->name, current->priority, current->dueDate.day, 
                   current->dueDate.month, current->dueDate.year);

            previous = current;
            current = current->next;
        }
    }

    // Function to export project list in CSV format
    void exportProjects(Project** head) {
        FILE* file = fopen("project_list.csv", "w");
        if (!file) {
            printf("Error: Unable to create file.\n");
            return;
        }

        Project* current = *head;

        while (current) {
            fprintf(file, "\"%s\", %d, %d/%d/%d\n", 
                    current->name, current->priority, current->dueDate.day, 
                    current->dueDate.month, current->dueDate.year);
            current = current->next;
        }

        fclose(file);
    }

    return head;
}

int main() {
    Project** projects = manageProjects();
    // Example usage: Add and remove projects
    addProject(projects, "Project A", 1, (Date){1, 1, 2023});
    addProject(projects, "Project B", 2, (Date){15, 4, 2023});
    addProject(projects, "Project C", 3, (Date){30, 6, 2023});

    removeProject(projects, "Project A");

    // Example usage: List all projects
    listProjects(projects);

    // Example usage: Export project list in CSV format
    exportProjects(projects);

    return 0;
}
