    struct timeval tv;
    int i;

    if (size == 0) {
        return NULL;
    }

    // Initialize array with a specified size, ensuring unique values for each field
    records = malloc(sizeof(record_status) * size);
    if (!records) {
        return NULL; // Out of memory
    }
