    printf("Initial memory allocation at %ld.%06d\n", tv.tv_sec, tv.tv_usec);

    for (i = 0; i < size; i++) {
        // Handle metadata buffer resizing and null-termination
        char* metadata = malloc(MAX_METADATA_SIZE);
        if (!metadata) {
            free(records); // Free existing records to prevent memory leaks
            return NULL; // Out of memory
        }
        memset(metadata, 0, MAX_METADATA_SIZE);

        // Initialize record fields with unique values
        long offset = i;
        int key = i + 1;
        float data = (float) i;
        strcpy(metadata, "metadata");

        records[i].offset = offset;
        records[i].key = key;
        records[i].data = data;
        records[i].status = RECORD_OK;
    }

