#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    float data;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} RecordCollection;

void record_collection_init(RecordCollection* collection, size_t initial_capacity) {
    collection->records = (Record*)malloc(initial_capacity * sizeof(Record));
    collection->capacity = initial_capacity;
    collection->size = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    pthread_cond_init(&collection->cond, NULL);
}

void record_collection_add(RecordCollection* collection, Record record) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->size >= collection->capacity * 0.8) { // notify when nearing capacity
        pthread_cond_signal(&collection->cond);
    }

    if (collection->size >= collection->capacity) { // resize if full
        size_t new_capacity = collection->capacity * 2;
        Record* new_records = (Record*)realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            printf("Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    // add record at the end
    Record* pos = &collection->records[collection->size];
    memcpy(pos, &record, sizeof(Record));
    collection->size++;

    pthread_mutex_unlock(&collection->mutex);
}

void record_collection_remove(RecordCollection* collection, size_t index) {
    if (index >= collection->size) {
        printf("Invalid index\n");
        return;
    }

    Record* pos = &collection->records[index];
    memcpy(pos, &collection->records[--collection->size], sizeof(Record));
}

void record_collection_retrieve(const RecordCollection* collection, size_t index, Record* out_record) {
    if (index >= collection->size) {
        printf("Invalid index\n");
        return;
    }

    *out_record = collection->records[index];
}

void record_collection_garbage_collect(RecordCollection* collection) {
    pthread_mutex_lock(&collection->mutex);

    // collect garbage
    Record* new_records = (Record*)malloc(collection->size * sizeof(Record));
    memcpy(new_records, collection->records, collection->size * sizeof(Record));
    free(collection->records);
    collection->records = new_records;

    pthread_mutex_unlock(&collection->mutex);
}

void record_collection_destroy(RecordCollection* collection) {
    pthread_mutex_lock(&collection->mutex);

    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);
}
