#include <time.h>

// Structure definition for record
typedef struct {
    int value;
} Record;

// Function to dynamically allocate memory for an array of long integers (offsets)
long* allocateOffsets(int size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    return offsets;
}

// Function to dynamically allocate memory for an array of int keys
int* allocateKeys(int size, int (*transform)(long)) {
    int* keys = (int*)malloc(size * sizeof(int));
    for (int i = 0; i < size; i++) {
        keys[i] = transform(i);
    }
    return keys;
}

// Function to dynamically allocate memory for an array of record structures
Record* allocateRecords(int size) {
    Record* records = (Record*)malloc(size * sizeof(Record));
    return records;
}

// Pseudo-random number generator function with unique seed based on offset and key
int generateSeed(long offset, int key) {
    return (offset + key) % RAND_MAX;
}

// Function to initialize each record's value using pseudo-random number generator
void initRecords(Record* records, long* offsets, int* keys, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand_r(generateSeed(offsets[i], keys[i]));
    }
}

// Function to manage memory deallocation and logging
void freeMemory(long* offsets, int* keys, Record* records) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(records);
    }
}

// Main function
int main() {
    // Example usage: dynamically allocate memory for arrays of offsets, keys, and records
    int size = 100;
    long* offsets = allocateOffsets(size);
    int* keys = allocateKeys(size, &generateSeed);
    Record* records = allocateRecords(size);
    initRecords(records, offsets, keys, size);

    // Example usage: manage memory deallocation and logging
    freeMemory(offsets, keys, records);

    return 0;
}
