void processAndAggregateNetworkEvents(int recordCount, int* records, Event** events, LogEntry** logEntries, Statistics** statistics, Metadata** metadata) {
    // Initialize memory pool
    void* pool = malloc(1024);
    if (!pool) {
        printf("Memory allocation failed. Exiting.\n");
        exit(EXIT_FAILURE);
    }

    // Initialize record array
    *records = (int*)malloc(recordCount * sizeof(int));
    if (!*records) {
        printf("Memory allocation failed. Exiting.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < recordCount; i++) {
        (*records)[i] = rand() % 100 + 1;
        (*records)[i * 2] = (long)rand() % 1024;
        (*records)[i * 2 + 1] = (int)rand();
    }

    // Initialize events array
    int eventCount = 0;
    *events = (Event*)malloc(1024 * sizeof(Event));
    if (!*events) {
        printf("Memory allocation failed. Exiting.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < recordCount; i++) {
        Event event;
        event.value = (double)rand() / RAND_MAX;
        event.description = (char*)malloc(strlen("Event ") + 10);
        strcpy(event.description, "Event ");
        sprintf(event.description + strlen("Event "), "%d", i);
        event.timestamp = time(NULL);
        (*events)[eventCount++] = event;
    }

    // Initialize log entries array
    int logEntryCount = 0;
    *logEntries = (LogEntry*)malloc(1024 * sizeof(LogEntry));
    if (!*logEntries) {
        printf("Memory allocation failed. Exiting.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < eventCount; i++) {
        LogEntry logEntry;
        logEntry.id = i + 1;
        logEntry.name = (char*)malloc(strlen("Log Entry ") + 10);
        strcpy(logEntry.name, "Log Entry ");
        sprintf(logEntry.name + strlen("Log Entry "), "%d", i);
        logEntry.timestamp = time(NULL);
        (*logEntries)[logEntryCount++] = logEntry;
    }

    // Initialize statistics array
    int statisticCount = 0;
    *statistics = (Statistics*)malloc(1024 * sizeof(Statistics));
    if (!*statistics) {
        printf("Memory allocation failed. Exiting.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < eventCount; i++) {
        Statistics statistic;
        statistic.count = i + 1;
        statistic.sum = (int)rand() % 1000;
        statistic.average = (double)statistic.sum / (i + 1);
        (*statistics)[statisticCount++] = statistic;
    }

    // Initialize metadata array
    int metadataCount = 0;
    *metadata = (Metadata*)malloc(1024 * sizeof(Metadata));
    if (!*metadata) {
        printf("Memory allocation failed. Exiting.\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < eventCount; i++) {
        Metadata metadata;
        metadata.type = (char*)malloc(strlen("Event ") + 10);
        strcpy(metadata.type, "Event ");
        sprintf(metadata.type + strlen("Event "), "%d", i);
        metadata.flags = i % 2;
        metadata.timestamp = time(NULL);
        (*metadata)[metadataCount++] = metadata;
    }

    // Validate allocated memory blocks
    printf("Memory allocation validated.\n");

    // Free all allocated memory
    free(pool);
    for (int i = 0; i < eventCount; i++) {
        free((*events)[i].description);
    }
    free(*events);
    for (int i = 0; i < logEntryCount; i++) {
        free((*logEntries)[i].name);
    }
    free(*logEntries);
    for (int i = 0; i < statisticCount; i++) {
        // No memory to free for statistics
    }
    for (int i = 0; i < metadataCount; i++) {
        free((*metadata)[i].type);
    }
    free(*metadata);

    exit(EXIT_SUCCESS);
}
