#include "memory_manager.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    float price;
    char* description;
    struct item* related_item;
} item;

item* list = NULL;
int num_items = 0;
char buffer[257]; // for string copying

// Allocate and initialize a new item
void add_item(int initial_num, const char* description_pattern) {
    // Initialize the first 'initial_num' items
    if (!list) {
        list = (item*)malloc((initial_num + 1) * sizeof(item));
        num_items = initial_num;
    }

    // Add more items as needed
    while (num_items < initial_num) {
        item* new_item = (item*)malloc(sizeof(item));

        // Initialize the item's fields
        strcpy(buffer, description_pattern);
        buffer[256] = '\0'; // null-terminate the buffer
        new_item->description = strdup(buffer);

        new_item->price = 0.0f;
        new_item->related_item = NULL;

        // Add the new item to the list and update num_items
        if (num_items == 0) {
            list = new_item;
        } else {
            ((item*)malloc(sizeof(item)));
            list[num_items].related_item = new_item;
        }
        num_items++;
    }

    // Serialize the updated list of items
    serialize_list("output.json");
}

// Calculate total revenue from selling each item once
float calculate_revenue() {
    float total = 0.0f;

    for (int i = 0; i < num_items; i++) {
        if (list[i].price > 0.0f) {
            total += list[i].price;
        } else {
            printf("Error: Negative price found! Skipping item %d.\n", i);
        }
    }

    return total;
}

// Free allocated memory upon function exit
void cleanup() {
    for (int i = 0; i < num_items; i++) {
        free(list[i].description);
        if (list[i].related_item) {
            cleanup();
            free(list[i].related_item);
        }
    }

    free(list);
}

// Serialize the list of items to a file
void serialize_list(const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        printf("Error opening file for writing!\n");
        return;
    }

    fprintf(file, "[\n");

    for (int i = 0; i < num_items; i++) {
        fprintf(file, "{\"price\": %f, \"description\": \"%s\", \"related_item\": {\"description\": \"%s\"}\n",
            list[i].price, list[i].description, (list[i].related_item) ? "pointer" : "null"};

    fclose(file);
}

int main() {
    add_item(5, "Product %d: ");
    printf("Total revenue: %.2f\n", calculate_revenue());
    cleanup();
}
