// Custom Memory Pool Structure
typedef struct {
    void **pool;
    size_t capacity;
    size_t used;
} MemPool;

MemPool *mem_pool = NULL;
size_t MEM_POOL_CAPACITY = 1024; // Initial Capacity

void mem_pool_init() {
    if (!mem_pool) {
        mem_pool = (MemPool *)malloc(sizeof(MemPool));
        mem_pool->pool = (void **)calloc(MEM_POOL_CAPACITY, sizeof(void *));
        mem_pool->capacity = MEM_POOL_CAPACITY;
        mem_pool->used = 0;
    }
}

void *mem_pool_alloc(size_t size) {
    if (!mem_pool || mem_pool->used + size > MEM_POOL_CAPACITY) {
        // Resize the pool if necessary
        size_t new_capacity = MEM_POOL_CAPACITY * 2;
        void **new_pool = (void **)realloc(mem_pool->pool, sizeof(void *) * new_capacity);
        if (!new_pool) return NULL; // Out of memory
        mem_pool->pool = new_pool;
        mem_pool->capacity = new_capacity;
    }
    void *ptr = mem_pool->pool[mem_pool->used];
    mem_pool->used += size;
    return ptr;
}

void mem_pool_free(void *ptr, size_t size) {
    // Update the pool's used capacity
    mem_pool->used -= size;
    // Release memory blocks if necessary
    if (mem_pool->used < MEM_POOL_CAPACITY / 2) {
        void **new_pool = (void **)realloc(mem_pool->pool, sizeof(void *) * MEM_POOL_CAPACITY / 2);
        if (!new_pool) return; // Out of memory
        mem_pool->pool = new_pool;
        mem_pool->capacity = MEM_POOL_CAPACITY / 2;
    }
}

// Function to manage data structures and allocate/free memory
void *allocate_and_init_data_structures(size_t size) {
    void *ptr = mem_pool_alloc(size);
    if (!ptr) {
        // Handle allocation failure gracefully
        printf("Memory allocation failed!\n");
        return NULL; // Return a fallback value or exit with error code
    }
    return ptr;
}

// Example usage:
int main() {
    size_t max_size = 1024;
    int *keys = (int *)allocate_and_init_data_structures(sizeof(int) * max_size);
    long *offsets = (long *)allocate_and_init_data_structures(sizeof(long) * max_size);
    // ... Initialize and use the data structures ...
    mem_pool_free(keys, sizeof(int) * max_size);
    mem_pool_free(offsets, sizeof(long) * max_size);
    return 0;
}
