void* complex_array_init(int size) {
    void *ptr = malloc(sizeof(ComplexData) * size);
    if (!ptr) return NULL;  // Handle memory allocation failure

    for (int i = 0; i < size; i++) {
        ComplexData *cd = (ComplexData*)(((char*)ptr) + i * sizeof(ComplexData));
        cd->d = 0.0;
        cd->i = 0;
        cd->b = false;
        // Generate a random alphanumeric string
        char* id = malloc(32);
        if (!id) return NULL;  // Handle memory allocation failure
        for (int j = 0; j < 16; j++) {
            sprintf((char*)id + j, "%c", (rand() % 2 == 0 ? 'a' : 'A') | (rand() % 26));
        }
        cd->id = id;
    }

    return ptr;
}

void complex_array_free(void *ptr) {
    if (!ptr) return;  // Handle null pointer

    ComplexData* cd = ((ComplexData*)ptr);
    for (int i = 0; i < sizeof(ComplexData); i++) {
        free(((char*)cd + i));
    }

    free(ptr);
}
