Sensor* process_data(int num_sensors, int* timestamps, double* temperatures) {
    // Allocate memory for sensors
    Sensor* sensors = (Sensor*)malloc(num_sensors * sizeof(Sensor));

    // Calculate and populate average temperature fields
    for (int i = 0; i < num_sensors; i++) {
        sensors[i].average_temperature = 0.0;
        int count = 0;
        for (int j = 0; j < i + 1; j++) {
            if (timestamps[j] > 0) {
                sensors[i].average_temperature += temperatures[j];
                count++;
            }
        }
        if (count > 0)
            sensors[i].average_temperature /= count;
    }

    return sensors;
}
