#include <string.h>
#include <time.h>

typedef struct {
    double d;
    int i;
    bool flag;
    char* id;
} Element;

typedef struct {
    unsigned short rnti;
    char tag[16];
} NFAPI_CRC_INDICATION_PDU_T;

void mergeAndValidateArrays(Element** array1, int size1, NFAPI_CRC_INDATION_PDU_T** array2, int size2) {
    // Create a thread-safe hash table for validating RX_UE_INFORMATION_TAG
    pthread_hash_t* tags = pthread_hash_create(16);

    // Initialize the output array and its size
    Element** result = (Element**)malloc((size1 + size2) * sizeof(Element*));
    int resultSize = 0;

    // Merge and validate arrays
    for (int i = 0; i < size1; i++) {
        Element* elem = array1[i];
        // Validate RX_UE_INFORMATION_TAG against the hash table
        bool tagValid = pthread_hash_lookup(tags, elem->id) != NULL;
        if (tagValid) {
            // Add the element to the output array and increment its size
            result[resultSize] = elem;
            resultSize++;
        }
    }

    for (int i = 0; i < size2; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = array2[i];
        // Validate RX_UE_INFORMATION_TAG against the hash table
        bool tagValid = pthread_hash_lookup(tags, pdu->tag) != NULL;
        if (tagValid) {
            // Allocate memory for a new Element struct and initialize its fields
            Element* elem = (Element*)malloc(sizeof(Element));
            elem->d = 0.0;
            elem->i = 0;
            elem->flag = false;
            elem->id = strdup(pdu->tag);
            // Add the element to the output array and increment its size
            result[resultSize] = elem;
            resultSize++;
        }
    }

    pthread_hash_destroy(tags);

    // Print each element's details in a structured format
    for (int i = 0; i < resultSize; i++) {
        Element* elem = result[i];
        printf("Element %d:\n", i);
        printf("   Double: %.2f\n", elem->d);
        printf("   Integer: %d\n", elem->i);
        printf("   Flag: %s\n", elem->flag ? "true" : "false");
        printf("   ID: %s\n", elem->id);
    }

    // Free the output array and its elements
    for (int i = 0; i < resultSize; i++) {
        free(result[i]->id);
        free(result[i]);
    }
    free(result);
}
