void initialize_matrices(int rows, int cols) {
    // Dynamically allocate memory for both matrices using malloc()
    TemperatureData** temperature_matrix = (TemperatureData**)malloc(rows * sizeof(TemperatureData*));
    time_t* timestamp_matrix = (time_t*)malloc(rows * sizeof(time_t));

    // Initialize the 'temperature' matrix with values read from a CSV file
    FILE* csv_file = fopen("temperature_data.csv", "r");
    if (!csv_file) {
        printf("Error opening CSV file.\n");
        return;
    }
    for (int i = 0; i < rows; i++) {
        temperature_matrix[i] = (TemperatureData*)malloc(cols * sizeof(TemperatureData));
        for (int j = 0; j < cols; j++) {
            fscanf(csv_file, "%f,", &temperature_matrix[i][j].temperature);
            // Handle missing or invalid data gracefully
            if (feof(csv_file)) {
                break;
            }
        }
    }

    // Initialize the 'timestamp' matrix with Unix timestamps
    for (int i = 0; i < rows; i++) {
        timestamp_matrix[i] = time(NULL); // Assign current timestamp to each row
    }

    // Free allocated memory when the function returns
    for (int i = 0; i < rows; i++) {
        free(temperature_matrix[i]);
    }
    free(temperature_matrix);
    free(timestamp_matrix);

    // Validate that the dimensions of both matrices match
    if (rows != cols) {
        printf("Error: Dimensions mismatch.\n");
        return;
    }

    // Save initialized matrices back to a CSV file
    FILE* output_file = fopen("output_data.csv", "w");
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            fprintf(output_file, "%f,", temperature_matrix[i][j].temperature);
        }
        fprintf(output_file, "\n");
    }

    fclose(csv_file);
    fclose(output_file);

    return;
}
