void printArrays(const char**, int, int);

struct record {
    int value;
};

int main() {
    // Initialize random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 1000);

    // Allocate memory for arrays
    long* offset = (long*)allocateMemory(sizeof(long) * 6);
    int* key = (int*)allocateMemory(sizeof(int) * 6);
    struct record* recordArr = (struct record*)allocateMemory(sizeof(struct record) * 6);
    time_t* timestamp = (time_t*)allocateMemory(sizeof(time_t) * 6);
    short* priority = (short*)allocateMemory(sizeof(short) * 6);
    char* status = (char*)allocateMemory(sizeof(char) * 6);

    // Initialize arrays
    for (int i = 0; i < 6; i++) {
        offset[i] = i;
        key[i] = i;
        recordArr[i].value = dis(gen);
        timestamp[i] = time(NULL);
        priority[i] = rand() % 2;
        status[i] = 'A' + (i % 26);
    }

    // Print arrays
    printArrays((const char**)status, 6, 5);

    // Free allocated memory
    free(offset);
    free(key);
    free(recordArr);
    free(timestamp);
    free(priority);
    free(status);

    return 0;
}

// Allocate memory in chunks to optimize cache performance and reduce fragmentation
void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        // Handle allocation error
        printf("Error allocating memory!\n");
        exit(1);
    }
    return ptr;
}

// Print the contents of all arrays for debugging purposes
void printArrays(const char** arr, int size, int limit) {
    for (int i = 0; i < size && i < limit; i++) {
        printf("%c: %s\n", arr[i], arr[i]);
    }
