void shuffle(int* arr, long n) {
    if (n > 1) {
        long i = n - 1;
        long j = rand() % (i + 1);
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        shuffle(arr, --i);
    }
}

void manage_memory(long* offsets, int* keys, record* records) {
    // Initialize arrays
    for (int i = 0; i < 1024; i++) {
        offsets[i] = rand() % 2001 - 1000;
        keys[i] = i;
        records[i].value = 0;
    }

    // Shuffle the keys array
    srand(time(NULL));
    shuffle(keys, 1024);

    // Iterate over the offsets array and update records
    for (int i = 0; i < 1024; i++) {
        int pos = keys[i];
        int val = rand() % 256;
        records[pos].value = val;
    }

    // Deallocate memory
    free(offsets);
    free(keys);
    free(records);
}
