#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* records = NULL;
long* offsets = NULL;
int* keys = NULL;

void shuffle_keys(int* array, int n) {
    for (int i = 0; i < n; --i) {
        int j = rand() % (n - i) + i;
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

void update_records(long* offsets, int* keys, record* records) {
    for (int i = 0; i < 1024; ++i) {
        int offset_index = keys[i] % 1024;
        records[offset_index].value = rand() % 256;
    }
}

void serialize_records(record* records, FILE* file) {
    fwrite(records, sizeof(record), 1024, file);
}

int deserialize_records(record* records, FILE* file) {
    if (fread(records, sizeof(record), 1024, file) != 1024) {
        return -1;
    }
    return 0;
}

void log_performance(char* operation, double time_taken) {
    printf("%s took %.3f seconds\n", operation, time_taken);
}

int main() {
    srand(time(NULL));

    offsets = (long*)malloc(1024 * sizeof(long));
    keys = (int*)malloc(1024 * sizeof(int));
    records = (record*)malloc(1024 * sizeof(record));

    for (int i = 0; i < 1024; ++i) {
        offsets[i] = rand() % 2001 - 1000;
        keys[i] = rand() % 1024;
        records[i].value = 0;
    }

    shuffle_keys(keys, 1024);

    for (int i = 0; i < 1024; ++i) {
        update_records(&offsets[i], &keys[i], &records[offsets[i]]);
    }

    FILE* file = fopen("records.bin", "wb");
    serialize_records(records, file);
    fclose(file);

    file = fopen("records.bin", "rb");
    if (deserialize_records(records, file) != 0) {
        printf("Deserialization failed\n");
        return -1;
    }
    fclose(file);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
