// Structure definition for record data type
typedef struct {
    int key;
} Record;

// Function to manage memory and initialize arrays
void initArrays(int* offsets, long* values, Record** records, int numRecords) {
    // Allocate memory for arrays
    offsets = (int*)malloc(numRecords * sizeof(int));
    values = (long*)malloc(numRecords * sizeof(long));
    records = (Record**)malloc(numRecords * sizeof(Record));

    // Initialize arrays with random values and key values in ascending order
    int i;
    for (i = 0; i < numRecords; i++) {
        offsets[i] = randlib_int();
        values[i] = (long)i;
        records[i]->key = i;
        records[i].data = randlib_int_range(1, 100);
    }

    // Sort the record array based on key values
    qsort(records, numRecords, sizeof(Record), compareRecords);

    // Function to compare two records for sorting
    int compareRecords(const void* a, const void* b) {
        Record* record1 = *(Record**)a;
        Record* record2 = *(Record**)b;

        return (record1->key - record2->key);
    }

    // Free allocated memory upon function exit
    free(offsets);
    free(values);
    for (i = 0; i < numRecords; i++) {
        free(records[i].data);
        free(records[i]);
    }
    free(records);

