long* allocate_offsets(int size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % 2001 - 1000;
    }

    return offsets;
}

// Initialize keys array with unique values
int* allocate_keys(int size) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        keys[i] = i;
    }

    return keys;
}

// Shuffle the keys array in place using Fisher-Yates algorithm
void shuffle_keys(int* keys, int size) {
    int i = size - 1;
    while (i > 0) {
        int j = rand() % (i + 1);
        int temp = keys[i];
        keys[i] = keys[j];
        keys[j] = temp;
        i--;
    }
}

// Initialize records array with zeros
record* allocate_records(int size) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        records[i].value = 0;
    }

    return records;
}

// Shuffle and update records array
void shuffle_update_records(long* offsets, int* keys, record* records) {
    int i;
    for (i = 0; i < 1024; i++) {
        int key = keys[i];
        long offset = offsets[key];
        int value = rand() % 256;
        records[key].value = value + offset;
    }
}

// Deallocate memory
void deallocate_memory(long* offsets, int* keys, record* records) {
    free(offsets);
    free(keys);
    free(records);
}
