        if (strcmp(entry->d_name, ".") != 0 && strcmp(entry->d_name, "..") != 0) {
            char filepath[1024];
            sprintf(filepath, "%s/%s", directory_path, entry->d_name);

            // Parse log file using external logging library
            // ... ( omitted for brevity )

            log_entry* log_entry_ptr = (log_entry*)malloc(sizeof(log_entry));
            log_entry_ptr->log_message = malloc(strlen(log_entry_ptr->log_message) + 1);
            strcpy(log_entry_ptr->log_message, log_entry_ptr->log_message);
            log_entry_ptr->timestamp = ...; // Parse timestamp
            log_entry_ptr->log_level = ...; // Parse log level

            size_t new_log_entries_size = log_entries_size * 2;
            log_entries = (log_entry**)realloc(log_entries, new_log_entries_size * sizeof(log_entry*));
            log_entries[log_entries_size - 1] = log_entry_ptr;
            log_entries_size = new_log_entries_size;

            // Manage metadata array
            if (metadata->version_number < ... /* version number from log file */) {
                metadata = (metadata*)realloc(metadata, (metadata->version_number + 1) * sizeof(metadata));
                metadata[metadata->version_number].description = malloc(strlen(entry->d_name) + 1);
                strcpy(metadata[metadata->version_number].description, entry->d_name);
            }

            // Manage errors array
            if (errors == NULL || ... /* error code from log file */) {
                errors = (error*)malloc(1 * sizeof(error));
                errors[0].error_code = ...; // Parse error code
                errors[0].error_message = malloc(strlen(entry->d_name) + 1);
                strcpy(errors[0].error_message, entry->d_name);
            } else {
                size_t new_errors_size = (errors != NULL) ? (errors->size * 2) : 1;
                errors = (error*)realloc(errors, new_errors_size * sizeof(error));
                errors[errors->size - 1].error_code = ...; // Parse error code
                errors[errors->size - 1].error_message = malloc(strlen(entry->d_name) + 1);
                strcpy(errors[errors->size - 1].error_message, entry->d_name);
            }

            // Manage dependencies array
            if (dependencies == NULL || ... /* dependency count from log file */) {
                dependencies = (dependency*)malloc(1 * sizeof(dependency));
                dependencies->log_entry_ptr = log_entry_ptr;
                dependencies->metadata_ptr = metadata;
                dependencies->error_ptr = errors;
                dependencies->dependency_count = 0;
            } else {
                size_t new_dependencies_size = (dependencies != NULL) ? (dependencies->size * 2) : 1;
                dependencies = (dependency*)realloc(dependencies, new_dependencies_size * sizeof(dependency));
                dependencies[dependencies->size - 1].log_entry_ptr = log_entry_ptr;
                dependencies[dependencies->size - 1].metadata_ptr = metadata;
                dependencies[dependencies->size - 1].error_ptr = errors;
                dependencies[dependencies->size - 1].dependency_count = ...; // Parse dependency count
            }
        }
    }

    closedir(dir);

    // Free all allocated memory
    for (int i = 0; i < log_entries_size; i++) {
        free(log_entries[i]->log_message);
        free(log_entries[i]);
    }
    free(log_entries);

    for (int i = 0; i < metadata->version_number + 1; i++) {
        free(metadata[i].description);
    }
    free(metadata);

    // Print contents of arrays for debugging purposes
    printf("Log Entries:\n");
    for (int i = 0; i < log_entries_size; i++) {
        printf("%s\n", log_entries[i]->log_message);
    }

    printf("Metadata:\n");
    for (int i = 0; i <= metadata->version_number; i++) {
        printf("%s - Version %d\n", metadata[i].description, metadata[i].version_number);
    }

    // Calculate and store statistical metrics
    int log_level_counts[4] = {0}; // Initialize counts for each log level
    time_t previous_timestamp = 0;
    int timestamp_diff_sum = 0;

    for (int i = 0; i < log_entries_size; i++) {
        switch (log_entries[i]->log_level) {
            case 1:
                log_level_counts[0]++;
                break;
            case 2:
                log_level_counts[1]++;
                break;
            case 3:
                log_level_counts[2]++;
                break;
            case 4:
                log_level_counts[3]++;
                break;
        }
        if (previous_timestamp != 0) {
            timestamp_diff_sum += abs(log_entries[i]->timestamp - previous_timestamp);
        }
        previous_timestamp = log_entries[i]->timestamp;
    }

    printf("Log Level Counts: %d, %d, %d, %d\n", log_level_counts[0], log_level_counts[1], log_level_counts[2], log_level_counts[3]);
    printf("Average Timestamp Interval: %ld\n", (long)timestamp_diff_sum / (log_entries_size - 1));

    // Deinitialize external logging library
    // ... ( omitted for brevity )

    return;
