        // Calculate average packet length for each flow
        if (packet_index > 0) {
            double average_length = (double)packets[packet_index - 1].length / (packet_index - 1);
            statistics->average_length += average_length;
        }

        // Update statistics
        statistics->packet_count++;
        statistics->total_length += packets[packet_index].length;
    }

    fclose(file);

    // Print arrays for debugging
    printf("Packets:\n");
    for (int i = 0; i < packet_index; i++) {
        printf("%d %ld %d\n", packets[i].packet_id, packets[i].timestamp, packets[i].length);
