    printf("Flows:\n");
    for (int i = 0; i < flow_index; i++) {
        printf("%s %s\n", flows[i].source_ip, flows[i].destination_ip);
    }

    printf("Events:\n");
    for (int i = 0; i < packet_index + flow_index; i++) {
        printf("%p %s %ld\n", events[i].packet, events[i].event_type, events[i].timestamp);
    }

    printf("Log Entries:\n");
    for (int i = 0; i < log_entry_index; i++) {
        printf("%d %s %ld\n", log_entries[i].log_level, log_entries[i].message, log_entries[i].timestamp);
    }

    printf("Statistics: packet_count = %d, total_length = %.2f, average_length = %.2f\n",
           statistics->packet_count, statistics->total_length, statistics->average_length);

    // Free memory
    for (int i = 0; i < flow_index; i++) {
        free(flows[i].packets);
    }
    free(flows);
    free(packets);
    free(events);
    for (int i = 0; i < log_entry_index; i++) {
        free(log_entries[i].message);
    }
    free(log_entries);

    // Deinitialize logging library
    // ...
}

int main() {
    analyzeAndProcessNetworkTraffic("network_traffic.log");
