#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct schedule {
    char* start_date;
    char* end_date;
    int status;
} Schedule;

typedef struct project {
    char title[50];
    float budget_estimate;
    Schedule* schedule;
} Project;

Project* create_project(const char* title, const char* start_date, const char* end_date, int status) {
    Project* project = (Project*)malloc(sizeof(Project));
    if (!project) return NULL; // handle memory allocation error

    strcpy(project->title, title ? title : "Unnamed");
    project->budget_estimate = 0.0;
    project->schedule = create_schedule(start_date, end_date, status);

    return project;
}

Schedule* create_schedule(const char* start_date, const char* end_date, int status) {
    Schedule* schedule = (Schedule*)malloc(sizeof(Schedule));
    if (!schedule) return NULL; // handle memory allocation error

    schedule->start_date = strdup(start_date);
    schedule->end_date = strdup(end_date);
    schedule->status = status;

    return schedule;
}

void update_budget_estimate(Project** projects, int num_projects, float percentage) {
    for (int i = 0; i < num_projects; i++) {
        Project* project = projects[i];
        if (!project) continue; // handle null pointer

        project->budget_estimate *= (1.0 + percentage);
    }
}

void free_project(Project* project) {
    if (!project) return;

    free(project->schedule->start_date);
    free(project->schedule->end_date);

    free(project);
}

void free_projects(Project** projects, int num_projects) {
    for (int i = 0; i < num_projects; i++) {
        Project* project = projects[i];
        if (!project) continue;

        free_project(project);
    }

    free(projects);
}
