#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct Record {
    int value;
    char* string;
} Record;

Record** record_array = NULL;
int array_size = 0; // Initial capacity
int resize_threshold = 10; // Resize threshold (e.g., 10 records)

void* record_new(void* data) {
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        return NULL;
    }
    new_record->value = *(int*)data;
    // Dynamically allocate space for the string
    char* string = malloc(*(int*)data * sizeof(char)); // Assuming variable-sized strings
    strcpy(string, "Default_string");
    new_record->string = string;
    return (void*)new_record;
}

void record_free(void* data) {
    Record* record = (Record*)data;
    free(record->string);
    free(record);
}

int record_resize(int new_capacity) {
    int old_size = array_size;
    array_size = new_capacity;
    record_array = realloc(record_array, array_size * sizeof(Record*));
    if (!record_array || array_size < old_size) {
        return -1; // Resize failed
    }
    return 0; // Resize successful
}

int record_add(int value) {
    if (array_size >= resize_threshold) {
        int new_capacity = array_size + (array_size / 2); // Dynamic resizing strategy
        if (record_resize(new_capacity)) {
            return -1; // Resize failed, unable to add record
        }
    }
    Record** new_array = malloc(array_size * sizeof(Record*) + (array_size / 2) * sizeof(Record*));
    for (int i = 0; i < array_size; i++) {
        new_array[i] = record_array[i];
    }
    free(record_array);
    record_array = new_array;
    Record* new_record = record_new(&value); // Allocate and initialize a new record
    if (!new_record) {
        return -1; // Allocation failed, unable to add record
    }
    record_array[array_size++] = new_record;
    return 0; // Record added successfully
}

void record_free_all() {
    for (int i = 0; i < array_size; i++) {
        record_free(record_array[i]);
    }
    free(record_array);
}
