#define MAX_RECORDS 1000
#define KEY_ARRAY_CAPACITY 10
#define MEMORY_USAGE_THRESHOLD (1024 * 1024) // 1MB

typedef struct {
    int value;
} Record;

Record* records = NULL;
int record_count = 0;
int key_count = 0;
int* keys = NULL;
int memory_usage = 0;

void resizeKeyArray(int new_capacity) {
    if (new_capacity < KEY_ARRAY_CAPACITY) return;
    int* new_keys = realloc(keys, sizeof(int) * new_capacity);
    if (!new_keys) return; // allocation failed
    keys = new_keys;
}

void addRecord(int value) {
    if (record_count >= MAX_RECORDS) {
        printf("Reached maximum number of records. Cannot add more.\n");
        return;
    }

    Record* new_record = realloc(records, sizeof(Record) * (record_count + 1));
    if (!new_record) {
        printf("Memory allocation failed. Cannot add record.\n");
        return;
    }
    records = new_record;

    int* new_keys = realloc(keys, sizeof(int) * (key_count + 1));
    if (!new_keys) {
        printf("Memory allocation failed. Cannot add key.\n");
        return;
    }
    keys = new_keys;

    records[record_count].value = value;
    keys[key_count] = value;
    record_count++;
    key_count++;
}

void logMemoryUsage() {
    printf("Current memory usage: %d MB\n", memory_usage / (1024 * 1024));
}

double averageRecordValues() {
    int sum = 0;
    for (int i = 0; i < record_count; i++) {
        sum += records[i].value;
    }
    return (double)sum / record_count;
}
