#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    char* name;
    int attendance;
} Participant;

typedef struct {
    int timestamp;
    int participants_count;
    Participant** participants;
} Event;

Event* event_new() {
    Event* e = (Event*)malloc(sizeof(Event));
    if (!e) return NULL; // handle error

    e->timestamp = 0;
    e->participants_count = 0;
    e->participants = NULL;

    return e;
}

void event_free(Event* e) {
    for (int i = 0; i < e->participants_count; i++) {
        Participant* p = e->participants[i];
        free(p->name);
        free(p);
    }
    free(e->participants);
    free(e);
}

Event* event_insert(Event* e, int timestamp, int participant_id, const char* name) {
    // handle error
    if (e->timestamp > 0 && timestamp < e->timestamp) return NULL; // duplicate or out-of-order event

    Participant* p = (Participant*)malloc(sizeof(Participant));
    if (!p) return NULL; // handle error

    p->id = participant_id;
    p->name = strdup(name);
    p->attendance = 0;

    if (e->participants_count == e->participants_size) {
        // resize participants array
        e->participants_size *= 2;
        e->participants = realloc(e->participants, sizeof(Participant*) * e->participants_size);
    }

    e->participants[e->participants_count++] = p;

    e->timestamp = timestamp;

    return e;
}

Event* event_remove(Event* e, int participant_id) {
    // handle error
    for (int i = 0; i < e->participants_count; i++) {
        if (e->participants[i]->id == participant_id) {
            Participant* p = e->participants[i];
            memmove(&e->participants[i], &e->participants[i + 1], sizeof(Participant*) * (e->participants_count - i));
            free(p->name);
            free(p);

            e->participants_count--;

            if (i >= e->participants_count) {
                // resize participants array
                e->participants_size /= 2;
                e->participants = realloc(e->participants, sizeof(Participant*) * e->participants_size);
            }

            return e;
        }
    }

    return NULL; // participant not found
}

Event* event_update_attendance(Event* e, int participant_id, int attendance) {
    // handle error
    for (int i = 0; i < e->participants_count; i++) {
        if (e->participants[i]->id == participant_id) {
            e->participants[i]->attendance = attendance;
            return e;
        }
    }

    return NULL; // participant not found
}

Event* event_iterate(Event* e, int (*callback)(int timestamp, const char* name, int attendance)) {
    for (int i = 0; i < e->participants_count; i++) {
        Participant* p = e->participants[i];
        callback(e->timestamp, p->name, p->attendance);
    }

    return e;
}

void event_destroy(Event* e) {
    event_free(e);
}
