// Define the record structure
typedef struct {
    int val;
    long* ptr;
    time_t timestamp;
} record;

// Custom hash function for efficient access
unsigned long custom_hash(int key, long offset) {
    return (key + offset) % 1024; // Adjust this value based on your specific requirements
}

// Function to manage memory and initialize the data structure
void init_data_structure(int num_records, int min_val, int max_val, int* offsets, int* keys, long** records) {
    // Initialize arrays
    *offsets = (long*)malloc((num_records + 1) * sizeof(long));
    *keys = (int*)malloc((num_records + 1) * sizeof(int));

    // Initialize doubly linked list nodes
    record* head = NULL;
    record* tail = NULL;
    for (int i = 0; i < num_records; i++) {
        record* new_node = (record*)malloc(sizeof(record));
        new_node->val = rand() % (max_val - min_val + 1) + min_val;
        new_node->ptr = (long*)malloc(sizeof(long));
        *new_node->ptr = offsets[i];
        time_t timestamp = time(NULL);
        new_node->timestamp = timestamp;

        if (!head) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }

    // Print contents of arrays for debugging
    printf("Offsets: ");
    for (int i = 0; i <= num_records; i++) {
        printf("%ld ", *(offsets + i));
    }
    printf("\n");
    printf("Keys: ");
    for (int i = 0; i <= num_records; i++) {
        printf("%d ", keys[i]);
    }
    printf("\n");

    // Free allocated memory upon function return
    record* current = head;
    while (current) {
        record* next = current->next;
        free(current->ptr);
        free(current);
        current = next;
    }

    // Deallocate arrays and library resources
    free(*offsets);
    free(*keys);
}

int main() {
    srand(time(NULL)); // Initialize random number generator

    int num_records = 10; // Adjust this value based on your specific requirements
    int min_val = 0, max_val = 100;
    long* offsets = NULL;
    int* keys = NULL;
    record** records = NULL;

    init_data_structure(num_records, min_val, max_val, &offsets, &keys, &records);

    return 0;
}
