// Define the size of each hash table entry
#define TABLE_ENTRY_SIZE 1024

// Custom memory pool structure
typedef struct {
    void *ptr;
    size_t size;
} MemoryPool;

// Function to initialize and populate the hash tables
void* init_hash_tables(int num_keys, int max_values) {
    // Initialize the key-value pair hash table
    MemoryPool key_pool = {malloc(num_keys * TABLE_ENTRY_SIZE), num_keys * TABLE_ENTRY_SIZE};
    MemoryPool value_pool = {malloc(max_values * sizeof(float)), max_values * sizeof(float)};

    // Initialize the key and value hash tables
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    // Allocate memory for the key-value pairs
    long* keys = (long*)key_pool.ptr;
    char** values = (char**)malloc(num_keys * sizeof(char*));

    // Initialize the random number generator
    srand(time(NULL));

    // Populate the key-value pair hash table
    int i;
    for(i = 0; i < num_keys; i++) {
        keys[i] = i;
        values[i] = (char*)malloc(strlen("Value") + 1);
        strcpy(values[i], "Value");
    }

    // Initialize and populate the value hash table
    float* values_f = (float*)value_pool.ptr;
    for(i = 0; i < max_values; i++) {
        values_f[i] = (float)rand() / RAND_MAX;
    }

    // Free allocated memory
    free(key_pool.ptr);
    free(value_pool.ptr);
    pthread_mutex_destroy(&lock);

    return NULL;
}

int main(int argc, char* argv[]) {
    init_hash_tables(1000, 5000);
    return 0;
}
