#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    long* offset;
    float* weight;
    time_t timestamp;
} Record;

// Define the custom hash function
unsigned int hash_function(int key) {
    return (key ^ 0xdeadbeef) & 0xffffffff;
}

// Define the data structure
typedef struct {
    Record** records;
    long* offset;
    int* key;
    float* weight;
    int size;
} DataStructure;

DataStructure* create_data_structure(int num_records, int max_offset, int max_key, int max_weight) {
    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));

    // Initialize arrays
    ds->offset = (long*)malloc(max_offset * sizeof(long));
    ds->key = (int*)malloc(max_key * sizeof(int));
    ds->weight = (float*)malloc(max_weight * sizeof(float));

    // Set initial values for offset, key, and weight arrays
    for (int i = 0; i < max_offset; i++) {
        ds->offset[i] = i;
    }
    for (int i = 0; i < max_key; i++) {
        ds->key[i] = i;
    }
    for (int i = 0; i < max_weight; i++) {
        ds->weight[i] = i / (float)max_weight;
    }

    // Allocate array of record structures
    ds->records = (Record**)malloc(num_records * sizeof(Record*));

    // Initialize record structures with random values and timestamps
    for (int i = 0; i < num_records; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->value = rand() % 100;
        record->offset = &ds->offset[rand() % max_offset];
        record->weight = &ds->weight[rand() % max_weight];
        record->timestamp = time(NULL);
        ds->records[i] = record;
    }

    // Set the size of the data structure
    ds->size = num_records;

    return ds;
}

void free_data_structure(DataStructure* ds) {
    for (int i = 0; i < ds->size; i++) {
        Record* record = ds->records[i];
        free(record);
    }
    free(ds->offset);
    free(ds->key);
    free(ds->weight);
    free(ds->records);
    free(ds);
}

void print_data_structure(DataStructure* ds) {
    for (int i = 0; i < ds->size; i++) {
        Record* record = ds->records[i];
        printf("Value: %d, Offset: %ld, Weight: %f, Timestamp: %lu\n", record->value, *record->offset, *record->weight, record->timestamp);
    }
}

// Example usage
int main() {
    srand(time(NULL));
    DataStructure* ds = create_data_structure(10, 1000, 10000, 100000);
    print_data_structure(ds);
    free_data_structure(ds);
    return 0;
}
