```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int **data;
    int rows;
    int cols;
} MDA;

MDA* mda_new(int rows, int cols) {
    MDA* mda = (MDA*)malloc(sizeof(MDA));
    if (!mda) return NULL;

    mda->rows = rows;
    mda->cols = cols;
    mda->data = (int**)malloc(rows * sizeof(int*));
    for (int i = 0; i < rows; i++) {
        mda->data[i] = (int*)malloc(cols * sizeof(int));
    }

    return mda;
}

void mda_free(MDA* mda) {
    if (!mda) return;

    for (int i = 0; i < mda->rows; i++) {
        free(mda->data[i]);
    }
    free(mda->data);
    free(mda);
}

void mda_set(MDA* mda, int row, int col, int value) {
    if (!mda || row >= mda->rows || col >= mda->cols) return;

    mda->data[row][col] = value;
}

int mda_get(MDA* mda, int row, int col) {
    if (!mda || row >= mda->rows || col >= mda->cols) return -1; // or throw an exception

    return mda->data[row][col];
}

void mda_resize(MDA* mda, int new_rows, int new_cols) {
    if (!mda || new_rows <= 0 || new_cols <= 0) return;

    MDA* new_mda = mda_new(new_rows, new_cols);
    for (int i = 0; i < mda->rows && i < new_rows; i++) {
        for (int j = 0; j < mda->cols && j < new_cols; j++) {
            if (!mda_get(mda, i, j)) continue;
            mda_set(new_mda, i < new_rows ? i : 0, j < new_cols ? j : 0, mda_get(mda, i, j));
        }
    }

    free(mda);
    *mda = *new_mda;
}

void mda_log(MDA* mda) {
    printf("MDA: rows=%d, cols=%d\n", mda->rows, mda->cols);
}
