#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

typedef struct node {
    int key;
    char value[20];
    struct node* prev;
    struct node* next;
} Node;

Node* create_node(int key, const char* value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->key = key;
    strcpy(new_node->value, value);
    new_node->prev = new_node->next = NULL;
    return new_node;
}

void free_nodes(Node** head, int num_nodes) {
    Node* curr = *head;
    for (int i = 0; i < num_nodes; i++) {
        if (curr != NULL) {
            Node* temp = curr;
            curr = curr->next;
            free(temp);
        } else break;
    }
}

void insert(Node** head, int key, const char* value) {
    Node* new_node = create_node(key, value);
    if (*head == NULL || new_node->key < (*head)->key) {
        new_node->next = *head;
        if (*head != NULL) (*head)->prev = new_node;
        *head = new_node;
    } else {
        Node* curr = *head;
        while (curr->next != NULL && curr->next->key <= key) curr = curr->next;
        new_node->next = curr->next;
        if (curr->next != NULL) curr->next->prev = new_node;
        curr->next = new_node;
    }
}

void delete(Node** head, int key) {
    Node* curr = *head;
    while (curr != NULL && curr->key < key) curr = curr->next;
    if (curr == NULL || curr->key > key) return;
    if (curr->prev != NULL) curr->prev->next = curr->next;
    else *head = curr->next;
    if (curr->next != NULL) curr->next->prev = curr->prev;
    free(curr);
}

Node* initialize_doubly_linked_list(int num_nodes, int min_key, int max_key) {
    Node* head = NULL;
    srand(time(NULL));
    for (int i = 0; i < num_nodes; i++) {
        int key = rand() % (max_key - min_key + 1) + min_key;
        const char* value = "Value";
        insert(&head, key, value);
    }
    return head;
}

void log_operations(int num_inserts, int num_deletes) {
    printf("Insertions: %d\n", num_inserts);
    printf("Deletes: %d\n", num_deletes);
}
