event_t* add_event(event_t** events, int* size, int new_timestamp) {
    *size += 1;
    event_t* new_events = realloc(*events, (*size) * sizeof(event_t));
    if (!new_events) return NULL; // Memory allocation failed
    new_events[*size - 1].timestamp = new_timestamp;
    return new_events;
}

void update_event(event_t** events, int* size, int id, char type[20]) {
    for (int i = 0; i < *size; i++) {
        if (events[i]->timestamp == id) {
            strcpy(events[i]->type, type);
            return;
        }
    }
}

event_t* get_events(event_t** events, int* size, int start_timestamp, int end_timestamp) {
    event_t* filtered_events = malloc((*size) * sizeof(event_t));
    if (!filtered_events) return NULL; // Memory allocation failed
    for (int i = 0; i < *size; i++) {
        if (events[i]->timestamp >= start_timestamp && events[i]->timestamp <= end_timestamp) {
            filtered_events[i] = *events[i];
        }
    }
    return filtered_events;
}

