        if (strcmp(cache->cache[i].key, key.key) == 0) return i;
    }
    return -1; // Not found in cache
}

void cache_set(cache_t* cache, event_t key, int value) {
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->cache[i].key, key.key) == 0) {
            cache->cache[i].value = value;
            return;
        }
    }
}

