typedef struct {
    time_t timestamp;
    int severity;
    char *message;
} LogEntry;

LogEntry **processAndStoreLogData(int logThreshold, FILE *logFile) {
    // Initialize internal data structure
    LogEntry **logs = (LogEntry **)malloc(logThreshold * sizeof(LogEntry *));
    for (int i = 0; i < logThreshold; i++) {
        logs[i] = NULL;
    }

    int logCount = 0;

    while (1) {
        // Read log entry from file
        LogEntry *logEntry = malloc(sizeof(LogEntry));
        fscanf(logFile, "%ld %d %s", &logEntry->timestamp, &logEntry->severity, logEntry->message);

        // Handle edge cases
        if (!logEntry->timestamp || !logEntry->message) {
            free(logEntry);
            continue;
        }

        // Store log entry and manage memory efficiently
        if (logCount >= logThreshold) {
            LogEntry *oldestLog = logs[0];
            for (int i = 1; i < logThreshold; i++) {
                logs[i - 1] = logs[i];
            }
            free(oldestLog);
        } else {
            logs[logCount++] = logEntry;
        }

        // Check if log size exceeds threshold and prune oldest entries
        if (logCount >= logThreshold) {
            for (int i = logThreshold; i < logCount; i++) {
                LogEntry *oldestLog = logs[i];
                free(oldestLog);
            }
            logCount = logThreshold;
        }
    }

    return logs;
}

void queryAndDisplayLogs(LogEntry **logs, int threshold) {
    // Implement filtering and display logic
}

void configureLogging(int logThreshold) {
    // Integrate with configuration management system
}

int main() {
    FILE *logFile = fopen("log.txt", "r");
    LogEntry **logs = processAndStoreLogData(1000, logFile);
    fclose(logFile);

    queryAndDisplayLogs(logs, 100);

    configureLogging(500);

    return 0;
}
