// Define struct Event and LogEntry
typedef struct {
    double measurement;
    char* identifier;
    time_t timestamp;
} Event;

typedef struct {
    time_t timestamp;
    char* log_message;
    int log_level;
} LogEntry;

// Function to print arrays for debugging purposes
void printArrays(double* measurements, char** identifiers, time_t* timestamps, Event* events, LogEntry* log_entries) {
    printf("Measurements:\n");
    for (int i = 0; i < sizeof(measurements)/sizeof(measurements[0]); i++) {
        printf("%f\n", measurements[i]);
    }

    printf("Identifiers:\n");
    for (int i = 0; i < sizeof(identifiers)/sizeof(identifiers[0]); i++) {
        printf("%s\n", identifiers[i]);
    }

    printf("Timestamps:\n");
    for (int i = 0; i < sizeof(timestamps)/sizeof(timestamps[0]); i++) {
        printf("%ld\n", timestamps[i]);
    }

    printf("Events:\n");
    for (int i = 0; i < sizeof(events)/sizeof(events[0]); i++) {
        printf("Measurement: %f, Identifier: %s, Timestamp: %ld\n", events[i].measurement, events[i].identifier, events[i].timestamp);
    }

    printf("Log Entries:\n");
    for (int i = 0; i < sizeof(log_entries)/sizeof(log_entries[0]); i++) {
        printf("Timestamp: %ld, Log Message: %s, Log Level: %d\n", log_entries[i].timestamp, log_entries[i].log_message, log_entries[i].log_level);
    }
}

// Function to calculate and print the average measurement
double calculateAverage(double* measurements, int size) {
    double sum = 0;
    for (int i = 0; i < size; i++) {
        sum += measurements[i];
    }
    return sum / size;
}

// Process and aggregate data function
