    measurements[3] = 7.8;
    measurements[4] = 9.10;

    for (int i = 0; i < 5; i++) {
        identifiers[i] = (char*)malloc(10 * sizeof(char));
        strcpy(identifiers[i], "Identifier");
    }

    // Initialize timestamp, event, and log_entry arrays with random values
    srand(time(NULL));
    for (int i = 0; i < 5; i++) {
        timestamps[i] = rand() % 100;
        events[i].measurement = (double)rand() / RAND_MAX;
        events[i].identifier = identifiers[rand() % 5];
        events[i].timestamp = rand() % 100;

        log_entries[i].timestamp = rand() % 100;
        log_entries[i].log_message = (char*)malloc(20 * sizeof(char));
        strcpy(log_entries[i].log_message, "Log Message");
    }

    // Free allocated memory
    for (int i = 0; i < 5; i++) {
        free(identifiers[i]);
        free(log_entries[i].log_message);
    }
    free(measurements);
    free(identifiers);
    free(timestamps);
    free(events);
    free(log_entries);

    // Print arrays for debugging purposes
    printArrays(measurements, identifiers, timestamps, events, log_entries);

    // Read measurements from standard input and store them in an array
    int measurementSize = 0;
    double* measurementArray = NULL;
    while (fscanf(stdin, "%lf", &measurement) == 1) {
        measurementSize++;
        measurementArray = (double*)realloc(measurementArray, sizeof(double) * (measurementSize + 1));
        measurementArray[measurementSize - 1] = measurement;
    }
    if (measurementSize > 0) {
        printf("Average measurement: %f\n", calculateAverage(measurementArray, measurementSize));
        free(measurementArray);
