    for (int i = 0; i < 5; i++) {
        fprintf(logFile, "Timestamp: %ld, Log Message: %s\n", events[i].timestamp, events[i].identifier);
    }
    fclose(logFile);

    // Free allocated memory
    free(measurements);
    free(identifiers);
    free(timestamps);
    free(events);
    free(log_entries);
}
