Event* init_event_array(int num_events) {
    if (num_events > EVENT_ARRAY_SIZE) {
        printf("Error: Exceeding maximum event array size.\n");
        return NULL; // Handle error
    }

    Event* events = (Event*)malloc(num_events * sizeof(Event));
    if (!events) {
        printf("Memory allocation failed.\n");
        return NULL; // Handle error
    }

    for (int i = 0; i < num_events; i++) {
        events[i].timestamp = time(NULL); // Generate timestamp
        events[i].status = 'a' + rand() % STATUS_CHAR_RANGE; // Random status
    }

    return events;
}

long* init_timestamp_array(int num_timestamps) {
    if (num_timestamps > TIMESTAMP_ARRAY_SIZE) {
        printf("Error: Exceeding maximum timestamp array size.\n");
        return NULL; // Handle error
    }

    long* timestamps = (long*)malloc(num_timestamps * sizeof(long));
    if (!timestamps) {
        printf("Memory allocation failed.\n");
        return NULL; // Handle error
    }

    for (int i = 0; i < num_timestamps; i++) {
        timestamps[i] = time(NULL); // Generate timestamp
    }

    return timestamps;
}

