// Thread-safe random number generator
unsigned int rand_thread_safe() {
    static unsigned int seed = time(NULL);
    return (seed = (seed * 1103515245 + 12345)) % (1 << 31);
}

char generate_random_status_char() {
    return 'A' + (rand_thread_safe() % STATUS_CHAR_RANGE);
}

// Initialize event records with timestamps and random statuses
void initialize_event_records(long* timestamps, char** statuses) {
    for (int i = 0; i < MAX_EVENT_RECORDS; i++) {
        timestamps[i] = time(NULL); // current timestamp
        statuses[i] = (char*)malloc(1);
        *statuses[i] = generate_random_status_char();
    }
