void initializeMemoryArrays(int numSensors, int numMeasurements, int numLogs) {
    // Dynamically allocate memory for arrays
    Sensor *sensorArray = (Sensor *)malloc(numSensors * sizeof(Sensor));
    MeasurementInterval *measurementArray = (MeasurementInterval *)malloc(numMeasurements * sizeof(MeasurementInterval));
    LogEntry *logArray = (LogEntry *)malloc(numLogs * sizeof(LogEntry));

