    for (int i = 0; i < numSensors; i++) {
        sensorArray[i].id = i;
        sensorArray[i].value = (float)rand() / RAND_MAX;
        sensorArray[i].status = 'A'; // Random status
    }

    // Initialize measurement intervals with random start and end timestamps
    for (int i = 0; i < numMeasurements; i++) {
        time_t now = time(NULL);
        measurementArray[i].start_timestamp = now - rand() % (24 * 60 * 60); // Random timestamp within a day
        measurementArray[i].end_timestamp = now + rand() % (24 * 60 * 60); // Random timestamp within a day
        measurementArray[i].sensor_id = i; // Assign sensor ID to each interval
    }

    // Initialize log entries with random timestamps, sensor IDs, values, and statuses
