    }

    printf("Log Array:\n");
    for (int i = 0; i < numLogs; i++) {
        printf("Timestamp: %ld, Sensor ID: %d, Value: %.2f, Status: %c\n", logArray[i].timestamp, logArray[i].sensor_id, logArray[i].value, logArray[i].status);
    }

    // Free allocated memory
    free(sensorArray);
    free(measurementArray);
