#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct session {
    int user_id;
    char* username;
    time_t login_time;
} Session;

void processUserSessions(int fd) {
    // Initialize random timestamp generation library
    srand(time(NULL));

    int num_sessions = 0; 
    int* user_ids = NULL;
    char** usernames = NULL;
    time_t* login_times = NULL;
    Session* sessions = NULL;

    // Read user session data from file descriptor
    while (1) {
        int user_id;
        char username[20];
        time_t login_time;

        read(fd, &user_id, sizeof(int));
        read(fd, username, 20);
        read(fd, &login_time, sizeof(time_t));

        // Dynamically allocate memory for new session structure
        Session* new_session = (Session*)malloc(sizeof(Session));
        if (!new_session) {
            // Handle out-of-memory error
            return;
        }

        new_session->user_id = user_id;
        new_session->username = strdup(username);
        new_session->login_time = login_time;

        // Reallocate arrays if necessary
        if (num_sessions >= sizeof(int) + 20 * sizeof(char) + sizeof(time_t)) {
            int* new_user_ids = (int*)realloc(user_ids, num_sessions * sizeof(int));
            char** new_usernames = (char**)realloc(usernames, num_sessions * sizeof(char*));
            time_t* new_login_times = (time_t*)realloc(login_times, num_sessions * sizeof(time_t));
            Session* new_sessions = (Session*)realloc(sessions, num_sessions * sizeof(Session));

            if (!new_user_ids || !new_usernames || !new_login_times || !new_sessions) {
                // Handle out-of-memory error
                return;
            }

            user_ids = new_user_ids;
            usernames = new_usernames;
            login_times = new_login_times;
            sessions = new_sessions;
        }

        user_ids[num_sessions] = user_id;
        usernames[num_sessions] = username;
        login_times[num_sessions] = login_time;
        sessions[num_sessions] = *new_session;

        free(new_session->username);
        free(new_session);

        num_sessions++;
    }
}

void printAverageLoginTime() {
    // Calculate and print the average login time for all processed sessions
    double total_login_time = 0.0;
    for (int i = 0; i < num_sessions; i++) {
        total_login_time += sessions[i].login_time;
    }

    printf("Average Login Time: %.2f seconds\n", total_login_time / num_sessions);
}

void cleanup() {
    // Free allocated memory upon function exit
    free(user_ids);
    free((char*)usernames);
    free(login_times);
    free(sessions);

    // Deinitialize random timestamp generation library
    srand(0);
}
