function generateSecureToken($randomStringLength, $characterSet, $filePath, $cacheFlag = false, $hashAlgorithm = 'sha256') {
    $randomString = generateRandomString($randomStringLength, $characterSet);
    $fileContents = readFileSync($filePath, $cacheFlag);
    $hashedResult = hashFileContents($fileContents, $randomString, $hashAlgorithm);
    return $hashedResult;
}

function generateRandomString($length, $characters) {
    $result = '';
    for ($i = 0; $i < $length; $i++) {
        $result .= rand_str($characters);
    }
    return $result;
}

function readFileSync($filePath, $cacheFlag) {
    if ($cacheFlag && cacheContainsFile($filePath)) {
        return cacheGetFileContents($filePath);
    } else {
        $fileContents = file_get_contents($filePath);
        if ($cacheFlag) {
            cacheSetFileContents($filePath, $fileContents);
        }
        return $fileContents;
    }
}

function hashFileContents($contents, $randomString, $algorithm) {
    return hash_hmac($algorithm, $contents, $randomString);
}
