char* pokemon_weaknesses(struct Pokemon p) {
    // Initialize random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, 100);

    // Dynamic memory allocation for arrays
    long* offset = (long*)malloc(sizeof(long) * 10);
    int* key = (int*)malloc(sizeof(int) * 5);
    struct record* record_array = (struct record*)malloc(sizeof(struct record) * 15);

    // Initialize 'offset' and 'key' arrays
    for (int i = 0; i < 10; i++) {
        offset[i] = i * 2;
    }
    for (int i = 0; i < 5; i++) {
        key[i] = i + 1;
    }

    // Initialize 'record' array with random integers
    for (int i = 0; i < 15; i++) {
        record_array[i].value = dis(gen) % 100;
    }

    // Validate integrity and print arrays
    if (p.type != 2 || p.stats != 10) {
        printf("Error: Invalid Pokemon data\n");
    } else {
        for (int i = 0; i < 10; i++) {
            printf("Offset %d: %ld\n", i, offset[i]);
        }
        for (int i = 0; i < 5; i++) {
            printf("Key %d: %d\n", i, key[i]);
        }
    }

    // Determine weaknesses based on Pokemon type and stats
    char* weakness_str;
    if (p.type == 1) { // Fire-type Pokemon
        if (p.stats > 50) {
            weakness_str = "Water";
        } else {
            weakness_str = "Electric";
        }
    } else if (p.type == 2) { // Water-type Pokemon
        if (p.stats > 70) {
            weakness_str = "Fire";
        } else {
            weakness_str = "Grass";
        }
    }

    // Dynamically allocate memory for weakness string
    int str_len = strlen(weakness_str);
    char* result = (char*)malloc(sizeof(char) * (str_len + 1));
    strcpy(result, weakness_str);

    // Deinitialize random number generator
    rd.seed(gen());

    // Free allocated memory
    free(offset);
    free(key);
    for (int i = 0; i < 15; i++) {
        free(&record_array[i]);
    }
    free(record_array);
    free(result);

    return result;
}
