#include <string.h>
#include <math.h>
#include <rand.h>

// Define an item struct to hold a double value and char* description
typedef struct {
    double value;
    char* description;
} Item;

// Function to manage a collection of items dynamically allocating memory
void addItem(Item** items, int* capacity, int currentSize, const char* desc) {
    // If the current size exceeds the capacity, reallocate memory
    if (currentSize >= *capacity) {
        *capacity *= 2; // Double the capacity for efficient memory usage
        *items = realloc(*items, sizeof(Item*) * *capacity);
    }

    Item* item = &((*items)[currentSize]);
    strcpy(item->description, desc);

    // Set the item's value to a random floating-point number within a specified range
    item->value = (double)rand() / RAND_MAX;
}

// Function to handle memory deallocation upon cleanup
void cleanUp(Item** items, int capacity) {
    if (*items != NULL) {
        for (int i = 0; i < capacity; i++) {
            free((*items)[i].description);
        }
        free(*items);
    }
}
