// Function prototypes
void* mem_init(int n, int m, int min_val, int max_val);
void mem_cleanup(void** ptrs);

// Memory management function implementation
void* mem_init(int n, int m, int min_val, int max_val) {
    // Allocate memory for offset values array
    long* offsets = (long*)malloc((n + 1) * sizeof(long));
    if (!offsets) return NULL;  // Handle allocation error

    // Initialize each long offset to the index multiplied by 10
    for (int i = 0; i <= n; i++) {
        offsets[i] = i * 10;
    }

    // Allocate memory for key values array
    int* keys = (int*)malloc((n + 1) * sizeof(int));
    if (!keys || !offsets) return NULL;  // Handle allocation error

    // Initialize each key value to a random value within the specified range
    srand(time(NULL));  // Seed for randomness
    for (int i = 0; i <= n; i++) {
        int val;
        do {
            val = min_val + rand() % ((max_val - min_val) + 1);
        } while (val < min_val || val > max_val);  // Validate random value generation
        keys[i] = val;
    }

    // Allocate memory for record structures array
    struct record* records = (struct record*)malloc(m * sizeof(struct record));
    if (!records) return NULL;  // Handle allocation error

    // Initialize each record's int field to the index multiplied by 10 and set long offset pointer
    for (int i = 0; i < m; i++) {
        records[i].val = i * 10;
        records[i].offset = &offsets[i];
    }

    return records;
}

// Custom cleanup mechanism function implementation
void mem_cleanup(void** ptrs) {
    // Free allocated memory blocks in reverse order of allocation to avoid dangling pointers
    for (int i = m - 1; i >= 0; i--) {
        free(ptrs[i]);
    }
}
