void initialize_data_structures(long *offsets, int num_offsets, int *keys, int num_keys, record **records, int *num_records) {
    int i, j;
    long value;
    record *record_ptr;

    // Allocate memory for the records array
    if((*num_records = (int *)malloc(num_records * sizeof(int))) == NULL) {
        fprintf(stderr, "Error: Unable to allocate memory for num_records.\n");
        exit(EXIT_FAILURE);
