                exit(EXIT_FAILURE);
            }

            // Populate the record structure
            record_ptr->value = value;
            record_ptr->key = keys[i % num_keys];
            record_ptr->status = 'V';  // Default status: Valid

            // Add metadata (assuming fixed-length metadata)
