void processAndFindMaxWithJsonParsing(int argc, char** argv) {
    int offset_count = 0;
    int key_count = 0;

    // Initialize arrays
    long* offsets = (long*)malloc(100 * sizeof(long));
    int* keys = (int*)malloc(100 * sizeof(int));
    record_t* records = (record_t*)malloc(100 * sizeof(record_t));
    metadata_t* metadata = (metadata_t*)malloc(100 * sizeof(metadata_t));

    // Initialize 'offset' and 'key' arrays
    for(int i = 0; i < offset_count; i++) {
        offsets[i] = rand();
        keys[i] = rand();
    }

    // Fill 'record' array with random integers
    for(int i = 0; i < 100; i++) {
        records[i].value = rand() % 100;
    }

    // Populate 'metadata' array with unique string identifiers and current timestamps
    for(int i = 0; i < 100; i++) {
        metadata[i].id = (char*)malloc(20 * sizeof(char));
        strcpy(metadata[i].id, "record_");
        itoa(i, (char*)malloc(3 * sizeof(char)), 10);
        strcat(metadata[i].id, itoa(i, (char*)malloc(3 * sizeof(char)), 10));
        metadata[i].timestamp = time(NULL);
    }

    // Handle JSON input
    json_object* root = json_object_from_file("input.json");

    if(json_object_object_get(root, "requests")) {
        json_object* requests = json_object_object_get(root, "requests");

        int request_count = 0;

        for(int i = 0; i < request_count; i++) {
            json_object* request = json_object_object_get(requests, "request");

            if(request) {
                // Process each request
                long offset = (long)json_object_get_int_value(json_object_object_get(request, "offset"));
                int key = (int)json_object_get_int_value(json_object_object_get(request, "key"));

                // Add to the corresponding arrays
                offsets[offset_count] = offset;
                keys[key_count] = key;
                record_t record;
                record.value = rand() % 100;
                records[request_count].value = record.value;
                metadata[request_count].id = (char*)malloc(20 * sizeof(char));
                strcpy(metadata[request_count].id, "record_");
                itoa(request_count, (char*)malloc(3 * sizeof(char)), 10);
                strcat(metadata[request_count].id, itoa(request_count, (char*)malloc(3 * sizeof(char)), 10));
                metadata[request_count].timestamp = time(NULL);

                request_count++;
            }
        }

        // Calculate average response time
        long total_response_time = 0;

        for(int i = 0; i < request_count; i++) {
            total_response_time += json_object_get_int_value(json_object_object_get(requests, "request")) % 100;
        }

        double average_response_time = (double)total_response_time / request_count;

        printf("Average response time: %.2f\n", average_response_time);
    }

    // Clean up memory
    free(offsets);
    free(keys);
    for(int i = 0; i < request_count; i++) {
        free(metadata[i].id);
    }
    free(metadata);

    // Print the largest integer in 'records' array using helper function
    int max_value = findMaxValue(records, request_count);

    printf("Largest value: %d\n", max_value);

    return;
}

int findMaxValue(record_t* records, int count) {
    int max_value = 0;

    for(int i = 0; i < count; i++) {
        if(records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

    return max_value;
}
