#include <stdlib.h>
#include <stdio.h>

typedef struct info {
    char* string;
    int integer;
} info;

typedef struct data_entry {
    int num;
    double value;
    info* infoptr;
} data_entry;

// Define a memory pool for reuse of structures
void* mempool_new(int size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    return ptr;
}

void mempool_free(void* ptr) {
    free(ptr);
}

// Design a data structure to manage the collection
typedef struct collection {
    data_entry** entries;
    int size;
    int capacity;
} collection;

collection* collection_new(int initialCapacity) {
    collection* coll = (collection*)mempool_new(sizeof(collection));
    coll->entries = (data_entry**)mempool_new(initialCapacity * sizeof(data_entry*));
    coll->size = 0;
    coll->capacity = initialCapacity;
    return coll;
}

void collection_free(collection* coll) {
    for (int i = 0; i < coll->size; ++i) {
        mempool_free(coll->entries[i]);
    }
    mempool_free(coll->entries);
    mempool_free(coll);
}

// Implement methods for adding, removing, and querying entries
void collection_add(collection* coll, int num, double value, char* string, int integer) {
    if (coll->size >= coll->capacity) {
        // Reallocate memory to increase capacity
        int newCapacity = coll->capacity * 2;
        data_entry** newEntries = (data_entry**)mempool_new(newCapacity * sizeof(data_entry*));
        for (int i = 0; i < coll->size; ++i) {
            newEntries[i] = coll->entries[i];
        }
        mempool_free(coll->entries);
        coll->entries = newEntries;
        coll->capacity = newCapacity;
    }
    coll->entries[coll->size] = (data_entry*)mempool_new(sizeof(data_entry));
    coll->entries[coll->size]->num = num;
    coll->entries[coll->size]->value = value;
    coll->entries[coll->size]->infoptr = (info*)mempool_new(sizeof(info));
    ((info*)coll->entries[coll->size]->infoptr)->string = string;
    ((info*)coll->entries[coll->size]->infoptr)->integer = integer;
    ++coll->size;
}

void collection_remove(collection* coll, int index) {
    if (index < 0 || index >= coll->size) {
        printf("Index out of bounds!\n");
        return;
    }
    // Free memory allocated for the entry
    mempool_free(coll->entries[index]->infoptr);
    mempool_free(coll->entries[index]);
    // Shift remaining entries down to fill the gap
    for (int i = index; i < coll->size - 1; ++i) {
        coll->entries[i] = coll->entries[i + 1];
    }
    --coll->size;
}

data_entry* collection_get(collection* coll, int index) {
    if (index < 0 || index >= coll->size) {
        printf("Index out of bounds!\n");
        return NULL;
    }
    return coll->entries[index];
}
