using namespace std;

struct record {
    char status;
    int value;
    string* str_ptr;
};

record* create_record(int num) {
    random_device rd;
    mt19937 gen(rd());
    uniform_int_distribution<> dis(1, 100);

    record* new_rec = new record;
    new_rec->status = (dis(gen) % 2 == 0 ? 'S' : 'F');
    new_rec->value = dis(gen);
    new_rec->str_ptr = new string(100, '\0');

    return new_rec;
}

void free_all(record* head) {
    while (head != nullptr) {
        record* temp = head;
        head = head->next;
        delete temp->str_ptr;
        delete temp;
    }
}

record* insert_string(forward_list<string>& lst, string target_str, string insert_str) {
    for (auto it = lst.begin(); it != lst.end(); ++it) {
        if (*it == target_str) {
            auto new_str = new string(insert_str);
            record* new_rec = create_record(0);
            new_rec->str_ptr = new_str;
            record* temp = head;
            while (temp != nullptr && temp->value < 10) {
                temp = temp->next;
            }
            head = new record;
            head->next = temp;
            return head;
        }
    }
    auto new_str = new string(insert_str);
    record* new_rec = create_record(0);
    new_rec->str_ptr = new_str;
    record* temp = head;
    while (temp != nullptr && temp->value < 10) {
        temp = temp->next;
    }
    head = new record;
    head->next = temp;
    return head;
}

int main() {
