```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <random>
#include <string>
#include <vector>
#include <map>

using namespace std;

struct record {
    int value;
};

void manageGameAndDataStreams(int numStreams, int streamSize) {
    // Initialize data streams
    map<int, vector<record>*> streams(numStreams);

    for (int i = 0; i < numStreams; i++) {
        streams[i] = new vector<record>();
        for (int j = 0; j < streamSize; j++) {
            record temp;
            temp.value = rand() % 100 + 1;
            streams[i]->push_back(temp);
        }
    }

    // Initialize game state
    int selectedAttack = -1;
    chrono::time_point<chrono::system_clock> lastUpdate;
    chrono::seconds cooldown[3] = {chrono::seconds(9), chrono::seconds(15), chrono::seconds(21)};

    while (true) {
        if (selectedAttack != -1) {
            auto now = chrono::system_clock::now();
            auto delta = now - lastUpdate;
            if (delta >= cooldown[selectedAttack]) {
                selectedAttack = -1;
            }
        }

        // Select next attack
        int newAttack = rand() % 3;
        while (selectedAttack == newAttack) {
            newAttack = rand() % 3;
        }
        selectedAttack = newAttack;

        cout << "Selected attack: " << selectedAttack + 1 << endl;
        lastUpdate = chrono::system_clock::now();

        // Print stream contents
        for (auto& stream : streams) {
            cout << "Stream contents: ";
            for (auto& record : *stream.second) {
                cout << record.value << " ";
            }
            cout << endl;
        }

        this_thread::sleep_for(chrono::seconds(1));
    }

    // Deallocate memory
    for (auto& stream : streams) {
        delete stream.second;
    }
}

int main() {
    manageGameAndDataStreams(3, 10);
    return 0;
}
