function processStringAndDOM(str, sizeLimit, selector, testFunc, syncMode, config = {}) {
  if (str.length > sizeLimit) return [];

  const modifiedStr = str.endsWith('/') ? str : `${str}/`;

  let matchingElements = [];
  let maxDepth = config.maxDepth || 100;
  let performanceThreshold = config.performanceThreshold || 0.5;
  let lazyLoadingEnabled = config.lazyLoading;

  function traverseDOM(node, depth = 0) {
    if (depth > maxDepth) return;

    const matches = testFunc(node);
    if (matches) matchingElements.push(node);

    if (!lazyLoadingEnabled && depth < performanceThreshold * node.childElementCount) {
      for (const child of node.children) {
        traverseDOM(child, depth + 1);
      }
    } else {
      for (const child of node.children) {
        setTimeout(() => traverseDOM(child, depth + 1), 0);
      }
    }
  }

  if (syncMode) {
    traverseDOM(document.querySelector(selector));
    return matchingElements;
  } else {
    return new Promise((resolve, reject) => {
      traverseDOM(document.querySelector(selector));
      resolve(matchingElements);
    });
  }
}
