// Structure definitions
typedef struct {
    double measurement;
    char *identifier;
    time_t timestamp;
} event_t;

typedef struct {
    int log_level;
    char *message;
    time_t timestamp;
} log_entry_t;

typedef struct {
    int min;
    int max;
    double average;
} statistics_t;

typedef struct {
    char *description;
    int version;
} metadata_t;

// Function to calculate MD5 hash for a file
void calc_md5_hash(const char *file_path, unsigned char *hash) {
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) return;

    EVP_MD_CTX md_ctx;
    EVP_MD *md = EVP_md5();
    unsigned char md_value[EVP_MAX_MD_SIZE];
    int md_len = sizeof(md_value);

    EVP_DigestInit_ex(&md_ctx, md, 0);
    EVP_DigestUpdate(&md_ctx, file_path, strlen(file_path));
    EVP_DigestFinal_ex(&md_ctx, md_value, &md_len);

    for (int i = 0; i < md_len; i++) {
        hash[i] = md_value[i];
    }

    fclose(file);
}

void processAndAggregateData(int num_measurements) {
    // Initialize arrays
    event_t *events = (event_t *)malloc(num_measurements * sizeof(event_t));
    log_entry_t *log_entries = (log_entry_t *)malloc(num_measurements * sizeof(log_entry_t));
    statistics_t *statistics = (statistics_t *)malloc(num_measurements * sizeof(statistics_t));
    metadata_t *metadata = (metadata_t *)malloc(1 * sizeof(metadata_t));

    // Initialize random timestamp and identifier generators
    srand(time(NULL));
    struct tm *timestamp;
    char buffer[32];

    for (int i = 0; i < num_measurements; i++) {
        // Generate random timestamp and identifier
        timestamp = localtime(&i);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timestamp);
        events[i].measurement = (double)i;
        events[i].identifier = malloc(strlen(buffer) + 1);
        strcpy(events[i].identifier, buffer);
        events[i].timestamp = time(NULL);

        // Initialize log entry
        log_entries[i].log_level = i % 2 ? LOG_INFO : LOG_ERROR;
        log_entries[i].message = malloc(strlen(buffer) + 10);
        sprintf(log_entries[i].message, "%s: Measurement %d", buffer, i);
        log_entries[i].timestamp = time(NULL);

        // Initialize statistics
        statistics[i].min = i;
        statistics[i].max = i;
        statistics[i].average = (double)i;

        // Initialize metadata
        metadata->description = malloc(strlen(buffer) + 15);
        sprintf(metadata->description, "Metadata for measurements %d to %d", 0, num_measurements - 1);
        metadata->version = i % 2 ? 1 : 2;
    }

    // Calculate MD5 hash for file
    unsigned char md_hash[EVP_MAX_MD_SIZE];
    calc_md5_hash("example.txt", md_hash);

    // Free allocated memory
    for (int i = 0; i < num_measurements; i++) {
        free(events[i].identifier);
        free(log_entries[i].message);
    }

    free(events);
    free(log_entries);
    free(statistics);
    free(metadata->description);

    printf("Memory freed successfully.\n");
}
