    // Initialize temperature array with specific values
    for (int i = 0; i < days; i++) {
        data.temperatures[i] = (double)(rand() % 100 + 1); // Replace with actual logic
    }

    // Initialize timestamp array with sequential timestamps starting from epoch
    time_t epoch = (time_t)0;
    for (int i = 0; i < days; i++) {
        data.timestamps[i] = epoch++;
    }

    return data;
}

double computeAverageTemp(struct TempData* data, int days) {
    if (days == 0)
        return -1.0; // Handle edge case where time span is zero

    double sum = 0.0;
    for (int i = 0; i < days; i++) {
        sum += data->temperatures[i];
    }
    return sum / days;
}

