void addProfileData(long id, float score, const char* status) {
    if(profileData == NULL || profileDataCount >= 100) {
        printf("No more space for profiles. Resizing the array.\n");
        // Resize and reallocate
        ProfileData* temp = (ProfileData*) realloc(profileData, sizeof(ProfileData) * (profileDataCount + 10));
        profileData = temp;
    }
    profileData[profileDataCount].id = id;
    profileData[profileDataCount].score = score;
    strcpy(profileData[profileDataCount].status, status);
    profileDataCount++;
}

void serializeProfileData() {
    FILE* file = fopen("profiles.bin", "wb");
    if(file == NULL) {
        printf("Could not open file for writing.\n");
        return;
    }

    int i;
    fwrite(&profileDataCount, sizeof(size_t), 1, file);
    for(i = 0; i < profileDataCount; i++) {
        fwrite(&profileData[i], sizeof(ProfileData), 1, file);
    }
    fclose(file);
}

void deserializeProfileData() {
    FILE* file = fopen("profiles.bin", "rb");
    if(file == NULL) {
        printf("Could not open file for reading.\n");
        return;
    }

    size_t profileCount;
    fread(&profileCount, sizeof(size_t), 1, file);

    profileData = (ProfileData*) malloc(sizeof(ProfileData) * profileCount);

    int i;
    for(i = 0; i < profileCount; i++) {
        fread(&profileData[i], sizeof(ProfileData), 1, file);
    }

    fclose(file);
}
