        strcpy(eventLogs[i]->filePath, "");
        eventLogs[i]->sharedData = NULL;
        eventLogs[i]->threadStatus = 0;
    }

    FILE* file = fopen("example.txt", "rb");
    if (file) {
        fseek(file, 0, SEEK_END);
        long fileSize = ftell(file);
        rewind(file);

        unsigned char* fileContent = (unsigned char*)malloc((size_t)fileSize + 1);
        fread(fileContent, 1, (size_t)fileSize, file);
        fclose(file);

        MD5_CTX ctx;
        MD5Init(&ctx);
        MD5Update(&ctx, fileContent, fileSize);
        MD5Final(&ctx, eventLogs[0]->md5Hash);

        free(fileContent);
    }

    return *eventLogs;
}

void releaseResources(EventLog** eventLogs) {
