#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int value;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    long* offsets;
    int* keys;
    int maxEntries;
} DoublyLinkedList;

DoublyLinkedList* dllCreate(int maxEntries) {
    DoublyLinkedList* dll = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    dll->head = NULL;
    dll->tail = NULL;
    dll->offsets = (long*)malloc(maxEntries * sizeof(long));
    dll->keys = (int*)malloc(maxEntries * sizeof(int));
    dll->maxEntries = maxEntries;
    return dll;
}

void dllDelete(DoublyLinkedList* dll) {
    if (dll == NULL) return;
    free(dll->offsets);
    free(dll->keys);
    free(dll);
}

Node* nodeCreate(int value) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->value = value;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void dllInsert(DoublyLinkedList* dll, int key, long offset) {
    if (dll == NULL || key < 0 || key >= dll->maxEntries) return;

    Node* node = nodeCreate(key);
    node->value = rand() % 100; // Initialize with a random value
    if (dll->head == NULL) {
        dll->head = node;
        dll->tail = node;
    } else {
        if (offset < dll->offsets[0]) {
            node->next = dll->head;
            dll->head->prev = node;
            dll->head = node;
        } else if (offset > dll->offsets[dll->maxEntries - 1]) {
            node->prev = dll->tail;
            dll->tail->next = node;
            dll->tail = node;
        } else {
            Node* current = dll->head;
            while (current != NULL && offset > dll->offsets[current->value]) {
                current = current->next;
            }
            if (current == NULL) {
                node->prev = dll->tail;
                dll->tail->next = node;
                dll->tail = node;
            } else {
                node->next = current;
                node->prev = current->prev;
                current->prev->next = node;
                current->prev = node;
            }
        }
    }
    dll->offsets[key] = offset;
}

void dllPrint(DoublyLinkedList* dll) {
    Node* current = dll->head;
    while (current != NULL) {
        printf("Key: %d, Value: %d\n", current->value, current->value);
        current = current->next;
    }
}
