    if (num_entries <= 0) {
        return NULL;
    }

    DataEntry* entries = (DataEntry*)malloc(num_entries * sizeof(DataEntry));
    if (!entries) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_entries; i++) {
        int new_id = rand() % ((max_id - min_id) + 1) + min_id;
        while (entries[i].id != 0 || entries[i].value > threshold) {
            new_id = rand() % ((max_id - min_id) + 1) + min_id;
            entries[i].id = new_id;
            entries[i].value = (float)rand() / RAND_MAX * threshold;
        }
    }

    return entries;
}
