// Define structure for linked list node
typedef struct Node {
    int key;
    long offset;
    double value;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to initialize and manage doubly linked list
Node* initDoublyLinkedList(int maxEntries) {
    // Initialize arrays for offset, key, and value
    long* offsets = (long*)malloc(maxEntries * sizeof(long));
    int* keys = (int*)malloc(maxEntries * sizeof(int));
    double* values = (double*)malloc(maxEntries * sizeof(double));

    // Initialize random number generator
    srand(time(NULL));

    // Initialize linked list and nodes
    Node* head = NULL;
    Node* tail = NULL;

    for (int i = 0; i < maxEntries; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->key = rand() % 100;
        newNode->offset = (long)i;
        newNode->value = (double)(rand() % 100);
        newNode->prev = NULL;
        newNode->next = NULL;

        // Add node to list
        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            newNode->prev = tail;
            tail = newNode;
        }
    }

    // Free memory for arrays
    free(offsets);
    free(keys);
    free(values);

    return head;
}

// Function to insert a new node into the linked list
void insertNode(Node** head, int key) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->key = key;
    newNode->offset = (long)srand(time(NULL)) % 1000;
    newNode->value = (double)(srand(time(NULL)) % 100);
    newNode->prev = NULL;
    newNode->next = NULL;

    if (*head == NULL) {
        *head = newNode;
        (*head)->prev = NULL;
        (*head)->next = NULL;
    } else {
        (*head)->prev = newNode;
        newNode->next = *head;
        *head = newNode;
    }
}

// Function to remove a node from the linked list
void removeNode(Node** head, int key) {
    Node* current = *head;
    Node* prev = NULL;

    while (current != NULL && current->key != key) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        printf("Key not found in the linked list.\n");
    } else {
        if (prev == NULL) {
            *head = current->next;
        } else {
            prev->next = current->next;
        }
        free(current);
    }
}

int main() {
    // Initialize linked list with 10 entries
    Node* head = initDoublyLinkedList(10);

    // Insert a new node into the linked list
    insertNode(&head, 55);

    // Remove a node from the linked list
    removeNode(&head, 25);

    return 0;
}
