#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000
#define MAX_MEMORY_PER_ALLOCATION (5 * 1024 * 1024)
#define MEMORY_THRESHOLD (200 * 1024 * 1024)

typedef struct {
    long offset;
    int key;
    int value;
} Record;

Record* allocateRecords(int numRecords) {
    if (numRecords > MAX_RECORDS || numRecords <= 0) return NULL;

    int initialAllocation = numRecords;
    Record* records = NULL;
    size_t totalMemoryUsed = 0;

    for (int i = 0; i < numRecords; i += initialAllocation) {
        int currentAllocation = ((i + initialAllocation > numRecords) ? numRecords - i : initialAllocation);
        void* ptr = malloc(currentAllocation * sizeof(Record));

        if (!ptr) {
            printf("Memory allocation failed.\n");
            return NULL;
        }

        records = (Record*) realloc(records, (i + currentAllocation) * sizeof(Record));
        totalMemoryUsed += currentAllocation * sizeof(Record);

        for (int j = 0; j < currentAllocation; j++) {
            Record* record = &((Record*) ptr)[j];
            record->offset = rand() % 10000000;
            record->key = rand() % 1000;
            record->value = rand() % 1000;
        }

        if (totalMemoryUsed > MEMORY_THRESHOLD) {
            printf("Memory usage exceeded threshold.\n");
            return NULL;
        }
    }

    return records;
}

void freeRecords(Record* records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free((void*) &records[i]);
    }

    free(records);
}
