// Define a custom hash table struct
typedef struct {
    int key;
    int value;
    long timestamp;
} record_t;

// Custom hash table with quadratic probing
void* hash_table_new(size_t size) {
    void* table = malloc(sizeof(record_t*) * size);
    return table;
}

int hash_function(void* key, size_t size) {
    return (size_t)(*(int*)key) % size;
}

record_t* probe(hash_table_t* table, int key, int size) {
    record_t* slot = (record_t*)table->slots + hash_function(key, size);
    while (slot->key != key && slot->key != -1) {
        slot++;
    }
    return slot;
}

void hash_insert(hash_table_t* table, int key, int value, long timestamp) {
    record_t* slot = probe(table, key, table->size);
    if (slot->key == -1) {
        // New entry
        slot->key = key;
        slot->value = value;
        slot->timestamp = timestamp;
    } else {
        // Duplicate key, skip allocation
        printf("Duplicate key %d skipped.\n", key);
    }
}

void* metadata_new(size_t size) {
    void* table = malloc(sizeof(int*) * size);
    return table;
}

int main() {

    // Define the four distinct data structures
    long offset_values[1000];
    int keys[1000];
    record_t records[1000];
    int metadata_tags[1000];

    // Initialize the hash table for `record` structures
    hash_table_t* record_hash = hash_table_new(1024);
    for (int i = 0; i < 1000; i++) {
        record_insert(record_hash, i, i * 2, time(NULL));
    }

    // Update offset values periodically based on the specified interval
