record** initializeRecords(int* numProcessed, int* secondaryTrack) {
    int numRecords = 1000;
    int maxKey = 500;
    int maxOffset = 1000;

    record** records = (record**)malloc(numRecords * sizeof(record));
    if (!records) return NULL; // handle memory allocation failure

    for (int i = 0; i < numRecords; i++) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) return NULL; // handle memory allocation failure

        int key = rand() % (maxKey + 1);
        while (key >= maxKey) key = rand() % (maxKey + 1); // ensure no duplicates
        records[i]->key = key;

        int offset = rand() % (maxOffset + 1);
        while (offset > maxOffset || records[offset / (maxOffset / numRecords)] != NULL) {
            offset = rand() % (maxOffset + 1);
        }
        records[i]->offset = offset;

        records[i]->status = false;
    }

    for (int i = 0; i < numRecords; i++) {
        int key = records[i]->key;
        if (rand() % 4 == 0) {
            records[i]->status = true;
        }
        secondaryTrack[key] = i;
    }

    *numProcessed = rand() % numRecords + 1; // select 25% of the records
    for (int i = 0; i < *numProcessed; i++) {
        int j = rand() % numRecords;
        while (records[j]->status) {
            j = rand() % numRecords;
        }
        records[j]->status = true;
    }

    return records;
}

void freeRecords(record** records, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        if (records[i]) free(records[i]);
    }
    free(records);
}
