#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum capacity for each data structure
#define MAX_DOUBLE 1000
#define MAX_CHAR 256
#define MAX_STRUCT 1000

// Data structures with dynamic resizing
typedef struct {
    double* values;
    size_t len, cap;
} DoubleArray;

typedef struct {
    char** strings;
    size_t len, cap;
} CharArray;

typedef struct {
    int* ints;
    float* floats;
    size_t len, cap;
} StructArray;

// Function to manage memory allocation and dynamic resizing
void* resize(void* ptr, size_t new_len) {
    // Check if the pointer is NULL
    if (!ptr) return NULL;

    // Get the original length and capacity
    size_t orig_len = 0, orig_cap = 0;
    switch (ptr) {
        case ((DoubleArray*) ptr)->values:
            orig_len = ((DoubleArray*) ptr)->len;
            orig_cap = ((DoubleArray*) ptr)->cap;
            break;
        case ((CharArray*) ptr)->strings:
            orig_len = ((CharArray*) ptr)->len;
            orig_cap = ((CharArray*) ptr)->cap;
            break;
        case ((StructArray*) ptr)->ints:
            orig_len = ((StructArray*) ptr)->len;
            orig_cap = ((StructArray*) ptr)->cap;
            break;
    }

    // Calculate the new capacity
    size_t new_cap = (new_len > 1) ? (orig_cap * 2) : MAX_DOUBLE;

    // Allocate memory for the new data structure
    void* new_ptr = NULL;
    switch (ptr) {
        case ((DoubleArray*) ptr)->values:
            new_ptr = malloc(sizeof(double) * new_cap);
            break;
        case ((CharArray*) ptr)->strings:
            new_ptr = malloc(sizeof(char*) * new_cap);
            break;
        case ((StructArray*) ptr)->ints:
            new_ptr = malloc(sizeof(int) + sizeof(float) * new_cap);
            break;
    }

    // Copy the original data to the new location
    if (new_ptr) {
        switch (ptr) {
            case ((DoubleArray*) ptr)->values:
                memcpy(new_ptr, ((DoubleArray*) ptr)->values, orig_len * sizeof(double));
                break;
            case ((CharArray*) ptr)->strings:
                for (size_t i = 0; i < orig_len; ++i)
                    memcpy((char**) new_ptr + i, ((CharArray*) ptr)->strings + i, sizeof(char*));
                break;
            case ((StructArray*) ptr)->ints:
                memcpy(new_ptr, ((StructArray*) ptr)->ints, orig_len * sizeof(int));
                for (size_t i = 0; i < orig_len; ++i)
                    memcpy((float*)((char*)new_ptr + sizeof(int) * i), &((StructArray*) ptr)->floats[i], sizeof(float));
                break;
        }
    }

    // Free the original memory
    free(ptr);

    return new_ptr;
}

// Initialize a data structure with initial capacity and length
void init(DoubleArray* arr, size_t cap, size_t len) {
    arr->values = malloc(sizeof(double) * cap);
    arr->len = len;
    arr->cap = cap;
}

void init(CharArray* arr, size_t cap, size_t len) {
    arr->strings = malloc(sizeof(char*) * cap);
    arr->len = len;
    arr->cap = cap;
}

void init(StructArray* arr, size_t cap, size_t len) {
    arr->ints = malloc(sizeof(int) * cap);
    arr->floats = malloc(sizeof(float) * cap);
    arr->len = len;
    arr->cap = cap;
}

// Print memory usage statistics
void print_stats(size_t curr_usage, size_t peak_usage) {
    printf("Current memory usage: %zu MB\n", curr_usage / (1024 * 1024));
    printf("Peak memory usage: %zu MB\n", peak_usage / (1024 * 1024));
}

int main() {
    // Example usage
    DoubleArray arr1;
    init(&arr1, MAX_DOUBLE, 0);

    CharArray arr2;
    init(&arr2, MAX_CHAR, 0);

    StructArray arr3;
    init(&arr3, MAX_STRUCT, 0);

    // Dynamically resize and manage memory allocation
    arr1.values = resize(arr1.values, arr1.len + 10);
    arr2.strings = resize(arr2.strings, arr2.len + 5);
    arr3.ints = resize(arr3.ints, arr3.len + 20);

    return 0;
}
