            Console.Write(_keys[i] + " ");
        Console.WriteLine();

        Console.WriteLine("Records:");
        for (int i = 0; i < _records.Length; i++)
            Console.WriteLine($"Record {i}: {_records[i].Value}");
    }

    public override string ToString()
    {
        return $"RandomValueGenerator - Record values: {GetRecordRange()}";
    }

    private void InitializeOffsetsAndKeys(int offsetSize, int keySize)
    {
        // initialize offsets and keys
    }

    private void InitializeRecords(int recordSize)
    {
        for (int i = 0; i < recordSize; i++)
            _records[i].Value = _rng.Next(1, 100); // random integer between 1 and 100
    }

    public float GenerateRandomFloat()
    {
        return (float)_rng.NextDouble();
    }

    public int GenerateRandomInt(bool inclusive)
    {
        if (!inclusive)
        {
            // exclude the end value
        }
        return _rng.Next(1, 100); // random integer between 1 and 100
    }

    private string GetRecordRange()
    {
        int min = _records[0].Value;
        int max = _records[0].Value;

        for (int i = 1; i < _records.Length; i++)
        {
            if (_records[i].Value < min)
                min = _records[i].Value;
            else if (_records[i].Value > max)
                max = _records[i].Value;
        }

        return $"Range: {min} - {max}";
    }
}
