            status_stack[i] = STATUS_PROCESSED;
        } else {
            status_stack[i] = STATUS_INITIAL;
        }
    }

    // Free allocated memory
    for (int i = 0; i < num_streams; i++) {
        if (i % 2 == 0) {
            free(record_stack[i]);
        } else {
            free(record_stack[i]->value);
        }
    }

    // Reset used resources...
