        offsets[i] = i * 10;
        keys[i] = i % 2;
        if (i % 2 == 0) {
            records[i] = malloc(sizeof(record_t));
            record_ids[i] = rand();
            timestamps[i] = alloca(1);
            strcpy(timestamps[i][0], "timestamp");
