#include <stdlib.h>
#include <stdio.h>

typedef struct {
    long timestamp;
    int priority;
    double value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
} RecordCollection;

RecordCollection* record_collection_create(size_t initial_capacity) {
    RecordCollection* collection = malloc(sizeof(RecordCollection));
    collection->records = malloc(initial_capacity * sizeof(Record));
    collection->capacity = initial_capacity;
    collection->count = 0;
    return collection;
}

void record_collection_add_record(RecordCollection* collection, long timestamp, int priority, double value) {
    if (collection->count == collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        Record* new_records = realloc(collection->records, new_capacity * sizeof(Record));
        if (!new_records) {
            printf("Error: Memory allocation failed.\n");
            return;
        }
        collection->records = new_records;
        collection->capacity = new_capacity;
    }
    Record* record = &collection->records[collection->count];
    record->timestamp = timestamp;
    record->priority = priority;
    record->value = value;
    collection->count++;
}

void record_collection_update_field(RecordCollection* collection, long timestamp, double value) {
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->records[i].timestamp == timestamp) {
            collection->records[i].value = value;
            return;
        }
    }
}

void record_collection_iterate(RecordCollection* collection, void (*callback)(const Record*)) {
    for (size_t i = 0; i < collection->count; i++) {
        callback(collection->records[i]);
    }
}

void record_collection_free(RecordCollection* collection) {
    free(collection->records);
    free(collection);
}
