#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct record {
    int value;
} Record;

typedef struct node {
    long offset;
    int key;
    Record *data;
    struct node *prev;
    struct node *next;
} Node;

Node *head = NULL;
Node *tail = NULL;
int record_count = 0;

void *malloc_node(size_t size) {
    return malloc(size);
}

void free_node(void *ptr) {
    free(ptr);
}

void insert_record(Node **head, int key, Record *data) {
    Node *new_node = (Node *)malloc_node(sizeof(Node));
    new_node->key = key;
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = (*head);
    if ((*head) != NULL)
        (*head)->prev = &new_node;
    else
        tail = &new_node;
    (*head) = &new_node;
    record_count++;
}

void remove_record(Node **head, int key) {
    Node *current = (*head);
    while (current != NULL && current->key != key)
        current = current->next;
    if (current == NULL)
        return;
    if (current->prev != NULL)
        current->prev->next = current->next;
    else
        (*head) = current->next;
    if (current->next != NULL)
        current->next->prev = current->prev;
    else
        tail = current->prev;
    record_count--;
    free_node(current);
}

void serialize_data(FILE *file) {
    Node *current = head;
    while (current != NULL) {
        fwrite(&current->key, sizeof(int), 1, file);
        fwrite(&current->data->value, sizeof(int), 1, file);
        current = current->next;
    }
}

void deserialize_data(FILE *file) {
    Node *new_node = (Node *)malloc_node(sizeof(Node));
    while (!feof(file)) {
        fread(&new_node->key, sizeof(int), 1, file);
        Record *data = (Record *)malloc_node(sizeof(Record));
        fread(&data->value, sizeof(int), 1, file);
        insert_record(&head, new_node->key, data);
        free_node(new_node);
        new_node = (Node *)malloc_node(sizeof(Node));
    }
}

void *update_data(void *ptr) {
    // update data from external source
    return NULL;
}

void periodic_update() {
    pthread_t thread;
    pthread_create(&thread, NULL, update_data, NULL);
    pthread_join(thread, NULL);
    if (head != NULL)
        remove_record(&head, 0);  // remove any records that were updated
}

int main() {
    FILE *file = fopen("data.bin", "wb");
    serialize_data(file);
    fclose(file);

    periodic_update();

    file = fopen("data.bin", "rb");
    deserialize_data(file);
    fclose(file);

    return 0;
}
