typedef struct {
    double time;
    char* log_message;
} Data;

Data processAndAggregateData(int buffer_size) {
    Data data;

    // Initialize arrays
    double* time = (double*)malloc(buffer_size * sizeof(double));
    char** log_message = (char**)malloc(buffer_size * sizeof(char*));

    int i;
    for(i=0; i<buffer_size; i++) {
        time[i] = (i % 3 == 0) ? 1.5 : 2.25; // Initialize time array
        log_message[i] = NULL;
    }

    char line[256];
    const char* sentinel = "END";

    for(i=0; i<buffer_size; i++) {
        fgets(line, sizeof(line), stdin);
        if(strcmp(line, sentinel) == 0)
            break;
        log_message[i] = (char*)malloc(strlen(line));
        strcpy(log_message[i], line);
    }

    // Free memory
    for(i=0; i<buffer_size; i++) {
        free(log_message[i]);
    }
    free(log_message);

    double total_time = 0.0;
    int max_log_len = 0;

    // Calculate average time and length of longest log message
    for(i=0; i<buffer_size-1; i++) {
        total_time += time[i];
        if(strlen(log_message[i]) > max_log_len)
            max_log_len = strlen(log_message[i]);
    }

    data.time = total_time / buffer_size;
    data.log_message = log_message[buffer_size-1];

    return data;
}
