MetricEvent processAndAggregateMetrics(int* input1, FILE* file1) {
    // Initialize arrays
    float* metrics = (float*)malloc(sizeof(float) * 10);
    int* eventCounts = (int*)malloc(sizeof(int) * 10);
    char** eventDescriptions = (char**)malloc(sizeof(char*) * 10);

    // Initialize metric values
    for (int i = 0; i < 10; i++) {
        metrics[i] = (float)(i + 1.0);
    }

    // Read event counts from file descriptor until sentinel value is encountered
    int readCount = 0;
    while (fscanf(file1, "%d", &eventCounts[readCount]) == 1) {
        if (eventCounts[readCount] == -1) break;
        readCount++;
    }
    eventCounts[readCount] = -1; // Sentinel value

    // Read event descriptions from standard input until sentinel string is encountered
    int descReadCount = 0;
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), stdin)) {
        if (strcmp(buffer, "SENTINEL\n") == 0) break;
        eventDescriptions[descReadCount] = (char*)malloc(strlen(buffer));
        strcpy(eventDescriptions[descReadCount], buffer);
        descReadCount++;
    }
    eventDescriptions[descReadCount] = NULL; // Sentinel string

    // Check for memory usage and print arrays
    printf("Metrics: ");
    for (int i = 0; i < readCount + 1; i++) {
        printf("%f ", metrics[i]);
    }
    printf("\n");
    printf("Event Counts: ");
    for (int i = 0; i < readCount + 1; i++) {
        printf("%d ", eventCounts[i]);
    }
    printf("\n");
    int descLen = 0;
    for (int i = 0; i <= descReadCount; i++) {
        if (eventDescriptions[i] != NULL) {
            printf("Event Descriptions: %s\n", eventDescriptions[i]);
            descLen += strlen(eventDescriptions[i]) + 1;
        }
    }
    if (descLen > 1024) {
        printf("Warning: Total description length exceeds allocated size.\n");
    }

    // Compute average metric, highest event count, and longest event description
    float avgMetric = 0.0;
    int highestCount = -1;
    char* longestDesc = NULL;
    for (int i = 0; i < readCount + 1; i++) {
        avgMetric += metrics[i];
        if (eventCounts[i] > highestCount) highestCount = eventCounts[i];
    }
    avgMetric /= (float)(readCount + 1);
    int maxDescLen = 0;
    for (int i = 0; i <= descReadCount; i++) {
        if (eventDescriptions[i] != NULL) {
            if (strlen(eventDescriptions[i]) > maxDescLen) maxDescLen = strlen(eventDescriptions[i]);
            if (maxDescLen == 0) longestDesc = eventDescriptions[i];
        }
    }

    // Free allocated memory
    for (int i = 0; i <= descReadCount; i++) {
        free(eventDescriptions[i]);
    }
    free(eventDescriptions);
    free(metrics);
    free(eventCounts);

    return (MetricEvent){avgMetric, highestCount, longestDesc};
}
