    int* lineCounts = (int*)malloc(LINE_COUNT_ARRAY_SIZE * sizeof(int));
    int* numericalData = (int*)malloc(NUMERICAL_DATA_ARRAY_SIZE * sizeof(int));
    struct stat* metadata = (struct stat*)malloc(METADATA_ARRAY_SIZE * sizeof(struct stat));

