    }
    for (int i = 0; i < NUMERICAL_DATA_ARRAY_SIZE; i++) {
        numericalData[i] = 0;
    }
    for (int i = 0; i < METADATA_ARRAY_SIZE; i++) {
        metadata[i].st_size = 0;
    }

