        }

        fclose(file);
    }

    // Free memory
    free(lineCounts);
    free(numericalData);
    free(metadata);

    printf("Memory usage: %zu bytes\n", sizeof(int) * (LINE_COUNT_ARRAY_SIZE + NUMERICAL_DATA_ARRAY_SIZE + METADATA_ARRAY_SIZE));
