        printf("{value: %ld, status: %c}\n", metadata[i].value, metadata[i].status);
    }

    // Free allocated memory
    free(data);
    free(timestamp);
    free(label);
    free(metadata);

    // Read CSV from standard input and perform statistical analysis
    char csvLine[MAX_CSV_LINE_LENGTH];
    int dataCount = 0;
    double sum = 0.0, avg = 0.0, median = 0.0, mode = 0.0;

    while (fgets(csvLine, sizeof(char) * MAX_CSV_LINE_LENGTH, stdin)) {
        char* valueStr = strtok(csvLine, ",");
        if (valueStr != NULL && strlen(valueStr) > 0) {
            data[dataCount] = atof(valueStr);
            sum += data[dataCount];
            dataCount++;
        }
    }

    if (dataCount > 0) {
        avg = sum / dataCount;
        qsort(data, dataCount, sizeof(double), compareDouble);
        median = data[(dataCount - 1) / 2];

        // Find mode
        int modeCount[100] = {0};
        for (i = 0; i < dataCount; i++) {
            modeCount[(int)(data[i])]++;
        }
        double maxMode = 0.0;
        for (i = 1; i <= 100; i++) {
            if (modeCount[i] > modeCount[(int)maxMode]) {
                maxMode = (double)i;
            }
        }

        printf("Average: %f\n", avg);
        printf("Median: %f\n", median);
        printf("Mode: %f\n", maxMode);
    }
}

int compareDouble(const void* a, const void* b) {
    double x = *(const double*)a;
    double y = *(const double*)b;

    if (x < y)
        return -1;
    else if (x > y)
        return 1;
    else
        return 0;
}

int main() {
    processAndAnalyzeData();
    return 0;
}
