// Define a structure for LogEntry
typedef struct {
    double time;
    char* logMessage;
} LogEntry;

// Function to process and aggregate data
LogEntry* processAndAggregateData(int numEntries, int bufferTime, int bufferMessages, int* pAverageTime, int* pMaxLength, int* pMaxDiff) {
    // Dynamically allocate memory for arrays
    double* time = (double*)malloc(bufferTime * sizeof(double));
    char** logMessage = (char**)malloc(bufferMessages * sizeof(char*));
    LogEntry* logEntries = (LogEntry*)malloc(bufferMessages * sizeof(LogEntry));

    int i;
    FILE* fp = stdin;
    for(i = 0; i < numEntries; i++) {
        // Read time interval from standard input
        double t;
        scanf("%lf", &t);
        time[i] = t;

        // Read log message from standard input until sentinel string is encountered
        char buffer[256];
        int j = 0;
        while(fgets(buffer, sizeof(buffer), fp) != NULL && strcmp(buffer, "SENTINEL\n") != 0) {
            logMessage[j] = (char*)malloc(strlen(buffer) + 1);
            strcpy(logMessage[j], buffer);
            j++;
        }
        logMessage[j] = NULL;

        // Populate LogEntry array
        for(int k = 0; k < j; k++) {
            logEntries[k].time = time[i];
            logEntries[k].logMessage = logMessage[k];
        }

        // Initialize remaining LogEntry structures to zero
        for(int k = j; k < bufferMessages; k++) {
            logEntries[k].time = 0;
            logEntries[k].logMessage = NULL;
        }
    }

    // Compute average time interval and maximum length of log messages
    double sumTime = 0;
    int maxLength = 0;
    for(i = 0; i < numEntries; i++) {
        sumTime += time[i];
        if(strlen(logMessage[i]) > maxLength) {
            maxLength = strlen(logMessage[i]);
        }
    }
    *pAverageTime = sumTime / numEntries;

    // Determine maximum difference between consecutive log entries
    int maxDiff = 0;
    for(i = 1; i < numEntries; i++) {
        maxDiff = MAX(maxDiff, abs(time[i] - time[i-1]));
    }
    *pMaxLength = maxLength;
    *pMaxDiff = maxDiff;

    // Free allocated memory
    for(i = 0; i < bufferMessages; i++) {
        if(logMessage[i]) free(logMessage[i]);
    }
    free(logMessage);
    free(time);

    return logEntries;
}

int main() {
    int numEntries, bufferTime, bufferMessages;
    double averageTime;
    int maxLength, maxDiff;

    // Load configuration from external system (not shown)
    numEntries = 10;
    bufferTime = 100;
    bufferMessages = 256;

    LogEntry* logEntries = processAndAggregateData(numEntries, bufferTime, bufferMessages, &averageTime, &maxLength, &maxDiff);

    // Print contents of arrays for debugging
    int i;
    printf("Time intervals:\n");
    for(i = 0; i < numEntries; i++) {
        printf("%f\n", logEntries[i].time);
    }
    printf("Log messages:\n");
    for(i = 0; i < bufferMessages; i++) {
        if(logEntries[i].logMessage) printf("%s", logEntries[i].logMessage);
        printf("\n");
    }

    // Compute and print computed metrics
    printf("Average time interval: %f\n", averageTime);
    printf("Maximum length of log message: %d\n", maxLength);
    printf("Maximum difference between consecutive log entries: %d\n", maxDiff);

    return 0;
}
