        printf("Metric: %f, Label: %s, Timestamp: %ld\n", perfMetrics[i].metric, perfMetrics[i].label, perfMetrics[i].timestamp);
    }

    // Calculate and print median metric value
    float* sortedMetrics = (float*)malloc(numMetrics * sizeof(float));
    for (i = 0; i < numMetrics; i++) {
        sortedMetrics[i] = metrics[i];
    }
    qsort(sortedMetrics, numMetrics, sizeof(float), &compareFloats);
    printf("Median Metric Value: %f\n", median(sortedMetrics, numMetrics));

    // Free allocated memory
    for (i = 0; i < numLabels; i++) {
        free(labels[i]);
    }
    free(labels);
    free(metrics);
    free(perfMetrics);

    // Log operation details
    for (i = 0; i < min(numMetrics, numLabels); i++) {
        logOperation(perfMetrics[i].metric, perfMetrics[i].label, perfMetrics[i].timestamp);
    }

    return;
}

int compareFloats(const void* a, const void* b) {
    float fa = *(const float*)a;
    float fb = *(const float*)b;
    if (fa < fb) {
        return -1;
    } else if (fa > fb) {
        return 1;
    } else {
        return 0;
    }
}

float median(float* arr, int n) {
    int start = 0;
    int end = n - 1;

    while (end - start > 0) {
        int mid = start + (end - start) / 2;
        if (mid == 0 || (mid < end && arr[mid] >= arr[mid-1])) {
            start = mid + 1;
        } else {
            end = mid - 1;
        }
    }

    return (n % 2 == 0) ? (arr[start] + arr[start-1]) / 2.0 : arr[start];
}

void logOperation(float metric, char* label, time_t timestamp) {
    printf("Logged operation: Metric = %f, Label = %s, Timestamp = %ld\n", metric, label, timestamp);
}
