    free(offsets);
    free(keys);
    free(records);
}

void* aligned_malloc(size_t size, int alignment) {
    void *ptr = malloc(size + (alignment - 1) * sizeof(void *));
    if (!ptr) {
        printf("Error allocating memory.\n");
        return NULL;
    }

    ptr = (void *)((size_t)ptr + (alignment - 1) * sizeof(void *));
    return ptr;
}

