// Function to initialize and manage dynamic collection of records
Record** initRecords(int* count, long maxOffset) {
    // Initialize static variables
    static int size = 1;
    static Record** records = (Record**)malloc(size * sizeof(Record*));

    if (*count < size || maxOffset > (long)(size - 1) * sizeof(Record)) {
        // Resize array and allocate memory for new records
        size *= 2;
        records = (Record**)realloc(records, size * sizeof(Record*));
    }

    *count = size;

    // Initialize each record with a random value within the range [0, 100]
    srand(time(NULL));
    for (int i = 0; i < *count; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->key = i;
        records[i]->value = rand() % 101;
    }

    return records;
}

// Function to free all allocated memory
void freeRecords(int* count, Record** records) {
    // Iterate over the array of records and free each one
    for (int i = 0; i < *count; i++) {
        free(records[i]);
    }

    // Free the dynamic array itself
    free(records);

    *count = 0;
}

// Example usage:
int main() {
    int count = 0;
    long maxOffset = 1024;

    Record** records = initRecords(&count, maxOffset);

    printf("Initialized %d records.\n", count);

    // Use the records...

    freeRecords(&count, records);

    return 0;
}
