// Node structure definition.
typedef struct {
    char* key;
    double value;
} Node;

// Function to initialize and return an array of nodes from an external data source.
Node* initialize_nodes_from_source(void* data_source, int* count) {
    // Initialize variables
    Node* nodes = NULL;
    *count = 0;

    // Implement data source integration here
    // For example:
    // data_source is a pointer to a file or socket
    FILE* file = (FILE*)data_source;
    if (file == NULL) {
        return NULL; // Handle invalid data source
    }

    // Read nodes from the data source and allocate memory dynamically
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            return nodes; // Handle memory allocation failure
        }

        // Initialize node fields based on the input format
        // For example:
        // assuming key-value pairs separated by commas and a colon
        char* token = strtok(line, ":");
        node->key = malloc(strlen(token) + 1);
        strcpy(node->key, token);
        token = strtok(NULL, ",");
        node->value = atof(token);

        if (nodes == NULL) {
            nodes = node;
        } else {
            Node* last_node = nodes;
            while (last_node->next) {
                last_node = last_node->next;
            }
            last_node->next = node;
        }

        (*count)++;
    }

    // Close the file
    fclose(file);

    return nodes;
}

// Function to compute the average value of all nodes.
double compute_average(Node* nodes, int count) {
    if (nodes == NULL || count == 0) {
        return 0; // Handle edge cases with empty or zero-node arrays
    }

    double sum = 0.0;
    Node* current_node = nodes;
    while (current_node) {
        sum += current_node->value;
        current_node = current_node->next;
    }

    return sum / count;
}

// Cleanup function to free allocated memory for the nodes array.
void cleanup_nodes(Node* nodes) {
    if (!nodes) {
        return; // Handle edge cases with a null node array
    }

    Node* current_node = nodes;
    while (current_node) {
        Node* next_node = current_node->next;
        free(current_node->key);
        free(current_node);
        current_node = next_node;
    }
}
