#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

// Define a record structure with an int value
typedef struct {
    int key;
    int value;
} record_t;

// Define a dynamic collection of records
typedef struct {
    record_t* data;
    size_t size;
    size_t capacity;
    long offset[1]; // This array will be dynamically resized
    pthread_mutex_t mutex; // Mutex for thread safety
} collection_t;

// Initialize the collection and allocate memory for arrays
collection_t* init_collection(size_t max_size) {
    collection_t* coll = (collection_t*)malloc(sizeof(collection_t));
    coll->data = (record_t*)malloc(sizeof(record_t) * 1);
    coll->size = 0;
    coll->capacity = 1;
    pthread_mutex_init(&coll->mutex, NULL);
    return coll;
}

// Insert a record into the collection
int insert_collection(collection_t* coll, int key, int value) {
    if (coll->size == coll->capacity) {
        // Realloc and resize the array
        coll->data = (record_t*)realloc(coll->data, sizeof(record_t) * (coll->capacity * 2));
        coll->capacity *= 2;
        coll->offset = (long*)realloc(coll->offset, sizeof(long) * (coll->capacity + 1));
    }

    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    new_record->key = key;
    new_record->value = value;

    // Insert the new record into the sorted collection
    int i = coll->size;
    while (i > 0 && new_record->key < coll->data[i-1].key) {
        coll->data[i] = coll->data[i-1];
        i--;
    }
    coll->data[i] = *new_record;
    free(new_record);

    coll->size++;
    return 0;
}

// Delete a record from the collection
int delete_collection(collection_t* coll, int key) {
    pthread_mutex_lock(&coll->mutex);

    // Find and remove the record with matching key
    for (int i = 0; i < coll->size; i++) {
        if (coll->data[i].key == key) {
            for (int j = i + 1; j < coll->size; j++) {
                coll->data[j-1] = coll->data[j];
            }
            coll->size--;
            break;
        }
    }

    pthread_mutex_unlock(&coll->mutex);
    return 0;
}

// Reset the collection and free all allocated memory
void reset_collection(collection_t* coll) {
    pthread_mutex_lock(&coll->mutex);

    for (int i = 0; i < coll->size; i++) {
        free(coll->data[i].key);
        free(coll->data[i].value);
    }
    free(coll->data);
    free(coll->offset);

    coll->data = NULL;
    coll->size = 0;
    coll->capacity = 1;

    pthread_mutex_unlock(&coll->mutex);
}

// Helper function to generate a random integer value
int rand_value(int min, int max) {
    return (rand() % ((max + 1) - min)) + min;
}
