record* init_records(int offset_count, int min_value, int max_value, int max_memory_kb) {
    // Determine the size of offset_array based on user-provided offset_count
    int offset_array_size = (offset_count > 0 && offset_count <= MAX_OFFSET_COUNT) ? offset_count : -1;

    if (offset_array_size < 0) {
        printf("Invalid offset count. Exiting.\n");
        return NULL;
    }

    // Calculate the size of key_array as offset_count / 2
    int key_array_size = (int) floor((double) offset_count / 2);

    // Define a record structure containing a single int value and a pointer to a long from offset_array
    record* record_array;

    if ((record_array = (record*) malloc(offset_array_size * sizeof(record))) == NULL) {
        printf("Error allocating memory for records. Exiting.\n");
        return NULL;
    }

    // Initialize each record's int value to a random number within the specified range
    srand(time(NULL));

    for (int i = 0; i < offset_array_size; i++) {
        record_array[i].value = rand() % (max_value - min_value + 1) + min_value;
        record_array[i].offset = (long*) malloc(sizeof(long)); // Allocate memory for the long pointer
    }

    // Enforce a total memory usage limit of max_memory_kb by adjusting the size of any array if necessary
    int total_memory_allocated = offset_array_size * sizeof(record) + key_array_size * sizeof(long);

    while (total_memory_allocated > max_memory_kb * 1024 && offset_array_size > 0) {
        offset_array_size--;
        key_array_size = (int) floor((double) offset_array_size / 2);
        total_memory_allocated = offset_array_size * sizeof(record) + key_array_size * sizeof(long);
    }

    // Return a pointer to the record array upon successful initialization
    return record_array;
}

void free_records(record* record_array, int offset_count) {
    for (int i = 0; i < offset_count; i++) {
        if (record_array[i].offset != NULL) {
            free(record_array[i].offset);
        }
