record_t* dataManager(int num_offsets) {
    srand(time(NULL)); // Initialize random number generator

    int num_keys = num_offsets; // Each offset is associated with a key
    int total_size = (num_offsets + num_keys) * sizeof(record_t);

    record_t* records = (record_t*)malloc(total_size);
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < num_offsets; i++) {
        // Initialize key and offset
        int key = rand() % 1000;
        long offset = rand() % 1000000;

        records[i].key = key;
        records[i].offset = offset;
        records[i].value = rand() % 1001; // Value is a random integer between 0 and 1000

        // Initialize key structure
        int* keys = (int*)malloc((num_offsets + num_keys) * sizeof(int));
        if (!keys) {
            free(records);
            return NULL;
        }

        for (int j = i; j < num_offsets + num_keys; j++) {
            keys[j] = rand() % 1000;
        }

        // Allocate memory for 'offset' structure
        long* offsets = (long*)malloc((num_offsets + num_keys) * sizeof(long));
        if (!offsets) {
            free(records);
            free(keys);
            return NULL;
        }

        for (int j = i; j < num_offsets + num_keys; j++) {
            offsets[j] = rand() % 1000000;
        }

        // Validate user input to avoid buffer overflows
        if (total_size > INT_MAX) {
            printf("Error: Memory allocation failed due to buffer overflow.\n");
            free(records);
            free(keys);
            free(offsets);
            return NULL;
        }

        // Free allocated memory upon function exit
        free(offsets);
        free(keys);

        // Print contents of arrays for debugging purposes
        printf("Key: ");
        for (int j = 0; j < num_offsets + num_keys; j++) {
            printf("%d ", keys[j]);
        }
        printf("\n");

        printf("Offset: ");
        for (int j = 0; j < num_offsets + num_keys; j++) {
            printf("%ld ", offsets[j]);
        }
        printf("\n");

        // Free allocated memory upon function exit
        free(records);

        return records;
    }

    // Deallocate remaining memory upon function exit
    free(keys);
    free(offsets);

    return NULL;
}
