#define MAX_RECORDS 1000
#define MAX_KEY 1000
#define TIME_LIMIT 10 // in seconds

typedef struct record {
    int key;
    long offset;
} record_t;

record_t* records = NULL;
int num_records = 0;
int max_key = 0;

// Algorithm to compute new 'long' value combining record's key and offset
long compute_value(int key, long offset) {
    return (long)key * (offset + 1);
}

// Validate uniqueness of keys against external data source
int validate_keys(record_t* records, int num_records, int key) {
    // Simulate unreliable external data source
    if (rand() % 2 == 0) { 
        return -1; // Key not found or invalid response
    }
    for (int i = 0; i < num_records; i++) {
        if (records[i].key == key) {
            return -1; // Key already exists
        }
    }
    return 1; // Key is unique
}

// Initialize arrays and validate keys
void init_arrays() {
    int* long_offsets = NULL;
    int* keys = NULL;
    record_t* records = NULL;

    // Allocate memory for arrays
    long_offsets = (int*)malloc(MAX_RECORDS * sizeof(int));
    keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    records = (record_t*)malloc(MAX_RECORDS * sizeof(record_t));

    // Initialize variables
    num_records = 0;
    max_key = 0;

    // Loop until time limit is reached or maximum number of records is reached
    int start_time = time(NULL);
    while (time(NULL) - start_time < TIME_LIMIT && num_records < MAX_RECORDS) {
        // Simulate data source response delay
        usleep(rand() % 100000 + 1);

        int key;
        long offset;

        // Get new record from data source
        // ...
        // ...

        if (validate_keys(records, num_records, key) == -1) {
            break; // Key is not unique or invalid response from data source
        }

        // Compute new 'long' value and store in array
        long_values[num_records] = compute_value(key, offset);

        // Store record in array
        records[num_records].key = key;
        records[num_records].offset = offset;

        num_records++;
    }

    free(long_offsets);
    free(keys);
}

// Release all allocated memory
void release_memory() {
    free(records);
}
