    record_t* records = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&lock);

        // Allocate memory for the current record
        record_t* new_record = malloc(sizeof(record_t));

        if (!new_record) {
            // Handle allocation failure
            printf("Memory allocation failed.\n");
            return NULL;
        }

        int key = validate_key(i);  // Custom algorithm to compute the key

        new_record->offset = i;
        new_record->key = key;
        new_record->value = compute_value(key, i);

        if (!verify_key(new_record->key)) {
            free(new_record);
            printf("Invalid record key. Aborting.\n");
            return NULL;
        }

        // Store the computed metadata in a space-efficient manner
        long metadata = compute_metadata(key, i);
        new_record->metadata = (void*) &metadata;

        pthread_mutex_unlock(&lock);

        if (!records) {
            records = new_record;
        } else {
            record_t* last_record = records;
            while (*last_record != NULL) {
                last_record = *last_record;
            }
            *last_record = new_record;
        }
    }

    return records;
}

