    }

    // Calculate and print average measurement in the 'measurements' array using a helper function
    double averageMeasurement = calculateAverage(measurements, measurementCount);
    printf("Average measurement: %.2f\n", averageMeasurement);

    // Implement caching mechanism to store frequently accessed metrics
    int cacheSize = 100;
    struct metric* cache = (struct metric*)malloc(cacheSize * sizeof(struct metric));
    for (int i = 0; i < eventCount && i < cacheSize; i++) {
        cache[i] = metrics[i];
    }

    // Implement logging functionality to record detailed operation logs
    int logEntryCount = 100;
    struct log_entry* logEntries = (struct log_entry*)malloc(logEntryCount * sizeof(struct log_entry));
    for (int i = 0; i < eventCount && i < logEntryCount; i++) {
        logEntries[i].timestamp = timestamps[rand() % measurementCount];
        logEntries[i].eventDetails = events[rand() % eventCount];
    }

    // Export all collected data in a CSV format
    FILE* outputFile = fopen("data.csv", "w");
    if (outputFile != NULL) {
        for (int i = 0; i < eventCount; i++) {
            fprintf(outputFile, "%f, %s, %llu\n", metrics[i].value, events[i].identifier, events[i].timestamp);
        }
        fclose(outputFile);
    }

    // Free all allocated memory when the function returns
    free(measurements);
    free(identifiers);
    free(timestamps);
    free(events);
    free(metrics);
    free(cache);
    for (int i = 0; i < logEntryCount; i++) {
        free(logEntries[i].eventDetails);
    }
    free(logEntries);
}

double calculateAverage(double* measurements, int measurementCount) {
    // Helper function to calculate and return the average measurement
    double sum = 0;
    for (int i = 0; i < measurementCount; i++) {
        sum += measurements[i];
    }
    return sum / measurementCount;
}
