    int log_level;
    char* message;
    time_t timestamp;
} log_entry_t;

typedef struct {
    int type;
    double value;
} metrics_t;

void processAndAggregateData(int num_measurements, const char* measurement_data) {
    // Initialize memory pool
    void* pool = malloc(1024 * 1024); // 1MB memory pool

    // Initialize arrays
    double* measurements = (double*)malloc(num_measurements * sizeof(double));
    char** identifiers = (char**)malloc(num_measurements * sizeof(char*));
    time_t* timestamps = (time_t*)malloc(num_measurements * sizeof(time_t));

    event_t* events = (event_t*)malloc(num_measurements * sizeof(event_t));
    log_entry_t* log_entries = (log_entry_t*)malloc(num_measurements * sizeof(log_entry_t));
    metrics_t* metrics = (metrics_t*)malloc(10 * sizeof(metrics_t)); // assume 10 metrics

    // Initialize arrays
    for (int i = 0; i < num_measurements; i++) {
        measurements[i] = atof(measurement_data);
        identifiers[i] = malloc(strlen("measurement") + 1);
        strcpy(identifiers[i], "measurement");
        timestamps[i] = time(NULL);

        events[i].value = measurements[i];
        events[i].identifier = identifiers[i];
        events[i].timestamp = timestamps[i];

        log_entries[i].log_level = i % 3; // random log level
        log_entries[i].message = malloc(strlen("Log message") + 1);
        strcpy(log_entries[i].message, "Log message");
        log_entries[i].timestamp = time(NULL);

        metrics[i].type = i % 2; // random metric type
        metrics[i].value = measurements[i] * (i + 1); // calculate value based on measurement
    }

    // Free memory when returning from function
    free(pool);
    for (int i = 0; i < num_measurements; i++) {
        free(identifiers[i]);
        free(log_entries[i].message);
    }
    free(identifiers);
    free(timestamps);
    free(events);
    free(log_entries);
    free(metrics);

    // Print array contents for debugging
    printf("Measurements: ");
    for (int i = 0; i < num_measurements; i++) {
        printf("%.2f ", measurements[i]);
    }
    printf("\n");

