void processAndAggregateData(int argc, char** argv, measurement_t** measurements, event_t** events, log_entry_t** log_entries, config_t** configs) {
    // Initialize random seed for timestamp generation
    srand(time(NULL));

    // Allocate memory for arrays using malloc
    int num_measurements = 10;
    *measurements = (measurement_t*)malloc(num_measurements * sizeof(measurement_t));
    *events = (event_t*)malloc((num_measurements + 5) * sizeof(event_t));
    *log_entries = (log_entry_t*)malloc(10 * sizeof(log_entry_t));
    *configs = (config_t*)malloc(sizeof(config_t));

    // Initialize measurement and identifier arrays
    for (int i = 0; i < num_measurements; i++) {
        (*measurements)[i].measurement = i;
        (*measurements)[i].identifier = "Measurement";
    }

    // Initialize event and log_entry arrays with random data
    for (int i = 0; i < (num_measurements + 5); i++) {
        (*events)[i].timestamp = rand() % 100;
        (*events)[i].value = (double)rand() / RAND_MAX;
        (*events)[i].name = "Event";
    }

    for (int i = 0; i < 10; i++) {
        (*log_entries)[i].log_level = i % 3;
        (*log_entries)[i].message = "Log message";
        (*log_entries)[i].timestamp = rand() % 100;
    }

    // Initialize config array with command-line arguments
    (*configs)->config_file_path = argv[0];
    (*configs)->max_measurement_count = num_measurements;
    (*configs)->max_log_entries = 10;

    // Free allocated memory when the function returns
    free(*measurements);
    free(*events);
    free(*log_entries);
    free(*configs);

    // Read measurements from standard input and calculate average
    for (int i = 0; i < num_measurements; i++) {
        printf("Measurement %d: %f\n", i, (*measurements)[i].measurement);
    }

    double sum = 0;
    for (int i = 0; i < num_measurements; i++) {
        sum += (*measurements)[i].measurement;
    }
    printf("Average measurement: %f\n", sum / num_measurements);

    // Record detailed operation logs into the log_entry array
    for (int i = 0; i < 10; i++) {
        int log_level = i % 3;
        char* message = "Log message";
        time_t timestamp = rand() % 100;
        printf("Logged: Log level %d, Message: %s, Timestamp: %lu\n", log_level, message, timestamp);
    }
}
