Record** data_records;
int* offsets;
char* identifiers;

void handleDataProcessing(int num_files, pthread_mutex_t* mutex) {
    // Dynamically allocate memory for arrays
    data_records = (Record**)malloc(num_files * sizeof(Record*));
    offsets = (int*)malloc(num_files * sizeof(int));
    identifiers = (char*)malloc(BUFFER_SIZE);

    // Initialize random number generator
    randlib_init();

    // Populate identifier and offset arrays with unique values
    for (int i = 0; i < num_files; i++) {
        identifiers[i] = (char)randlib_generate();
        offsets[i] = i;
    }

    // Process data in parallel using multiple threads
    pthread_t threads[MAX_CONCURRENT];
    for (int i = 0; i < num_files; i += MAX_CONCURRENT) {
        int range_start = i, range_end = i + MAX_CONCURRENT - 1;
        if (range_end >= num_files) range_end = num_files - 1;

        pthread_create(&threads[i], NULL, process_file, &data_records[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_files / MAX_CONCURRENT; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up allocated memory
    free(data_records);
    free(offsets);
    free(identifiers);

    return;
}

void* process_file(void* arg) {
    Record* record = (Record*)arg;

    // Perform file I/O operations here...
    printf("Processed file: %s\n", record->filename);

    // Release lock
    pthread_mutex_unlock((pthread_mutex_t*)record->record_number);

    return NULL;
}
