#define MAX_LINE_LENGTH 1024
#define MAX_FILE_NAME_LENGTH 256
#define MAX_METADATA_LENGTH 2048

typedef struct {
    char description[MAX_METADATA_LENGTH];
    uint32_t version;
    uint8_t *hash;
} FileMetadata;

void processFileList(int argc, const char **argv) {
    FILE *fp = stdin;
    int lineCount = 0;
    int nonCommentLineCount = 0;
    size_t totalBytes = 0;
    timestamp_t start_time, end_time;

    // Initialize metadata and statistics
    FileMetadata *fileMetaList = (FileMetadata *)malloc(argc * sizeof(FileMetadata));
    if (!fileMetaList) {
        perror("Memory allocation failed");
        return -1;
    }

    // Parse each file line by line
    char lineBuffer[MAX_LINE_LENGTH];
    while (fgets(lineBuffer, MAX_LINE_LENGTH, fp)) {
        // Calculate line statistics
        size_t lineBytes = strlen(lineBuffer);
        totalBytes += lineBytes;

        // Check for comments and count non-comment lines
        if (!strstarts(lineBuffer, "#")) {
            nonCommentLineCount++;
        }
        lineCount++;
    }

    // Compute MD5 hash for each file (TO DO: Implement this)
    uint8_t *fileHashList = (uint8_t *)malloc(argc * sizeof(uint8_t));
    if (!fileHashList) {
        perror("Memory allocation failed");
        return -1;
    }

    // Write metadata and statistics to log file
    FILE *log_fp = fopen("process_file_list.log", "w");
    if (!log_fp) {
        perror("Error opening log file");
        return -1;
    }

    for (int i = 0; i < argc; i++) {
        fprintf(log_fp, "File %d: Description=%s, Version=%u, MD5 Hash=", i+1, fileMetaList[i].description, fileMetaList[i].version);
        fwrite(fileHashList+i*sizeof(uint8_t), sizeof(uint8_t), 16, log_fp);
        fprintf(log_fp, "\n");
    }

    // Log processing statistics
    start_time = timestamp();
    end_time = timestamp();
    fprintf(log_fp, "Processing time: %" PRIu64 " seconds\n", (uint64_t)(end_time - start_time));
    fclose(log_fp);

    // Clean up resources and free allocated memory
    free(fileMetaList);
    free(fileHashList);
}
