typedef struct {
    int log_level;
    char* message;
    time_t timestamp;
} log_entry;

void processAndAggregateData(int argc, char* argv[]) {
    srand(time(NULL)); // seed the random number generator

    // initialize arrays
    double* measurements = (double*)malloc(SIZE * sizeof(double));
    char** identifiers = (char**)malloc(SIZE * sizeof(char*));
    time_t* timestamps = (time_t*)malloc(SIZE * sizeof(time_t));
    event* events = (event*)malloc(SIZE * sizeof(event));
    log_entry* log_entries = (log_entry*)malloc(SIZE * sizeof(log_entry));

    // initialize measurement and identifier arrays
    for (int i = 0; i < SIZE; i++) {
        measurements[i] = (double)(i + 1);
        identifiers[i] = (char*)strdup(argv[i % argc]);
    }

    // initialize timestamp, event, and log_entry arrays with random values
    for (int i = 0; i < SIZE; i++) {
        timestamps[i] = time(NULL) + rand() % 100;
        events[i].measurement = measurements[i];
        events[i].identifier = identifiers[i];
        events[i].timestamp = timestamps[i];
        log_entries[i].log_level = rand() % 2;
        log_entries[i].message = (char*)strdup(argv[i % argc]);
        log_entries[i].timestamp = time(NULL) + rand() % 100;
    }

    // ensure thread safety through synchronization
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // print array contents for debugging purposes
    for (int i = 0; i < SIZE; i++) {
        printf("Measurement: %f, Identifier: %s, Timestamp: %lu\n", measurements[i], identifiers[i], timestamps[i]);
        printf("Event: measurement = %f, identifier = %s, timestamp = %lu\n", events[i].measurement, events[i].identifier, events[i].timestamp);
        printf("Log Entry: log_level = %d, message = %s, timestamp = %lu\n", log_entries[i].log_level, log_entries[i].message, log_entries[i].timestamp);
    }

    // free allocated memory to avoid leaks
    for (int i = 0; i < SIZE; i++) {
        free(identifiers[i]);
        free(log_entries[i].message);
    }
    free(identifiers);
    free(events);
    free(log_entries);

    pthread_mutex_unlock(&mutex);
}

int main() {
    processAndAggregateData(3, argv);
    return 0;
}
