void manage_records(record ***records, long **offsets, int *size) {
    int new_size = 2 * (*size);
    if (new_size > 10000) {
        new_size = 10000;
    }

    record ***new_records = realloc(*records, sizeof(record *) * new_size);
    if (!new_records) {
        printf("Memory allocation failed for records\n");
        *size /= 2;
        new_records = realloc(*records, sizeof(record *) * (*size));
        if (!new_records) {
            printf("Failed to resize records\n");
            return;
        }
    }

    long **new_offsets = realloc(*offsets, sizeof(long *) * new_size);
    if (!new_offsets) {
        printf("Memory allocation failed for offsets\n");
        *size /= 2;
        new_offsets = realloc(*offsets, sizeof(long *) * (*size));
        if (!new_offsets) {
            printf("Failed to resize offsets\n");
            return;
        }
    }

    *records = new_records;
    *offsets = new_offsets;
