typedef struct {
    double temperature;
    int humidity;
    char* location;
    char status;
} sensor_data;

int parse_json_to_arrays(json_object*, long**, double**, sensor_data**, char***);
void free_allocated_memory(long**, double**, sensor_data**, char**);

int main() {
    // Example usage
    json_object* json_data = ...;  // Load JSON data from external API

    long* timestamps;
    double* temperatures;
    sensor_data* sensor_data_records;
    char** status_messages;

    parse_json_to_arrays(json_data, &timestamps, &temperatures, &sensor_data_records, &status_messages);

    // Use the allocated arrays
    for (int i = 0; i < ...; i++) {
        printf("Timestamp: %ld, Temperature: %.2f, Status: %c\n", timestamps[i], temperatures[i], status_messages[i][0]);
    }

    free_allocated_memory(timestamps, temperatures, sensor_data_records, status_messages);

    return 0;
}

int parse_json_to_arrays(json_object* json_data, long** timestamps, double** temperatures, sensor_data** sensor_data_records, char*** status_messages) {
    int num_records = json_object_array_length(json_data);
    *timestamps = (long*)malloc(num_records * sizeof(long));
    *temperatures = (double*)malloc(num_records * sizeof(double));
    *sensor_data_records = (sensor_data*)malloc(num_records * sizeof(sensor_data));
    *status_messages = (char**)malloc((num_records + 1) * sizeof(char*));

    for (int i = 0; i < num_records; i++) {
        json_object* record = json_object_array_get_idx(json_data, i);
        long timestamp = json_object_get_int(record, "timestamp");
        double temperature = json_object_get_double(record, "temperature");
        int humidity = json_object_get_int(record, "humidity");
        char* location = json_string_value(json_object_get_string(record, "location"));
        char status = json_object_get_string(record, "status")[0];

        (*timestamps)[i] = timestamp;
        (*temperatures)[i] = temperature;
        (*sensor_data_records)[i].temperature = temperature;
        (*sensor_data_records)[i].humidity = humidity;
        (*sensor_data_records)[i].location = location;
        (*sensor_data_records)[i].status = status;

        char* status_message = json_string_value(json_object_get_string(record, "status_message"));
        (*status_messages)[i] = (char*)malloc(strlen(status_message) + 1);
        strcpy((*status_messages)[i], status_message);

        free(location);
    }

    return num_records;
}

void free_allocated_memory(long** timestamps, double** temperatures, sensor_data** sensor_data_records, char*** status_messages) {
    for (int i = 0; i < ...; i++) {
        free(((*status_messages))[i]);
    }
    free(*status_messages);
    free(*sensor_data_records);
    free(*temperatures);
    free(*timestamps);
}
