#include <time.h>

typedef struct {
    int value;
    long *offset;
} record;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int is_prime(int n) {
    if (n <= 1)
        return 0;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0)
            return 0;
    }
    return 1;
}

void init_memory(long n, int m, long p) {
    if (n <= 0 || m <= 0 || p <= 0) {
        printf("Error: All input parameters must be positive.\n");
        exit(1);
    }

    long* offsets = my_malloc(n * sizeof(long));
    for (long i = 0; i < n; i++) {
        offsets[i] = i;
    }

    int* keys = my_malloc(m * sizeof(int));
    int key_idx = 0;
    for (int i = 2; ; i++) {
        if (!is_prime(i)) continue;
        if (key_idx >= m) break;
        keys[key_idx++] = i;
    }
    while (key_idx < m) {
        keys[key_idx++] = rand() % 100 + 1;
    }

    record* records = my_malloc(p * sizeof(record));
    for (long i = 0; i < p; i++) {
        records[i].value = rand() % 1000 + 1;
        while (rand() % 1000 + 1 == records[i].value) {
            records[i].value = rand() % 1000 + 1;
        }
        records[i].offset = &offsets[records[i].value];
    }

    printf("Memory initialization complete.\n");
}

void cleanup(long n, int m, long p) {
    my_free((void*) offsets);
    my_free((void*) keys);
    my_free((void*) records);
}
