#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structure for task management
typedef struct {
    int priority;
    char* description;
    int deadline;
} Task;

// Dynamic array of tasks
Task** tasks = NULL;
int task_count = 0;

// Function to allocate memory for a new task
Task* create_task(int priority, const char* description) {
    Task* task = (Task*)malloc(sizeof(Task));
    task->priority = priority;
    task->deadline = time(NULL) + (3600 * 24 * deadline); // Convert deadline to seconds since epoch
    task->description = (char*)malloc((strlen(description) + 1) * sizeof(char));
    strcpy(task->description, description);
    return task;
}

// Function to add a new task
void add_task(int priority, const char* description) {
    Task* task = create_task(priority, description);
    tasks = realloc(tasks, (task_count + 1) * sizeof(Task*));
    tasks[task_count++] = task;
}

// Function to retrieve a specific task by index
Task* get_task(int index) {
    if(index >= 0 && index < task_count) {
        return tasks[index];
    } else {
        printf("Invalid task index\n");
        return NULL;
    }
}

// Function to delete a specific task by index
void delete_task(int index) {
    if(index >= 0 && index < task_count) {
        free(tasks[index]->description);
        free(tasks[index]);
        tasks = realloc(tasks, (task_count - 1) * sizeof(Task*));
        for(int i=index; i<task_count-1; i++) {
            tasks[i] = tasks[i+1];
        }
        task_count--;
    } else {
        printf("Invalid task index\n");
    }
}

// Function to synchronize tasks with an external data source
void sync_tasks() {
    // Implement logic to sync tasks with the external data source
    // For demonstration purposes, just print a message
    printf("Syncing tasks...\n");
}

// Function to periodically sync tasks with an external data source
void periodic_sync(int interval) {
    for(int i=0; i<task_count; i++) {
        Task* task = get_task(i);
        if(task != NULL) {
            // Implement logic to handle task deadline
            // For demonstration purposes, just print a message
            printf("Task %s has deadline in %d days\n", task->description, task->deadline - time(NULL));
        }
    }
}

// Function to deallocate all resources when tasks are no longer needed
void clean_up() {
    for(int i=0; i<task_count; i++) {
        Task* task = get_task(i);
        if(task != NULL) {
            free(task->description);
            free(task);
        }
    }
    free(tasks);
}

int main() {
    // Initialize the task management system
    add_task(1, "Task 1 description");
    add_task(2, "Task 2 description");
    add_task(3, "Task 3 description");

    // Periodically sync tasks with an external data source
    periodic_sync(60); // Synchronize every minute

    // Clean up resources when the system is shutting down
    clean_up();

    return 0;
}
