    if (!node) return NULL;
    return node;
}

// Define a function to free allocated resources
void freeResources(void* pool, Node* node) {
    // Free each item in the linked list
    Item* current = node->head;
    while (current != NULL) {
        Item* next = current->next;
        free(current);
        current = next;
    }
    // Free the node itself
    free(node);
}

