    Item* current = node->head;
    while (current != NULL) {
        // Decrement reference count and remove item if necessary
        if (--current->refCount == 0) {
            // Remove the item from the linked list
            Item* next = current->next;
            free(current);
            current = next;
        } else {
            current = current->next;
