typedef struct {
    int priority;
    char* description;
    time_t deadline;
} task;

task* create_tasks(int num_tasks);
void reschedule_tasks(task** tasks, int num_tasks);
int main() {
    // Initialize random seed
    srand(time(NULL));

    int num_tasks = 100; // Maximum number of tasks to handle

    // Create the dynamic collection of 'task' structures
    task* tasks = create_tasks(num_tasks);

    // Simulate rescheduling tasks with new deadlines
    for (int i = 0; i < num_tasks; i++) {
        reschedule_tasks(&tasks, num_tasks);
    }

    // Free dynamically allocated memory
    for (int i = 0; i < num_tasks; i++) {
        free(tasks[i].description);
    }
    free(tasks);

    return 0;
}

task* create_tasks(int num_tasks) {
    task* tasks = malloc(num_tasks * sizeof(task));

    if (!tasks) {
        return NULL;
    }

    for (int i = 0; i < num_tasks; i++) {
        tasks[i].priority = i + 1;

        // Allocate memory for the description string
        int desc_len = rand() % 50 + 1;
        tasks[i].description = malloc((desc_len + 1) * sizeof(char));
        if (!tasks[i].description) {
            return NULL; // Memory allocation failed
        }
        memset(tasks[i].description, '\0', desc_len + 1);
        for (int j = 0; j < desc_len; j++) {
            tasks[i].description[j] = 'a' + rand() % 26;
        }

        // Set the deadline to a random time within the next thirty days
        tasks[i].deadline = time(NULL) + rand() % (30 * 24 * 60 * 60);
    }
    return tasks;
}

void reschedule_tasks(task** tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; i++) {
        // Reschedule the task with a new deadline
        time_t new_deadline = time(NULL) + rand() % (30 * 24 * 60 * 60);
        while (new_deadline < (*tasks)[i].deadline) {
            new_deadline += rand() % (30 * 24 * 60 * 60);
        }
        (*tasks)[i].deadline = new_deadline;

        // Check for overlapping deadlines with dependent tasks
        for (int j = i + 1; j < num_tasks; j++) {
            if ((*tasks)[j].deadline <= (*tasks)[i].deadline) {
                reschedule_tasks(&(*tasks), num_tasks);
                return;
            }
        }
    }
}
