Record** records = NULL;
int recordCount = 0;
int initialCapacity = 10;

void manageMemory(int newCapacity) {
    Record** newRecords = (Record**)malloc(newCapacity * sizeof(Record*));
    for (int i = 0; i < newCapacity && i < recordCount; i++) {
        newRecords[i] = records[i];
    }
    if (records != NULL) {
        for (int i = newCapacity - 1; i >= recordCount; i--) {
            free(records[i]->offset);
            free(records[i]);
        }
        free(records);
    }
    records = newRecords;
}

void updateOffsets(int key) {
    if (recordCount == 0 || records[recordCount-1]->key != key) {
        for (int i = recordCount - 1; i >= 0; i--) {
            records[i]->offset[records[i]->key] += key;
        }
    } else {
        long newOffset = records[recordCount-1]->offset[records[recordCount-1]->key] + key;
        if (newOffset > 0) {
            for (int i = recordCount - 1; i >= 0; i--) {
                records[i]->offset[records[i]->key] += key;
            }
        } else {
            for (int i = recordCount - 1; i >= 0; i--) {
                long* oldOffset = records[i]->offset;
                int newKey = records[i]->key;
                free(oldOffset);
                records[i]->offset = (long*)malloc((newKey + 2) * sizeof(long));
                for (int j = 0; j <= newKey; j++) {
                    records[i]->offset[j] = oldOffset ? oldOffset[j] : 0;
                }
                free(oldOffset);
            }
        }
    }
}

void setRandomSeed(int seed) {
    srand(seed);
}

int main() {
    // Initialize offsets array
    int* offsets = (int*)malloc(initialCapacity * sizeof(int));
    for (int i = 0; i < initialCapacity; i++) {
        offsets[i] = rand();
    }

    // Initialize records array
    manageMemory(initialCapacity);

    return 0;
}
