NFAPI_CRC_INDICATION_PDU_T* mergeAndProcessArrays(int num_arrays, int array_size) {
    // Initialize arrays
    long** offsets = (long**)malloc(num_arrays * sizeof(long*));
    int** keys = (int**)malloc(num_arrays * sizeof(int*));
    NFAPI_CRC_INDICATION_PDU_T** records = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_arrays * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Initialize validation hash table
    pthread_hash_table_t* tag_map = pthread_hash_table_create();

    // Initialize log file
    FILE* log_file = fopen("log.txt", "a");
    if (!log_file) {
        printf("Error opening log file\n");
        exit(1);
    }

    // Merge and process arrays
    int offset_size = 0;
    for (int i = 0; i < num_arrays; i++) {
        offsets[i] = (long*)malloc(array_size * sizeof(long));
        keys[i] = (int*)malloc(array_size * sizeof(int));
        records[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Validate tags
        for (int j = 0; j < array_size; j++) {
            pthread_hash_table_insert(tag_map, &records[i][j].key, records[i][j].value);
        }

        offset_size += array_size;
    }

    // Merge sorted arrays
    NFAPI_CRC_INDICATION_PDU_T* merged_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc((offset_size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int merge_size = 0;
    for (int i = 0; i < num_arrays; i++) {
        NFAPI_CRC_INDICATION_PDU_T* temp_array = records[i];
        int temp_size = array_size;
        // Merge and copy arrays
        while (temp_size > 0) {
            merged_array[merge_size] = *temp_array++;
            merge_size++;
            temp_size--;
        }
    }

    // Print merged array details
    for (int i = 0; i < offset_size; i++) {
        printf("Key: %d, Offset: %ld, Value: %d\n", merged_array[i].key, merged_array[i].offset, merged_array[i].value);
    }

    // Close log file and exit
    fclose(log_file);

    return merged_array;
}
