void transformAndProcessDataStreams(int num_streams) {
    char** streams = (char**)malloc(num_streams * sizeof(char*));
    for(int i=0; i<num_streams; i++) {
        char buffer[256];
        printf("Enter stream identifier: ");
        scanf("%s", buffer);

        // Extract the main part of the filename
        int length = strlen(buffer) - strlen(strrchr(buffer, '.')) - 1;
        char* main_part = (char*)malloc((length + 1)*sizeof(char));
        strncpy(main_part, buffer, length);
        main_part[length] = '\0';

        // Determine file type based on vowel count
        int vowel_count = 0;
        for(int j=0; j<length; j++) {
            if(strchr("aeiouAEIOU", main_part[j]) != NULL) {
                vowel_count++;
            }
        }
        char* extension;
        if(vowel_count % 2 == 0) {
            extension = "txt";
        } else if(vowel_count > 0) {
            extension = "bin";
        } else {
            extension = "cfg";
        }

        // Format timestamp
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y%m%d-%H%M%S", localtime(&now));

        // Validate new filename and ensure it does not exceed 256 characters
        int new_length = strlen(main_part) + strlen(extension) + 2;
        if(new_length > 256) {
            printf("Filename too long.\n");
            return;
        }
        char* new_filename = (char*)malloc((new_length + 1)*sizeof(char));
        sprintf(new_filename, "%s.%s", main_part, extension);

        // Store measurements in array
        int* measurements = (int*)malloc(100 * sizeof(int)); // assume a maximum of 100 measurements per stream
        for(int j=0; j<100; j++) {
            printf("Enter measurement %d: ", j+1);
            scanf("%d", &measurements[j]);
        }

        double average = calculateAverage(measurements, 100); // use helper function to calculate average

        // Print stream contents
        printf("Stream identifier: %s\n", new_filename);
        printf("Timestamp: %s\n", timestamp);
        printf("Measurements:\n");
        for(int j=0; j<100; j++) {
            printf("%d ", measurements[j]);
        }
        printf("\nEvent log: \n"); // add event logging functionality

        free(measurements);
        free(new_filename);
        free(main_part);

        streams[i] = new_filename;
    }

    // Print all stream contents
    for(int i=0; i<num_streams; i++) {
        printf("Stream %d: \n", i+1);
        printf("Identifier: %s\n", streams[i]);
        printf("Timestamp: \n"); // add timestamp printing functionality
        printf("Measurements:\n");
        // add measurement and event log printing functionality

        free(streams[i]);
    }

    free(streams);
}

double calculateAverage(int* measurements, int size) {
    double sum = 0.0;
    for(int i=0; i<size; i++) {
        sum += (double)measurements[i];
    }
    return sum / size;
}
