record_t* allocate_records(int numRecords) {
    if (numRecords <= 0) {
        printf("Invalid number of records: %d\n", numRecords);
        return NULL;
    }

    record_t* records = (record_t*)malloc(numRecords * sizeof(record_t));
    if (!records) {
        printf("Memory allocation failed for records\n");
        return NULL;
    }

    int* keys = (int*)malloc(numRecords * sizeof(int));
    long* offsets = (long*)malloc(numRecords * sizeof(long));

    // Check if memory allocation was successful
    if (!(keys && offsets)) {
        printf("Memory allocation failed for keys or offsets\n");
        free(records);
        return NULL;
    }

    srand(time(NULL));  // Initialize random number generator

    for (int i = 0; i < numRecords; ++i) {
        offsets[i] = i * (rand() % 100 + 1); // Randomly generated multiplier within a specified range
        keys[i] = i;
    }

    record_t* result = (record_t*)malloc(numRecords * sizeof(record_t));
    if (!result) {
        printf("Memory allocation failed for final records\n");
        free(keys);
        free(offsets);
        free(records);
        return NULL;
    }

    // Copy values from offsets and keys arrays to the record array
    for (int i = 0; i < numRecords; ++i) {
        result[i].value = offsets[i];
        result[i].key = keys[i];
    }

    free(keys);
    free(offsets);

    return result;
}

void deallocate_records(record_t* records, int numRecords) {
    if (!records) {
        return;
    }

    free(records);
}
