#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    char* key;
    long offset;
    int value;
} item;

void addItem(item** items, int* size, const char* key, long offset, int value) {
    item* newItem = (item*)malloc(sizeof(item));
    newItem->key = (char*)malloc(strlen(key) + 1);
    strcpy(newItem->key, key);
    newItem->offset = offset;
    newItem->value = value;
    *size += 1;
    if (*items == NULL) {
        *items = (item*)malloc(sizeof(item));
        (*items) = newItem;
    } else {
        item* temp = *items;
        *items = newItem;
        newItem->next = temp;
    }
}

int getItemByKey(item** items, int size, const char* key) {
    for (int i = 0; i < size; i++) {
        if (strcmp((*items)->key, key) == 0) {
            return (*items)->value;
        }
        *items = (*items)->next;
    }
    return -1;
}

void serializeItems(item* items, int size, FILE* file) {
    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        fwrite(&items[i].offset, sizeof(long), 1, file);
        fwrite(&items[i].key, strlen(items[i].key) + 1, 1, file);
        fwrite(&items[i].value, sizeof(int), 1, file);
    }
}

void deserializeItems(item** items, int* size, FILE* file) {
    fread(size, sizeof(int), 1, file);
    *items = (item*)malloc(*size * sizeof(item));
    for (int i = 0; i < *size; i++) {
        item* newItem = (*items) + i;
        fread(&newItem->offset, sizeof(long), 1, file);
        newItem->key = (char*)malloc(strlen((char*)fread(NULL, 1, file, NULL)) + 1);
        strcpy(newItem->key, (char*)fread(NULL, 1, file, NULL));
        fread(&newItem->value, sizeof(int), 1, file);
    }
}

void setRandomValue(item* items, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        items[i].value = rand() % 100;
    }
}
