void manage_memory_allocation(size_t floats_size, size_t strings_size, size_t items_size, size_t summaries_size) {
    // Allocate memory for floats
    float* floats = (float*)malloc(floats_size * sizeof(float));
    if (!floats) {
        printf("Error: Failed to allocate memory for floats.\n");
        return;
    }

    // Allocate memory for strings
    char** strings = (char**)malloc(strings_size * sizeof(char*));
    if (!strings) {
        free(floats);
        printf("Error: Failed to allocate memory for strings.\n");
        return;
    }
    for (size_t i = 0; i < strings_size; i++) {
        strings[i] = (char*)malloc(256); // assume max string length is 255
        if (!strings[i]) {
            for (size_t j = 0; j < i; j++)
                free(strings[j]);
            free(floats);
            free(strings);
            printf("Error: Failed to allocate memory for strings.\n");
            return;
        }
    }

    // Allocate memory for items
    struct item* items = (struct item*)malloc(items_size * sizeof(struct item));
    if (!items) {
        for (size_t i = 0; i < strings_size; i++)
            free(strings[i]);
        free(strings);
        free(floats);
        printf("Error: Failed to allocate memory for items.\n");
        return;
    }

    // Allocate memory for summaries
    struct summary* summaries = (struct summary*)malloc(summaries_size * sizeof(struct summary));
    if (!summaries) {
        for (size_t i = 0; i < strings_size; i++)
            free(strings[i]);
        free(strings);
        free(floats);
        free(items);
        printf("Error: Failed to allocate memory for summaries.\n");
        return;
    }

    // Perform validation routine
    for (size_t i = 0; i < items_size; i++) {
        if (!items[i].str || !items[i].str[0]) {
            printf("Error: Invalid string detected.\n");
            for (size_t j = 0; j < strings_size; j++)
                free(strings[j]);
            free(strings);
            free(floats);
            free(items);
            free(summaries);
            return;
        }
    }

    // Release allocated memory
    for (size_t i = 0; i < strings_size; i++) {
        free(strings[i]);
    }
    free(strings);
    free(floats);
    free(items);
    free(summaries);
}

int main() {
    size_t floats_size = 10000;
    size_t strings_size = 10000;
    size_t items_size = 10000;
    size_t summaries_size = 10000;

    manage_memory_allocation(floats_size, strings_size, items_size, summaries_size);

    return 0;
}
