typedef struct {
    long offset;
    int key;
} record_t;

void manage_memory(size_t num_records, size_t max_offset_size, size_t max_key_size) {
    // Validate input parameters
    if (num_records > (max_offset_size + max_key_size)) {
        printf("Invalid configuration: too many records.\n");
        return;
    }

    // Allocate memory for the long offset array
    long *offsets = (long *)malloc(max_offset_size * sizeof(long));
    if (!offsets) {
        printf("Out of memory: allocating long offsets.\n");
        return;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Populate the long offset array
    for (size_t i = 0; i < max_offset_size; i++) {
        offsets[i] = rand() % (long)(1 << 31);
    }

    // Allocate memory for the int key array
    int *keys = (int *)malloc(max_key_size * sizeof(int));
    if (!keys) {
        printf("Out of memory: allocating int keys.\n");
        free(offsets);
        return;
    }

    // Initialize random number generator again to avoid sequential numbers
    srand(time(NULL));

    // Populate the int key array with unique values
    for (size_t i = 0; i < max_key_size; i++) {
        while (1) {
            keys[i] = rand() % (int)(1 << 31);
            if (!binary_search(keys, i)) break;
        }
    }

    // Allocate memory for the record structures
    record_t *records = (record_t *)malloc(num_records * sizeof(record_t));
    if (!records) {
        printf("Out of memory: allocating records.\n");
        free(offsets);
        free(keys);
        return;
    }

    // Populate the record structures with random values
    for (size_t i = 0; i < num_records; i++) {
        records[i].offset = offsets[rand() % max_offset_size];
        records[i].key = keys[rand() % max_key_size];
    }

    // Free all allocated memory
    free(records);
    free(keys);
    free(offsets);

    return;
}

// Binary search function to prevent duplicate int values
int binary_search(int *keys, size_t n) {
    int low = 0;
    int high = n - 1;

    while (low <= high) {
        int mid = (low + high) / 2;
        if (keys[mid] == 0) return 1; // found a duplicate
        else if (keys[mid] < 0) low = mid + 1;
        else high = mid - 1;
    }

    return 0; // no duplicates found
}
