#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum total memory usage threshold (in bytes)
#define MAX_MEMORY_USAGE 1048576

typedef struct {
    int key;
    int value;
} Record;

int generateUniqueKey(int* attemptCount) {
    static int currentKey = 0;
    if (*attemptCount > 5) {
        return -1; // Failure after 5 attempts
    }
    for (int i = 0; i < *attemptCount; i++) {
        currentKey++;
        if (currentKey % 2 != 0) {
            return currentKey;
        }
    }
    return -1; // Failure to generate a unique key
}

void processPipeline(int longOffsetsSize, int integerKeysSize, int recordStructuresSize) {
    void* memory = NULL;
    size_t totalMemoryUsage = 0;

    // Calculate the required memory for each component
    size_t offsetsMemory = longOffsetsSize * sizeof(long);
    size_t keysMemory = integerKeysSize * sizeof(int);
    size_t recordsMemory = recordStructuresSize * sizeof(Record);

    // Calculate the maximum allowed memory usage
    if (offsetsMemory + keysMemory + recordsMemory > MAX_MEMORY_USAGE) {
        int reducedRecordsSize = recordStructuresSize - 1;
        while (reducedRecordsSize >= 0 && ((offsetsMemory + keysMemory + (recordsMemory * sizeof(Record))) / sizeof(Record)) > MAX_MEMORY_USAGE) {
            reducedRecordsSize--;
        }
        recordsMemory = reducedRecordsSize * sizeof(Record);
    }

    // Allocate memory for the pipeline components
    memory = malloc(offsetsMemory + keysMemory + recordsMemory);
    if (memory == NULL) {
        printf("Failed to allocate memory.\n");
        return;
    }

    totalMemoryUsage += offsetsMemory + keysMemory + recordsMemory;

    // Initialize and fill the pipeline components
    long* longOffsets = memory;
    int* integerKeys = (int*)((char*)longOffsets + offsetsMemory);
    Record* recordStructures = (Record*)((char*)integerKeys + keysMemory);

    // Validate memory usage and notify accordingly
    if (totalMemoryUsage > MAX_MEMORY_USAGE) {
        printf("Memory threshold exceeded. Adjusting the pipeline.\n");
    }

    // Log memory allocation success or failure to external service
    FILE* logFile = fopen("memory_log.txt", "a+");
    fprintf(logFile, "Allocated %zu bytes of memory.\n", totalMemoryUsage);
    fclose(logFile);

    free(memory);
}
