typedef struct {
    long offset;
    int key;
    float timestamp;
} record;

typedef struct {
    int key;
    int count;
} summary;

record* allocateRecords(int size) {
    return (record*)malloc(size * sizeof(record));
}

void initializeRecords(record* records, int size) {
    time_t now = time(NULL);
    srand(now);

    for (int i = 0; i < size; i++) {
        records[i].offset = rand();
        records[i].key = rand() % 100;
        records[i].timestamp = (float)rand() / RAND_MAX;
    }
}

summary* allocateSummaries(int size) {
    return (summary*)malloc(size * sizeof(summary));
}

void initializeSummaries(summary* summaries, int size) {
    for (int i = 0; i < size; i++) {
        summaries[i].key = -1;
        summaries[i].count = 0;
    }
}

int main() {
    int recordCount = 10000;

    record* records = allocateRecords(recordCount);
    initializeRecords(records, recordCount);

    summary* summaries = allocateSummaries(recordCount);
    initializeSummaries(summaries, recordCount);

    // Populate summaries based on key matches
    for (int i = 0; i < recordCount; i++) {
        int key = records[i].key;
        for (int j = 0; j < recordCount; j++) {
            if (records[j].key == key) {
                summaries[key].count++;
            }
        }
    }

    // Retrieve the total number of unique keys encountered
    int uniqueKeys = -1;
    for (int i = 0; i < recordCount; i++) {
        if (summaries[i].key != -1 && (uniqueKeys == -1 || summaries[uniqueKeys].key != summaries[i].key)) {
            uniqueKeys = i;
        }
    }

    printf("Total number of unique keys: %d\n", uniqueKeys);

    // Free allocated memory
    free(records);
    free(summaries);

    return 0;
}
