char* generate_unique_name(PeopleList *list, const char *base_name) {
    int i=0;
    while(1) {
        char* name = (char*)malloc(strlen(base_name)+i+1);
        sprintf(name, "%s_%d", base_name, i);
        for(int j=0; j<list->size; j++) {
            if(strcmp(list->people[j]->name, name)==0) {
                free(name);
                break;
            }
        }
        if(j==list->size) {
            return name;
        }
        free(name);
        i++;
    }
}

