    if(config.threshold > 0 && (list->size * sizeof(Person) + config.threshold) >= getpagesize()) {
        // Handle memory allocation failure and log error
        fprintf(stderr, "Memory allocation failed! (%d entries)\n", list->size);
        people_list_destroy(list);
        exit(1);
