// Function to find and print the largest integer in an array
void findLargest(int* arr, int count) {
    int max = arr[0];
    for (int i = 1; i < count; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    printf("The largest integer is: %d\n", max);
