void* batchProcessRecords(int numRecords, int numOffsets, int numKeys) {
    // Allocate memory for arrays
    long* offsetArr = (long*)malloc(numOffsets * sizeof(long));
    int* keyArr = (int*)malloc(numKeys * sizeof(int));
    record* recordArr = (record*)malloc(numRecords * sizeof(record));

    // Initialize arrays with specific values based on input parameters
    for (int i = 0; i < numOffsets; i++) {
        offsetArr[i] = 12345;
    }
    for (int i = 0; i < numKeys; i++) {
