    for (int i = 0; i < numRecords; i++) {
        recordArr[i].value = rand() % 100;
        recordArr[i].position = i;
    }

    // Implement a thread-safe linked list to manage the 'record' structures
    Node* head = NULL;
    Node* tail = NULL;

    // Define helper function for adding nodes to the linked list
    void addNode(record* data, Node** head, Node** tail) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data = data;
        newNode->next = NULL;

        if (*head == NULL)
            *head = *tail = newNode;
        else {
            (*tail)->next = newNode;
            *tail = newNode;
        }
    }

    // Add nodes to the linked list based on key values
    for (int i = 0; i < numRecords; i++) {
        addNode(&recordArr[i], &head, &tail);
    }

    // Free dynamically allocated memory
    free(offsetArr);
    free(keyArr);
    free(recordArr);

    return head;
}

// Function to read a list of integers from standard input and store them in an array
