typedef struct {
    double* values;
    int size;
} DataRecord;

DataRecord* create_data_record(int n, double mean, double std_dev) {
    DataRecord* record = (DataRecord*)malloc(sizeof(DataRecord));
    if (!record) return NULL; // Handle memory allocation failure

    record->values = (double*)malloc(n * sizeof(double));
    if (!record->values) {
        free(record);
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        record->values[i] = mean + std_dev * (rand() / (double)RAND_MAX - 0.5); // Gaussian distribution
    }
    record->size = n;

    return record;
}

void free_data_record(DataRecord* record) {
    if (!record) return; // Handle null pointer
    free(record->values);
    free(record);
}
