// Function to manage memory and initialize dynamic arrays
void streamMediaProcessor() {
    // Initialize random string library
    randlib_init();

    // Allocate memory for arrays
    array* value_array = (array*)malloc(sizeof(array));
    array* string_array = (array*)malloc(sizeof(array));

    // Read input data from standard input
    int i;
    for(i=0; i<10; i++) {
        double val;
        char str[100];
        // read floating-point numbers and strings
        printf("Enter value %d: ", i);
        scanf("%lf", &val);
        printf("Enter string %d: ", i);
        fgets(str, sizeof(str), stdin);

        // Store data in arrays
        value_array->items = (item*)realloc(value_array->items, sizeof(item)*(i+1));
        value_array->items[i].value = val;
        value_array->items[i].id = i;

        string_array->ptr = (char*)realloc(string_array->ptr, sizeof(char)*(i+1)*100);
        strcpy(string_array->ptr + (i*100), str);
    }

    // Calculate average of 'value' array
    double avg = 0.0;
    for(i=0; i<10; i++) {
        avg += value_array->items[i].value;
    }
    avg /= 10;

    // Concatenate all strings into a single string
    char* concatenated_string = (char*)malloc(sizeof(char)*(strlen(string_array->ptr) + strlen(string_array->ptr) + 1));
    strcpy(concatenated_string, string_array->ptr);
    for(i=1; i<10; i++) {
        strcat(concatenated_string, string_array->ptr + (i*100));
    }

    // Free allocated memory
    free(value_array->items);
    free(string_array->ptr);

    // Deinitialize random string library
    randlib_deinit();
}
