    double *values = malloc(sizeof(double) * size);
    char **strings = malloc(sizeof(char *) * size);
    item_t *items = malloc(sizeof(item_t) * size);
    summary_t *summaries = malloc(sizeof(summary_t) * (size / 2));
    metadata_t *metadata = malloc(sizeof(metadata_t) * size);

    // Initialize the value array
    for (size_t i = 0; i < size; i++) {
        values[i] = i + 1.0;
    }

    // Initialize the string array
    for (size_t i = 0; i < size; i++) {
        strings[i] = malloc(strlen(inputStr) * sizeof(char));
        strncpy(strings[i], inputStr, strlen(inputStr) - 1);
        strings[i][strlen(inputStr) - 1] = '\0';
    }

    // Initialize the item array
    for (size_t i = 0; i < size; i++) {
        items[i].value = (double) rand() / RAND_MAX;
        items[i].id = i + 1;
    }

    // Initialize the summary array
    for (size_t i = 0; i < (size / 2); i++) {
        summaries[i].str = malloc(strlen(inputStr) * sizeof(char));
        strncpy(summaries[i].str, inputStr, strlen(inputStr) - 1);
        summaries[i].str[strlen(inputStr) - 1] = '\0';
        summaries[i].count = i + 1;
    }

    // Initialize the metadata array
    for (size_t i = 0; i < size; i++) {
        metadata[i].timestamp = time(NULL);
        metadata[i].unique_id = (unsigned long) rand();
    }

    // Check if the summary array is not greater than the sum of value and string arrays
    if ((size / 2) > (size + size)) {
        printf("Error: Summary array size exceeds the sum of value and string arrays.\n");
        return;
    }

    // Print the contents of all arrays for debugging purposes
    for (size_t i = 0; i < size; i++) {
        printf("Value: %f\n", values[i]);
        printf("String: %s\n", strings[i]);
        printf("Item: %.2f, %d\n", items[i].value, items[i].id);
        printf("Summary: %s, %d\n", summaries[i / 2].str, summaries[i / 2].count);
        printf("Metadata: %lu, %lu\n", metadata[i].unique_id, (long) metadata[i].timestamp);
    }

    // Free all allocated memory when the function returns
    for (size_t i = 0; i < size; i++) {
        free(strings[i]);
    }
    free(strings);

    for (size_t i = 0; i < (size / 2); i++) {
        free(summaries[i].str);
    }
    free(summaries);

    free(metadata);
}
