void processAndAggregateJsonStream() {
    json_parser_init();
    AggregateStruct *agg = (AggregateStruct *)malloc(sizeof(AggregateStruct));
    agg->total_count = 0;
    agg->cumulative_sum = 0;
    agg->unique_key_count = 0;

    size_t buffer_size = 1024;
    char *buffer = (char *)malloc(buffer_size);
    json_value *json_obj;
    while ((json_obj = json_parse_string_from_fd(0, buffer, buffer_size)) != NULL) {
        if (json_obj->type == JSON_OBJECT) {
            for (int i = 0; i < json_obj->u.object.values_size; i++) {
                const char *key = json_obj->u.object.values[i].name;
                int value = json_obj->u.object.values[i].value.int_value;

                // Handle potential integer overflow
                if (agg->cumulative_sum > LLONG_MAX / 2 || value > LLONG_MAX / 2) {
                    printf("Potential integer overflow detected\n");
                    break;
                }

                agg->total_count++;
                agg->cumulative_sum += value;

                int key_index = 0;
                while (agg->unique_keys[key_index] != NULL) {
                    key_index++;
                }
                if (key_index >= agg->unique_key_count) {
                    char **new_unique_keys = (char **)realloc(agg->unique_keys, sizeof(char *) * (agg->unique_key_count + 1));
                    new_unique_keys[agg->unique_key_count] = (char *)malloc(strlen(key) + 1);
                    strcpy(new_unique_keys[agg->unique_key_count], key);
                    free(agg->unique_keys);
                    agg->unique_keys = new_unique_keys;
                    agg->unique_key_count++;
                }
            }
        }
    }

    json_parser_deinit();
    // Print aggregate structure contents
    printf("Total count: %d\n", agg->total_count);
    printf("Cumulative sum: %lld\n", agg->cumulative_sum);
    printf("Unique keys:\n");
    for (int i = 0; i < agg->unique_key_count; i++) {
        printf("%s\n", agg->unique_keys[i]);
    }

    size_t largest_value = findLargestValue();
    if (largest_value != LLONG_MAX) {
        printf("Largest integer value found: %d\n", largest_value);
    } else {
        printf("No integer values found\n");
    }
}

