#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define the structure for a record
typedef struct {
    int value;
    char message[256];
    struct record* next;
} record;

// Define the custom memory pool structure
typedef struct {
    void** blocks;
    size_t capacity;
    size_t used;
    pthread_mutex_t mutex;
} memory_pool;

// Initialize a new record with random integer values and empty message buffer
record* init_record(size_t range) {
    record* r = (record*)malloc(sizeof(record));
    r->value = rand() % range;
    memset(r->message, 0, sizeof(r->message));
    r->next = NULL;
    return r;
}

// Initialize the memory pool with a given capacity
memory_pool* init_memory_pool(size_t capacity) {
    memory_pool* mp = (memory_pool*)malloc(sizeof(memory_pool));
    mp->blocks = (void**)malloc(capacity * sizeof(void*));
    mp->capacity = capacity;
    mp->used = 0;
    pthread_mutex_init(&mp->mutex, NULL);
    return mp;
}

// Clear the memory pool to manage resources efficiently
void clear_memory_pool(memory_pool* mp) {
    for (size_t i = 0; i < mp->used; i++) {
        free(mp->blocks[i]);
    }
    mp->used = 0;
}

// Add a record to the linked list using the memory pool
record* add_record(memory_pool* mp, size_t range) {
    record* r = init_record(range);
