        // Add a new record to the linked list
        add_record(mp, range);
        // Remove an existing record from the linked list
        remove_record(&head, mp);
        pthread_mutex_unlock(&mp->mutex);

        // Report performance metrics and memory usage
        printf("Memory used: %zu / %zu\n", mp->used, mp->capacity);
    }
}

int main() {
    // Initialize the custom memory pool with a capacity of 1000 blocks
    memory_pool* mp = init_memory_pool(1000);

