// Define the maximum number of elements allowed in each array type
#define MAX_DOUBLE_ARRAY 10000
#define MAX_CHAR_ARRAY 1000000
#define MAX_DATA_STRUCT_ARRAY 5000

// Define the thresholds at which arrays will be resized
#define DOUBLE_ARRAY_THRESHOLD 7500
#define CHAR_ARRAY_THRESHOLD 900000
#define DATA_STRUCT_ARRAY_THRESHOLD 4500

typedef struct {
    float value1;
    int value2;
    char* ptr;
} data_t;

// Double array management
double** double_array = NULL;
int double_array_size = 0;
int double_array_used = 0;

void* allocate_double(int size) {
    if (double_array_used >= DOUBLE_ARRAY_THRESHOLD) {
        // Resize the array when necessary
        double_array = realloc(double_array, sizeof(double*) * MAX_DOUBLE_ARRAY);
        double_array_size = MAX_DOUBLE_ARRAY;
        double_array_used = 0;
    }
    return malloc(size);
}

void deallocate_double(void* ptr) {
    free(ptr);
    double_array_used++;
    if (double_array_used >= DOUBLE_ARRAY_THRESHOLD / 2 && double_array_size < MAX_DOUBLE_ARRAY) {
        // Resize the array again when half of the threshold is reached
        double_array = realloc(double_array, sizeof(double*) * MAX_DOUBLE_ARRAY);
        double_array_size = MAX_DOUBLE_ARRAY;
        double_array_used = 0;
    }
}

// Char array management
