int char_array_size = 0;
int char_array_used = 0;

void* allocate_char(int size) {
    if (char_array_used >= CHAR_ARRAY_THRESHOLD) {
        // Resize the array when necessary
        char_array = realloc(char_array, sizeof(char*) * MAX_CHAR_ARRAY);
        char_array_size = MAX_CHAR_ARRAY;
        char_array_used = 0;
    }
    return malloc(size);
}

void deallocate_char(void* ptr) {
    free(ptr);
    char_array_used++;
    if (char_array_used >= CHAR_ARRAY_THRESHOLD / 2 && char_array_size < MAX_CHAR_ARRAY) {
        // Resize the array again when half of the threshold is reached
        char_array = realloc(char_array, sizeof(char*) * MAX_CHAR_ARRAY);
        char_array_size = MAX_CHAR_ARRAY;
        char_array_used = 0;
    }
}

// Data struct array management
data_t** data_struct_array = NULL;
int data_struct_array_size = 0;
int data_struct_array_used = 0;

void* allocate_data_struct(int size) {
    if (data_struct_array_used >= DATA_STRUCT_ARRAY_THRESHOLD) {
        // Resize the array when necessary
        data_struct_array = realloc(data_struct_array, sizeof(data_t*) * MAX_DATA_STRUCT_ARRAY);
        data_struct_array_size = MAX_DATA_STRUCT_ARRAY;
        data_struct_array_used = 0;
    }
    return malloc(size);
}

void deallocate_data_struct(void* ptr) {
    free(ptr);
    data_struct_array_used++;
    if (data_struct_array_used >= DATA_STRUCT_ARRAY_THRESHOLD / 2 && data_struct_array_size < MAX_DATA_STRUCT_ARRAY) {
        // Resize the array again when half of the threshold is reached
        data_struct_array = realloc(data_struct_array, sizeof(data_t*) * MAX_DATA_STRUCT_ARRAY);
        data_struct_array_size = MAX_DATA_STRUCT_ARRAY;
        data_struct_array_used = 0;
    }
}

// Free all arrays
void free_arrays() {
    for (int i = 0; i < double_array_size; i++) {
        deallocate_double(double_array[i]);
    }
