#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_POOL_SIZE 1024
#define MIN_CONCURRENT_OPERATIONS 10
#define LOG_BUFFER_SIZE 256

typedef struct record {
    int value;
    char log_buffer[LOG_BUFFER_SIZE];
    struct record* next;
} Record;

Record* pool_head = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
int pool_size = 0;
int min_concurrent_ops = MIN_CONCURRENT_OPERATIONS;

void init_pool() {
    if (pool_head == NULL) {
        pool_head = (Record*)malloc(sizeof(Record));
        pool_head->next = NULL;
        pool_size = sizeof(Record);
    }
}

Record* allocate_record(int value, char* log_buffer) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->value = value;
    strcpy(record->log_buffer, log_buffer);
    record->next = pool_head;
    pool_head = record;
    pool_size += sizeof(Record);
    return record;
}

void deallocate_record(Record* record) {
    Record* prev = NULL;
    Record* curr = pool_head;
    while (curr != NULL && curr != record) {
        prev = curr;
        curr = curr->next;
    }
    if (curr == NULL) {
        printf("Error: record not found\n");
        return;
    }
    if (prev == NULL) {
        pool_head = curr->next;
    } else {
        prev->next = curr->next;
    }
    free(record);
    pool_size -= sizeof(Record);
}

void clear_pool() {
    Record* temp = pool_head;
    while (temp != NULL) {
        Record* next = temp->next;
        free(temp);
        temp = next;
    }
    pool_head = NULL;
    pool_size = 0;
}

int add_record(int value, char* log_buffer) {
    pthread_mutex_lock(&pool_lock);
    if (pool_size > MAX_POOL_SIZE) {
        clear_pool();
    }
    Record* record = allocate_record(value, log_buffer);
    pthread_mutex_unlock(&pool_lock);
    return pool_size;
}

void remove_record(Record* record) {
    pthread_mutex_lock(&pool_lock);
    deallocate_record(record);
    pthread_mutex_unlock(&pool_lock);
}

int traverse_records(void (*callback)(Record*)) {
    Record* curr = pool_head;
    while (curr != NULL) {
        callback(curr);
        curr = curr->next;
    }
    return 0;
}

void print_log_buffer(Record* record) {
    printf("%s\n", record->log_buffer);
}

int main() {
    pthread_t thread;

    // Create a new thread
    pthread_create(&thread, NULL, (pthread_start_routine)print_log_buffer, pool_head);

    return 0;
}
