['Here's an example implementation in C for a scalable and efficient memory manager:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the struct data type
typedef struct {
    float f;
    int i;
    char *s;
} data_t;

// Define the collection structure
typedef struct {
    size_t capacity;
    size_t size;
    double *doubles;
    char **chars;
    data_t **data;
    // Add any other necessary fields or structures here
} collection_t;

// Initialize a new collection
collection_t *collection_init(size_t initial_capacity) {
    collection_t *col = (collection_t *)malloc(sizeof(collection_t));
    col->capacity = initial_capacity;
    col->size = 0;
    col->doubles = (double *)malloc(col->capacity * sizeof(double));
    col->chars = (char **)malloc(col->capacity * sizeof(char *));
    col->data = (data_t **)malloc(col->capacity * sizeof(data_t *));
    return col;
}

// Resize the collection to a new capacity
void collection_resize(collection_t *col, size_t new_capacity) {
    // Calculate the new memory requirements
    size_t old_size = col->size;
    size_t new_size = (new_capacity > 0 ? new_capacity : 1);

    // Reallocate arrays with the new sizes
    double *old_doubles = col->doubles;
    char **old_chars = col->chars;
    data_t **old_data = col->data;

    col->capacity = new_capacity;
    col->size = new_size;
    col->doubles = (double *)malloc(col->capacity * sizeof(double));
    col->chars = (char **)malloc(col->capacity * sizeof(char *));
    col->data = (data_t **)malloc(col->capacity * sizeof(data_t *));

    // Copy data from old arrays to new arrays
    memcpy(col->doubles, old_doubles, old_size * sizeof(double));
    for (size_t i = 0; i < old_size; i++) {
        col->chars[i] = old_chars[i];
        col->data[i] = old_data[i];
    }

    // Free the old arrays
    free(old_doubles);
    free(old_chars);
    free(old_data);
}

// Add a new element to the collection
void collection_add(collection_t *col, double d) {
    if (col->size >= col->capacity) {
        collection_resize(col, col->capacity * 2); // Double the capacity for resizing
    }
    col->doubles[col->size] = d;
    col->chars[col->size] = malloc(1);
    strcpy(col->chars[col->size], ""); // Initialize with empty string
    col->data[col->size] = malloc(sizeof(data_t));
    col->data[col->size]->f = 0.0; // Initialize float to zero
    col->data[col->size]->i = 0; // Initialize int to zero
    col->data[col->size]->s = NULL;
    col->size++;
}

// Add a new element to the collection using custom data structure
void collection_add_data(collection_t *col, data_t *d) {
    if (col->size >= col->capacity) {
        collection_resize(col, col->capacity * 2); // Double the capacity for resizing
    }
    col->data[col->size] = d;
    col->chars[col->size] = malloc(strlen(d->s) + 1);
    strcpy(col->chars[col->size], d->s); // Copy string from data structure to array
    col->doubles[col->size] = d->f; // Copy float value from data structure to array
    col->data[col->size]->i = d->i; // Copy int value from data structure to array
    col->size++;
}

// Remove an element from the collection
void collection_remove(collection_t *col, size_t index) {
    if (index >= col->size) {
        printf("Index out of bounds\n");
        return;
    }

    memmove(col->doubles + index, col->doubles + index + 1, (col->size - index - 1) * sizeof(double));
    for (size_t i = 0; i < col->size - index - 1; i++) {
        free(col->chars[i]);
    }
    col->size--;
}

// Free the collection
void collection_free(collection_t *col) {
    for (size_t i = 0; i < col->size; i++) {
        free(col->chars[i]);
        free(col->data[i]);
    }
    free(col->doubles);
    free(col->chars);
    free(col->data);
    free(col);
}
