// Function to calculate and store file hash in metadata array
void process_file(char *filename, metadata *metadata) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: Cannot open file.\n");
        return;
    }

    // Calculate MD5 hash of the file
    unsigned char hash[16];
    int errCode = 0;
    ERR_clear_error();
    errCode = EVP_DigestInit_ex(NULL, EVP_md5(), NULL);
    if (errCode != 1) {
        printf("Error: Cannot initialize MD5.\n");
        return;
    }
    EVP_DigestUpdate(file, NULL, 0);
    EVP_DigestFinal_ex(NULL, hash, &errCode);
    fclose(file);

    // Store file hash in metadata array
    strcpy(metadata->file_hash, (char *)hash);
}

