        logs[i].message = (char *)malloc(20);
        sprintf(logs[i].message, "Log message for measurement %d", i);

        configurations[i].setting1 = rand() % 2;
        configurations[i].setting2 = rand() % 3;
        configurations[i].setting3 = rand() % 4;

        // Check array sizes
        if (numMeasurements > sizeOfMeasurementArray) {
            printf("Error: measurement array exceeded size limit.\n");
            exit(1);
        }
    }

    // Read and process measurements from standard input
    for (int i = 0; i < numMeasurements; i++) {
        int measurement;
        scanf("%d", &measurement);
        measurements[i] = measurement;
    }

    // Calculate and print the average measurement in the array using a helper function
    double averageMeasurement = calculateAverage(measurements, numMeasurements);
    printf("Average measurement: %f\n", averageMeasurement);

    // Free all allocated memory when the function returns
    for (int i = 0; i < numMeasurements; i++) {
        free(identifiers[i]);
        free(logs[i].message);
    }
    free(measurements);
    free(identifiers);
    free(timestamps);
    free(events);
    free(logs);
    free(configurations);

    // Return success
    return 0;
}

// Helper function to calculate the average measurement in the array
double calculateAverage(double *measurements, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += measurements[i];
    }
    return sum / size;
}
